export const v45Questions = [{"id":"m45-pt-concordancia-01","subject":"Português","topic":"Concordância","subtopic":"Concordância verbal — sujeito simples com termos intercalados","prompt":"Complete a frase: No conjunto de medidas aprovadas pelo conselho _____ um reajuste salarial.","options":["figuram","figurou","figura","figuraram"],"answer":2,"explanation":"O núcleo do sujeito é \"um reajuste salarial\" (singular). A expressão preposicionada \"no conjunto de medidas aprovadas pelo conselho\" não integra o sujeito; é adjunto adverbial. Logo, o verbo deve ir ao singular: \"figura\". As demais formas ou estão no plural (figuram/figuraram) ou em tempo inadequado ao enunciado neutro (figurou).","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Identificar núcleo do sujeito e aplicar concordância verbal correta.","commonError":"Concordar o verbo com o termo mais próximo (\"medidas\") e não com o núcleo do sujeito.","whyWrong":"- \"figuram/figuraram\": erro por atração com \"medidas\" (termo preposicionado) e número incorreto do sujeito.\n- \"figurou\": troca desnecessária de tempo verbal; a questão exige concordância, não mudança de tempo.","reviewHint":"Isole o sujeito: retire termos preposicionados e pergunte \"o que é que figura?\".","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-02","subject":"Português","topic":"Concordância","subtopic":"Concordância verbal — sujeito composto anteposto","prompt":"Assinale a forma correta: A falta de peças e o excesso de calor _____ o desempenho do equipamento.","options":["comprometem","compromete","comprometeram","comprometeu"],"answer":0,"explanation":"Sujeito composto anteposto (\"A falta de peças e o excesso de calor\") exige, como regra geral, verbo no plural: \"comprometem\". As formas no singular (compromete/comprometeu) ferem a concordância; as do passado (comprometeram/comprometeu) alteram o tempo sem justificativa.","difficulty":"intermediária","sourceBasis":"https://open.umn.edu/opentextbooks/textbooks/portugues-para-principiantes (CC BY-NC-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://open.umn.edu/opentextbooks/textbooks/portugues-para-principiantes (CC BY-NC-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Reconhecer sujeito composto e ajustar o verbo ao plural.","commonError":"Usar o singular por influência do núcleo mais próximo ou por automatismo.","whyWrong":"- \"compromete/comprometeu\": não concordam com o sujeito composto anteposto (plural).\n- \"comprometeram\": embora no plural, muda o tempo verbal sem necessidade.","reviewHint":"Com dois núcleos ligados por \"e\", antes do verbo, use o plural.","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-03","subject":"Português","topic":"Concordância","subtopic":"Concordância verbal — estruturas com \"nem... nem...\"","prompt":"Preencha corretamente: Nem o gerente nem os analistas _____ à reunião.","options":["compareceu","tinha comparecido","compareceria","compareceram"],"answer":3,"explanation":"\"Nem... nem...\" forma sujeito composto; a regra geral determina verbo no plural: \"compareceram\". As demais alternativas estão no singular e, portanto, não concordam com o sujeito composto.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Aplicar a concordância verbal em estruturas negativas coordenadas.","commonError":"Pensar que o verbo pode concordar com o núcleo mais próximo e ficar no singular.","whyWrong":"- \"compareceu\", \"tinha comparecido\", \"compareceria\": todas concordam com apenas um núcleo; com \"nem... nem...\" o verbo deve ir ao plural.","reviewHint":"Com \"nem... nem...\", trate como sujeito composto: verbo no plural.","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-04","subject":"Português","topic":"Concordância","subtopic":"Concordância verbal com partitivos/coletivos (maioria/parte)","prompt":"Assinale a alternativa que completa corretamente: A maioria dos voluntários _____ cedo, mas parte deles _____ até tarde.","options":["chegaram; ficaram","chegou; ficou","chegaram; ficou","chegou; ficaram"],"answer":1,"explanation":"Em \"a maioria dos voluntários\", o núcleo é \"maioria\" (coletivo singular), portanto: \"chegou\". Em \"parte deles\", o núcleo é \"parte\" (singular), portanto: \"ficou\". O plural é aceitável em alguns contextos por concordância atrativa, mas a forma preferencial normativa é o singular para os coletivos/partitivos.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Identificar núcleos coletivos/partitivos e aplicar a concordância preferencial no singular.","commonError":"Deixar-se atrair pelo plural do complemento posposto e pluralizar o verbo.","whyWrong":"- \"chegaram; ficaram\" e \"chegaram; ficou\" e \"chegou; ficaram\": fazem o verbo concordar com o termo posposto (\"voluntários/eles\"), não com o núcleo coletivo/partitivo no singular.","reviewHint":"Em coletivos como \"maioria/parte\", prefira verbo no singular.","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-05","subject":"Português","topic":"Concordância","subtopic":"Concordância com porcentagens","prompt":"Complete de acordo com a norma: Cerca de 30% dos inscritos _____ isenção; 1% da taxa _____ destinado ao fundo.","options":["tem; estão","têm; estão","têm; está","tem; está"],"answer":2,"explanation":"Com porcentagem, o verbo pode concordar com o numeral/termo regido: \"30% dos inscritos\" pede plural: \"têm\". Já \"1% da taxa\" é singular: \"está\". Assim, \"têm; está\" é a combinação correta.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Aplicar regras de concordância com percentuais ligados a nomes no singular/plural.","commonError":"Concordar pelo substantivo posposto sem considerar o valor percentual ou ignorar o singular de 1%.","whyWrong":"- \"tem; estão\": erra nos dois verbos (30% pede plural; 1% pede singular).\n- \"têm; estão\": acerta o primeiro, erra o segundo (1% no plural).\n- \"tem; está\": erra o primeiro (30% no singular).","reviewHint":"Olhe o número: 1% → singular; percentuais maiores, em geral → plural (com nome plural).","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-06","subject":"Português","topic":"Concordância","subtopic":"Verbos impessoais — haver (existência)","prompt":"Complete a lacuna: _____ três casos de fraude no relatório.","options":["Há","Houveram","Existiu","Fazem"],"answer":0,"explanation":"\"Haver\" com sentido de existir é impessoal e fica no singular: \"Há\". \"Houveram\" é incorreto nesse uso. \"Existiu\" exigiria sujeito no singular (o correto seria \"existiram\"). \"Fazem\" é de tempo decorrido e, além disso, impessoalmente deve ficar no singular.","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Reconhecer verbos impessoais e fixar sua forma no singular.","commonError":"Flexionar \"haver\" de existência no plural por atração com o termo plural subsequente.","whyWrong":"- \"Houveram\": não se flexiona no impessoal de existência.\n- \"Existiu\": concordância errada (sujeito plural).\n- \"Fazem\": uso inadequado (não indica tempo) e, mesmo que indicasse, seria singular (faz).","reviewHint":"Se \"haver\" = existir, mantenha no singular: há, havia, houve, haverá.","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-07","subject":"Português","topic":"Concordância","subtopic":"Concordância com a expressão \"mais de um\"","prompt":"Assinale a alternativa correta: Mais de um candidato _____ o formulário incorretamente.","options":["preencheram","têm preenchido","preencheria","preencheu"],"answer":3,"explanation":"A estrutura \"mais de um\" pede, como regra geral, verbo no singular: \"preencheu\". O plural só aparece em casos específicos (ideia de reciprocidade, entre outros), não sugeridos aqui.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Aplicar a regra de concordância de expressões quantitativas cristalizadas.","commonError":"Supor que \"mais de um\" obriga plural por referência a vários indivíduos.","whyWrong":"- \"preencheram/têm preenchido\": aplicam plural indevido.\n- \"preencheria\": muda o modo/tempo sem necessidade e permanece no singular sem marcar o pretérito como pede o contexto de ação concluída.","reviewHint":"Com \"mais de um\" use o singular, salvo exceções estilísticas (reciprocidade).","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-08","subject":"Português","topic":"Concordância","subtopic":"Concordância verbal com pronomes relativos (\"um dos que...\")","prompt":"Escolha a forma adequada: Eu sou um dos que _____ de madrugada para estudar.","options":["acorda","acordam","acordou","acordaria"],"answer":1,"explanation":"Com o relativo \"que\", o verbo concorda com seu antecedente: \"os (que)\". Assim, o verbo fica no plural: \"acordam\". \"Acorda/acordou/acordaria\" estão no singular e não concordam com o antecedente plural.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Identificar o antecedente de pronomes relativos e ajustar a concordância do verbo.","commonError":"Concordar o verbo do relativo com \"um\" (singular), e não com \"os que\" (plural).","whyWrong":"- \"acorda/acordou/acordaria\": erro de concordância com o antecedente plural do relativo (\"os que\").","reviewHint":"Em \"um dos que\", o verbo após \"que\" vai ao plural: concorda com \"os (que)\".","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-09","subject":"Português","topic":"Concordância","subtopic":"Concordância nominal — adjetivo posposto a dois núcleos de gêneros distintos","prompt":"Assinale a opção correta: Foram entregues o relatório e a planilha _____.","options":["atualizada","atualizado","atualizados","atualizadas"],"answer":2,"explanation":"Com dois substantivos de gêneros diferentes e adjetivo posposto, a concordância vai para o masculino plural: \"atualizados\". As demais alternativas não atendem ao gênero e número resultantes (masc. + fem. → masc. plural).","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Aplicar concordância nominal com adjetivo posposto a núcleos heterogêneos.","commonError":"Fazer o adjetivo concordar com o núcleo mais próximo, ignorando o outro.","whyWrong":"- \"atualizada/atualizado\": concordam só com um dos núcleos.\n- \"atualizadas\": plural correto, mas gênero feminino, inadequado ao conjunto (há núcleo masculino).","reviewHint":"Adjetivo posposto a masc. + fem. → masculino plural.","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-10","subject":"Português","topic":"Concordância","subtopic":"Concordância nominal — \"proibido/permitido\" + infinitivo/substantivo com artigo","prompt":"Complete: É _____ estacionar aqui; é _____ a entrada de veículos.","options":["proibido; proibida","proibida; proibida","proibido; proibido","proibida; proibido"],"answer":0,"explanation":"Com infinitivo, o adjetivo fica invariável: \"é proibido estacionar\". Com substantivo determinado por artigo, o adjetivo concorda: \"é proibida a entrada\". Portanto, \"proibido; proibida\" é a forma correta.","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Distinguir quando o adjetivo se flexiona em construções fixas.","commonError":"Flexionar \"proibido\" diante de infinitivo ou deixar invariável diante de substantivo com artigo.","whyWrong":"- \"proibida; proibida\": erra a primeira, que deve ficar invariável com infinitivo.\n- \"proibido; proibido\": erra a segunda, que deve concordar com \"a entrada\" (fem. sing.).\n- \"proibida; proibido\": inverte os padrões.","reviewHint":"Infinitivo → adjetivo invariável; com artigo → adjetivo concorda.","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-11","subject":"Português","topic":"Concordância","subtopic":"Concordância nominal e verbal — uso de \"anexo/em anexo\"","prompt":"Selecione a redação correta:","options":["Segue anexas as fichas solicitadas.","Seguem anexas as fichas solicitadas.","Seguem em anexo a ficha solicitada.","Segue anexo as fichas solicitadas."],"answer":1,"explanation":"O verbo \"seguir\" deve concordar com o sujeito \"as fichas\" (plural): \"seguem\". Usando o adjetivo \"anexas\", ele concorda com \"fichas\" (fem. pl.): \"anexas\". As demais alternativas apresentam erro de concordância verbal e/ou nominal.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Sincronizar concordância verbal do enunciador com a concordância nominal do adjetivo.","commonError":"Achar que \"em anexo\" dispensa a concordância verbal ou usar \"anexo\" invariável.","whyWrong":"- \"Segue anexas...\": verbo no singular com sujeito plural.\n- \"Seguem em anexo a ficha...\": verbo no plural com sujeito singular; com \"em anexo\" (invariável) o verbo ainda deve concordar com \"a ficha\" → singular.\n- \"Segue anexo as fichas...\": além do verbo no singular, \"anexo\" não concorda com \"fichas\" (fem. pl.).","reviewHint":"Identifique o sujeito de \"seguir\" e ajuste o adjetivo: em anexo (invariável) vs. anexo/anexas (variável).","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-12","subject":"Português","topic":"Concordância","subtopic":"Concordância do verbo \"ser\" com predicativo e sujeito posposto","prompt":"Assinale a frase correta quanto à concordância do verbo ser.","options":["É três os motivos do atraso.","Foi três os motivos do atraso.","É muitos os motivos do atraso.","São três os motivos do atraso."],"answer":3,"explanation":"Quando o sujeito posposto é plural (\"os motivos\"), o verbo \"ser\" vai ao plural: \"São três os motivos do atraso\". As demais alternativas mantêm o verbo no singular com sujeito plural, ferindo a norma.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Aplicar a concordância de \"ser\" em construções com sujeito posposto e numerais.","commonError":"Fixar \"é\" como forma neutra antes de numerais, esquecendo a concordância com o sujeito plural posposto.","whyWrong":"- A, B, C: verbo no singular com sujeito plural (\"os motivos\"), contrariando a concordância exigida.","reviewHint":"Olhe o núcleo do sujeito; com plural posposto, use \"são\".","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-13","subject":"Português","topic":"Concordância","subtopic":"Concordância verbal com sujeito coletivo simples","prompt":"Complete segundo a norma: Um grupo de alunos _____ o laboratório pela manhã.","options":["visitou","visitaram","têm visitado","visitaria"],"answer":0,"explanation":"O núcleo é o coletivo \"grupo\" (singular). Por isso, o verbo vai ao singular: \"visitou\". As formas no plural ou com tempos/modos deslocados não atendem ao foco na concordância.","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Reconhecer coletivos e fixar a concordância pelo núcleo real do sujeito.","commonError":"Concordar com \"alunos\" (plural) em vez de com \"grupo\" (singular).","whyWrong":"- \"visitaram\": concorda com o termo posposto (\"alunos\"), não com o núcleo coletivo.\n- \"têm visitado/visitaria\": alteram o tempo/modo sem necessidade e fogem ao ponto da concordância.","reviewHint":"Em \"um grupo de...\", o verbo concorda com \"grupo\" (singular).","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-14","subject":"Português","topic":"Concordância","subtopic":"Concordância verbal com frações","prompt":"Assinale a forma adequada: Dois terços do material _____ separados para descarte.","options":["foi","está","foram","será"],"answer":2,"explanation":"Com frações, a concordância costuma ser feita com o numerador: \"dois terços\" (plural). Portanto, \"foram\" (e o predicativo, \"separados\", também no plural).","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Aplicar a concordância com expressões fracionárias.","commonError":"Concordar com o nome pós-\"de\" (\"material\", singular) por atração.","whyWrong":"- \"foi/está/será\": formas no singular, em desacordo com o sujeito plural (\"dois terços\").","reviewHint":"Concorde com o numerador: dois terços → plural; um terço → singular.","contentId":"pt-concordancia"},{"id":"m45-pt-concordancia-15","subject":"Português","topic":"Concordância","subtopic":"Verbos impessoais de tempo e concordância de \"ser\" com horas","prompt":"Complete corretamente: _____ cinco anos que ele ingressou; agora _____ sete horas.","options":["Fazem; é","Faz; são","Fazem; são","Faz; é"],"answer":1,"explanation":"\"Fazer\" indicando tempo decorrido é impessoal e fica no singular: \"Faz cinco anos\". Com horas, o verbo \"ser\" concorda com o numeral plural: \"são sete horas\".","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA); calibração apenas: https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Reconhecer o valor impessoal de \"fazer\" e a concordância de \"ser\" com horas.","commonError":"Flexionar \"fazer\" de tempo e usar \"é\" com horas no plural.","whyWrong":"- \"Fazem; é\" e \"Fazem; são\": flexionam indevidamente o impessoal \"fazer\".\n- \"Faz; é\": erra a concordância de \"ser\" com horas (deve ser plural).","reviewHint":"Tempo decorrido: \"faz\"; horas no plural: \"são\".","contentId":"pt-concordancia"},{"id":"m45-pt-gramatica-01","subject":"Português","topic":"Gramática","subtopic":"Acentuação gráfica (Novo Acordo)","prompt":"Assinale a alternativa em que todas as palavras estão grafadas conforme a norma vigente quanto a acentos em hiato/ditongo e supressões do Acordo Ortográfico:","options":["saída, heróico, Piauí, feiúra","saida, heroico, Piaui, feiura","saída, heroico, Piauí, feiura","saída, heróico, Piauí, feiura"],"answer":2,"explanation":"Saída mantém acento por hiato a-í; heroico perdeu o acento (não há mais heróico); Piauí mantém acento no í final por hiato u-í; feiura perdeu o acento (antes feiúra) por ser i/u tônico após ditongo em palavra paroxítona. As demais alternativas trazem grafias abolidas pelo AO (heróico, feiúra) ou omitem acentos obrigatórios (saída, Piauí).","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reconhecer regras atuais de acentuação de hiatos e ditongos","commonError":"Confundir o caso do hiato com os acentos abolidos em ditongos (heroico) e em i/u tônicos após ditongo (feiura).","whyWrong":"A: contém heróico (forma abolida) e feiúra (acento abolido). B: omite acentos obrigatórios em saída e Piauí. D: mantém heróico (indevido).","reviewHint":"Revise as exceções do AO: i/u tônicos após ditongo (palavras paroxítonas) e a queda do acento em ditongos abertos de paroxítonas.","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-02","subject":"Português","topic":"Gramática","subtopic":"Fonologia: encontros vocálicos","prompt":"Classifique, na ordem, os encontros vocálicos em: caixa — saguão — saúde — dia.","options":["ditongo decrescente — tritongo — hiato — ditongo crescente","ditongo decrescente — ditongo nasal — hiato — hiato","ditongo crescente — ditongo nasal — hiato — ditongo decrescente","hiato — ditongo nasal — hiato — hiato"],"answer":1,"explanation":"Caixa apresenta ditongo decrescente (ai); saguão tem ditongo nasal decrescente (uã); saúde apresenta hiato (a-ú); dia apresenta hiato (di-a).","difficulty":"intermediária","sourceBasis":"https://open.umn.edu/opentextbooks/textbooks/portugues-para-principiantes; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://open.umn.edu/opentextbooks/textbooks/portugues-para-principiantes; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Classificar encontros vocálicos em contexto real","commonError":"Tomar a sequência ‘ia’ sempre como ditongo; em dia, o i é vogal nuclear e separa-se em hiato.","whyWrong":"A: saguão não tem tritongo; em dia há hiato, não ditongo crescente. C: caixa não tem ditongo crescente e dia não tem ditongo decrescente. D: caixa não é hiato.","reviewHint":"Relembre critérios: ditongo (uma sílaba), hiato (separação silábica), nasalização indicada por til/ambiente.","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-03","subject":"Português","topic":"Gramática","subtopic":"Formação de palavras: derivação parassintética","prompt":"Assinale a alternativa em que todas as palavras foram formadas por derivação parassintética.","options":["entristecer, empobrecer, amanhecer","clarear, alargar, esverdear","desleal, felizmente, infeliz","pedreiro, guarda-roupa, girassol"],"answer":0,"explanation":"Entristecer, empobrecer e amanhecer resultam da adição simultânea de prefixo e sufixo (en-/em-/a- + radical + -ecer). Nas demais: clarear/alargar/esverdear são sufixais; desleal/infeliz são prefixais e felizmente é sufixal; pedreiro é sufixal, guarda-roupa e girassol são compostos.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Identificar processos de formação vocabular em verbos derivados","commonError":"Confundir verbos em -ecer por sufixação simples; quando há também prefixo indispensável, trata-se de parassíntese.","whyWrong":"B: apenas sufixação. C: processos mistos, sem parassíntese. D: um caso sufixal e dois de composição, não parassíntese.","reviewHint":"Verifique se a palavra existe sem o prefixo ou sem o sufixo; se não, é indício de parassíntese.","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-04","subject":"Português","topic":"Gramática","subtopic":"Pronomes relativos e regência","prompt":"Reescreva mantendo correção e sentido: “A solução a que chegamos foi distinta da que propúnhamos.” Assinale a reformulação adequada.","options":["A solução que chegamos foi distinta da qual propúnhamos.","A solução à que chegamos foi distinta de que propúnhamos.","A solução à qual chegamos foi distinta da que propúnhamos.","A solução à qual chegamos foi distinta da qual propúnhamos."],"answer":3,"explanation":"O verbo chegar rege “a”: “a que” = “à qual”. O adjetivo/locução “distinto de” exige “de”: “da que/da qual”. A forma plenamente paralela é “à qual … da qual”.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Ajustar pronomes relativos com a preposição exigida pela regência","commonError":"Ignorar a regência de “chegar a” e trocar “de” por “a” após “distinto”.","whyWrong":"A: Falta a preposição exigida por “chegar (a)”. B: Crase indevida antes de “que” e regência trocada após “distinta”. C: Mantém correção em “à qual”, mas quebra a paralelismo ao usar “da que”; a opção D é a integralmente paralela.","reviewHint":"Substitua “que” por “o qual/a qual” para checar a preposição contraída correta.","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-05","subject":"Português","topic":"Gramática","subtopic":"Colocação pronominal (próclise)","prompt":"Quanto à norma-padrão de colocação pronominal, assinale a frase correta.","options":["Ninguém enviou-lhe o relatório.","Ninguém lhe enviou o relatório.","Lhe enviou ninguém o relatório.","Enviou-lhe ninguém o relatório."],"answer":1,"explanation":"Palavras negativas atraem o pronome (próclise obrigatória): “Ninguém lhe enviou…”. As demais tentam ênclise após atrativo (vedada) ou descolam o pronome da posição natural.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Aplicar regras de próclise com termos atrativos","commonError":"Achar que ênclise é sempre preferível em português; após palavras atrativas, a próclise é mandatória.","whyWrong":"A e D: ênclise proibida após atrativo “ninguém”. C: ordem agramatical, com pronome antes do verbo sem atrativo e sujeito posposto inadequadamente.","reviewHint":"Memorize os principais atrativos: negativas, pronomes relativos, conjunções subordinativas, advérbios sem pausa.","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-06","subject":"Português","topic":"Gramática","subtopic":"Emprego do “se” (índice/apassivador)","prompt":"Classifique o “se” em: “Precisa-se de voluntários.” e “Vendem-se ingressos.”, respectivamente.","options":["partícula apassivadora e índice de indeterminação do sujeito","pronome reflexivo e partícula apassivadora","índice de indeterminação do sujeito e partícula apassivadora","partícula expletiva e pronome recíproco"],"answer":2,"explanation":"Em “Precisa-se de voluntários”, o verbo é transitivo indireto (“precisar de”), logo “se” indetermina o sujeito. Em “Vendem-se ingressos”, o verbo é transitivo direto; “se” é partícula apassivadora: “ingressos são vendidos”.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Distinguir usos do “se” conforme a transitividade verbal","commonError":"Confundir indeterminação (VTIs, intransitivos) com voz passiva sintética (VTD/VTDI com concordância).","whyWrong":"A: Inverte os papéis. B e D: classificações que não se aplicam aos exemplos dados.","reviewHint":"Cheque a regência do verbo: VTD/VTDI tendem à passiva sintética; VTI/intransitivo, à indeterminação.","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-07","subject":"Português","topic":"Gramática","subtopic":"Crase e regência nominal","prompt":"Assinale a alternativa em que o uso do acento grave é INCORRETO.","options":["Ele se referiu à ela durante a reunião.","Voltaremos à tarde para concluir o teste.","Fiquei à disposição da equipe após o voo.","Entreguei o relatório à diretora ontem."],"answer":0,"explanation":"É vedada a crase antes de pronomes pessoais: “a ela” (sem artigo). As outras: locução adverbial feminina (“à tarde”), locução prepositiva (“à disposição”) e regência com artigo feminino (“à diretora”) exigem crase.","difficulty":"intermediária","sourceBasis":"https://www.letras.ufmg.br/arquivos/gramaticaonline/exercicios/exerciciossobrecrase.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://www.letras.ufmg.br/arquivos/gramaticaonline/exercicios/exerciciossobrecrase.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Aplicar a regra de crase em locuções e com nomes femininos","commonError":"Generalizar a crase antes de quaisquer palavras femininas, incluindo pronomes pessoais (onde é proibida).","whyWrong":"B, C e D: trazem contextos que pedem crase por locução feminina ou fusão de preposição com artigo definido feminino.","reviewHint":"Teste a substituição por “ao” (masc.); se couber, há forte indício de crase no feminino.","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-08","subject":"Português","topic":"Gramática","subtopic":"Pontuação: orações adjetivas (efeito de sentido)","prompt":"Compare: I) “Os pilotos que treinam diariamente alcançam melhor desempenho.” II) “Os pilotos, que treinam diariamente, alcançam melhor desempenho.” Sobre o efeito da vírgula, assinale a correta.","options":["As duas frases são equivalentes; a vírgula é estilística.","Na segunda, restringe-se o conjunto de pilotos aos que treinam diariamente.","Na primeira, o relativo acrescenta comentário acessório, válido para todos os pilotos.","Na segunda, a oração adjetiva é explicativa e indica que todos os pilotos treinam diariamente."],"answer":3,"explanation":"Sem vírgulas (I), a oração adjetiva é restritiva: apenas os pilotos que treinam diariamente. Com vírgulas (II), é explicativa: afirma-se que todos os pilotos treinam diariamente.","difficulty":"avançada","sourceBasis":"https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Analisar o impacto semântico da vírgula em orações adjetivas","commonError":"Ignorar que vírgulas em adjetivas mudam de restrição para explicação, alterando o referente.","whyWrong":"A: Há mudança de sentido. B: É o inverso: a restrição ocorre na frase I. C: Na I, a oração é restritiva, não acessória.","reviewHint":"Pergunte-se: a informação distingue um subconjunto (sem vírgula) ou comenta sobre o todo (com vírgulas)?","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-09","subject":"Português","topic":"Gramática","subtopic":"Pontuação e tipos de discurso: citação direta","prompt":"Assinale a redação com pontuação adequada para introduzir citação direta curta.","options":["O comandante ordenou, \"Concluam o reparo imediato\".","O comandante ordenou \"Concluam o reparo imediato.\"","O comandante ordenou: \"Concluam o reparo imediato.\"","O comandante ordenou — \"Concluam o reparo imediato\"."],"answer":2,"explanation":"A forma canônica é usar dois-pontos antes da citação e fechar a frase pontuando dentro das aspas quando a frase citada se encerra ali: “O comandante ordenou: ‘Concluam o reparo imediato.’”.","difficulty":"intermediária","sourceBasis":"https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Empregar pontuação normativa em citação direta","commonError":"Usar vírgula em vez de dois-pontos para introduzir citação direta formal.","whyWrong":"A e B: faltam os dois-pontos antes da fala. D: travessão não é o sinal padrão ante citação introduzida por verbo dicendi e falta o ponto final dentro das aspas.","reviewHint":"Após verbo dicendi, use dois-pontos; pontuação final da fala fica dentro das aspas.","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-10","subject":"Português","topic":"Gramática","subtopic":"Tipos de discurso: direto → indireto","prompt":"Converta mantendo a correlação temporal: “O técnico afirmou: ‘Entregarei o satélite amanhã’.” Assinale a opção correta em discurso indireto.","options":["O técnico afirmou que entregaria o satélite no dia seguinte.","O técnico afirmou que entregará o satélite amanhã.","O técnico afirmou que entregaríamos o satélite no dia seguinte.","O técnico afirmou que iria entregar o satélite amanhã."],"answer":0,"explanation":"Com verbo de elocução no passado, o futuro do presente converte-se em futuro do pretérito (“entregaria”) e o deíctico “amanhã” em “no dia seguinte”.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Converter discurso direto em indireto com ajustes de tempo e deíxis","commonError":"Esquecer de ajustar os deícticos (amanhã → no dia seguinte) ao passar para o indireto.","whyWrong":"B: Mantém tempos e deíxis como no direto. C: Pessoa verbal troca-se indevidamente (1ª plural). D: Troca perifrástica aceitável do tempo, mas mantém “amanhã”, falhando na deíxis temporal.","reviewHint":"Aplique backshift de tempos e substitua deícticos: aqui/amanhã/este → ali/no dia seguinte/aquele.","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-11","subject":"Português","topic":"Gramática","subtopic":"Conjunções e valor semântico","prompt":"Complete: “________ esteja nublado, a decolagem ocorrerá no horário.”","options":["Porque","Embora","Portanto","Logo"],"answer":1,"explanation":"O contexto pede concessão: “Embora esteja nublado…”. As demais expressam causa (porque) ou conclusão (portanto, logo), incoerentes com o contraste.","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Selecionar conjunções de acordo com o valor semântico","commonError":"Confundir conectivos conclusivos com concessivos em orações adversativas.","whyWrong":"A: Introduz causa, não concessão. C e D: Marcam conclusão, não contraste concessivo.","reviewHint":"Concessão admite oposição esperada: mesmo que X, ocorre Y; teste com embora/ainda que.","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-12","subject":"Português","topic":"Gramática","subtopic":"Flexão de número em compostos","prompt":"Assinale a alternativa com plural formado corretamente.","options":["guardas-chuvas","navio-escolas","couves-flor","bem-te-vis"],"answer":3,"explanation":"Bem-te-vis é o plural consagrado do nome da ave. Guarda-chuva pluraliza o segundo elemento: guarda-chuvas; navio-escola pluraliza apenas o primeiro: navios-escola; couve-flor pluraliza os dois: couves-flores.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Aplicar regras de plural em compostos por justaposição","commonError":"Pluralizar todos os elementos indiscriminadamente ou apenas o último em compostos fixos.","whyWrong":"A: O primeiro elemento (verbo) é invariável: guarda-chuvas. B: Pluraliza-se só “navios-”. C: Ambos os núcleos vão ao plural: couves-flores.","reviewHint":"Identifique a classe/valor de cada elemento do composto para decidir a flexão.","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-13","subject":"Português","topic":"Gramática","subtopic":"Ortografia: uso do hífen com prefixos","prompt":"Segundo o Novo Acordo, assinale a alternativa em que todas as palavras estão corretamente grafadas.","options":["anti-ético, semi-analfaBeto, micro ondas","antiinflamatório, anti-higiênico, auto-estrada","anti-inflamatório, anti-higiênico, autoescola","anti ético, micro-ondas, semi-analfabeto"],"answer":2,"explanation":"Usa-se hífen quando o prefixo termina em vogal e o segundo elemento começa com a mesma vogal (anti-inflamatório) e com h (anti-higiênico). Com vogais diferentes, sem hífen: autoescola. As demais trazem separação indevida, falta de hífen necessário ou hífen abolido.","difficulty":"avançada","sourceBasis":"https://www.letras.ufmg.br/arquivos/gramaticaonline/exercicios/exerciciosnovoacordoortografico.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://www.letras.ufmg.br/arquivos/gramaticaonline/exercicios/exerciciosnovoacordoortografico.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Aplicar regras de hífen com prefixos em contextos variados","commonError":"Aplicar hífen por analogia sem observar as regras de vogal igual e de prefixo ante h.","whyWrong":"A: Grafias incorretas e separação indevida. B: Falta hífen em antiinflamatório; auto-estrada perdeu hífen (autoestrada). D: “anti ético” separado é incorreto, embora micro-ondas e semi-analfabeto estejam corretas.","reviewHint":"Confira: vogal igual → hífen; h inicial → hífen; vogais diferentes → sem hífen (salvas exceções).","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-14","subject":"Português","topic":"Gramática","subtopic":"Correlação de tempos (período hipotético)","prompt":"Assinale a alternativa que respeita a correlação padrão da condição irreal no passado.","options":["Se ele tivesse treinado mais, teria sido aprovado.","Se ele tivesse treinado mais, será aprovado.","Se ele treinar mais, teria sido aprovado.","Se ele treinasse mais, seria aprovado no ano passado."],"answer":0,"explanation":"Para hipótese irreal no passado: protase no pretérito mais-que-perfeito do subjuntivo (tivesse treinado) e apódose no futuro do pretérito (teria sido aprovado).","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Ajustar tempos verbais em períodos condicionais","commonError":"Misturar tempos simples de futuro/presente com estruturas condicionais do passado.","whyWrong":"B: Mistura passado hipotético com futuro do presente. C: Condição no presente com resultado no passado é incoerente. D: Correlação de tempos incompatível com referência passada explícita.","reviewHint":"Para irreal do passado, use “se + PqP do subj.” na prótase e “futuro do pretérito” na apódose.","contentId":"pt-gramatica"},{"id":"m45-pt-gramatica-15","subject":"Português","topic":"Gramática","subtopic":"Pontuação: vírgula e conectores adversativos","prompt":"Assinale a alternativa pontuada conforme a norma-padrão.","options":["Em 2026 a equipe retornará ao centro; no entanto, o projeto seguirá ativo.","Em 2026, a equipe retornará ao centro; no entanto, o projeto seguirá ativo.","Em 2026 a equipe, retornará ao centro; no entanto, o projeto seguirá ativo.","Em 2026, a equipe retornará ao centro no entanto, o projeto seguirá ativo."],"answer":1,"explanation":"É adequada a vírgula após o adjunto deslocado (facultativa, aqui adotada) e obrigatória a vírgula após “no entanto” quando este liga orações coordenadas separadas por ponto e vírgula: “Em 2026, …; no entanto, …”.","difficulty":"intermediária","sourceBasis":"https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Usar vírgulas com adjuntos deslocados e conectores adversativos","commonError":"Esquecer a vírgula após conectores adversativos intercalados (“porém”, “no entanto”).","whyWrong":"A: Falta vírgula após “no entanto”. C: Vírgula indevida separando sujeito de predicado. D: Ausência do ponto e vírgula ou conjunção sem a devida pausa antes.","reviewHint":"Após conectores adversativos em posição medial/inicial, isole-os com vírgula; evite separar sujeito de predicado sem motivo.","contentId":"pt-gramatica"},{"id":"m45-pt-leitura-01","subject":"Português","topic":"Interpretação","subtopic":"tema e tese","prompt":"Em um artigo de opinião hipotético, o autor considera a adoção de jornadas de seis horas. Para ele, em vez de controlar o tempo de permanência, as empresas deveriam avaliar entregas e bem-estar, pois isso favoreceria equipes resilientes. De acordo com o texto, qual tese é defendida?","options":["Reduzir o expediente parece arriscado e deve ser evitado.","Absenteísmo é o único indicador realmente relevante.","Medir entregas e bem-estar é mais eficaz do que controlar horas.","Toda empresa que adota seis horas se torna mais lucrativa."],"answer":2,"explanation":"O autor defende que a avaliação do trabalho deve priorizar entregas e bem-estar, e não apenas o tempo de permanência. A referência a equipes resilientes apresenta a justificativa da proposta. As demais alternativas acrescentam proibição, exclusividade ou garantia de lucro que não aparecem no texto.","difficulty":"avançada","sourceBasis":"https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA, conceitos adaptados) + https://www.fab.mil.br/cabine/concursos/IE%20EA%20CFS%201%202027_11_02_2026.pdf (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA, conceitos adaptados) + https://www.fab.mil.br/cabine/concursos/IE%20EA%20CFS%201%202027_11_02_2026.pdf (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"identificar tese a partir de indícios e conclusão do parágrafo","commonError":"Confundir o tema (jornadas de trabalho) com a tese (como medir desempenho).","whyWrong":"0 confunde a observação inicial com a posição final do texto; 1 exagera um dado parcial e transforma-o em tese, o que não ocorre; 3 faz generalização absoluta não afirmada pelo autor.","reviewHint":"Localize verbos deônticos ou recomendativos (deveriam, é isso que) e veja que afirmação o autor quer que se adote.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-02","subject":"Português","topic":"Interpretação","subtopic":"inferência","prompt":"A livraria abriu às 9h com fila. Às 15h, as prateleiras dedicadas a um único autor estavam praticamente vazias; os funcionários registraram três reposições ao longo do dia, e, ainda assim, clientes saíram sem o livro. A partir do texto, infere-se que:","options":["A procura por ao menos um título do autor estava muito elevada.","a livraria reduziu o estoque por contenção de custos.","o autor compareceu a uma sessão de autógrafos.","a loja vendeu menos do que o esperado."],"answer":0,"explanation":"A fila, as reposições repetidas e a falta do livro apesar das reposições sustentam a inferência de procura elevada. O texto não informa corte de estoque, sessão de autógrafos nem vendas abaixo do esperado, e tampouco prova que se tratava de um lançamento.","difficulty":"intermediária","sourceBasis":"https://open.umn.edu/opentextbooks/textbooks/portugues-para-principiantes (CC BY-NC-SA, leitura e inferência, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://open.umn.edu/opentextbooks/textbooks/portugues-para-principiantes (CC BY-NC-SA, leitura e inferência, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"inferência lógica a partir de evidências textuais","commonError":"Confundir correlação de fatos narrados com causas externas não citadas.","whyWrong":"1 atribui causa não mencionada; 2 introduz evento sem evidência; 3 contradiz o relato de procura intensa e reposição.","reviewHint":"Liste os fatos explícitos e pergunte qual explicação os acomoda todos sem adicionar suposições externas.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-03","subject":"Português","topic":"Interpretação","subtopic":"finalidade comunicativa","prompt":"Comunicado do condomínio: Vazamentos recentes elevaram a conta de água. Fechem bem as torneiras, avisem a portaria sobre gotejamentos e evitem lavar garagens até a conclusão dos reparos. Qual é a finalidade predominante do texto?","options":["Advertir sobre punições aos moradores.","Promover os serviços da administração.","Explicar tecnicamente os reparos a serem feitos.","Orientar moradores para reduzir o consumo temporariamente."],"answer":3,"explanation":"O texto instrui condutas específicas e temporárias para enfrentar um problema (conta alta por vazamentos), portanto sua finalidade é orientar moradores para reduzir consumo até o fim dos reparos.","difficulty":"intermediária","sourceBasis":"https://educamidia.org.br/wp-content/uploads/2023/06/ATIVIDADES-Leitura-visual-II-autoria-e-edic%CC%A7a%CC%83o-1.pdf (CC BY 4.0, finalidade e propósito, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://educamidia.org.br/wp-content/uploads/2023/06/ATIVIDADES-Leitura-visual-II-autoria-e-edic%CC%A7a%CC%83o-1.pdf (CC BY 4.0, finalidade e propósito, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"identificar finalidade e público-alvo de textos funcionais","commonError":"Tomar qualquer comunicado como advertência, sem observar verbos no imperativo orientador.","whyWrong":"0 não há ameaça de punição; 1 não há autovalorização da administração; 2 não se descreve o procedimento técnico, mas o que os moradores devem fazer.","reviewHint":"Observe verbos e estrutura: pedidos e instruções apontam para finalidade orientadora.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-04","subject":"Português","topic":"Interpretação","subtopic":"coesão referencial (pronomes)","prompt":"Pedro avisou a Luiza que o relatório atrasaria. Isso a preocupou, mas ele lhe prometeu entregar uma versão preliminar ainda hoje. No trecho, o pronome \"lhe\" retoma:","options":["o relatório.","Luiza.","Pedro.","a versão preliminar."],"answer":1,"explanation":"Em \"ele lhe prometeu\", o pronome dativo \"lhe\" indica destinatário da promessa. O referente mais plausível e próximo no contexto é Luiza (a quem Pedro falou). \"Relatório\" e \"versão preliminar\" não recebem promessas; \"Pedro\" é o sujeito que promete, não o destinatário.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA, pronomes e coesão, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA, pronomes e coesão, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"resolver referentes pronominais com base em função e proximidade","commonError":"Atribuir \"lhe\" ao termo mais recente sem testar a função sintática de destinatário.","whyWrong":"0 e 4 violam a função de dativo (pessoa/coisa animada alvo da promessa); 2 troca papéis sintáticos, fazendo do sujeito o destinatário.","reviewHint":"Substitua \"lhe\" por \"a + possível referente\" e verifique a naturalidade: prometer a Luiza funciona; prometer ao relatório não.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-05","subject":"Português","topic":"Interpretação","subtopic":"sentido contextual de palavra","prompt":"Para a equipe médica, o ponto do estudo não era provar uma cura milagrosa, mas mostrar limites do tratamento atual. No contexto, a palavra \"ponto\" significa:","options":["marcador utilizado em costura.","local específico no espaço.","questão central ou objetivo principal.","sinal gráfico de pontuação."],"answer":2,"explanation":"O contexto acadêmico-científico e a estrutura \"o ponto do estudo\" indicam \"questão central/objetivo\". Os demais sentidos são literais de outras áreas e não se encaixam ao enunciado.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/122016/89e37050506a18d67892651721082ce9.pdf (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/122016/89e37050506a18d67892651721082ce9.pdf (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"determinar sentido lexical a partir de co-texto e campo semântico","commonError":"Escolher o primeiro significado lembrado do dicionário, ignorando o campo semântico do texto.","whyWrong":"0 e 4 limitam-se a sentidos técnicos não pertinentes; 1 sugere localização física, incompatível com a ideia de finalidade do estudo.","reviewHint":"Troque a palavra por sinônimos possíveis e veja qual mantém a coerência global do trecho.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-06","subject":"Português","topic":"Interpretação","subtopic":"ironia e efeitos de sentido","prompt":"Fantástico: depois de apenas duas horas na fila do atendimento \"rápido\", descobri que o sistema caiu. Nada como a eficiência de sempre. O efeito de sentido predominante é:","options":["uso de ironia para criticar o mau serviço.","elogio sincero à equipe do atendimento.","constatação neutra de um atraso pontual.","justificativa técnica para a falha do sistema."],"answer":0,"explanation":"Há contraste irônico entre \"fantástico\"/\"rápido\" e a situação descrita (fila longa e sistema fora do ar). Aparentes elogios geram crítica implícita ao serviço.","difficulty":"avançada","sourceBasis":"https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA, efeitos de linguagem, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA, efeitos de linguagem, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"reconhecer ironia pelo contraste entre palavras e situação","commonError":"Tomar os adjetivos ao pé da letra, sem perceber o contraste com o fato narrado.","whyWrong":"1 ignora o uso invertido dos adjetivos; 2 desconsidera a carga avaliativa; 3 não há explicação técnica, apenas sarcasmo.","reviewHint":"Procure marcas de contraste entre adjetivos positivos e resultados negativos; isso costuma sinalizar ironia.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-07","subject":"Português","topic":"Interpretação","subtopic":"relações lógicas (concessão)","prompt":"Embora o edital fosse claro, muitos candidatos deixaram de enviar um anexo; portanto, tiveram a inscrição indeferida. No segmento inicial, a relação introduzida por \"Embora\" é de:","options":["causa e efeito.","concessão: um fato que não impede o outro.","condição necessária.","comparação de equivalência."],"answer":1,"explanation":"\"Embora\" marca concessão: reconhece-se um fato (edital claro) que, porém, não impediu outro (erro dos candidatos). Não é causa, condição nem comparação.","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA, conjunções e relações semânticas, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA, conjunções e relações semânticas, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"identificar relações semântico-discursivas marcadas por conectores","commonError":"Confundir concessão com causa porque os eventos aparecem próximos.","whyWrong":"0 atribui causalidade inexistente; 3 supõe condição que não há; 4 trata de comparação, o que não ocorre.","reviewHint":"Teste a paráfrase \"apesar de\"; se funcionar, a relação é concessiva.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-08","subject":"Português","topic":"Interpretação","subtopic":"pressuposição","prompt":"O gestor parou de ignorar as reclamações dos clientes. Entre as alternativas, qual informação é pressuposta pela frase, permanecendo verdadeira mesmo se ela for negada?","options":["Os clientes deixaram de reclamar.","O gestor respondeu a todas as reclamações.","O gestor sempre atendeu prontamente antes.","O gestor ignorava as reclamações antes."],"answer":3,"explanation":"O gatilho \"parar de\" pressupõe a ocorrência anterior da ação interrompida. Logo, antes ele ignorava reclamações. As outras proposições não decorrem da estrutura e podem ser falsas.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/122016/89e37050506a18d67892651721082ce9.pdf (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/122016/89e37050506a18d67892651721082ce9.pdf (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"reconhecer pressuposições acionadas por verbos e locuções","commonError":"Confundir conteúdo afirmado com conteúdo pressuposto e tomar inferências causais como garantidas.","whyWrong":"0 extrapola um efeito não mencionado; 1 descreve um resultado não garantido; 2 contradiz a pressuposição ativada por \"parou de\".","reviewHint":"Negue a frase e veja o que permanece verdadeiro; esse resíduo costuma ser a pressuposição.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-09","subject":"Português","topic":"Interpretação","subtopic":"intertextualidade e ponto de vista","prompt":"Texto 1 (slogan): \"Menos embalagem. Mais planeta.\" Texto 2 (post): \"Curioso ver a marca X falar em 'mais planeta' enquanto lança sachês descartáveis individuais.\" Considerando a relação entre os textos, conclui-se que o post:","options":["endossa a campanha da marca ao reforçar a mensagem.","ignora o slogan e trata de outro tema.","contesta a imagem \"verde\" do slogan, apontando contradição.","comprova que a empresa aboliu plásticos em suas linhas."],"answer":2,"explanation":"O post contrapõe o apelo ambiental do slogan a uma prática concreta (sachês descartáveis), sugerindo incoerência. Não há apoio, mudança de tema ou comprovação de eliminação de plásticos.","difficulty":"avançada","sourceBasis":"https://educamidia.org.br/wp-content/uploads/2023/06/ATIVIDADES-Leitura-visual-II-autoria-e-edic%CC%A7a%CC%83o-1.pdf (CC BY 4.0, leitura crítica de propósito e ponto de vista, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://educamidia.org.br/wp-content/uploads/2023/06/ATIVIDADES-Leitura-visual-II-autoria-e-edic%CC%A7a%CC%83o-1.pdf (CC BY 4.0, leitura crítica de propósito e ponto de vista, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"identificar diálogo crítico entre textos e avaliar coerência entre discurso e prática","commonError":"Tomar slogans ao pé da letra sem confrontá-los com evidências contextuais.","whyWrong":"0 interpreta como apoio quando há crítica; 1 desconsidera a referência direta ao slogan; 3 atribui um fato não mencionado.","reviewHint":"Verifique expressões que marcam contraste entre o dito (slogan) e o feito (exemplo concreto).","contentId":"pt-leitura"},{"id":"m45-pt-leitura-10","subject":"Português","topic":"Interpretação","subtopic":"opinião x fato","prompt":"Em uma notícia hipotética, lê-se: “Segundo dados da prefeitura, os acidentes caíram 12% no último ano. Mesmo assim, é preocupante que metade deles envolva motociclistas, alertam especialistas.” Nesse trecho, qual enunciado expressa opinião?","options":["é preocupante que metade deles envolva motociclistas","os acidentes caíram 12% no último ano","metade deles envolve motociclistas","segundo dados da prefeitura"],"answer":0,"explanation":"\"É preocupante\" é avaliação subjetiva; as demais expressões reportam dados ou a fonte dos dados, compondo enunciados factuais na moldura da reportagem.","difficulty":"intermediária","sourceBasis":"https://pt.khanacademy.org/humanities/portugues-6-ano (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.khanacademy.org/humanities/portugues-6-ano (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"distinguir julgamento de valor de informação factual","commonError":"Confundir avaliação do risco com o próprio dado estatístico.","whyWrong":"1 e 3 são informações quantificáveis; 4 introduz a fonte, não uma opinião.","reviewHint":"Procure adjetivos e expressões avaliativas; geralmente marcam opinião do enunciador.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-11","subject":"Português","topic":"Interpretação","subtopic":"tema central","prompt":"Desliguei as notificações por uma semana. Sem banners piscando, terminei relatórios mais cedo e voltei a ler no ônibus. O mundo não acabou; meus amigos continuaram lá, e eu, menos ansioso. O tema central do texto é:","options":["benefícios do transporte público para leitores.","impactos das notificações digitais sobre foco e bem-estar.","amizade verdadeira resiste ao tempo e à distância.","vantagens de concluir relatórios mais cedo no trabalho."],"answer":1,"explanation":"Todos os exemplos giram em torno dos efeitos de desligar notificações: mais foco, leitura retomada, menos ansiedade. Não se trata de transporte, amizade ou produtividade isoladamente.","difficulty":"intermediária","sourceBasis":"https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA, leitura como produção de sentidos, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA, leitura como produção de sentidos, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"identificar a ideia nuclear que organiza os exemplos","commonError":"Confundir exemplos do texto com seu foco temático mais amplo.","whyWrong":"0 e 3 captam efeitos pontuais, não o foco; 2 desloca o assunto para relações pessoais, tangencial na argumentação.","reviewHint":"Resuma cada frase em uma palavra e veja qual fio comum as conecta.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-12","subject":"Português","topic":"Interpretação","subtopic":"ambiguidade e desambiguação por contexto","prompt":"Depois de alguns minutos ajustando o tripé, vi o cometa com o telescópio. A criança ao meu lado aplaudiu. Segundo o contexto, quem usa o telescópio?","options":["A criança, pois aplaudiu depois.","Um astrônomo profissional, porque havia tripé.","Qualquer pessoa presente, já que todos compartilharam o equipamento.","O narrador, que ajustou o tripé antes de ver o cometa."],"answer":3,"explanation":"O contexto resolve a ambiguidade estrutural: quem ajustou o tripé e, em seguida, viu o cometa foi o narrador, logo ele é quem usou o telescópio. Não há menção a profissional, compartilhamento geral ou uso pela criança.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/122016/89e37050506a18d67892651721082ce9.pdf (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/122016/89e37050506a18d67892651721082ce9.pdf (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"desfazer ambiguidades valendo-se de pistas coesivas e sequenciais","commonError":"Aderir à leitura mais imediata da preposição \"com\" sem considerar pistas de coesão temporal e agentes mencionados.","whyWrong":"0 infere uso pelo aplauso, que indica reação, não operação; 1 cria personagem não citado; 2 generaliza sem base textual.","reviewHint":"Reconstrua a sequência de ações e atribua-as ao mesmo sujeito quando o texto assim o sugere.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-13","subject":"Português","topic":"Interpretação","subtopic":"leitura de dados e inferência cautelosa","prompt":"Descrição fictícia: em 2023 e 2024, um gráfico de barras mostra o tempo médio de resposta do suporte da empresa A caindo de 48 para 24 horas; no mesmo período, a satisfação dos clientes (0 a 10) sobe de 6,8 para 8,1. A partir dessa descrição, infere-se corretamente que:","options":["houve correlação entre a redução do tempo de resposta e o aumento da satisfação.","a empresa reduziu a equipe do suporte no período.","a satisfação só aumentou devido a treinamento dos atendentes.","os clientes passaram a abrir menos chamados em 2024."],"answer":0,"explanation":"Os dois indicadores variaram em direções compatíveis (menos tempo, mais satisfação), o que permite afirmar correlação observada na série apresentada. As demais hipóteses explicativas (equipe menor, treinamento, menos chamados) não constam da descrição.","difficulty":"avançada","sourceBasis":"https://educamidia.org.br/wp-content/uploads/2023/06/ATIVIDADES-Leitura-visual-II-autoria-e-edic%CC%A7a%CC%83o-1.pdf (CC BY 4.0, leitura de evidências e cautela interpretativa, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://educamidia.org.br/wp-content/uploads/2023/06/ATIVIDADES-Leitura-visual-II-autoria-e-edic%CC%A7a%CC%83o-1.pdf (CC BY 4.0, leitura de evidências e cautela interpretativa, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"inferir com base em dados evitando extrapolações causais","commonError":"Confundir correlação observada com causalidade e inventar causas não sustentadas pelo dado.","whyWrong":"1, 2 e 3 atribuem causas específicas sem evidência; 3 supõe mudança de volume de chamados não mencionada.","reviewHint":"Pergunte-se: o que o dado mostra diretamente? Evite explicar o porquê sem evidência adicional.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-14","subject":"Português","topic":"Interpretação","subtopic":"modalização e grau de certeza","prompt":"Os atrasos devem estar ligados à mudança de fornecedor; talvez ajustes no cronograma minimizem o impacto, mas é preciso avaliar. No trecho, qual expressão marca hipótese, não certeza?","options":["é preciso avaliar","devem estar ligados","talvez ajustes no cronograma minimizem o impacto","mudança de fornecedor"],"answer":2,"explanation":"\"Talvez\" é marcador explícito de possibilidade/hipótese. \"Devem estar\" também indica probabilidade, mas com maior compromisso do enunciador; \"é preciso avaliar\" expressa necessidade; \"mudança de fornecedor\" é conteúdo referencial.","difficulty":"avançada","sourceBasis":"https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA, argumentação e modalização, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA, argumentação e modalização, conceitos adaptados); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"reconhecer marcas linguísticas de hipótese e avaliação","commonError":"Tomar expressões de probabilidade como afirmações categóricas.","whyWrong":"0 trata de obrigação, não hipótese; 1 marca probabilidade mais forte, confundida com certeza por alguns; 3 não é modalizador.","reviewHint":"Procure advérbios como \"talvez\" e locuções que atenuam o compromisso com a verdade da proposição.","contentId":"pt-leitura"},{"id":"m45-pt-leitura-15","subject":"Português","topic":"Interpretação","subtopic":"estratégia argumentativa (refutação)","prompt":"Em um cenário hipotético de uma empresa, afirma-se que “trabalhar remotamente derruba a colaboração”. Contudo, em três projetos nos últimos seis meses, equipes híbridas entregaram antes do prazo; em dois deles, as reuniões assíncronas reduziram retrabalho em 30%, segundo relatórios internos do próprio cenário. Portanto, não é o modelo remoto em si o problema, mas a falta de processos. Na refutação apresentada, predomina a estratégia de:","options":["apelo à autoridade externa para validar o ponto.","uso de dados e exemplos concretos para rebater a generalização.","ataque pessoal aos defensores do argumento inicial.","redefinição do termo \"colaboração\" para torná-lo inútil."],"answer":1,"explanation":"O autor contrapõe a generalização com evidências empíricas específicas (prazos cumpridos e redução de retrabalho), construindo uma refutação baseada em dados. Não há autoridade externa, ad hominem ou redefinição de termos.","difficulty":"intermediária","sourceBasis":"https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA, argumentação — exemplos e contraexemplos, conceitos adaptados) + https://www.fab.mil.br/cabine/concursos/IE%20EA%20CFS%201%202027_11_02_2026.pdf (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA, argumentação — exemplos e contraexemplos, conceitos adaptados) + https://www.fab.mil.br/cabine/concursos/IE%20EA%20CFS%201%202027_11_02_2026.pdf (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"reconhecer estratégias de refutação por evidência e contraexemplo","commonError":"Confundir contraexemplo fundamentado com opinião isolada ou ataque pessoal.","whyWrong":"0 não há citação de especialista externo; 2 desvia o foco do argumento para pessoas; 3 não se observa redefinição de conceito, e sim contestação com dados.","reviewHint":"Verifique se a resposta apresenta fatos que contradizem diretamente a generalização inicial.","contentId":"pt-leitura"},{"id":"m45-pt-ortografia-01","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"acentuação — hiato com i/u tônicos (regra e exceção)","prompt":"Assinale a alternativa em que todas as palavras estão corretamente acentuadas segundo a regra do hiato (i/u tônicos) vigente no Acordo Ortográfico.","options":["saída, Piauí, balaústre, feiúra","saída, Piauí, balaustre, feiura","saída, Piauí, balaústre, feiura","saída, Piaui, balaústre, feiura"],"answer":2,"explanation":"Acentuam-se i e u tônicos em hiato quando aparecem sozinhos na sílaba ou seguidos de s, não precedidos de ditongo e não formando dígrafo com nh: saída (sa-í-da), Piauí (Pi-au-í) e balaústre (ba-la-ús-tre) recebem acento. Já feiura não se acentua, pois o i tônico vem após ditongo (fei-u-ra), caso em que o acento é proibido. Assim, apenas a alternativa C está integralmente correta.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (ortografia e acentuação — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (ortografia e acentuação — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Aplicar a regra dos hiatos i/u com suas exceções pós-AO.","commonError":"Acentuar feiura por generalização da regra do hiato, esquecendo a exceção quando i/u tônicos são precedidos de ditongo.","whyWrong":"A: erra feiúra (i após ditongo não acentua). B: falta acento em balaústre. D: falta acento em Piauí.","reviewHint":"Revise: i/u tônicos em hiato só levam acento se não vierem após ditongo e não estiverem diante de nh; podem estar sozinhos ou seguidos de s.","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-02","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"hífen — prefixos (anti-, micro-, e duplicação de r)","prompt":"Reescreva os compostos com hífen quando necessário: \"O creme antirrugas foi aquecido no micro-ondas, e o remédio antiinflamatório estava vencido.\" Assinale a forma correta segundo o Acordo Ortográfico.","options":["O creme antirrugas foi aquecido no micro-ondas, e o remédio anti-inflamatório estava vencido.","O creme anti-rugas foi aquecido no microondas, e o remédio anti-inflamatório estava vencido.","O creme antirrugas foi aquecido no micro ondas, e o remédio antiinflamatório estava vencido.","O creme anti-rugas foi aquecido no micro-ondas, e o remédio antiinflamatório estava vencido."],"answer":0,"explanation":"1) anti + palavra iniciada por r: não há hífen; duplica-se o r: antirrugas. 2) micro + palavra iniciada pela mesma vogal (o): usa-se hífen: micro-ondas. 3) anti + palavra iniciada pela mesma vogal (i): usa-se hífen: anti-inflamatório. A alternativa A aplica todas as três regras corretamente.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (hífen no pós-AO — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (hífen no pós-AO — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Reconhecer padrões do hífen com prefixos em contexto real.","commonError":"Inserir hífen antes de r após prefixo anti- ou esquecer o hífen quando as vogais iguais se encontram (anti-inflamatório, micro-ondas).","whyWrong":"B: usa anti-rugas (indevido) e microondas (falta hífen). C: separa micro ondas (indevido) e mantém antiinflamatório sem hífen. D: anti-rugas (indevido) e antiinflamatório sem hífen.","reviewHint":"Memorize: anti-/micro- levam hífen se o segundo elemento começar pela mesma vogal; com r, não há hífen e duplica-se o r (antirracismo).","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-03","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"parônimos — discriminar × descriminar","prompt":"Complete corretamente: \"O parecer concluiu por ___ o réu, por falta de provas, mas não podemos ___ ninguém.\"","options":["discriminar; descriminar","descriminar; discriminar","descriminar; descrever","discriminar; descriminar-se"],"answer":1,"explanation":"Descriminar = inocentar, absolver: \"descriminar o réu\". Discriminar = distinguir/tratar com preconceito: \"não podemos discriminar ninguém\". Logo: \"concluiu por descriminar o réu ... mas não podemos discriminar ninguém\".","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (homônimos e parônimos — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (homônimos e parônimos — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Distinguir parônimos pelo sentido no contexto.","commonError":"Achar que \"descriminar\" é apenas variante de \"discriminar\" por semelhança gráfica.","whyWrong":"A e D: trocam os sentidos; discriminar o réu não expressa absolvição. C: \"descrever\" não é sinônimo, muda o sentido.","reviewHint":"Associe: descriminar ~ \"tirar o crime\" (inocentar); discriminar ~ tratar diferente (preconceito) ou listar/distinguir.","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-04","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"locuções — acerca de × a cerca de × há cerca de × cerca de","prompt":"Complete: \"Falamos ___ políticas públicas ___ dois anos; a tenda ficou ___ 500 metros da praça.\"","options":["a cerca de; há cerca de; a cerca de","acerca de; a cerca de; a cerca de","há cerca de; acerca de; a cerca de","acerca de; há cerca de; a cerca de"],"answer":3,"explanation":"Acerca de = sobre (assunto). Há cerca de = tempo decorrido (verbo haver impessoal). A cerca de = distância aproximada e relação espacial. Assim: \"Falamos acerca de... há cerca de dois anos; ... a tenda ficou a cerca de 500 metros...\".","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (dúvidas frequentes de ortografia — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (dúvidas frequentes de ortografia — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Empregar corretamente locuções parônimas em contextos distintos.","commonError":"Trocar \"há\" por \"a\" em indicação de tempo passado e usar \"a cerca de\" para tema/assunto.","whyWrong":"A: começa com a cerca de (distância) para assunto. B: usa a cerca de para tempo (deveria ser há cerca de). C: inverte acerca de e há cerca de na 1ª e 2ª lacunas.","reviewHint":"Regra prática: sobre = acerca de; tempo passado = há cerca de; distância = a cerca de; aproximação sem distância explícita = cerca de.","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-05","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"acentuação — ditongos abertos em paroxítonas (AO 1990)","prompt":"Assinale a alternativa em que todas as palavras estão grafadas conforme o Acordo Ortográfico (ditongos abertos em paroxítonas).","options":["ideia, assembleia, jiboia","idéia, assembleia, jibóia","ideia, assembléia, jiboia","idéia, platéia, jiboia"],"answer":0,"explanation":"O AO 1990 aboliu o acento em paroxítonas com ditongos abertos -ei e -oi: ideia, assembleia, jiboia. As grafias com acento (idéia, assembléia, jibóia, platéia) são anteriores e não valem na norma atual.","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (acentuação — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (acentuação — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Atualizar a acentuação de ditongos abertos após o AO.","commonError":"Aplicar regra antiga e acentuar paroxítonas com -éi/-ói.","whyWrong":"B, C e D: mantêm acentos abolidos em ditongos abertos de paroxítonas.","reviewHint":"Memorize o padrão: paroxítonas em -ei/-oi perderam acento (ideia, jiboia, assembleia). Oxítonas como herói mantêm acento.","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-06","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"pontuação expressiva — travessão como inciso enfático","prompt":"Leia: \"Ele chegou — finalmente — e nada explicou.\" O emprego dos travessões produz qual efeito principal no período?","options":["Introduz fala direta do narrador, marcando citação literal.","Marca enumeração de eventos simultâneos, com pausa breve.","Isola comentário incidental com ênfase e pausa expressiva.","Indica elipse do verbo principal, produzindo suspensão."],"answer":2,"explanation":"Os travessões isolam um comentário intercalado (finalmente), com pausa mais enfática que a das vírgulas, destacando o incômodo/ênfase da intervenção. Não há citação, enumeração nem elipse verbal.","difficulty":"intermediária","sourceBasis":"https://educamidia.org.br/wp-content/uploads/2023/06/ATIVIDADES-Leitura-visual-II-autoria-e-edic%CC%A7a%CC%83o-1.pdf (efeitos de escolhas expressivas — CC BY 4.0); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://educamidia.org.br/wp-content/uploads/2023/06/ATIVIDADES-Leitura-visual-II-autoria-e-edic%CC%A7a%CC%83o-1.pdf (efeitos de escolhas expressivas — CC BY 4.0); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Relacionar sinal de pontuação ao efeito discursivo produzido.","commonError":"Confundir travessão de inciso com sinal de diálogo ou com reticências.","whyWrong":"A: não há citação. B: não é enumeração. D: não há termo elidido; o verbo está presente.","reviewHint":"Compare vírgulas x travessões em incisos: travessão destaca e enfatiza a intervenção.","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-07","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"figuras de linguagem — personificação (prosopopeia)","prompt":"No enunciado \"O silêncio da noite me respondeu\", a figura de linguagem predominante é e produz qual efeito?","options":["Metáfora; intensifica uma comparação implícita sem animar objetos.","Personificação (prosopopeia); atribui ação humana a ente inanimado.","Eufemismo; suaviza a ideia para atenuar o impacto.","Hipérbole; exagera um fato para causar surpresa."],"answer":1,"explanation":"Há atribuição de ação humana (responder) ao silêncio (ente inanimado): personificação, também chamada prosopopeia, o que humaniza o cenário e intensifica a expressividade.","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (semântica e estilística — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (semântica e estilística — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Identificar a figura pelo traço semântico central no contexto.","commonError":"Chamar qualquer expressão figurada de metáfora sem observar o traço humano atribuído a coisas.","whyWrong":"A: não é apenas comparação implícita. C: não há abrandamento de conteúdo. D: não há exagero numérico/qualitativo.","reviewHint":"Procure ações tipicamente humanas aplicadas a objetos/abstratos: indício claro de personificação.","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-08","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"pontuação — vírgula com adjuntos adverbiais e inciso intercalado","prompt":"Assinale a opção com pontuação adequada para destacar um inciso sem alterar a coesão:","options":["Naquela manhã de inverno sem pressa partimos.","Naquela manhã de inverno sem pressa, partimos.","Naquela manhã, de inverno, sem pressa, partimos.","Naquela manhã de inverno, sem pressa, partimos."],"answer":3,"explanation":"O adjunto adverbial inicial (Naquela manhã de inverno) pode vir sem vírgula por ser curto, mas o inciso intercalado (sem pressa) deve ser isolado por vírgulas. A forma D mantém fluência e destaca o inciso corretamente.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (pontuação — CC BY-SA); https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (pontuação — CC BY-SA); https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf (calibração apenas); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Ajustar vírgulas para incisos adverbiais sem quebrar sintagmas internos.","commonError":"Sair pontuando todos os adjuntos iniciais ou suprimir vírgulas de incisos intercalados.","whyWrong":"A: ausência de vírgulas apaga o inciso. B: falta vírgula antes do inciso, quebrando a simetria. C: vírgulas indevidas em \"de inverno\", separando núcleo de seu complemento.","reviewHint":"Não quebre núcleo + complemento (manhã de inverno); isole apenas o inciso intercalado (sem pressa).","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-09","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"ortografia e morfossintaxe — por que/porque/por quê/porquê","prompt":"Escolha a sequência correta: \"___ — ele perguntou. ___ não encontrei o documento; o ___ ainda é desconhecido. Você sabe ___ sumiu?\"","options":["Por quê? Porque; o porquê; por que","Por que? Porque; o porquê; por quê","Por quê? Por que; o porquê; porque","Por que? Porque; por quê; por que"],"answer":0,"explanation":"Por quê? (interrogativo no fim); Porque (conjunção explicativa); o porquê (substantivo com artigo); por que (interrogativo em pergunta indireta). Logo: \"Por quê? Porque...; o porquê...; por que...\".","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (dúvidas frequentes: por que/porque — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (dúvidas frequentes: por que/porque — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Diferenciar as quatro grafias conforme função sintática.","commonError":"Usar uma única forma (porque) em todos os contextos ou acentuar por quê fora de final de pergunta.","whyWrong":"B: último termo interrogativo no fim pede por quê, não na 4ª lacuna. C: troca conjunção explicativa por por que. D: usa por quê sem artigo na posição de substantivo.","reviewHint":"Teste: substitua por \"pelo qual\" (por que), use por quê só no fim, porque como explicação e o porquê como substantivo.","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-10","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"acentos diferenciais — pôde × pode; pôr × por","prompt":"Assinale a alternativa cuja acentuação diferencial está de acordo com a norma vigente.","options":["Ele pôde sair ontem, mas hoje não pôde.","É preciso pôr os livros no lugar, e ela pára na esquina.","Ele pôde sair ontem, mas hoje não pode. É preciso pôr os livros no lugar.","Ele pode sair ontem, mas hoje não pôde. É preciso por os livros no lugar."],"answer":2,"explanation":"Mantêm-se: pôde (pretérito) × pode (presente) e pôr (verbo) × por (preposição). A opção C aplica as duas distinções corretamente. O acento em pára foi abolido.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (acentos diferenciais — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (acentos diferenciais — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Aplicar os acentos diferenciais remanescentes do AO.","commonError":"Manter o acento de pára ou não distinguir pôde/pode.","whyWrong":"A: repete pôde nas duas formas; a segunda deveria ser pode. B: usa pára (acento abolido). D: troca tempos em pode/pôde e escreve por (preposição) no lugar do verbo pôr.","reviewHint":"Decore os poucos casos mantidos: pôde/pode e pôr/por (pára foi abolido).","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-11","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"ortografia — emprego de x/ch/ss/ç","prompt":"Assinale a alternativa em que todas as palavras estão ortograficamente corretas.","options":["enxergar, exessão, mecher","enxergar, exceção, mexer","enchergar, excessão, mexer","enxergar, exceção, mexêr"],"answer":1,"explanation":"Formas corretas: enxergar (com x), exceção (com ç e ção) e mexer (sempre com x). As demais opções trazem trocas comuns indevidas: ss/ç, ch/x e acento inexistente.","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (dúvidas ortográficas — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (dúvidas ortográficas — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Dominar grafias convencionais de casos frequentes com x/ch/ç/ss.","commonError":"Grafar mexer com ch e exceção com ss por analogia.","whyWrong":"A: \"exessão\" e \"mecher\" estão incorretas. C: \"enchergar\" e \"excessão\" incorretas. D: \"mexêr\" nunca leva acento.","reviewHint":"Mexer e enxergar sempre com x; exceção tem ç + ão: exceção.","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-12","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"pontuação — uso de etc.","prompt":"Quanto ao emprego de etc., assinale a alternativa correta e econômica.","options":["Leve água, frutas, protetor solar, etc.","Leve água, frutas e etc.","Leve água, frutas, protetor solar etc...","Leve água, frutas, protetor solar etc."],"answer":3,"explanation":"A forma recomendada é listar os itens e encerrar com etc., sem vírgula antes nem reticências: \"... protetor solar etc.\" Usar e etc. é redundante, a vírgula antes de etc. é dispensável e etc... soma sinais com o mesmo valor.","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (pontuação — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (pontuação — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Empregar etc. com pontuação adequada em enumerações.","commonError":"Colocar vírgula antes de etc. e combinar etc. com reticências.","whyWrong":"A: vírgula imediatamente antes de etc. é desnecessária. B: e etc. é redundante. C: reticências com etc. duplicam ideia de continuidade.","reviewHint":"Regra prática: ... item, item, item etc. (sem e etc., sem vírgula antes, sem reticências).","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-13","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"figuras de linguagem — aliteração (efeito sonoro)","prompt":"No trecho \"Ventos varrem vales: vãs vozes vazias\", identifique a figura e o efeito produzido.","options":["Anáfora; repetição de palavras no início de versos/orações para coesão.","Aliteração; repetição de consoantes, criando efeito de sonoridade e ritmo.","Onomatopeia; imitação direta de sons naturais por vocábulos.","Hipérbato; inversão sintática para deslocar termos por ênfase."],"answer":2,"explanation":"Há repetição da consoante inicial v, produzindo musicalidade e reforçando semanticamente a ideia do vento: aliteração. Não há repetição inicial de termos (anáfora), nem imitação literal de ruídos (onomatopeia), nem inversão sintática marcada (hipérbato).","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (semântica e estilística — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (semântica e estilística — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Reconhecer aliteração e associar o padrão sonoro ao efeito expressivo.","commonError":"Confundir aliteração com onomatopeia por ambos lidarem com som.","whyWrong":"A: não há repetição de palavras no início. C: não é som imitativo específico como tic-tac. D: a ordem não está forçosamente invertida para efeito sintático.","reviewHint":"Procure repetição de consoantes iniciais; se o foco é o timbre repetido, tende a ser aliteração.","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-14","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"hífen — ex-, vice-, pré- (prefixos terminados em vogal)","prompt":"Assinale a alternativa em que o uso do hífen está correto.","options":["ex marido, vice-presidente, pré-natal","ex-aluno, vice-presidente, pré-natal","ex-aluno, vice presidente, prénatal","exaluno, vice-presidente, pré natal"],"answer":1,"explanation":"Com os prefixos ex-, vice- e pré- usa-se o hífen: ex-aluno, vice-presidente, pré-natal. As demais opções omitem ou inserem indevidamente o hífen, além de erros como prénatal sem hífen.","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (hífen — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (hífen — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Aplicar casos fixos do hífen com certos prefixos.","commonError":"Esquecer que ex- e vice- sempre pedem hífen antes do substantivo seguinte.","whyWrong":"A: falta hífen em ex-marido. C: falta hífen em vice-presidente e em pré-natal. D: falta hífen em ex-aluno e pré-natal.","reviewHint":"Memorize blocos: ex-, vice- e pré- (com valor de anterioridade) exigem hífen.","contentId":"pt-ortografia"},{"id":"m45-pt-ortografia-15","subject":"Português","topic":"Ortografia e recursos expressivos","subtopic":"acentuação verbal — formas tem/têm; vem/vêm","prompt":"Assinale a alternativa com acentuação correta nas formas verbais:","options":["Eles têm razão e vêm de longe, mas ela tem pressa e vem só.","Eles tem razão e vem de longe, mas ela têm pressa e vêm só.","Eles têm razão e vem de longe, mas ela tem pressa e vêm só.","Eles tem razão e vêm de longe, mas ela têm pressa e vem só."],"answer":0,"explanation":"3ª pessoa do plural de ter e vir recebe acento circunflexo: têm, vêm. No singular (ele/ela), as formas são tem e vem, sem acento. A alternativa A registra corretamente a oposição singular/plural nas duas ocorrências.","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (acentuação — verbos ter/vir — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs (acentuação — verbos ter/vir — CC BY-SA); questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Distinguir acentuação gráfica de ter/vir no singular e plural.","commonError":"Acentuar o singular (tem/vem) por analogia com as formas plurais.","whyWrong":"B, C e D: trocam os acentos entre singular e plural, produzindo concordâncias gráficas incorretas.","reviewHint":"Regra: plural (eles) tem acento — têm/vêm; singular (ele) não tem acento — tem/vem.","contentId":"pt-ortografia"},{"id":"m45-pt-regencia-01","subject":"Português","topic":"Regência e crase","subtopic":"regência de “assistir” (ver) + crase obrigatória","prompt":"Complete a lacuna de acordo com a norma-padrão: O público assistiu ___ chegada da equipe a Brasília.","options":["a","à","para a","de"],"answer":1,"explanation":"No sentido de “ver”, o verbo assistir é transitivo indireto e rege a preposição a: assistir a algo. Como o núcleo é feminino com artigo (a chegada), ocorre a fusão da preposição a com o artigo a, formando à (crase): assistiu à chegada.","difficulty":"intermediária","sourceBasis":"Questão autoral; fundamentada em regência e crase conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Questão autoral; fundamentada em regência e crase conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Identificar a preposição regida pelo verbo e reconhecer a crase obrigatória.","commonError":"Confundir assistir (ver) — que pede a — com assistir (prestar auxílio) — que é transitivo direto.","whyWrong":"“a”: falta o artigo feminino e, portanto, a crase; “para a”: troca indevida de preposição, altera a regência; “de”: não é a preposição exigida por assistir (ver).","reviewHint":"Verbo assistir (ver): quem assiste, assiste a alguma coisa; com feminino, use crase.","contentId":"pt-regencia"},{"id":"m45-pt-regencia-02","subject":"Português","topic":"Regência e crase","subtopic":"regência de “preferir”","prompt":"Complete com a preposição exigida por preferir, mantendo a estrutura dada: Prefiro café ___ chá.","options":["a","de","para","com"],"answer":0,"explanation":"A regência de preferir é: preferir X a Y. Logo, Prefiro café a chá. Outras preposições desfiguram a construção regida.","difficulty":"intermediária","sourceBasis":"Referência de calibração: Dicas de Português — Sintaxe (CNJ). https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"Referência de calibração: Dicas de Português — Sintaxe (CNJ). https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Aplicar regência verbal específica em construções comparativas.","commonError":"Inserir “do que” após preferir por influência da fala.","whyWrong":"“de”, “para”, “com”: não são as preposições regidas por preferir nessa construção; criam estrutura não padrão (ex.: “preferir X do que Y” não é recomendada).","reviewHint":"Memorize o esquema: preferir X a Y; evitar “do que” nessa estrutura.","contentId":"pt-regencia"},{"id":"m45-pt-regencia-03","subject":"Português","topic":"Regência e crase","subtopic":"crase em locuções adverbiais femininas","prompt":"Escolha a opção que completa corretamente: O relatório será entregue ___.","options":["a tarde","na tarde","pela tarde","à tarde"],"answer":3,"explanation":"Locuções adverbiais femininas fixas, como à tarde, à noite, à esquerda, pedem crase: preposição a + artigo a. Portanto: será entregue à tarde.","difficulty":"intermediária","sourceBasis":"Referência de calibração: Exercícios sobre crase — UFMG. https://www.letras.ufmg.br/arquivos/gramaticaonline/exercicios/exerciciossobrecrase.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"Referência de calibração: Exercícios sobre crase — UFMG. https://www.letras.ufmg.br/arquivos/gramaticaonline/exercicios/exerciciossobrecrase.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reconhecer locuções adverbiais femininas que exigem crase.","commonError":"Esquecer que locuções femininas cristalizadas normalmente exigem crase.","whyWrong":"“a tarde”: falta o artigo, crase obrigatória; “na tarde”: muda a construção (em + a), pouco natural nesse caso; “pela tarde”: uso coloquial, menos prestigiado na norma escrita formal para essa locução consagrada.","reviewHint":"Locuções adverbiais femininas fixas costumam vir com crase: à tarde, à noite, à vista.","contentId":"pt-regencia"},{"id":"m45-pt-regencia-04","subject":"Português","topic":"Regência e crase","subtopic":"regência nominal: “favorável a” + crase","prompt":"Complete: O parecer é favorável ___ concessão do benefício.","options":["à","a","de","para a"],"answer":3,"explanation":"O adjetivo favorável rege a: favorável a algo. Como “concessão” vem com artigo definido feminino (a concessão), há crase: favorável à concessão.","difficulty":"intermediária","sourceBasis":"Questão autoral; fundamentada em regência nominal (preposições) conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Questão autoral; fundamentada em regência nominal (preposições) conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Aplicar regência nominal e verificar a presença de artigo para crase.","commonError":"Esquecer que muitos adjetivos regem preposição (“favorável a”, “contrário a”).","whyWrong":"“a”: falta o artigo feminino; “de”: regência nominal incorreta; “para a”: troca de preposição, não é a exigida por “favorável”.","reviewHint":"Teste: substitua por um masculino (“favorável ao projeto”); se ocorre artigo, no feminino haverá crase.","contentId":"pt-regencia"},{"id":"m45-pt-regencia-05","subject":"Português","topic":"Regência e crase","subtopic":"regência de “obedecer” + crase no plural","prompt":"Complete: Os recrutas obedeceram ___ ordens do comandante.","options":["a","as","às","para as"],"answer":2,"explanation":"Obedecer é transitivo indireto e rege a: obedecer a algo/alguém. Com “as ordens” (artigo definido), ocorre crase no plural: obedeceram às ordens.","difficulty":"intermediária","sourceBasis":"Questão autoral; fundamentada em regência verbal conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Questão autoral; fundamentada em regência verbal conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Identificar preposição exigida por verbo transitivo indireto e aplicar crase.","commonError":"Trocar a preposição por “para” ou suprimir a crase no plural.","whyWrong":"“a”: falta o artigo (crase obrigatória); “as”: não há preposição exigida pelo verbo; “para as”: preposição inadequada para a regência de “obedecer”.","reviewHint":"Quem obedece, obedece a; havendo artigo feminino/plural, haverá crase: à/às.","contentId":"pt-regencia"},{"id":"m45-pt-regencia-06","subject":"Português","topic":"Regência e crase","subtopic":"regência de “implicar” (acarretar): transitivo direto","prompt":"Complete, no sentido de “acarretar”: O erro implicará ___ cancelamento do voo.","options":["no","ao","o","em"],"answer":2,"explanation":"No sentido de “acarretar”, implicar é transitivo direto: implicar algo. Logo, “implicará o cancelamento”.","difficulty":"avançada","sourceBasis":"Referência de calibração: Dicas de Português — Sintaxe (CNJ). https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"Referência de calibração: Dicas de Português — Sintaxe (CNJ). https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Distinguir sentidos do verbo e respectivas regências.","commonError":"Generalizar “implicar em” para todos os sentidos do verbo.","whyWrong":"“no” (em + o) e “em”: trocam a regência do verbo; “ao” (a + o): também não é a regência nesse sentido. “Implicar em” ocorre no sentido de “envolver-se, incorrer em”.","reviewHint":"Regra prática: implicar (acarretar) = VTD; implicar em (envolver-se) = VTI.","contentId":"pt-regencia"},{"id":"m45-pt-regencia-07","subject":"Português","topic":"Regência e crase","subtopic":"crase com demonstrativos: àquele/àquela/àquilo","prompt":"Complete corretamente: Referi-me ___quela diretriz publicada ontem.","options":["a aquella","àquela","à aquela","aquela"],"answer":1,"explanation":"Referir-se rege a: referir-se a algo. Diante de aquela, há contração da preposição a com o demonstrativo: àquela. A grafia é aglutinada.","difficulty":"avançada","sourceBasis":"Questão autoral; fundamentada em crase com demonstrativos conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Questão autoral; fundamentada em crase com demonstrativos conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Aplicar crase com demonstrativos após verbos que regem a.","commonError":"Esquecer que a preposição a se funde com aquele/aquela/aquilo: àquele, àquela, àquilo.","whyWrong":"“a aquella”: grafia e regência incorretas; “à aquela”: separação indevida (a forma correta é aglutinada); “aquela”: falta a preposição exigida por “referir-se a”.","reviewHint":"Depois de verbos que pedem a + aquela/aquele/aquilo, use àquela/àquele/àquilo (forma aglutinada).","contentId":"pt-regencia"},{"id":"m45-pt-regencia-08","subject":"Português","topic":"Regência e crase","subtopic":"crase com topônimos (nomes de cidade)","prompt":"Assinale a única frase correta quanto ao uso da crase com topônimos.","options":["Voltaremos à Paris em julho.","Voltaremos a Paris em julho.","Regressamos à Lisboa após o curso.","Fomos à Tóquio para o evento."],"answer":1,"explanation":"Nomes de cidade sem artigo não admitem crase com a: vai-se a Paris, a Lisboa, a Tóquio. Assim, “Voltaremos a Paris” é a forma correta entre as opções dadas.","difficulty":"intermediária","sourceBasis":"Referência de calibração: Exercícios sobre crase — UFMG. https://www.letras.ufmg.br/arquivos/gramaticaonline/exercicios/exerciciossobrecrase.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"Referência de calibração: Exercícios sobre crase — UFMG. https://www.letras.ufmg.br/arquivos/gramaticaonline/exercicios/exerciciossobrecrase.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reconhecer quando topônimos exigem ou não artigo e, portanto, crase.","commonError":"Generalizar a crase antes de qualquer nome de lugar.","whyWrong":"“à Paris”, “à Lisboa”, “à Tóquio”: crase indevida, pois esses topônimos, em uso comum, não vêm com artigo. A crase só ocorreria se o topônimo admitisse artigo (“à Bahia”, “ao Rio de Janeiro”) ou se viesse especificado exigindo artigo.","reviewHint":"Teste o artigo: se é natural dizer “a a cidade” (com artigo), haverá crase; se não, use apenas a preposição a.","contentId":"pt-regencia"},{"id":"m45-pt-regencia-09","subject":"Português","topic":"Regência e crase","subtopic":"pronome relativo e regência: “referir-se a” (a que/à qual)","prompt":"Complete: As normas ___ me referi foram atualizadas.","options":["a que","à que","de que","em que"],"answer":0,"explanation":"“Referir-se” rege a: referir-se a algo. Com o relativo “que”, não há artigo para contrair; logo, usa-se a que: “as normas a que me referi…”.","difficulty":"avançada","sourceBasis":"Referência de calibração: Dicas de Português — Sintaxe (CNJ). https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"Referência de calibração: Dicas de Português — Sintaxe (CNJ). https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Selecionar a preposição correta antes de relativo, conforme a regência do verbo da oração relativa.","commonError":"Forçar crase antes de “que” por analogia com “à qual/às quais”.","whyWrong":"“à que”: crase indevida, pois “que” não admite artigo; “de que” e “em que”: trocas de preposição, incompatíveis com a regência de “referir-se a”.","reviewHint":"Com “que”, use só a preposição exigida; com “o qual/a qual”, pode haver artigo e crase (às quais).","contentId":"pt-regencia"},{"id":"m45-pt-regencia-10","subject":"Português","topic":"Regência e crase","subtopic":"locuções conjuntivas: “à medida que” x “na medida em que”","prompt":"Assinale a frase correta segundo a norma-padrão.","options":["À medida que avançávamos, o nevoeiro diminuía.","A medida que avançávamos, o nevoeiro diminuía.","Na medida que avançávamos, o nevoeiro diminuía.","À medida em que avançávamos, o nevoeiro diminuía."],"answer":0,"explanation":"A locução proporcional é à medida que (com crase). Já a causal/explicativa é na medida em que. No período dado, a relação é proporcional, logo: “À medida que…”.","difficulty":"avançada","sourceBasis":"Questão autoral; fundamentada em locuções e crase conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Questão autoral; fundamentada em locuções e crase conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Diferenciar locuções conjuntivas e aplicar crase nas formas fixas.","commonError":"Confundir “à medida que” (proporção) com “na medida em que” (causa/explicação).","whyWrong":"“A medida que”: falta crase; “Na medida que”: falta “em” e indica outra relação; “À medida em que”: mistura indevida de duas locuções diferentes.","reviewHint":"Proporção: à medida que. Causa/razão: na medida em que.","contentId":"pt-regencia"},{"id":"m45-pt-regencia-11","subject":"Português","topic":"Regência e crase","subtopic":"colocação pronominal + regência de “comunicar (algo a alguém)”","prompt":"Respeitando a regência de comunicar (algo a alguém) e a próclise exigida por “não”, complete: O diretor não ___ comunicará o resultado hoje.","options":["o","o lhe","lhe","lhes-o"],"answer":2,"explanation":"Quem comunica, comunica algo a alguém; o pronome adequado para “a ele/ela” é lhe. Como há o advérbio “não”, impõe-se próclise: “não lhe comunicará”.","difficulty":"avançada","sourceBasis":"Questão autoral; fundamentada em colocação pronominal e regência: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Questão autoral; fundamentada em colocação pronominal e regência: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Aplicar regência para selecionar o pronome oblíquo e posicioná-lo corretamente.","commonError":"Usar “o” para retomar complemento indireto ou ignorar a próclise após palavras atrativas como “não”.","whyWrong":"“o”: retoma objeto direto (“o resultado”), não o indireto (a alguém); “o lhe” e “lhes-o”: combinações incorretas na norma-padrão e não resolvem a exigência do objeto indireto com próclise.","reviewHint":"Para complemento indireto (a alguém), use lhe/lhes; com palavra atrativa (não), use próclise.","contentId":"pt-regencia"},{"id":"m45-pt-regencia-12","subject":"Português","topic":"Regência e crase","subtopic":"regência de “assistir” (prestar assistência): transitivo direto","prompt":"No sentido de “prestar assistência”, assinale a frase correta.","options":["A equipe médica assistiu aos feridos a medicação.","A equipe médica assistiu aos feridos no local.","A equipe médica assistiu os feridos no local.","A equipe médica assistiu aos que necessitavam."],"answer":2,"explanation":"No sentido de “prestar assistência”, assistir é transitivo direto: assistir alguém. Logo, “assistiu os feridos”. As formas com “a/os” indicam o sentido de “ver/assistir a”, que não é o pretendido.","difficulty":"avançada","sourceBasis":"Referência de calibração: Dicas de Português — Sintaxe (CNJ). https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"Referência de calibração: Dicas de Português — Sintaxe (CNJ). https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Distinguir a transitividade/regência de verbos polissêmicos conforme o contexto.","commonError":"Levar a preposição a para o sentido de “prestar assistência”, confundindo com “ver”.","whyWrong":"“assistiu aos feridos a medicação.”: estrutura inviável (duplo a e sem objeto direto claro); “assistiu aos feridos no local.” e “assistiu aos que necessitavam.”: preposição indevida para o sentido de “prestar assistência”.","reviewHint":"Assistir = ver → a algo; assistir = dar assistência → VTD (sem preposição).","contentId":"pt-regencia"},{"id":"m45-pt-regencia-13","subject":"Português","topic":"Regência e crase","subtopic":"crase: horas e locuções fixas (“a tempo”)","prompt":"Complete corretamente: A reunião vai de ___ 14h ___ 18h; chegue ___ tempo.","options":["das — às — a","de — à — à","das — as — à","de — as — a"],"answer":0,"explanation":"Entre horas, usa-se: das 14h às 18h (de + as; a + as). A locução a tempo é cristalizada sem crase. Assim: das — às — a.","difficulty":"avançada","sourceBasis":"Questão autoral; fundamentada em crase (horas e locuções) conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Questão autoral; fundamentada em crase (horas e locuções) conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Empregar crase correta em horas e reconhecer locuções fixas sem crase.","commonError":"Aplicar crase indevida em “a tempo” e esquecer a crase obrigatória antes de horas determinadas.","whyWrong":"“de — à — à”: falta artigo no início e sobra crase em “a tempo”; “das — as — à”: falta crase em “às 18h” e sobra em “à tempo”; “de — as — a”: faltam contrações com artigo nas horas.","reviewHint":"Antes de horas certas: às; entre horas: das… às…; a tempo não leva crase.","contentId":"pt-regencia"},{"id":"m45-pt-regencia-14","subject":"Português","topic":"Regência e crase","subtopic":"regência nominal: “alheio a” + crase no plural","prompt":"Complete: Permaneceu alheio ___ discussões internas.","options":["as","a","de","às"],"answer":3,"explanation":"“Alheio” rege a: alheio a algo. Como “discussões” vem com artigo definido (as discussões), há crase no plural: alheio às discussões.","difficulty":"intermediária","sourceBasis":"Referência de calibração: Dicas de Português — Sintaxe (CNJ). https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"Referência de calibração: Dicas de Português — Sintaxe (CNJ). https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf (calibração apenas).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Aplicar regência nominal e verificar necessidade de crase no plural.","commonError":"Confundir “alheio a” com “alheio de”.","whyWrong":"“as”: falta a preposição; “a”: falta o artigo; “de”: regência incorreta para “alheio”.","reviewHint":"Adjetivos como alheio, favorável, contrário costumam exigir a; com feminino/plural, crase.","contentId":"pt-regencia"},{"id":"m45-pt-regencia-15","subject":"Português","topic":"Regência e crase","subtopic":"regência de “visar (ter por objetivo) a” + crase","prompt":"Complete de acordo com a regência: O plano visa ___ redução de custos.","options":["a","à","para a","na"],"answer":1,"explanation":"No sentido de “ter por objetivo”, “visar” rege a: visar a algo. Com nome feminino com artigo (“a redução”), dá-se a crase: visa à redução de custos.","difficulty":"avançada","sourceBasis":"Questão autoral; fundamentada em regência verbal (visar a) conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Questão autoral; fundamentada em regência verbal (visar a) conforme: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Identificar a regência de verbos com mudança de sentido e aplicar crase quando há artigo.","commonError":"Usar “visar em/para” por analogia com outros verbos ou esquecer a crase com nome feminino definido.","whyWrong":"“a”: falta a fusão com o artigo (crase); “para a” e “na”: trocam a regência, criando construções menos formais/indevidas.","reviewHint":"Visar (objetivar) → a algo; se houver artigo feminino, ocorre crase: à.","contentId":"pt-regencia"},{"id":"m45-pt-semantica-01","subject":"Português","topic":"Semântica e léxico","subtopic":"sinonímia em contexto","prompt":"No trecho: \"O acordo firmado é tênue e pode se desfazer com qualquer pressão\", a melhor substituição de \"tênue\" sem alterar o sentido é:","options":["espesso","robusto","frágil","denso"],"answer":2,"explanation":"No contexto, \"tênue\" significa algo pouco resistente, fácil de romper. \"Frágil\" preserva o sentido. \"Espesso\" e \"denso\" relacionam-se a alta concentração/espessura, invertendo a ideia. \"Robusto\" sugere força/solidez, o oposto de frágil.","difficulty":"intermediária","sourceBasis":"Conceitos de sinonímia contextual — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Conceitos de sinonímia contextual — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"substituir vocábulo por sinônimo adequado ao contexto","commonError":"Escolher um sinônimo de dicionário para \"fraco\" que não se aplica a relações abstratas (ex.: densidade física).","whyWrong":"0: \"espesso\" descreve espessura, não fragilidade textual do acordo; 1: \"robusto\" implica força/estabilidade, antônimo contextual; 3: \"denso\" indica grande concentração, não delicadeza/instabilidade.","reviewHint":"Teste a palavra candidata no lugar da original e verifique se o sentido global permanece o mesmo.","contentId":"pt-semantica"},{"id":"m45-pt-semantica-02","subject":"Português","topic":"Semântica e léxico","subtopic":"antonímia contextual","prompt":"Em: \"Foi um discurso franco sobre as falhas da equipe\", o antônimo contextual de \"franco\" é:","options":["evasivo","sincero","aberto","transparente"],"answer":0,"explanation":"\"Franco\" aqui equivale a \"sincero\", \"direto\". O antônimo é \"evasivo\" (foge do ponto, não enfrenta). \"Sincero\", \"aberto\" e \"transparente\" são sinônimos contextuais, não antônimos.","difficulty":"intermediária","sourceBasis":"Conceitos de antônimos contextuais — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Conceitos de antônimos contextuais — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"reconhecer antônimos contextuais em textos","commonError":"Confundir antônimo com sinônimo por associação positiva do traço de sinceridade.","whyWrong":"1,3: reforçam a mesma ideia de franqueza; 2: \"aberto\" mantém o sentido de transparência; só 0 inverte o traço semântico central.","reviewHint":"Identifique o traço semântico central do adjetivo no contexto e procure o item que o negue.","contentId":"pt-semantica"},{"id":"m45-pt-semantica-03","subject":"Português","topic":"Semântica e léxico","subtopic":"polissemia","prompt":"Considere: a) \"Ele fez um ponto no tecido\"; b) \"O time marcou um ponto no fim\"; c) \"Estávamos no ponto do ônibus\". A relação entre os usos de \"ponto\" é:","options":["Homônimos sem relação semântica.","Idêntico significado literal em todos os casos.","Metáforas esporádicas sem vínculo lexical.","Polissemia: um núcleo de \"marca/unidade/local\" especializa-se em contextos distintos."],"answer":3,"explanation":"Há um mesmo lexema cujos sentidos se ramificam: \"marca\" (costura), \"unidade\" (placar) e \"local estabelecido\" (parada). Isso caracteriza polissemia motivada por extensão/metonimização de um núcleo semântico.","difficulty":"avançada","sourceBasis":"Semântica lexical (polissemia) — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Semântica lexical (polissemia) — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"identificar e explicar redes polissêmicas","commonError":"Tomar sentidos estabilizados como se fossem palavras distintas (homônimos), ignorando o vínculo semântico.","whyWrong":"0: não são palavras diferentes sem laço; 1: os sentidos não são idênticos; 2: não são metáforas ocasionais desconectadas, mas sentidos estabilizados no léxico.","reviewHint":"Procure o traço semântico comum que se preserva ao mudar o contexto de uso.","contentId":"pt-semantica"},{"id":"m45-pt-semantica-04","subject":"Português","topic":"Semântica e léxico","subtopic":"denotação e conotação","prompt":"No enunciado \"A cirurgiã tem mãos de ouro\", a expressão \"mãos de ouro\" expressa, predominantemente:","options":["riqueza material","habilidade excepcional","dureza das mãos","uso de luvas douradas"],"answer":1,"explanation":"Trata-se de conotação que atribui à profissional grande habilidade/destreza. Não há referência a riqueza, dureza ou literalidade de luvas douradas.","difficulty":"intermediária","sourceBasis":"Leitura como produção de sentidos — ver: https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Leitura como produção de sentidos — ver: https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"distinguir valores denotativos e conotativos em expressões","commonError":"Ler metáforas de prestígio como se fossem literais.","whyWrong":"0 e 3: leem literalmente o adjetivo \"de ouro\"; 2: \"dureza\" não é ativada pela metáfora; 1 captura o valor figurado de excelência.","reviewHint":"Pergunte-se: que leitura torna o texto coerente sem recorrer ao absurdo literal?","contentId":"pt-semantica"},{"id":"m45-pt-semantica-05","subject":"Português","topic":"Semântica e léxico","subtopic":"ambiguidade estrutural","prompt":"Em \"Marina viu o homem com binóculos\", qual reescrita elimina a ambiguidade e preserva o sentido de que Marina usou o objeto?","options":["\"Marina viu o homem, com binóculos.\"","\"Marina viu, com binóculos, o homem.\"","\"Usando binóculos, Marina viu o homem.\"","\"Marina viu o homem que tinha binóculos.\""],"answer":2,"explanation":"A construção absoluta \"Usando binóculos, Marina viu o homem\" fixa a adjunção no sujeito (Marina). As outras mantêm ou deslocam a leitura para o objeto: a vírgula não desambigua (0 e 1) e a relativa (3) fixa o acessório no homem, mudando o sentido pretendido.","difficulty":"avançada","sourceBasis":"Ambiguidade (calibração apenas): https://canal.cecierj.edu.br/122016/89e37050506a18d67892651721082ce9.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"Ambiguidade (calibração apenas): https://canal.cecierj.edu.br/122016/89e37050506a18d67892651721082ce9.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"diagnosticar e remover ambiguidade estrutural por reescritura","commonError":"Confiar que a vírgula, por si, resolva ambiguidade de adjuntos do SN.","whyWrong":"0 e 1: a posição do adjunto com vírgulas não impede a leitura no SN \"o homem\"; 3: resolve para o outro sentido (o homem portava os binóculos), contrariando o enunciado.","reviewHint":"Para desambiguar, torne o adjunto uma oração adverbial ou troque por relativa quando quiser ligá-lo ao objeto.","contentId":"pt-semantica"},{"id":"m45-pt-semantica-06","subject":"Português","topic":"Semântica e léxico","subtopic":"parônimos","prompt":"Complete com o par adequado: \"O lançamento é ____; faltam poucas horas.\" / \"Trata-se de pesquisador ____ na área.\"","options":["eminente / iminente","iminente / eminente","eminente / eminente","iminente / iminente"],"answer":1,"explanation":"\"Iminente\" = prestes a acontecer; \"eminente\" = destacado/notável. Portanto: \"lançamento é iminente\" e \"pesquisador eminente\".","difficulty":"intermediária","sourceBasis":"Homônimos e parônimos — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Homônimos e parônimos — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"distinguir parônimos pelo sentido","commonError":"Confundir a inicial i/e por semelhança gráfica/fônica.","whyWrong":"0: inverte os sentidos; 2 e 3: repetem a mesma forma, errando uma das acepções.","reviewHint":"Associe i de \"iminente\" a \"imediato\" (proximidade temporal) e e de \"eminente\" a \"excelência\" (notoriedade).","contentId":"pt-semantica"},{"id":"m45-pt-semantica-07","subject":"Português","topic":"Semântica e léxico","subtopic":"metonímia e outros efeitos de sentido","prompt":"Em \"O Brasil chorou com a tragédia\", o recurso semântico predominante é:","options":["Hipérbole: exagero no verbo \"chorou\".","Prosopopeia: o país foi humanizado como sujeito.","Catacrese: nome figurado por ausência de termo próprio.","Metonímia: o país pelos habitantes afetados."],"answer":3,"explanation":"A leitura natural troca o nome do todo (Brasil) pelas pessoas que o compõem — metonímia. A ação de chorar é humana, mas o sujeito de referência já são os habitantes; a personificação não é necessária para interpretar o enunciado.","difficulty":"avançada","sourceBasis":"Semântica e estilística — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Semântica e estilística — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"reconhecer processos metonímicos em enunciados","commonError":"Confundir metonímia (troca de referentes) com personificação (atribuição de traço humano a não humano).","whyWrong":"0: não há intensificação numérica do choro; 1: supõe humanizar o território, mas a operação central é substituição parte/todo; 2: não é uso consolidado por falta de termo, e sim troca de referentes contíguos.","reviewHint":"Verifique se há troca de nomes entre entidades contíguas (autor/obra, parte/todo, lugar/habitantes).","contentId":"pt-semantica"},{"id":"m45-pt-semantica-08","subject":"Português","topic":"Semântica e léxico","subtopic":"homófonos/homógrafos (parônimos usuais)","prompt":"Complete corretamente: \"O ____ de 2022 aferiu a população\" / \"Ele tem muito ____ de responsabilidade\".","options":["censo / senso","senso / censo","censo / censo","senso / senso"],"answer":0,"explanation":"\"Censo\" (com c) é pesquisa demográfica oficial; \"senso\" (com s) é juízo/entendimento. A sequência correta é censo / senso.","difficulty":"intermediária","sourceBasis":"Semântica e estilística (parônimos) — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Semântica e estilística (parônimos) — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"aplicar distinções de parônimos frequentes em contexto","commonError":"Trocar censo/senso por semelhança sonora.","whyWrong":"1: inverte os termos; 2 e 3: repetem um só termo, errando uma das lacunas.","reviewHint":"Relacione censo a \"cadastrar\" (ambos com c) e senso a \"sentido\" (ambos com s).","contentId":"pt-semantica"},{"id":"m45-pt-semantica-09","subject":"Português","topic":"Semântica e léxico","subtopic":"hiperonímia/hiponímia e especificidade lexical","prompt":"No período: \"O jardim abriga diversas ____ — ipê, jacarandá e mangueira — que florescem no outono\", o termo que melhor preenche a lacuna, preservando a especificidade lexical, é:","options":["plantas","vegetais","árvores","flores"],"answer":2,"explanation":"Os itens listados são hipônimos de \"árvores\". \"Plantas/vegetais\" são hiperônimos excessivamente amplos; \"flores\" não corresponde ontologicamente aos itens (não são espécies de flor).","difficulty":"avançada","sourceBasis":"Semântica lexical (hiponímia/hiperonímia) — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Semântica lexical (hiponímia/hiperonímia) — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"selecionar hiperônimos adequados ao conjunto dado","commonError":"Escolher hiperônimo amplo demais e diluir o traço comum específico do conjunto.","whyWrong":"0 e 1: hiperônimos muito genéricos, perdem precisão do conjunto; 3: categoria diferente da lista dada.","reviewHint":"Compare a classe mais específica que inclui todos os itens sem incluir muitos outros irrelevantes ao contexto.","contentId":"pt-semantica"},{"id":"m45-pt-semantica-10","subject":"Português","topic":"Semântica e léxico","subtopic":"pressuposto e subentendido","prompt":"A frase \"Joana parou de fumar\" pressupõe que Joana fumava antes. Qual reescrita mantém esse mesmo pressuposto?","options":["Joana tentou parar de fumar.","Joana não fuma mais.","Joana nunca fumou.","Joana decidiu não fumar."],"answer":1,"explanation":"\"Joana não fuma mais\" preserva o pressuposto de hábito anterior. \"Tentou parar\" não implica sucesso; \"nunca fumou\" contradiz; \"decidiu não fumar\" exprime decisão presente sem indicar hábito pretérito.","difficulty":"avançada","sourceBasis":"Pressuposição e sentido (calibração apenas): https://canal.cecierj.edu.br/122016/89e37050506a18d67892651721082ce9.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"Pressuposição e sentido (calibração apenas): https://canal.cecierj.edu.br/122016/89e37050506a18d67892651721082ce9.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"identificar e preservar pressupostos em paráfrases","commonError":"Confundir intenção/decisão com estado factual pressuposto.","whyWrong":"0: não há implicatura de que fumava regularmente nem de que parou; 2: nega o pressuposto; 3: escolha atual, sem histórico anterior.","reviewHint":"Teste a negação: ao negar a frase original, o pressuposto costuma permanecer verdadeiro.","contentId":"pt-semantica"},{"id":"m45-pt-semantica-11","subject":"Português","topic":"Semântica e léxico","subtopic":"ironia (efeito de sentido)","prompt":"Depois de chegar 40 minutos atrasado, ele ouviu: \"Que pontualidade exemplar!\". O efeito de sentido predominante é:","options":["Ironia: o enunciado afirma o contrário para criticar.","Eufemismo para amenizar um elogio.","Hipérbole para intensificar a virtude.","Denotação: uso literal de \"pontualidade\"."],"answer":0,"explanation":"Há ironia: o falante enuncia o oposto do fato para censurar o atraso. Não há elogio amenizado (eufemismo), intensificação da virtude (hipérbole) nem literalidade.","difficulty":"intermediária","sourceBasis":"Leitura e inferência de sentido — ver: https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Leitura e inferência de sentido — ver: https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"reconhecer ironia por pistas contextuais","commonError":"Tomar o enunciado por literal em contextos de crítica velada.","whyWrong":"1: não se ameniza elogio, mas crítica; 2: não há intensificação da qualidade, e sim oposição; 3: nada de literal em \"pontualidade\" diante do atraso.","reviewHint":"Observe o descompasso entre o dito e a situação: elogio explícito em cenário negativo tende a ironia.","contentId":"pt-semantica"},{"id":"m45-pt-semantica-12","subject":"Português","topic":"Semântica e léxico","subtopic":"colocações e restrição semântica","prompt":"Assinale a opção que mantém naturalidade e sentido na norma-padrão: \"O gerente ____ uma decisão difícil ontem\".","options":["pegou","tirou","captou","tomou"],"answer":3,"explanation":"A colocação consagrada é \"tomar uma decisão\". \"Pegar/tirar/captar\" não se combinam idiomaticamente com \"decisão\" nesse sentido na norma-padrão.","difficulty":"avançada","sourceBasis":"Escolhas lexicais e estilísticas (colocações) — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Escolhas lexicais e estilísticas (colocações) — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"avaliar naturalidade lexical por colocações consagradas","commonError":"Projetar sinônimos gerais de \"pegar/fazer\" sobre combinações fixas do português padrão.","whyWrong":"0,1,2: verbos possíveis em outros contextos, mas inadequados aqui por restrição colocacional com \"decisão\".","reviewHint":"Verifique combinações consagradas em corpora/dicionários: alguns nomes pedem verbos preferenciais.","contentId":"pt-semantica"},{"id":"m45-pt-semantica-13","subject":"Português","topic":"Semântica e léxico","subtopic":"ambiguidade lexical (polissemia)","prompt":"Sem contexto adicional, \"A bateria estava fraca\" é ambígua porque:","options":["É homonímia perfeita: formas iguais, significados sem vínculo.","É polissemia: um mesmo item lexical tem sentidos relacionados (instrumento, conjunto, acumulador).","É metonímia: efeito estritamente sintático produz a ambiguidade.","É antonímia: o predicativo \"fraca\" cria contraste de sentido."],"answer":1,"explanation":"\"Bateria\" ativa uma rede polissêmica (instrumento, conjunto de instrumentos, acumulador elétrico, etc.). O contexto desambiguaria o sentido. Não é homonímia perfeita nem fenômeno sintático/antonímico.","difficulty":"avançada","sourceBasis":"Semântica lexical (polissemia) — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Semântica lexical (polissemia) — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"distinguir polissemia de homonímia em enunciados ambíguos","commonError":"Classificar como homonímia por conta de sentidos muito distantes na experiência do falante.","whyWrong":"0: ignora o vínculo semântico histórico/funcional entre acepções; 2: a ambiguidade é lexical, não estrutural; 3: não há par de antônimos em jogo.","reviewHint":"Verifique se há um núcleo conceitual comum entre as leituras possíveis; havendo, tende a ser polissemia.","contentId":"pt-semantica"},{"id":"m45-pt-semantica-14","subject":"Português","topic":"Semântica e léxico","subtopic":"figurado x literal (expressões idiomáticas)","prompt":"Em \"O zagueiro carregou o time nas costas no segundo tempo\", a expressão destaca que o jogador:","options":["assumiu a responsabilidade e conduziu a equipe.","literalmente transportou os colegas.","atuou pouco por estar cansado.","foi substituído por lesão."],"answer":0,"explanation":"Trata-se de sentido figurado: o atleta sustentou a equipe com seu desempenho. Não há transporte físico, queda de atuação ou substituição.","difficulty":"intermediária","sourceBasis":"Leitura e produção de sentidos — ver: https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Leitura e produção de sentidos — ver: https://educapes.capes.gov.br/bitstream/capes/553648/2/eBook%20EDK63%20-%20Leitura%20e%20Producao%20de%20Textos%20Orais%20e%20Escritos%20na%20Alfabetizacao.pdf (CC BY-NC-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"interpretar expressões idiomáticas em contexto","commonError":"Tomar expressões idiomáticas ao pé da letra.","whyWrong":"1: leitura literal absurda; 2 e 3: inferências não ancoradas na expressão idiomática.","reviewHint":"Substitua a expressão por um verbo de ação abstrata (conduzir/sustentar) e verifique a coerência do texto.","contentId":"pt-semantica"},{"id":"m45-pt-semantica-15","subject":"Português","topic":"Semântica e léxico","subtopic":"eufemismo/disfemismo (efeitos de sentido)","prompt":"No enunciado \"Após longo tratamento, ele partiu em paz\", identifica-se o seguinte efeito e uma reescrita literal equivalente:","options":["Disfemismo; reescrita: \"Ele bateu as botas\".","Hipérbole; reescrita: \"Ele virou uma estrela\".","Eufemismo; reescrita: \"Ele morreu\".","Metáfora; reescrita: \"Ele descansou\"."],"answer":2,"explanation":"\"Partiu em paz\" ameniza o fato da morte: é eufemismo. A forma literal correspondente é \"morreu\". \"Bateu as botas\" é coloquial disfemístico; \"virou uma estrela\" e \"descansou\" mantêm figuração/eufemismo, não literalidade.","difficulty":"avançada","sourceBasis":"Semântica e estilística (figuras de linguagem) — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Semântica e estilística (figuras de linguagem) — ver: https://pt.wikibooks.org/wiki/Portugu%C3%AAs (CC BY-SA).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"reconhecer e avaliar efeitos de eufemismo/disfemismo","commonError":"Confundir qualquer expressão figurada com literalidade aceitável em contexto formal.","whyWrong":"0: opõe-se ao eufemismo proposto; 1: recurso figurado sem literalidade; 3: ainda é eufemismo/metáfora, não equivalência literal.","reviewHint":"Diferencie: eufemismo suaviza; disfemismo acentua de modo brusco; a reescrita literal deve nomear o fato diretamente.","contentId":"pt-semantica"},{"id":"m45-pt-sintaxe-01","subject":"Português","topic":"Sintaxe","subtopic":"termos da oração — sujeito e transitividade verbal","prompt":"Leia: \"Faltam dados para a análise.\" Identifique o sujeito e a transitividade do verbo.","options":["Sujeito \"dados\"; verbo intransitivo.","Sujeito inexistente; verbo impessoal.","Sujeito \"dados\"; verbo de ligação.","Sujeito oracional \"para a análise\"; verbo transitivo indireto."],"answer":0,"explanation":"Em \"Faltam dados para a análise\", o núcleo do sujeito é \"dados\" (plural), o que justifica a forma verbal plural \"faltam\". O verbo \"faltar\" aqui não exige objeto; exprime falta/ausência, sendo, portanto, intransitivo. A locução \"para a análise\" funciona como termo acessório (valor finalístico ao nome \"dados\").","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Identificar sujeito e classificar a transitividade verbal em período simples","commonError":"Confundir verbos impessoais (como haver=existir) com verbos pessoais como faltar, que concordam com o sujeito expresso.","whyWrong":"(1) Há sujeito expresso: \"dados\". Impessoal seria, por exemplo, \"Há dados\" com o verbo haver no sentido de existir. (2) \"Faltar\" não é verbo de ligação; não liga sujeito a predicativo. (3) \"Para a análise\" não é sujeito; além disso, \"faltar\" não é transitivo indireto nessa construção.","reviewHint":"Revise a distinção entre verbo impessoal (haver=existir) e verbos pessoais que indicam falta/sobra (faltar, bastar), observando a concordância.","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-02","subject":"Português","topic":"Sintaxe","subtopic":"período composto — coordenação vs. subordinação (valor explicativo/causal)","prompt":"No período \"Feche a janela, porque está frio.\", a oração introduzida por \"porque\" é classificada como:","options":["Oração subordinada adverbial causal.","Oração coordenada sindética explicativa.","Oração subordinada substantiva objetiva direta.","Oração coordenada sindética conclusiva."],"answer":1,"explanation":"Em enunciados injuntivos/imperativos, a oração introduzida por \"porque\" frequentemente apresenta uma justificativa para a ordem, funcionando como oração coordenada sindética explicativa (e não como causa de um fato). Aqui, \"porque está frio\" explica o motivo do pedido \"Feche a janela\".","difficulty":"avançada","sourceBasis":"https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Analisar relações semântico-sintáticas entre orações coordenadas e subordinadas","commonError":"Tomar o conectivo \"porque\" como causal em qualquer contexto, sem considerar o valor explicativo em ordens/afirmações justificadas.","whyWrong":"(0) A classificação como causal é comum quando a relação expressa é de causa de um fato; neste caso, a estrutura explica/justifica a ordem, valor típico de coordenada explicativa. (2) Não há verbo que exija complemento substantivo. (3) \"Logo\"/\"portanto\" marcam conclusão; não é o caso de \"porque\" aqui.","reviewHint":"Compare usos de \"porque\": causa em declarações factuais vs. explicação/justificativa em ordens e opiniões.","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-03","subject":"Português","topic":"Sintaxe","subtopic":"pronomes relativos — função sintática do relativo","prompt":"Em \"O relatório que li ontem foi aprovado.\", o pronome relativo \"que\" exerce a função de:","options":["Sujeito da oração subordinada.","Complemento nominal de \"relatório\".","Objeto direto do verbo \"li\".","Adjunto adnominal de \"relatório\"."],"answer":2,"explanation":"Na subordinada adjetiva \"que li ontem\", o relativo \"que\" retoma \"relatório\" e funciona como objeto direto do verbo \"li\" (quem lê, lê algo).","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Determinar a função sintática de pronomes relativos em orações subordinadas","commonError":"Confundir a classe do relativo (pronome) com a função que ele desempenha dentro da oração subordinada.","whyWrong":"(0) O sujeito de \"li\" está elíptico (eu); \"que\" não é sujeito. (1) Não complementa nome; integra a oração como termo verbal. (3) Não é adjunto adnominal, mas termo oracional com função de objeto.","reviewHint":"Expanda a subordinada substituindo o relativo por um SN para testar a função: \"Eu li o relatório ontem\".","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-04","subject":"Português","topic":"Sintaxe","subtopic":"colocação pronominal — próclise, ênclise e atratores","prompt":"Assinale a alternativa correta segundo a norma-padrão de colocação pronominal do português do Brasil:","options":["Ninguém viu-o sair da sala.","Os pilotos se apresentaram-se cedo.","É proibido-se fumar neste setor.","Não me avisaram do atraso."],"answer":3,"explanation":"A forma correta é \"Não me avisaram do atraso.\": a partícula de negação \"não\" atrai o pronome para antes do verbo (próclise).","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Aplicar regras de colocação pronominal em diferentes contextos sintáticos","commonError":"Ignorar que elementos atratores (não, ninguém, que, se conjunção) impõem próclise.","whyWrong":"(0) \"Ninguém\" atrai próclise: o adequado é \"Ninguém o viu sair...\". (1) Há duplicação indevida do clítico. (2) Com valor impessoal, use \"É proibido fumar\" ou, com índice apassivador, \"Proíbe-se fumar\"; \"É proibido-se\" é incorreto.","reviewHint":"Liste os principais atratores de próclise (negação, advérbios atratores, pronomes relativos, conjunções subordinativas, indefinidos negativos).","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-05","subject":"Português","topic":"Sintaxe","subtopic":"oração subordinada adjetiva — restritiva vs. explicativa","prompt":"Em \"Os militares que concluírem o estágio seguirão para a base.\", a oração destacada é classificada como:","options":["Oração subordinada adjetiva explicativa.","Oração subordinada adjetiva restritiva.","Oração subordinada substantiva completiva nominal.","Oração subordinada apositiva."],"answer":1,"explanation":"Sem vírgulas, a oração adjetiva \"que concluírem o estágio\" restringe o referente de \"Os militares\" a um subconjunto: apenas os que concluírem o estágio seguirão para a base. É, portanto, restritiva.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufsm.br/bitstream/handle/1/16412/Curso_Let-Portug-Lit_Sintaxe-Portugues.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufsm.br/bitstream/handle/1/16412/Curso_Let-Portug-Lit_Sintaxe-Portugues.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Identificar o tipo de oração adjetiva a partir de pontuação e sentido","commonError":"Achar que toda oração com \"que\" é explicativa; os sinais de pontuação e o efeito de sentido são decisivos.","whyWrong":"(0) A explicativa requer vírgulas e não limita o referente. (2) Não tem valor substantivo nem complementa nome abstrato. (3) Não é aposto; modifica diretamente o nome como característica restritiva.","reviewHint":"Compare pares com/sem vírgulas para perceber a diferença de abrangência do referente.","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-06","subject":"Português","topic":"Sintaxe","subtopic":"partícula \"se\" — voz passiva sintética vs. indeterminação do sujeito","prompt":"Em \"Precisa-se de técnicos qualificados.\", o \"se\" e a construção são, respectivamente:","options":["Índice de indeterminação do sujeito; verbo transitivo indireto.","Partícula apassivadora; sujeito paciente \"técnicos qualificados\".","Partícula de realce; sujeito oculto \"nós\".","Partícula apassivadora; exige a forma \"Precisam-se de técnicos\"."],"answer":0,"explanation":"\"Precisar\" na acepção de \"necessitar\" é transitivo indireto (regência com \"de\"). Com verbos intransitivos ou transitivos indiretos, \"se\" funciona como índice de indeterminação do sujeito e o verbo permanece na 3ª pessoa do singular. Não há sujeito paciente passível de concordância.","difficulty":"avançada","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Distinguir usos do \"se\" como apassivador ou indeterminador conforme a transitividade verbal","commonError":"Tentar aplicar concordância de passiva sintética a verbos que não admitem objeto direto.","whyWrong":"(1) Passiva sintética exige verbo transitivo direto e sujeito paciente: não ocorre com TI. (2) \"Se\" não é expletivo; não há sujeito \"nós\". (3) Não há concordância com o termo preposicionado; manter o singular é a regra nessa indeterminação.","reviewHint":"Revise: só há passiva (analítica/sintética) com verbos transitivos diretos.","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-07","subject":"Português","topic":"Sintaxe","subtopic":"oração subordinada substantiva — subjetiva","prompt":"No período \"É necessário que todos compareçam.\", a oração introduzida por \"que\" classifica-se como:","options":["Oração subordinada substantiva objetiva direta.","Oração subordinada substantiva predicativa.","Oração subordinada substantiva completiva nominal.","Oração subordinada substantiva subjetiva."],"answer":3,"explanation":"A oração \"que todos compareçam\" exerce a função de sujeito do predicado impessoal \"é necessário\". Quando a subordinada desempenha função de sujeito do verbo da principal, temos a classificação de substantiva subjetiva.","difficulty":"avançada","sourceBasis":"https://repositorio.ufsm.br/bitstream/handle/1/16412/Curso_Let-Portug-Lit_Sintaxe-Portugues.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufsm.br/bitstream/handle/1/16412/Curso_Let-Portug-Lit_Sintaxe-Portugues.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reconhecer o papel sintático de orações substantivas no período composto","commonError":"Confundir completiva nominal (que completa nome) com subjetiva (que funciona como sujeito do enunciado).","whyWrong":"(0) Não completa verbo transitivo direto. (1) Não atribui predicado a sujeito; a estrutura é impessoal com predicativo de sujeito oracional. (2) Não completa nome; completa o verbo ser/locução impessoal como sujeito.","reviewHint":"Para testar, substitua a subordinada por \"isso\": se \"É necessário isso\" faz sentido, provavelmente é sujeito oracional.","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-08","subject":"Português","topic":"Sintaxe","subtopic":"orações adverbiais — valor concessivo","prompt":"Classifique a oração destacada: \"Embora esteja nublado, o voo não atrasará.\"","options":["Condicional.","Causal.","Concessiva.","Temporal."],"answer":2,"explanation":"\"Embora\" introduz, canonicamente, oração subordinada adverbial concessiva, que apresenta um fato contrário à expectativa, mas que não impede o fato principal: apesar de estar nublado, o voo não atrasará.","difficulty":"intermediária","sourceBasis":"https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Identificar o valor semântico de conjunções em orações subordinadas adverbiais","commonError":"Tomar a ideia de contraste como adversativa coordenada; aqui há subordinação concessiva.","whyWrong":"(0) Condição é marcada por \"se\", \"caso\" etc. (1) Causa esperada seria marcada por \"porque/como\" (em certos contextos). (3) Temporal seria \"quando/assim que/antes que\" etc.","reviewHint":"Monte um quadro com conjunções típicas: concessivas (embora, ainda que), condicionais (se, caso), causais (porque, como) e temporais (quando, assim que).","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-09","subject":"Português","topic":"Sintaxe","subtopic":"predicação — predicativo do objeto","prompt":"Em \"Consideraram o plano inviável.\", a expressão \"inviável\" exerce a função de:","options":["Predicativo do objeto.","Adjunto adnominal de \"plano\".","Objeto direto oracional.","Complemento nominal de \"consideraram\"."],"answer":0,"explanation":"\"Considerar\" é verbo transitivo direto; o termo \"o plano\" é objeto direto. O adjetivo \"inviável\" atribui uma propriedade ao objeto direto, funcionando como predicativo do objeto (predicação secundária).","difficulty":"avançada","sourceBasis":"https://repositorio.ufsm.br/bitstream/handle/1/16412/Curso_Let-Portug-Lit_Sintaxe-Portugues.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufsm.br/bitstream/handle/1/16412/Curso_Let-Portug-Lit_Sintaxe-Portugues.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reconhecer predicação secundária e distinguir termos nominais de termos oracionais","commonError":"Confundir adjunto adnominal (termo nominal) com predicativo (termo oracional que atribui estado a sujeito/objeto).","whyWrong":"(1) Não determina substantivo; atribui estado ao objeto. (2) Não há oração aqui. (3) \"Considerar\" não rege complemento nominal; recebe objeto direto.","reviewHint":"Verifique se o adjetivo pode ser parafraseado por \"que é/está\" aplicado ao objeto: \"o plano (é) inviável\".","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-10","subject":"Português","topic":"Sintaxe","subtopic":"orações reduzidas — infinitivo com valor temporal (expansão)","prompt":"Assinale a reescrita que desenvolve corretamente a oração reduzida: \"Ao iniciar o procedimento, os técnicos checaram os equipamentos.\"","options":["Quando os técnicos iniciavam o procedimento, checaram os equipamentos.","Quando foram iniciados o procedimento, os técnicos checavam os equipamentos.","Quando iniciaram o procedimento, os técnicos checaram os equipamentos.","Quando iniciar o procedimento, os técnicos checaram os equipamentos."],"answer":2,"explanation":"\"Ao + infinitivo\" expressa valor temporal (\"quando\"). Mantendo a correlação de sujeitos (os técnicos iniciam e checam) e o aspecto pontual, a forma adequada é: \"Quando iniciaram o procedimento, os técnicos checaram os equipamentos.\"","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Expandir orações reduzidas preservando sentido, tempo e concordância","commonError":"Ignorar a exigência de correferência de sujeito entre a reduzida de infinitivo e a oração principal.","whyWrong":"(0) O imperfeito (iniciavam) sugere habitualidade e conflita com o perfeito simples subsequente. (1) Muda a voz e cria erro de concordância (\"foram iniciados o procedimento\"). (3) O futuro do subjuntivo (iniciar) não corresponde ao passado perfeito da principal.","reviewHint":"Associe \"ao + infinitivo\" a valor temporal (quando) e confira se o sujeito subentendido é o mesmo da principal.","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-11","subject":"Português","topic":"Sintaxe","subtopic":"coordenação — classificação semântica das sindéticas","prompt":"No período \"Houve falha no sistema; logo, suspendemos o teste.\", a conjunção \"logo\" introduz oração:","options":["Adversativa.","Conclusiva.","Explicativa.","Alternativa."],"answer":1,"explanation":"\"Logo\" é conjunção coordenativa conclusiva, indicando que a segunda oração é inferida da primeira (resultado/conclusão).","difficulty":"avançada","sourceBasis":"https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Identificar a relação semântica entre orações coordenadas sindéticas","commonError":"Confundir \"logo/portanto\" (conclusão) com \"pois/porque\" explicativos.","whyWrong":"(0) Adversativa opõe ideias (mas, porém). (2) Explicativa justifica uma ordem/afirmação (pois, porque em certos contextos). (3) Alternativa indica alternância (ou, ora...ora).","reviewHint":"Monte um quadro: aditivas (e), adversativas (mas), alternativas (ou), conclusivas (logo/portanto), explicativas (pois/porque — valor de justificativa).","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-12","subject":"Português","topic":"Sintaxe","subtopic":"funções de pronomes — objeto indireto (lhe)","prompt":"Em \"Disseram-lhe que comparecesse.\", o pronome \"lhe\" funciona como:","options":["Complemento nominal da oração subordinada.","Objeto indireto do verbo \"comparecesse\".","Adjunto adnominal do pronome \"que\".","Objeto indireto do verbo \"disseram\"."],"answer":3,"explanation":"\"Dizer\" pode reger objeto indireto indicando destinatário (dizer algo a alguém). O pronome \"lhe\" marca esse destinatário: é objeto indireto de \"disseram\".","difficulty":"intermediária","sourceBasis":"https://open.umn.edu/opentextbooks/textbooks/portugues-para-principiantes; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://open.umn.edu/opentextbooks/textbooks/portugues-para-principiantes; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reconhecer funções dos pronomes oblíquos nas relações verbo-complemento","commonError":"Confundir o destinatário do verbo principal com termo interno da subordinada introduzida por \"que\".","whyWrong":"(0) Não completa nome; completa o verbo principal. (1) \"Comparecesse\" não tem complemento pronominal aqui; integra oração subordinada de conteúdo. (2) \"Que\" não recebe adjunto; é conectivo/pronome subordinativo.","reviewHint":"Teste com paráfrase: \"Disseram a ele/ela ...\"; se puder substituir por \"a ele/ela\", é objeto indireto (lhe).","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-13","subject":"Português","topic":"Sintaxe","subtopic":"termos acessórios — adjunto adnominal vs. complemento nominal","prompt":"Em \"O respeito dos alunos impressionou a comissão.\", a expressão \"dos alunos\" exerce a função de:","options":["Adjunto adnominal de \"respeito\".","Complemento nominal de \"respeito\".","Objeto indireto do verbo \"impressionou\".","Aposto especificativo."],"answer":0,"explanation":"Quando o nome abstrato indica a entidade que pratica/possui a qualidade (respeito que os alunos têm), o termo preposicionado funciona como adjunto adnominal. O complemento nominal, em geral, indica alvo/paciente da ação/qualidade (respeito aos alunos).","difficulty":"avançada","sourceBasis":"https://repositorio.ufsm.br/bitstream/handle/1/16412/Curso_Let-Portug-Lit_Sintaxe-Portugues.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufsm.br/bitstream/handle/1/16412/Curso_Let-Portug-Lit_Sintaxe-Portugues.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Distinguir adjunto adnominal de complemento nominal em nomes abstratos","commonError":"Classificar todo termo preposicionado após nome abstrato como complemento nominal, sem observar a relação agente/paciente.","whyWrong":"(1) Seria complemento nominal se indicasse o alvo/paciente (\"respeito aos alunos\"). (2) \"Dos alunos\" não é regido por verbo, mas por nome. (3) Não há relação de aposição explicativa.","reviewHint":"Verifique a pergunta respondida: respeito de quem? (agente → adjunto); respeito a quem? (paciente/alvo → complemento).","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-14","subject":"Português","topic":"Sintaxe","subtopic":"regência verbal e pronomes oblíquos — objeto indireto (lhe)","prompt":"Reescreva, segundo a norma-padrão, substituindo o termo destacado por pronome oblíquo: \"Assisti ao aluno durante a prova.\"","options":["Assisti-o durante a prova.","Assisti-lhe durante a prova.","Assisti-no durante a prova.","Assisti ao ele durante a prova."],"answer":1,"explanation":"\"Assistir\" (prestar assistência) rege preposição \"a\" e pede complemento indireto. O pronome correspondente é \"lhe\" para 3ª pessoa: \"Assisti-lhe durante a prova\".","difficulty":"intermediária","sourceBasis":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pt.wikibooks.org/wiki/Portugu%C3%AAs; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Aplicar regência verbal na pronominalização de complementos","commonError":"Generalizar o uso de \"o/a\" para todos os complementos de 3ª pessoa, ignorando a regência com preposição.","whyWrong":"(0) Trata o verbo como transitivo direto, o que fere a regência. (2) \"no\" não corresponde à regência com \"a\"; além disso, combina artigo indevido. (3) A sequência \"ao ele\" é incorreta; a contração pede artigo, mas com pronome pessoal usa-se \"a ele\", sem contração com artigo definido.","reviewHint":"Revise a regência de verbos polissêmicos (assistir: ver x prestar assistência) e o uso de \"lhe\" para objeto indireto de 3ª pessoa.","contentId":"pt-sintaxe"},{"id":"m45-pt-sintaxe-15","subject":"Português","topic":"Sintaxe","subtopic":"correlação verbal — período condicional (hipótese irreal no passado)","prompt":"Assinale a alternativa que expressa hipótese irreal no passado com correlação verbal adequada:","options":["Se eu soubesse, ajudaria.","Se eu soubesse, teria ajudado.","Se eu tive sabido, ajudaria.","Se eu tivesse sabido, teria ajudado."],"answer":3,"explanation":"Para hipótese irreal no passado, a correlação típica é: prótase no mais-que-perfeito do subjuntivo (composto: tivesse + particípio) e apódose no condicional composto (teria + particípio): \"Se eu tivesse sabido, teria ajudado.\"","difficulty":"avançada","sourceBasis":"https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://bibliotecadigital.cnj.jus.br/jspui/bitstream/123456789/184/1/SINTAXE.pdf — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reconhecer e empregar correlações de modo/tempo em períodos condicionais","commonError":"Trocar o tempo da prótase (imperfeito do subjuntivo) pelo do mais-que-perfeito do subjuntivo quando se quer referir ao passado.","whyWrong":"(0) Expressa hipótese irreal no presente (imperfeito do subjuntivo + condicional simples). (1) Mistura tempos, sugerindo condição presente e resultado passado. (2) Uso incorreto do pretérito perfeito do indicativo e do particípio; não expressa condicional irreal do passado.","reviewHint":"Revise as três correlações: real (se + futuro do subjuntivo → futuro do presente), potencial (se + imperfeito do subjuntivo → condicional simples) e irreal do passado (se + mais-que-perfeito do subjuntivo → condicional composto).","contentId":"pt-sintaxe"},{"id":"m45-en-connectors-01","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"coordinating conjunctions — consequence","prompt":"Escolha o conector que completa corretamente: \"The runway was wet, ___ the pilot delayed the departure.\"","options":["and","but","so","or"],"answer":2,"explanation":"A pista molhada explica a decisão de adiar a partida; portanto, a segunda oração é consequência da primeira. \"So\" é a conjunção coordenativa adequada para esse sentido.","difficulty":"intermediária","sourceBasis":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","skill":"identificar consequência e selecionar coordinating conjunction","commonError":"Escolher \"and\" apenas porque há duas orações ligadas.","whyWrong":"\"And\" apenas adiciona informação, \"but\" introduz contraste e \"or\" introduz alternativa; nenhuma dessas relações é indicada no enunciado.","reviewHint":"Pergunte se a segunda oração ocorre como resultado da primeira; se sim, teste \"so\".","contentId":"en-connectors"},{"id":"m45-en-connectors-02","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"coordinating conjunctions — contrast","prompt":"Complete a frase: \"The manual is brief, ___ it covers all emergency procedures.\"","options":["so","but","and","for"],"answer":1,"explanation":"A brevidade do manual contrasta com sua cobertura completa. \"But\" marca oposição entre as duas orações independentes.","difficulty":"intermediária","sourceBasis":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer contraste em coordenação","commonError":"Usar \"so\" por interpretar a segunda oração como consequência.","whyWrong":"A cobertura dos procedimentos não é causada pela brevidade; ela é apresentada como fato inesperado em relação a ela. \"And\" não explicita o contraste, \"for\" introduziria explicação e não há alternativa.","reviewHint":"Procure a oposição entre dois fatos verdadeiros, especialmente quando o segundo surpreende em relação ao primeiro.","contentId":"en-connectors"},{"id":"m45-en-connectors-03","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"coordinating conjunctions — addition","prompt":"Qual alternativa completa corretamente? \"The technicians checked the cables ___ replaced a damaged fuse.\"","options":["and","although","therefore","unless"],"answer":0,"explanation":"As duas ações são realizadas pelos técnicos e são simplesmente somadas: eles verificaram os cabos e substituíram um fusível. \"And\" coordena os verbos.","difficulty":"intermediária","sourceBasis":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer adição entre ações coordenadas","commonError":"Escolher um marcador de resultado porque as ações aparecem em sequência.","whyWrong":"A ordem das ações não prova consequência; o enunciado apenas acrescenta uma ação à outra. \"Although\" exigiria concessão, \"therefore\" é marcador de resultado e \"unless\" é condicional.","reviewHint":"Nem toda sequência é causa e efeito: verifique se a frase apenas enumera ações.","contentId":"en-connectors"},{"id":"m45-en-connectors-04","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"subordinating conjunctions — time","prompt":"Escolha a conjunção adequada: \"___ the alarm was sounding, the crew moved to the safe area.\"","options":["Because","While","Unless","Therefore"],"answer":1,"explanation":"A frase apresenta uma ação em andamento no mesmo intervalo em que outra ocorreu. \"While\" introduz essa relação temporal de simultaneidade.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/35163/5/Ingles_Leitura_Instrumental_2022%20-%20Livro.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/35163/5/Ingles_Leitura_Instrumental_2022%20-%20Livro.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"identificar conector subordinativo de simultaneidade","commonError":"Usar \"because\" por imaginar que o alarme é a causa direta do deslocamento.","whyWrong":"O enunciado destaca que as ações ocorreram ao mesmo tempo, não que o alarme explique necessariamente a decisão. \"Unless\" expressa condição e \"therefore\" expressa resultado.","reviewHint":"Para duas ações simultâneas, teste \"while\"; para causa, a relação precisaria responder \"por quê?\".","contentId":"en-connectors"},{"id":"m45-en-connectors-05","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"subordinating conjunctions — condition","prompt":"Complete: \"You may enter the laboratory ___ you wear protective glasses.\"","options":["because","although","provided that","so"],"answer":2,"explanation":"A entrada é permitida sob uma condição: o uso de óculos de proteção. \"Provided that\" significa \"desde que\" e introduz essa condição.","difficulty":"intermediária","sourceBasis":"https://warwick.ac.uk/fac/soc/al/globalpad-rip/openhouse/academicenglishskills/grammar/discourse/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://warwick.ac.uk/fac/soc/al/globalpad-rip/openhouse/academicenglishskills/grammar/discourse/ — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer condição explícita em oração subordinada","commonError":"Escolher \"because\" por relacionar óculos e segurança como causa.","whyWrong":"A estrutura estabelece uma exigência para que a entrada ocorra, não uma explicação causal já realizada. \"Although\" marca concessão e \"so\" resultado.","reviewHint":"Parafraseie por \"you may enter if you wear...\"; a equivalência aponta para uma condição.","contentId":"en-connectors"},{"id":"m45-en-connectors-06","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"subordinating conjunctions — concession","prompt":"Qual opção completa a frase? \"___ the test was demanding, the candidate completed it on time.\"","options":["Although","Because","If","So"],"answer":0,"explanation":"O teste ser exigente poderia dificultar a tarefa, mas não impediu sua conclusão no prazo. \"Although\" introduz essa concessão.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/37585/1/Habilidades_Integradas.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/37585/1/Habilidades_Integradas.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"distinguir concessão de causa e condição","commonError":"Interpretar a primeira oração como causa da conclusão no prazo.","whyWrong":"Um teste exigente não causa logicamente o cumprimento do prazo; há contraste entre dificuldade e resultado. \"Because\" marcaria causa, \"if\" condição e \"so\" consequência.","reviewHint":"Teste a paráfrase \"apesar de o teste ser exigente\"; se funcionar, a relação é concessiva.","contentId":"en-connectors"},{"id":"m45-en-connectors-07","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"discourse markers — result","prompt":"Escolha o marcador discursivo e a pontuação adequados: \"The battery was depleted. ___, the device did not start.\"","options":["However","Moreover","Meanwhile","Therefore"],"answer":3,"explanation":"A bateria descarregada explica o fato de o dispositivo não iniciar; a relação é de resultado. \"Therefore\" significa \"portanto\" e, no início da nova frase, é seguido por vírgula.","difficulty":"avançada","sourceBasis":"https://warwick.ac.uk/fac/soc/al/globalpad-rip/openhouse/academicenglishskills/grammar/discourse/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://warwick.ac.uk/fac/soc/al/globalpad-rip/openhouse/academicenglishskills/grammar/discourse/ — calibração apenas; questão autoral/similar; não oficial.","skill":"identificar resultado sinalizado por discourse marker","commonError":"Escolher \"however\" porque há duas frases separadas por ponto.","whyWrong":"A pontuação não determina contraste: o conteúdo mostra consequência. \"However\" é contraste, \"moreover\" é adição e \"meanwhile\" indica simultaneidade.","reviewHint":"Separe a forma da relação: primeiro pergunte se a segunda frase é conclusão ou oposição.","contentId":"en-connectors"},{"id":"m45-en-connectors-08","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"discourse markers — contrast and punctuation","prompt":"Complete corretamente: \"The first route was shorter; ___, it was closed to traffic.\"","options":["therefore","however","in addition","consequently"],"answer":1,"explanation":"A rota mais curta tinha uma desvantagem que muda a expectativa: estava fechada. \"However\" sinaliza contraste. O ponto e vírgula antes e a vírgula depois são compatíveis com um marcador que liga duas orações independentes.","difficulty":"avançada","sourceBasis":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","skill":"diferenciar conjunctive adverb de marcador de resultado e aplicar pontuação","commonError":"Escolher \"therefore\" por supor que a rota estar fechada decorre de ser curta.","whyWrong":"O enunciado não afirma causalidade; a segunda informação contraria a vantagem esperada da primeira. \"In addition\" apenas adicionaria informação, e \"consequently\" exigiria consequência.","reviewHint":"Observe a expectativa: algo aparentemente positivo é seguido por uma limitação, o que favorece \"however\".","contentId":"en-connectors"},{"id":"m45-en-connectors-09","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"discourse markers — sequence","prompt":"Qual marcador inicia adequadamente a sequência? \"___, inspect the panel; next, record the voltage.\"","options":["First","Therefore","Although","Because"],"answer":0,"explanation":"A frase apresenta o primeiro passo de um procedimento e depois anuncia o seguinte com \"next\". \"First\" organiza a sequência temporal/instrucional.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/35163/5/Ingles_Leitura_Instrumental_2022%20-%20Livro.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/35163/5/Ingles_Leitura_Instrumental_2022%20-%20Livro.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer marcador de ordenação de procedimentos","commonError":"Usar \"because\" por achar que o primeiro passo justifica o segundo.","whyWrong":"O par \"first/next\" organiza ordem, não causa. \"Although\" introduziria concessão e \"therefore\" conclusão.","reviewHint":"Procure pares de organização como \"first, next, finally\" antes de procurar causa ou contraste.","contentId":"en-connectors"},{"id":"m45-en-connectors-10","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"prepositions of time","prompt":"Selecione a sequência correta: \"The briefing begins ___ 06:30 ___ Tuesday ___ August.\"","options":["at / on / in","in / at / on","on / in / at","at / in / on"],"answer":0,"explanation":"Usa-se \"at\" para um horário pontual, \"on\" para dia/data e \"in\" para mês ou período amplo. Assim, a sequência correta é \"at 06:30 on Tuesday in August\".","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/35163/5/Ingles_Leitura_Instrumental_2022%20-%20Livro.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/35163/5/Ingles_Leitura_Instrumental_2022%20-%20Livro.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"aplicar o contraste at/on/in em expressões temporais","commonError":"Usar a mesma preposição para todos os marcadores de tempo.","whyWrong":"\"At\" não é a escolha padrão para dia ou mês; \"on\" não é a escolha padrão para horário ou mês; e \"in\" não marca normalmente um horário pontual.","reviewHint":"Classifique cada expressão da menor para a maior escala: horário, dia e mês.","contentId":"en-connectors"},{"id":"m45-en-connectors-11","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"prepositions of place","prompt":"Complete: \"The emergency exit is ___ the storage room and the main hall.\"","options":["among","under","between","through"],"answer":2,"explanation":"Há dois pontos de referência, a sala de armazenamento e o saguão principal. \"Between\" significa \"entre dois\" e descreve a localização da saída.","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/35163/5/Ingles_Leitura_Instrumental_2022%20-%20Livro.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/35163/5/Ingles_Leitura_Instrumental_2022%20-%20Livro.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"distinguir preposições de localização conforme o número de referências","commonError":"Escolher \"among\" sempre que a tradução portuguesa for \"entre\".","whyWrong":"\"Among\" normalmente se refere a um conjunto ou vários elementos; aqui há dois locais nomeados. \"Under\" indica posição inferior e \"through\" indica passagem, não localização estática.","reviewHint":"Conte os referentes explícitos: dois favorecem \"between\"; vários em um conjunto favorecem \"among\".","contentId":"en-connectors"},{"id":"m45-en-connectors-12","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"prepositions of movement and direction","prompt":"Escolha o par que completa a trajetória: \"The drone flew ___ the canyon and then rose ___ the ridge.\"","options":["into / at","through / towards","on / from","past / in"],"answer":1,"explanation":"O drone atravessa o interior do cânion, portanto usa-se \"through\"; depois sobe na direção da crista, sem necessariamente afirmar que a alcançou, portanto \"towards\".","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/35163/5/Ingles_Leitura_Instrumental_2022%20-%20Livro.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/35163/5/Ingles_Leitura_Instrumental_2022%20-%20Livro.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"interpretar trajetória por dentro e direção aproximada","commonError":"Usar \"into\" para qualquer movimento relacionado a uma área.","whyWrong":"\"Into\" enfatiza entrada em um espaço; a frase descreve passagem pelo interior. \"At\" não expressa direção, e as demais combinações não formam a trajetória indicada.","reviewHint":"Visualize uma linha: cruzar o interior é \"through\"; apontar para um destino é \"towards\".","contentId":"en-connectors"},{"id":"m45-en-connectors-13","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"prepositions of movement — out of","prompt":"Qual preposição completa corretamente? \"The technician took the cable ___ the casing before replacing it.\"","options":["out of","on","at","between"],"answer":0,"explanation":"O cabo é retirado de dentro do revestimento. \"Out of\" expressa saída ou remoção a partir do interior de um espaço.","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/35163/5/Ingles_Leitura_Instrumental_2022%20-%20Livro.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/35163/5/Ingles_Leitura_Instrumental_2022%20-%20Livro.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"selecionar preposição de saída em movimento","commonError":"Confundir localização estática com movimento de remoção.","whyWrong":"\"On\" indica superfície, \"at\" indica ponto de referência e \"between\" indica posição entre dois elementos; nenhuma expressa tirar algo de dentro.","reviewHint":"Pergunte de onde o cabo foi retirado; a resposta \"de dentro de\" aponta para \"out of\".","contentId":"en-connectors"},{"id":"m45-en-connectors-14","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"logical relations — cause","prompt":"Complete a frase com o conector de causa adequado: \"The flight was postponed ___ dense fog covered the runway.\"","options":["although","therefore","unless","because"],"answer":3,"explanation":"A neblina densa é apresentada como motivo do adiamento. Como a lacuna é seguida por uma oração completa, \"because\" é a conjunção causal adequada.","difficulty":"avançada","sourceBasis":"https://warwick.ac.uk/fac/soc/al/globalpad-rip/openhouse/academicenglishskills/grammar/discourse/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://warwick.ac.uk/fac/soc/al/globalpad-rip/openhouse/academicenglishskills/grammar/discourse/ — calibração apenas; questão autoral/similar; não oficial.","skill":"identificar causa e verificar que o conector introduz oração","commonError":"Escolher \"therefore\" porque a primeira oração aparece antes da causa.","whyWrong":"\"Therefore\" introduz consequência, geralmente após a causa; aqui a lacuna responde por que o voo foi adiado. \"Although\" é concessão e \"unless\" é condição.","reviewHint":"Leia a frase como pergunta: o que explica o adiamento? A resposta é a oração após \"because\".","contentId":"en-connectors"},{"id":"m45-en-connectors-15","subject":"Inglês","topic":"Connectors and prepositions","subtopic":"logical relations — concession versus preposition","prompt":"Escolha a forma que deve vir antes do grupo nominal: \"___ the heavy rain, the inspection continued.\"","options":["Although","Because","Despite","So"],"answer":2,"explanation":"A lacuna é seguida pelo grupo nominal \"the heavy rain\", sem sujeito e verbo. \"Despite\" é preposição e expressa concessão: apesar da chuva, a inspeção continuou.","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/37585/1/Habilidades_Integradas.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/37585/1/Habilidades_Integradas.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"distinguir despite de although pela estrutura que segue","commonError":"Escolher \"although\" por reconhecer apenas a relação de concessão.","whyWrong":"\"Although\" exigiria uma oração, como em \"although it was raining\". \"Because\" expressaria causa, e \"so\" resultado; apenas \"despite\" combina com o grupo nominal apresentado.","reviewHint":"Além do sentido, observe a forma: nome/gerúndio favorece \"despite\"; sujeito + verbo favorece \"although\".","contentId":"en-connectors"},{"id":"m45-en-modals-01","subject":"Inglês","topic":"Modals and passive voice","subtopic":"can — ability","prompt":"Because Leo trained every day, he ___ carry the 25-kilogram pack without help.","options":["may","must","can","should"],"answer":2,"explanation":"A frase descreve capacidade atual, portanto usa-se can + verbo na forma de base: can carry. May indica permissão ou possibilidade, must obrigação/inferência e should conselho ou expectativa.","difficulty":"intermediária","sourceBasis":"https://openoregon.pressbooks.pub/coalescence/chapter/grammar-modal-verbs/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://openoregon.pressbooks.pub/coalescence/chapter/grammar-modal-verbs/ — calibração apenas; questão autoral/similar; não oficial.","skill":"identificar can como marcador de capacidade e aplicar modal + verbo-base","commonError":"Escolher must apenas porque a frase apresenta uma ação possível, confundindo capacidade com obrigação.","whyWrong":"0 may não expressa a capacidade treinada; 1 must imporia uma obrigação ou conclusão forte; 3 should apresentaria conselho/expectativa, não habilidade.","reviewHint":"Pergunte se o sujeito consegue realizar a ação; se sim, a função central é ability.","contentId":"en-modals"},{"id":"m45-en-modals-02","subject":"Inglês","topic":"Modals and passive voice","subtopic":"may — permission","prompt":"___ I use your calculator during the test?","options":["Must","May","Should","Might"],"answer":1,"explanation":"May I...? é uma forma polida e relativamente formal de pedir permissão. Must expressaria obrigação; should, conselho; might, possibilidade cautelosa, não o pedido direto de autorização.","difficulty":"intermediária","sourceBasis":"https://openoregon.pressbooks.pub/coalescence/chapter/grammar-modal-verbs/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://openoregon.pressbooks.pub/coalescence/chapter/grammar-modal-verbs/ — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer may em pedidos formais de permissão","commonError":"Usar might por associá-lo genericamente a qualquer ideia de possibilidade.","whyWrong":"0 não pede autorização; 2 recomenda uma conduta; 3 introduz hipótese e não uma pergunta de permissão.","reviewHint":"Em uma pergunta iniciada por modal e seguida de I, verifique se o falante quer autorização para fazer algo.","contentId":"en-modals"},{"id":"m45-en-modals-03","subject":"Inglês","topic":"Modals and passive voice","subtopic":"might — cautious probability","prompt":"The speaker wants to express a remote and cautious possibility: The clouds are thick; it ___ rain before noon.","options":["might","must","has to","cannot"],"answer":0,"explanation":"Might rain apresenta uma possibilidade cautelosa, exatamente a intenção indicada. Must e has to sugerem necessidade ou certeza forte; cannot nega a possibilidade.","difficulty":"intermediária","sourceBasis":"https://www.sjsu.edu/writingcenter/docs/handouts/Modal%20Verbs.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.sjsu.edu/writingcenter/docs/handouts/Modal%20Verbs.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"relacionar might ao grau cauteloso de possibilidade","commonError":"Tratar todos os modais de probabilidade como equivalentes, sem observar o grau de cautela solicitado.","whyWrong":"1 e 2 marcam necessidade ou inferência forte, incompatíveis com uma possibilidade remota; 3 afirma impossibilidade, o sentido oposto.","reviewHint":"Palavras como remote, perhaps e cautious favorecem might, enquanto evidência conclusiva favorece must.","contentId":"en-modals"},{"id":"m45-en-modals-04","subject":"Inglês","topic":"Modals and passive voice","subtopic":"must not — prohibition","prompt":"Safety rule: Visitors ___ enter the hangar without an escort.","options":["do not have to","should","may","must not"],"answer":3,"explanation":"A expressão safety rule e a ausência de escolta indicam proibição: must not enter. Do not have to significaria que a ação não é necessária, o que não equivale a proibi-la.","difficulty":"intermediária","sourceBasis":"https://openoregon.pressbooks.pub/coalescence/chapter/grammar-modal-verbs/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://openoregon.pressbooks.pub/coalescence/chapter/grammar-modal-verbs/ — calibração apenas; questão autoral/similar; não oficial.","skill":"distinguir proibição com must not de ausência de obrigação","commonError":"Usar do not have to para traduzir qualquer frase negativa com a ideia de dever.","whyWrong":"0 diz apenas que não é necessário entrar; 1 aconselha a entrada; 2 dá permissão, todos incompatíveis com uma regra de segurança proibitiva.","reviewHint":"Teste as paráfrases: must not = é proibido; do not have to = não é preciso.","contentId":"en-modals"},{"id":"m45-en-modals-05","subject":"Inglês","topic":"Modals and passive voice","subtopic":"should — advice","prompt":"You ___ back up the file before installing the update; it is good advice, not a strict rule.","options":["can","might","should","must not"],"answer":2,"explanation":"A frase explicita que se trata de um bom conselho, não de regra obrigatória; por isso, should back up é a escolha adequada.","difficulty":"intermediária","sourceBasis":"https://www.sjsu.edu/writingcenter/docs/handouts/Modal%20Verbs.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.sjsu.edu/writingcenter/docs/handouts/Modal%20Verbs.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"identificar should como conselho ou advisability","commonError":"Escolher must sem considerar a informação explícita de que não há regra estrita.","whyWrong":"0 expressa capacidade ou permissão; 1 possibilidade; 3 proibição. Nenhum desses sentidos equivale a uma recomendação positiva.","reviewHint":"As expressões good advice e it is advisable são pistas para should.","contentId":"en-modals"},{"id":"m45-en-modals-06","subject":"Inglês","topic":"Modals and passive voice","subtopic":"passive voice — present simple","prompt":"Choose the correct passive form of: The lab checks each sample twice.","options":["Each sample is checked twice.","Each sample checks twice.","Each sample was check twice.","Each sample is checking twice."],"answer":0,"explanation":"O objeto each sample passa a sujeito, e o presente simples passivo usa is + particípio: is checked. O agente pode ser omitido porque o laboratório não é o foco.","difficulty":"intermediária","sourceBasis":"https://openoregon.pressbooks.pub/coalescence/chapter/grammar-passive-voice-verbs/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://openoregon.pressbooks.pub/coalescence/chapter/grammar-passive-voice-verbs/ — calibração apenas; questão autoral/similar; não oficial.","skill":"transformar uma oração ativa no presente simples em passiva","commonError":"Manter o verbo principal no presente ativo ou usar o gerúndio no lugar do particípio.","whyWrong":"1 não possui be nem particípio; 2 mistura was com a forma base check; 3 forma uma estrutura progressiva e não a passiva solicitada.","reviewHint":"Localize o objeto da ativa e aplique presente de be + past participle.","contentId":"en-modals"},{"id":"m45-en-modals-07","subject":"Inglês","topic":"Modals and passive voice","subtopic":"passive voice with modal","prompt":"Choose the correct passive form of: The committee may revise the schedule.","options":["The schedule may revised by the committee.","The schedule may be revised by the committee.","The schedule may be revise by the committee.","The schedule is may revised by the committee."],"answer":1,"explanation":"Na passiva com modal, a fórmula é modal + be + particípio. Assim, may + be + revised produz The schedule may be revised.","difficulty":"intermediária","sourceBasis":"https://udel.pressbooks.pub/language/chapter/active-and-passive-voice/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://udel.pressbooks.pub/language/chapter/active-and-passive-voice/ — calibração apenas; questão autoral/similar; não oficial.","skill":"aplicar a fórmula modal + be + particípio na voz passiva","commonError":"Achar que o modal elimina a necessidade de be na construção passiva.","whyWrong":"0 omite be; 2 usa a forma base revise, não o particípio revised; 3 coloca is antes do modal, rompendo a ordem da construção.","reviewHint":"Depois de qualquer um dos modais centrais, use be; depois de be, use o particípio.","contentId":"en-modals"},{"id":"m45-en-modals-08","subject":"Inglês","topic":"Modals and passive voice","subtopic":"perfect modals — strong inference","prompt":"The runway is dry now, and maintenance records show cleaning trucks were there overnight. The runway ___ have been cleaned.","options":["might be","must be","must have been","should be"],"answer":2,"explanation":"A frase pede uma conclusão forte sobre uma ação anterior. A estrutura correta é must + have been + particípio: must have been cleaned. O segmento have been marca o caráter retrospectivo e passivo.","difficulty":"avançada","sourceBasis":"https://udel.pressbooks.pub/language/chapter/perfect-modals/ e https://udel.pressbooks.pub/language/chapter/active-and-passive-voice/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://udel.pressbooks.pub/language/chapter/perfect-modals/ e https://udel.pressbooks.pub/language/chapter/active-and-passive-voice/ — calibração apenas; questão autoral/similar; não oficial.","skill":"combinar inferência forte no passado com a passiva modal perfeita","commonError":"Usar must be e ignorar que a limpeza ocorreu antes do momento da fala.","whyWrong":"0 indica possibilidade mais fraca e não a conclusão forte; 1 sugere estado presente; 3 indica expectativa presente, não inferência retrospectiva.","reviewHint":"Para concluir sobre uma ação passada recebida pelo sujeito, procure must have been + particípio.","contentId":"en-modals"},{"id":"m45-en-modals-09","subject":"Inglês","topic":"Modals and passive voice","subtopic":"passive voice — past simple and agent","prompt":"Choose the correct passive form of: The engineers designed the bridge in 2024.","options":["The bridge designed the engineers in 2024.","The bridge is designed by the engineers in 2024.","The bridge has been designed by the engineers in 2024.","The bridge was designed by the engineers in 2024."],"answer":3,"explanation":"A ação está no passado simples, portanto a passiva usa was + designed. O objeto bridge torna-se sujeito e o agente pode ser introduzido por by.","difficulty":"avançada","sourceBasis":"https://openoregon.pressbooks.pub/coalescence/chapter/grammar-passive-voice-verbs/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://openoregon.pressbooks.pub/coalescence/chapter/grammar-passive-voice-verbs/ — calibração apenas; questão autoral/similar; não oficial.","skill":"preservar o tempo passado e explicitar o agente na transformação passiva","commonError":"Escolher is designed por reconhecer a passiva, mas perder a indicação temporal in 2024.","whyWrong":"0 mantém a ordem sem transformar a oração; 1 usa presente; 2 usa present perfect, enquanto o enunciado fixa um momento passado concluído.","reviewHint":"Preserve o tempo no auxiliar de be: past simple ativo vira was/were + particípio.","contentId":"en-modals"},{"id":"m45-en-modals-10","subject":"Inglês","topic":"Modals and passive voice","subtopic":"causative make","prompt":"The commander made the recruits ___ the procedure again.","options":["to repeat","repeated","repeat","repeating"],"answer":2,"explanation":"A causativa make + pessoa exige o infinitivo sem to: made the recruits repeat. A construção comunica que o comandante obrigou os recrutas a repetir o procedimento.","difficulty":"avançada","sourceBasis":"https://ecampusontario.pressbooks.pub/essentialsoflinguistics2/chapter/adding-or-removing-arguments-causatives-and-passives/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://ecampusontario.pressbooks.pub/essentialsoflinguistics2/chapter/adding-or-removing-arguments-causatives-and-passives/ — calibração apenas; questão autoral/similar; não oficial.","skill":"selecionar o bare infinitive após make + objeto","commonError":"Generalizar a regra de to-infinitive e acrescentar to depois de make.","whyWrong":"0 usa to indevido; 1 é particípio passado e não completa a causativa; 3 é gerúndio, incompatível com a estrutura exigida.","reviewHint":"Memorize o contraste: make/let + pessoa + base, mas get + pessoa + to + base.","contentId":"en-modals"},{"id":"m45-en-modals-11","subject":"Inglês","topic":"Modals and passive voice","subtopic":"causative get","prompt":"The teacher got the student ___ the answer in full.","options":["explain","to explain","explained","explaining"],"answer":1,"explanation":"Get, na causativa com pessoa, segue o padrão get + pessoa + to + verbo. Portanto, got the student to explain está correto e sugere que a professora conseguiu ou persuadiu o aluno a explicar.","difficulty":"avançada","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette)/05%3A_Book_5/5.07%3A_The_Causative_and_Sensory_Verbs — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette)/05%3A_Book_5/5.07%3A_The_Causative_and_Sensory_Verbs — calibração apenas; questão autoral/similar; não oficial.","skill":"distinguir get + pessoa + to-infinitive de outras causativas","commonError":"Aplicar a estrutura de make e omitir to depois de get.","whyWrong":"0 seria compatível com make ou let, não com esta construção de get; 2 faria do aluno um objeto passivo sem sentido; 3 não completa a estrutura padrão.","reviewHint":"Associe get someone to do a conseguir/persuadir alguém a realizar uma ação.","contentId":"en-modals"},{"id":"m45-en-modals-12","subject":"Inglês","topic":"Modals and passive voice","subtopic":"causative have/get something done","prompt":"We had the navigation system ___ before departure.","options":["calibrate","to calibrate","calibrated","calibrating"],"answer":2,"explanation":"Em have + coisa + particípio, a coisa recebe o serviço: had the navigation system calibrated. A frase significa que providenciamos a calibração, não que o sistema realizou a ação.","difficulty":"avançada","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette)/05%3A_Book_5/5.07%3A_The_Causative_and_Sensory_Verbs — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette)/05%3A_Book_5/5.07%3A_The_Causative_and_Sensory_Verbs — calibração apenas; questão autoral/similar; não oficial.","skill":"formar a causativa de serviço com have + objeto + particípio","commonError":"Usar a forma de base, como se o sistema fosse o agente que calibra.","whyWrong":"0 deixaria o complemento sem marca de serviço recebido; 1 introduz to que não pertence ao padrão; 3 usa gerúndio em lugar do particípio.","reviewHint":"Se o objeto recebe o trabalho de um profissional, use have/get + objeto + past participle.","contentId":"en-modals"},{"id":"m45-en-modals-13","subject":"Inglês","topic":"Modals and passive voice","subtopic":"must not versus do not have to","prompt":"A notice says that wearing a jacket in the room is optional. Which sentence expresses the same meaning?","options":["You must not wear a jacket in the room.","You may not wear a jacket in the room.","You do not have to wear a jacket in the room.","You should not wear a jacket in the room."],"answer":2,"explanation":"Se algo é opcional, a pessoa não tem obrigação de fazê-lo: do not have to wear. Must not e should not indicam proibição ou recomendação negativa; may not pode ser interpretado como não ter permissão.","difficulty":"avançada","sourceBasis":"https://www.sjsu.edu/writingcenter/docs/handouts/Modal%20Verbs.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.sjsu.edu/writingcenter/docs/handouts/Modal%20Verbs.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"interpretar a diferença semântica entre obrigação negativa e proibição","commonError":"Traduzir não precisa como must not, confundindo falta de necessidade com impedimento.","whyWrong":"0 proíbe o uso; 1 tende a retirar a permissão; 3 aconselha contra o uso. Apenas 2 preserva a opcionalidade.","reviewHint":"Opcional = a pessoa pode fazer ou não; em inglês, isso é do not have to.","contentId":"en-modals"},{"id":"m45-en-modals-14","subject":"Inglês","topic":"Modals and passive voice","subtopic":"passive voice and intransitive verbs","prompt":"Which sentence cannot be transformed into a normal passive because its verb has no direct object?","options":["The storm damaged the roof.","The pilot closed the door.","The aircraft arrived at noon.","The mechanic tested the engine."],"answer":2,"explanation":"Arrive é intransitivo no contexto e não seleciona objeto direto; por isso, não há elemento que possa ser promovido a sujeito passivo. As outras orações têm objetos: roof, door e engine.","difficulty":"avançada","sourceBasis":"https://openoregon.pressbooks.pub/coalescence/chapter/grammar-passive-voice-verbs/ e https://ecampusontario.pressbooks.pub/essentialsoflinguistics2/chapter/adding-or-removing-arguments-causatives-and-passives/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://openoregon.pressbooks.pub/coalescence/chapter/grammar-passive-voice-verbs/ e https://ecampusontario.pressbooks.pub/essentialsoflinguistics2/chapter/adding-or-removing-arguments-causatives-and-passives/ — calibração apenas; questão autoral/similar; não oficial.","skill":"verificar a transitividade antes de formar uma voz passiva","commonError":"Supor que toda oração pode virar passiva apenas acrescentando be e particípio.","whyWrong":"0, 1 e 3 possuem objetos diretos que podem ocupar a posição de sujeito passivo; 2 apresenta apenas o verbo arrive e um adjunto de tempo.","reviewHint":"Pergunte ‘o quê?’ ou ‘quem?’ após o verbo; se não houver objeto direto, a passiva comum não se forma.","contentId":"en-modals"},{"id":"m45-en-modals-15","subject":"Inglês","topic":"Modals and passive voice","subtopic":"should have been — unmet expectation in passive","prompt":"The report was due yesterday, but it is still missing. Choose the sentence that expresses the unmet expectation in the passive voice.","options":["The report must be submitted yesterday.","The report should have been submitted yesterday.","The report should be submitted yesterday.","The report may have submitted yesterday."],"answer":1,"explanation":"Uma expectativa não cumprida no passado usa should have + particípio; como o relatório recebe a ação, a forma é should have been submitted. A construção preserva o foco passivo e o prazo anterior.","difficulty":"avançada","sourceBasis":"https://udel.pressbooks.pub/language/chapter/perfect-modals/ e https://udel.pressbooks.pub/language/chapter/active-and-passive-voice/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://udel.pressbooks.pub/language/chapter/perfect-modals/ e https://udel.pressbooks.pub/language/chapter/active-and-passive-voice/ — calibração apenas; questão autoral/similar; não oficial.","skill":"combinar should have com a forma passiva no passado","commonError":"Usar should be e esquecer o caráter passado indicado por yesterday e still missing.","whyWrong":"0 combina must com yesterday de forma inadequada e não expressa expectativa; 2 fala de uma ação presente; 3 omite been e não forma passiva.","reviewHint":"Para expectativa passada não realizada: should have been + past participle.","contentId":"en-modals"},{"id":"m45-en-pronouns-01","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"subject e object pronouns","prompt":"Choose the sentence with the correct personal pronoun:","options":["They invited we yesterday.","They invited us yesterday.","Them invited us yesterday.","They invited our yesterday."],"answer":1,"explanation":"Us é pronome de objeto e vem depois do verbo invited. They é o sujeito; we e them não podem ocupar essas posições na frase apresentada, e our é determinante possessivo, exigindo um substantivo.","difficulty":"intermediária","sourceBasis":"https://opentextbooks.library.arizona.edu/languageawareness/chapter/pronouns/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://opentextbooks.library.arizona.edu/languageawareness/chapter/pronouns/ — calibração apenas; questão autoral/similar; não oficial.","skill":"distinguir pronomes pessoais de sujeito e de objeto pela função sintática","commonError":"Escolher a forma de sujeito apenas porque ela parece mais familiar.","whyWrong":"0 usa we depois do verbo; 2 usa them como se fosse sujeito; 3 usa our sem substantivo e com função inadequada.","reviewHint":"Isole o termo: diga They invited ___. A forma natural é us.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-02","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"possessive determiners e possessive pronouns","prompt":"Complete the sentence with the correct pair: This is ___ checklist; the one on the desk is ___.","options":["our / ours","ours / our","us / ours","our / us"],"answer":0,"explanation":"Our acompanha o substantivo checklist e, portanto, é determinante possessivo. Ours aparece sozinho e substitui the one belonging to us, por isso é pronome possessivo.","difficulty":"intermediária","sourceBasis":"https://edifes.ifes.edu.br/images/stories/Ingles_Comunicativo-Sanda_Bassani.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://edifes.ifes.edu.br/images/stories/Ingles_Comunicativo-Sanda_Bassani.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"diferenciar determinante possessivo de pronome possessivo","commonError":"Usar a forma terminada em -s antes do substantivo.","whyWrong":"1 inverte as funções; 2 coloca um pronome de objeto antes de checklist; 3 usa us, que não expressa posse nem pode substituir o grupo nominal.","reviewHint":"Se houver substantivo logo depois, use our; se a palavra ficar sozinha, use ours.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-03","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"reflexive pronouns","prompt":"Choose the correct option: The trainee blamed ___ for skipping the safety check.","options":["herself","her","hers","she"],"answer":0,"explanation":"O sujeito the trainee e o alvo de blamed são a mesma pessoa; por isso, usa-se o reflexivo herself. Her é objeto não reflexivo, hers é possessivo e she é forma de sujeito.","difficulty":"intermediária","sourceBasis":"https://edifes.ifes.edu.br/images/stories/Ingles_Comunicativo-Sanda_Bassani.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://edifes.ifes.edu.br/images/stories/Ingles_Comunicativo-Sanda_Bassani.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer correferência entre sujeito e objeto","commonError":"Escolher her por traduzir o pronome como objeto, sem notar que a pessoa é a mesma.","whyWrong":"1 não marca a correferência; 2 indica posse, não o alvo da culpa; 3 é pronome de sujeito e não segue o verbo nessa posição.","reviewHint":"Pergunte quem culpou quem. Se a resposta for a própria trainee, use herself.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-04","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"demonstratives","prompt":"The speaker points to three instruments beside her and says: \"___ are ready for testing.\" Which demonstrative completes the sentence?","options":["This","That","These","It"],"answer":2,"explanation":"These é o demonstrativo plural para itens próximos. This é singular próximo, that é singular distante e it é pronome pessoal singular.","difficulty":"intermediária","sourceBasis":"https://opentextbooks.library.arizona.edu/languageawareness/chapter/pronouns/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://opentextbooks.library.arizona.edu/languageawareness/chapter/pronouns/ — calibração apenas; questão autoral/similar; não oficial.","skill":"relacionar número e distância à escolha de demonstrativos","commonError":"Confundir proximidade com número e escolher this para qualquer referente perto.","whyWrong":"0 é singular; 1 é singular e associa distância; 3 não funciona como demonstrativo plural.","reviewHint":"Primeiro conte o referente: três exige a forma plural these/those; depois verifique a distância.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-05","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"articles a/an","prompt":"Choose the correct articles: She is ___ honest analyst who works at ___ European laboratory.","options":["a / an","an / a","an / an","a / a"],"answer":1,"explanation":"Honest começa com som de vogal porque o h não é pronunciado, então recebe an. European começa com som consonantal /j/, apesar de começar pela letra E, então recebe a.","difficulty":"intermediária","sourceBasis":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","skill":"selecionar a e an pela pronúncia inicial","commonError":"Escolher o artigo olhando somente para a letra inicial.","whyWrong":"0 trata honest como som consonantal e European como som vocálico; 2 erra European; 3 erra honest.","reviewHint":"Leia a primeira sílaba em voz alta: a regra é fonética, não ortográfica.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-06","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"quantifiers e countability","prompt":"Complete correctly: We do not have ___ information, but there are ___ possible routes.","options":["many / much","much / many","few / little","a few / a little"],"answer":1,"explanation":"Information é normalmente incontável e combina com much; routes é contável plural e combina com many. A distinção depende da contabilidade do substantivo.","difficulty":"intermediária","sourceBasis":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","skill":"associar quantificadores a substantivos contáveis e incontáveis","commonError":"Traduzir much e many como se a escolha dependesse apenas de quantidade grande ou pequena.","whyWrong":"0 inverte as combinações; 2 e 3 usam quantificadores de pequena quantidade e ainda não correspondem às classes dos nomes.","reviewHint":"Classifique primeiro: information não tem plural regular; routes está no plural contável.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-07","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"relative pronouns","prompt":"Choose the relative pronoun: The operator ___ monitors the radar works at night.","options":["who","which","whose","where"],"answer":0,"explanation":"O antecedente é uma pessoa, the operator, e o relativo exerce a função de sujeito de monitors; who é a escolha adequada. Which se refere normalmente a coisas, whose indica posse e where indica lugar.","difficulty":"intermediária","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette)/01%3A_Book_1/1.05%3A_Parts_of_Speech/1.5.04%3A_Pronouns — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette)/01%3A_Book_1/1.05%3A_Parts_of_Speech/1.5.04%3A_Pronouns — calibração apenas; questão autoral/similar; não oficial.","skill":"identificar antecedente e função de um pronome relativo","commonError":"Escolher which apenas porque a oração fala de um equipamento ou atividade técnica.","whyWrong":"1 não corresponde ao antecedente humano; 2 acrescenta posse inexistente; 3 é marcador de lugar, não relativo pessoal nessa estrutura.","reviewHint":"Veja quem monitora o radar: o operador. A pessoa que faz a ação é retomada por who.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-08","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"relative pronouns e posse","prompt":"Complete the sentence: The engineer ___ prototype was tested thanked the laboratory team.","options":["who","which","that","whose"],"answer":3,"explanation":"Whose introduz uma relação de posse: o protótipo pertence ou está associado ao engenheiro. A estrutura é whose + noun, aqui whose prototype. Who, which e that não expressam essa posse nessa posição.","difficulty":"avançada","sourceBasis":"https://opentextbooks.library.arizona.edu/languageawareness/chapter/pronouns/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://opentextbooks.library.arizona.edu/languageawareness/chapter/pronouns/ — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer posse dentro de uma oração relativa","commonError":"Usar who porque o antecedente é uma pessoa, ignorando o substantivo possuído.","whyWrong":"0 e 2 poderiam introduzir uma oração em outras funções, mas não determinam prototype; 1 é usado normalmente para coisas e também não marca posse.","reviewHint":"Pergunte: de quem era o prototype? A resposta exige whose antes do nome.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-09","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"each/every e concordância","prompt":"Choose the correct verb: Each of the sensors ___ calibrated before the flight.","options":["have been","has been","are","were"],"answer":1,"explanation":"Each distribui a atenção por cada sensor individualmente e exige verbo singular. Por isso, a forma correta é has been calibrated, embora sensors esteja no plural depois de of.","difficulty":"avançada","sourceBasis":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","skill":"estabelecer concordância pelo núcleo each, não pelo termo de of","commonError":"Fazer o verbo concordar com sensors, o substantivo mais próximo.","whyWrong":"0, 2 e 3 são formas plurais; a expressão each of the sensors tem núcleo singular e requer has been.","reviewHint":"Retire o trecho of the sensors: Each has been calibrated.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-10","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"indefinite pronouns e concordância","prompt":"Complete correctly: Neither of the proposals ___ feasible under the current budget.","options":["are","is","were","have been"],"answer":1,"explanation":"Neither é pronome distributivo singular no padrão cobrado, portanto recebe is. O grupo of the proposals especifica as opções, mas não muda o núcleo da concordância.","difficulty":"avançada","sourceBasis":"https://opentextbooks.library.arizona.edu/languageawareness/chapter/pronouns/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://opentextbooks.library.arizona.edu/languageawareness/chapter/pronouns/ — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer o núcleo singular de neither of","commonError":"Usar are por influência do plural proposals.","whyWrong":"0 e 2 são plurais; 3 também é plural e ainda cria uma forma verbal incompatível com neither no padrão da questão.","reviewHint":"Reescreva como Neither proposal is feasible; depois acrescente of the proposals.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-11","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"zero article e referência específica","prompt":"Choose the pair that correctly expresses specific water first and water in general second: ___ water in this tank is safe, but ___ water is essential for life.","options":["The / the","Ø / the","The / Ø","A / Ø"],"answer":2,"explanation":"The water in this tank é uma quantidade específica identificada pelo complemento. Na segunda ocorrência, water é incontável e usado em sentido geral, portanto fica sem artigo (Ø). A não pode acompanhar water nesse uso.","difficulty":"avançada","sourceBasis":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","skill":"distinguir referência específica de generalização com substantivo incontável","commonError":"Repetir the por achar que toda retomada exige artigo definido.","whyWrong":"0 particulariza também a ideia geral; 1 inverte especificidade e generalidade; 3 usa a com incontável e não marca a primeira referência específica.","reviewHint":"Pergunte qual água: a do tanque. Depois pergunte se a segunda frase fala de uma porção ou da substância em geral.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-12","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"quantifiers e countability avançada","prompt":"Choose the correct pair: The lab has too ___ equipment and not ___ spare batteries.","options":["many / much","much / many","few / little","a little / a few"],"answer":1,"explanation":"Equipment é incontável, por isso combina com much; batteries é contável plural, por isso combina com many. A estrutura too much/not many mantém a distinção de contabilidade.","difficulty":"avançada","sourceBasis":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://oer.galileo.usg.edu/english-textbooks/14/ — calibração apenas; questão autoral/similar; não oficial.","skill":"aplicar quantificadores em estruturas de excesso e insuficiência","commonError":"Escolher many por associá-lo a qualquer quantidade de objetos do laboratório.","whyWrong":"0 inverte os quantificadores; 2 e 3 expressam pequena quantidade, mas não se ajustam às estruturas too e not nem às classes nominais.","reviewHint":"Ignore por um instante too/not: equipment pede much e batteries pede many.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-13","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"object pronouns e possessive determiners","prompt":"Complete the sentence: The supervisor asked Ana and ___ to review ___ own notes.","options":["me / their","I / our","me / our","I / their"],"answer":0,"explanation":"Ana e me formam o objeto de asked, logo se usa me. O possessivo se refere a Ana e a mim conjuntamente, então their own notes é a forma coerente com o plural do grupo.","difficulty":"avançada","sourceBasis":"https://edifes.ifes.edu.br/images/stories/Ingles_Comunicativo-Sanda_Bassani.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://edifes.ifes.edu.br/images/stories/Ingles_Comunicativo-Sanda_Bassani.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"resolver simultaneamente caso pronominal e posse em coordenação","commonError":"Usar I depois de asked ou our por traduzir literalmente a primeira pessoa do grupo.","whyWrong":"1 e 3 usam I como objeto; 2 acerta me, mas our não concorda com Ana e me como grupo plural e não é o determinante esperado para esse referente.","reviewHint":"Separe as lacunas: Ana and ___ = objeto; ___ notes pertence a duas pessoas.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-14","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"non-restrictive relative clauses","prompt":"Choose the correct relative pronoun: The satellite, ___ was launched in June, is transmitting normally.","options":["that","who","which","whose"],"answer":2,"explanation":"A oração está entre vírgulas e acrescenta informação explicativa sobre um objeto, satellite. Em oração relativa não restritiva, which é adequado; that não é usado nesse padrão, who é para pessoas e whose marcaria posse.","difficulty":"avançada","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette)/01%3A_Book_1/1.05%3A_Parts_of_Speech/1.5.04%3A_Pronouns — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette)/01%3A_Book_1/1.05%3A_Parts_of_Speech/1.5.04%3A_Pronouns — calibração apenas; questão autoral/similar; não oficial.","skill":"distinguir oração relativa explicativa pela pontuação e pelo antecedente","commonError":"Usar that para qualquer oração relativa, inclusive depois de vírgula.","whyWrong":"0 não é a opção padrão em non-restrictive clauses; 1 refere-se a pessoa; 3 indica posse e não apenas retomada do satellite.","reviewHint":"As vírgulas mostram que a informação é extra; para coisa nesse caso, use which.","contentId":"en-pronouns"},{"id":"m45-en-pronouns-15","subject":"Inglês","topic":"Pronouns and determiners","subtopic":"all of e concordância com countability","prompt":"Choose the correct pair: All of the equipment ___ ready, but all of the tools ___ labeled.","options":["is / are","are / is","is / is","are / are"],"answer":0,"explanation":"Equipment é incontável e recebe verbo singular: is. Tools é contável plural e recebe are. O determinante all não elimina a necessidade de concordar com o nome que o segue.","difficulty":"avançada","sourceBasis":"https://opentextbooks.library.arizona.edu/languageawareness/chapter/pronouns/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://opentextbooks.library.arizona.edu/languageawareness/chapter/pronouns/ — calibração apenas; questão autoral/similar; não oficial.","skill":"combinar all of com a concordância de nomes incontáveis e plurais","commonError":"Usar are automaticamente depois de all, sem classificar o substantivo.","whyWrong":"1 inverte as duas concordâncias; 2 trata tools como singular; 3 trata equipment como plural.","reviewHint":"Faça dois testes: equipment funciona como information; tools tem plural visível e exige are.","contentId":"en-pronouns"},{"id":"m45-en-reading-01","subject":"Inglês","topic":"Reading","subtopic":"main idea","prompt":"Read the text and choose the main idea.\nText: The neighborhood library recently tested a weekly Quiet Hour from 8:00 to 9:00 a.m. Lights stayed on, but no overhead announcements were made, and patrons were asked to silence devices. Many visitors reported better focus; a few parents with toddlers said the time was not ideal. Overall attendance did not drop, and staff used the low-noise window to trial new shelf layouts without disrupting others.\nQuestion: What is the main idea of the text?","options":["The library imposed a full phone ban that drove people away.","Early opening hours are described as harmful to families with children.","A short weekly quiet period improved focus, had some trade-offs, and let staff experiment.","New furniture was the key reason patrons stayed longer in the library."],"answer":2,"explanation":"The text centers on the Quiet Hour as a small change that improved focus, had mixed reception among some parents, and allowed staff to test layouts. This synthesizes benefits and trade-offs. No full phone ban or attendance drop is mentioned, and furniture is not the focus.","difficulty":"intermediária","sourceBasis":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading comprehension — main idea","commonError":"Confundir um detalhe (pais com toddlers) com a ideia central ou inferir proibições totais não mencionadas.","whyWrong":"A: Exagera para um banimento total e queda de público, não citados. B: Foca em um grupo específico; o texto não diz que o horário é \"harmful\"; apenas que não é ideal para alguns. D: Atribui o efeito principal a \"furniture\"; o texto fala em layout testing, não em ser a principal razão de permanência.","reviewHint":"Para ideia principal, combine a primeira apresentação da medida com o resultado global e evite detalhes que descrevem apenas um grupo.","contentId":"en-reading"},{"id":"m45-en-reading-02","subject":"Inglês","topic":"Reading","subtopic":"supporting detail","prompt":"Read the notice and select the statement that is explicitly stated.\nText: Orientation for the online course is mandatory. The live session is on Tuesday, 5 March, from 18:30 to 20:00 (Brasília time). A join link will be sent to confirmed students. Keep an ID handy for verification. Questions may be submitted via the form until Monday at 12:00.\nQuestion: Which statement is explicitly stated in the text?","options":["The orientation lasts 90 minutes.","Late arrivals will be blocked automatically.","The session will take place on Zoom.","International students have a separate session."],"answer":0,"explanation":"From 18:30 to 20:00 is 90 minutes, which is explicitly stated. The platform (Zoom) is not specified; blocking late arrivals and separate sessions for international students are not mentioned.","difficulty":"intermediária","sourceBasis":"https://opentextbc.ca/abealf2/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://opentextbc.ca/abealf2/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — scanning for specific detail","commonError":"Inferir plataforma ou regras punitivas com base em experiências prévias em vez de ler o que está no texto.","whyWrong":"B: Não há menção a bloqueio automático. C: A plataforma não é citada. D: O aviso não separa turmas por nacionalidade.","reviewHint":"Sublinhe números, horários e verbos de obrigação; confirme se a informação está literalmente no texto.","contentId":"en-reading"},{"id":"m45-en-reading-03","subject":"Inglês","topic":"Reading","subtopic":"inference (cause/implication)","prompt":"Read the report and infer the most reasonable conclusion.\nText: Our volunteer program struggled with training attendance when sessions were scheduled on weekday mornings. After moving training to early evenings, average attendance doubled and late withdrawals declined sharply, even though the content and duration stayed the same.\nQuestion: What can most reasonably be inferred from the change in results?","options":["The training became easier to pass after the change.","Volunteers were paid to attend evening sessions.","Evening timing aligned better with volunteers’ availability.","The new schedule reduced the length of the training."],"answer":3,"explanation":"Attendance doubled and withdrawals fell with only timing changed. The most reasonable inference is that evenings fit volunteer availability better. No evidence supports pay, easier content, or shorter sessions.","difficulty":"intermediária","sourceBasis":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — inference from stated contrasts","commonError":"Assumir mudanças em conteúdo/duração não declaradas ou inferir incentivos financeiros sem base textual.","whyWrong":"A: O texto afirma que o conteúdo permaneceu o mesmo. B: Não há menção a pagamento. D: A duração não mudou, segundo o texto.","reviewHint":"Quando só uma variável muda (horário), atribua o efeito a ela, evitando supor alterações não citadas.","contentId":"en-reading"},{"id":"m45-en-reading-04","subject":"Inglês","topic":"Reading","subtopic":"pronoun reference","prompt":"Read the excerpt and identify what the pronoun refers to. (Em português: referência pronominal.)\nText: Some safety guidelines are universal; those published before 2010 were archived and replaced with a single, updated document.\nQuestion: In the sentence, what does \"those\" refer to?","options":["the guidelines","the experts","the updates","the archives"],"answer":1,"explanation":"\"Those\" refers back to the plural noun \"guidelines\" mentioned immediately before. It cannot refer to experts, updates, or archives because only guidelines fit both number and context (published before 2010).","difficulty":"intermediária","sourceBasis":"https://openstax.org/books/writing-guide/pages/handbook — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://openstax.org/books/writing-guide/pages/handbook — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — resolving pronoun reference","commonError":"Tomar \"those\" como algo novo no texto ou como documento atualizado, quando o demonstrativo remete ao antecedente plural imediato.","whyWrong":"B: \"experts\" não aparecem no trecho. C: \"updates\" foram posteriores, não \"publicadas antes de 2010\". D: \"archives\" é lugar/estado, não algo que foi publicado.","reviewHint":"Procure o antecedente plural mais próximo que concorde em número e sentido com o modificador \"published before 2010\".","contentId":"en-reading"},{"id":"m45-en-reading-05","subject":"Inglês","topic":"Reading","subtopic":"author’s purpose","prompt":"Read the passage and determine the author’s primary purpose.\nText: Checklists may look simplistic, yet they consistently prevent avoidable errors in complex work. By forcing us to pause at critical steps, they reduce memory slips and coordination gaps. Pilots and surgical teams have documented better outcomes after adopting concise, well-tested lists. Skipping a checklist to save a minute is a false economy.\nQuestion: What is the author’s main purpose in writing this passage?","options":["To entertain readers with humorous stories about checklists.","To persuade readers to adopt concise, tested checklists.","To narrate the author’s first experience as a pilot.","To compare aviation and medicine without taking a stance."],"answer":2,"explanation":"The passage argues that checklists prevent errors and improve outcomes, urging adoption; this is persuasive. It is not humorous entertainment, a personal narrative, or a neutral comparison.","difficulty":"avançada","sourceBasis":"https://openstax.org/books/writing-guide/pages/handbook — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://openstax.org/books/writing-guide/pages/handbook — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — identifying author’s purpose","commonError":"Confundir exemplos de áreas (pilotos, cirurgias) com comparação neutra entre campos.","whyWrong":"A: Não há humor ou anedotas. C: Não é uma narrativa pessoal. D: O texto toma posição clara a favor de checklists, não é neutro.","reviewHint":"Observe verbos avaliativos (prevent, reduce) e julgamentos (false economy) que sinalizam intenção persuasiva.","contentId":"en-reading"},{"id":"m45-en-reading-06","subject":"Inglês","topic":"Reading","subtopic":"tone/attitude","prompt":"Read the paragraph and choose the option that best describes the tone.\nText: Using algorithms to screen job applications can reduce bias in theory, but only if companies audit the data and monitor outcomes. The tools should be tested, limited in scope, and open to challenge. Automation without accountability simply scales old mistakes.\nQuestion: What is the tone of the paragraph?","options":["Cautiously optimistic about algorithmic screening","Uncritically enthusiastic about automation","Detached and purely descriptive","Dismissive of all technological tools"],"answer":0,"explanation":"The writer sees potential benefits if strict safeguards exist, warning against unaccountable use. That is cautiously optimistic. It is not uncritical enthusiasm, not neutral description, and not a total rejection of technology.","difficulty":"avançada","sourceBasis":"https://openstax.org/books/writing-guide/pages/handbook — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://openstax.org/books/writing-guide/pages/handbook — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — identifying tone/attitude","commonError":"Ler as advertências como rejeição total em vez de prudência condicional.","whyWrong":"B: Ignora as condições e auditorias mencionadas. C: Há avaliações claras (should, simply scales old mistakes). D: O texto não rejeita toda tecnologia; condiciona seu uso responsável.","reviewHint":"Palavras de condição (if, should) e alertas indicam prudência; elogios sem reservas indicariam entusiasmo.","contentId":"en-reading"},{"id":"m45-en-reading-07","subject":"Inglês","topic":"Reading","subtopic":"organization/structure","prompt":"Read the passage and identify how it is organized.\nText: The city’s recycling rate has stalled over the past two years, largely because residents are confused about what belongs in the blue bins. To address this, the sanitation department tested two interventions: clearer bin labels and a text-message reminder on pickup days. Labels reduced contamination modestly, while reminders led to a larger improvement, especially in buildings with many tenants.\nQuestion: Which option best describes the organization of the passage?","options":["Chronological narration of events across many years","Simple cause-effect with no evaluation of alternatives","Definition followed by unrelated examples","Problem, two solutions tested, and comparative evaluation"],"answer":3,"explanation":"The text sets a problem (stalled rates, confusion), presents two solutions (labels, reminders), and evaluates which worked better. It is not a long chronology, not a single cause-effect without comparison, and not a definition with unrelated examples.","difficulty":"avançada","sourceBasis":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — recognizing text organization","commonError":"Marcar \"cause-effect\" sem notar a comparação entre soluções.","whyWrong":"A: Não há linha temporal extensa. B: Há comparação entre duas intervenções, não um único efeito. C: O texto não define termo algum; os exemplos são diretamente ligados.","reviewHint":"Identifique frases que introduzem um problema e, em seguida, múltiplas respostas com avaliação comparativa.","contentId":"en-reading"},{"id":"m45-en-reading-08","subject":"Inglês","topic":"Reading","subtopic":"vocabulary in context (cognate trap)","prompt":"Read the sentence and choose the best meaning of the word in context. (Atenção ao falso cognato.)\nText: The team struggled for weeks, but they eventually found a stable configuration for the server.\nQuestion: In this sentence, \"eventually\" most nearly means:","options":["soon","in the end","by chance","frequently"],"answer":1,"explanation":"\"Eventually\" means \"in the end/after some time.\" It does not mean \"soon\" (em breve), nor \"by chance\" (por acaso), nor \"frequently\" (frequentemente). In Portuguese, \"eventualmente\" can mean \"perhaps/occasionally,\" which is a trap.","difficulty":"intermediária","sourceBasis":"https://opentextbc.ca/abealf2/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://opentextbc.ca/abealf2/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — vocabulary in context","commonError":"Traduzir literalmente \"eventualmente\" como \"talvez/ocasionalmente\" e errar o sentido temporal de conclusão.","whyWrong":"A: Inverte a ideia de demora. C: Confunde com \"por acaso\". D: Sugere repetição, ausente no contexto.","reviewHint":"Substitua mentalmente por sinônimos e verifique se a lógica da frase (após semanas) combina com \"in the end\".","contentId":"en-reading"},{"id":"m45-en-reading-09","subject":"Inglês","topic":"Reading","subtopic":"connector function","prompt":"Read the sentence and identify the function of the connector. (Em português: função do conector.)\nText: While the new app reduces paperwork, it also raises privacy concerns.\nQuestion: In this sentence, \"while\" primarily expresses:","options":["time (simultaneity)","contrast between two ideas","cause and effect","condition"],"answer":2,"explanation":"Here, \"while\" contrasts benefits with concerns. It is not used for time, cause, or condition in this context.","difficulty":"intermediária","sourceBasis":"https://openstax.org/books/writing-guide/pages/handbook — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://openstax.org/books/writing-guide/pages/handbook — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — understanding connectors in context","commonError":"Assumir sempre valor temporal para \"while\" e ignorar seu uso contrastivo frequente em textos argumentativos.","whyWrong":"A: Nada indica simultaneidade temporal; o foco é contraste. C: Não há nexo causal explicitado. D: Não é uma condição (if).","reviewHint":"Verifique se as ideias são opostas/complementares; \"while\" frequentemente introduz contraste em argumentos.","contentId":"en-reading"},{"id":"m45-en-reading-10","subject":"Inglês","topic":"Reading","subtopic":"reference with demonstratives (this/that)","prompt":"Read the lines and decide what \"This\" refers to. (Em português: referência de \"This\".)\nText: He reset the router, cleared the browser cache, and tried a wired connection. This restored access for the entire team.\nQuestion: In the second sentence, \"This\" refers to:","options":["the sequence of troubleshooting steps taken","the wired connection only","the router hardware itself","the team’s support request"],"answer":0,"explanation":"\"This\" summarizes the preceding set of actions as a whole, not just one of them. It does not refer to the router as a device or to the request; it denotes the combined troubleshooting that produced the result.","difficulty":"avançada","sourceBasis":"https://openstax.org/books/writing-guide/pages/handbook — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://openstax.org/books/writing-guide/pages/handbook — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — resolving demonstrative reference","commonError":"Atribuir \"This\" ao último item da lista por proximidade, ignorando o uso anafórico resumidor.","whyWrong":"B: Reduz indevidamente a referência a um único passo. C: O hardware não \"restaurou\" nada por si só; foi a ação. D: A solicitação não restaurou o acesso; as ações o fizeram.","reviewHint":"Pergunte-se se o pronome retoma uma ideia completa (resumo) ou um substantivo específico; ações em série costumam ser resumidas por \"This/That\".","contentId":"en-reading"},{"id":"m45-en-reading-11","subject":"Inglês","topic":"Reading","subtopic":"inference with negation/quantifiers","prompt":"Read the statement and choose the inference supported by the text.\nText: No study reviewed by the panel concluded that the drug was effective for adolescents, although several noted slight improvements in sleep.\nQuestion: Which inference is supported?","options":["None of the reviewed studies found the drug effective for adolescents.","The panel recommended the drug for all teens.","The drug caused serious harm in most cases.","The sleep improvements were large and clinically decisive."],"answer":1,"explanation":"\"No study concluded effective\" supports that none found effectiveness. The text does not state a recommendation, harm, or the magnitude being large; it only mentions slight improvements in sleep.","difficulty":"avançada","sourceBasis":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — careful inference with negation","commonError":"Ignorar a negação com \"No study\" ou superestimar \"slight\" como se fosse efetividade geral.","whyWrong":"B: Não há recomendação. C: Não há menção a dano sério. D: O texto diz \"slight\" (pequenas), não grandes melhoras.","reviewHint":"Palavras como \"no, none, not\" e qualificadores como \"slight\" limitam fortemente as conclusões; não extrapole.","contentId":"en-reading"},{"id":"m45-en-reading-12","subject":"Inglês","topic":"Reading","subtopic":"best title/main focus","prompt":"Read the paragraph and select the best title.\nText: When campuses moved lab courses online, instructors replaced shared equipment with household experiments, live demos, and mailed kits. These substitutions couldn’t fully mirror in-person labs, but they kept core habits—hypothesis, measurement, reflection—alive. The most successful courses explained limitations transparently and assessed process rather than polished outcomes.\nQuestion: Which title best captures the paragraph’s focus?","options":["Perfecting Online Labs with Identical Results","Why Remote Labs Cannot Teach Any Real Skills","Making Lab Learning Work Online Through Process-Focused Design","The History of Science Kits in Distance Education"],"answer":3,"explanation":"The paragraph argues for preserving lab habits online and emphasizes process-focused design and transparency. It does not claim perfection or impossibility, nor does it narrate a historical survey.","difficulty":"avançada","sourceBasis":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — identifying best title","commonError":"Escolher títulos extremos (perfeito/impossível) por parecerem fortes, mas desalinhados ao tom equilibrado.","whyWrong":"A: \"Perfecting\" e resultados idênticos não são defendidos. B: Não afirma impossibilidade; há estratégias eficazes. D: Não é histórico; é sobre prática pedagógica atual.","reviewHint":"Procure palavras-chave sobre foco (hábitos, processo, transparência) e evite extremos não sustentados.","contentId":"en-reading"},{"id":"m45-en-reading-13","subject":"Inglês","topic":"Reading","subtopic":"paraphrase/equivalence of meaning","prompt":"Read the sentence and choose the option that best paraphrases it without changing the meaning. (Em português: paráfrase equivalente.)\nText: Unless the permits are approved this week, the launch will not proceed next month.\nQuestion: Which option is the best paraphrase?","options":["If the permits are approved this week, the launch will be canceled next month.","If the permits are not approved this week, the launch will be postponed beyond next month.","Even if the permits are approved this week, the launch will be delayed until next month.","Because the permits were approved last week, the launch will proceed next month."],"answer":2,"explanation":"\"Unless X, Y will not happen\" equals \"If not X, Y will be postponed/not proceed.\" Option B preserves the condition and outcome. The others invert time, add \"even if,\" or assume past approval.","difficulty":"intermediária","sourceBasis":"https://open.umn.edu/opentextbooks/textbooks/college-esl-writers-applied-grammar-and-composing-strategies-for-success — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://open.umn.edu/opentextbooks/textbooks/college-esl-writers-applied-grammar-and-composing-strategies-for-success — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — recognizing paraphrase equivalence","commonError":"Trocar \"unless\" por \"even if\" ou inverter a condição e o resultado temporal.","whyWrong":"A: Contradiz a relação; aprovar esta semana não cancela. C: \"Even if\" altera a lógica. D: Muda o tempo e afirma algo não dito (aprovado na semana passada).","reviewHint":"Reescreva \"Unless A, B not\" como \"If not A, not B\" e verifique tempos e prazos mantendo o sentido.","contentId":"en-reading"},{"id":"m45-en-reading-14","subject":"Inglês","topic":"Reading","subtopic":"assumption (argument analysis)","prompt":"Read the argument and identify a necessary assumption.\nText: If the campus bans student cars but increases shuttle frequency, congestion near classroom buildings will drop. With more frequent shuttles, students will have a reliable alternative to driving, so traffic will ease during peak hours.\nQuestion: Which assumption is necessary for the argument to hold?","options":["Most students will switch to shuttles if they are convenient.","Faculty will also stop driving to campus immediately.","New parking garages will be built near classrooms.","Shuttle rides will be free only for first-year students."],"answer":0,"explanation":"The argument depends on students actually using the more frequent shuttles when cars are banned; otherwise traffic might not ease. Faculty behavior, garage construction, or first-year pricing are not required by the reasoning presented.","difficulty":"avançada","sourceBasis":"https://openstax.org/books/writing-guide/pages/handbook — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://openstax.org/books/writing-guide/pages/handbook — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — identifying assumptions in arguments","commonError":"Confundir detalhes de política (preço, docentes) com a suposição central sobre adesão estudantil.","whyWrong":"B: O argumento fala de estudantes, não exige mudança imediata de docentes. C: Garagens novas não são premissa necessária. D: Preço especial para calouros não é mencionado nem essencial.","reviewHint":"Pergunte: o que precisa ser verdade para que o efeito ocorra? Geralmente, é a adesão/comportamento do grupo-alvo.","contentId":"en-reading"},{"id":"m45-en-reading-15","subject":"Inglês","topic":"Reading","subtopic":"scanning/time interpretation","prompt":"Read the announcement and choose the correct statement. (Em português: atenção a fuso horário.)\nText: Webinar date and time: 16 August, 18:00–19:30 Lisbon time (UTC+1). For São Paulo (UTC−3), the webinar runs 14:00–15:30. The access link will be emailed by 11:00 São Paulo time on the event day, only to registered participants.\nQuestion: Which statement is correct according to the announcement?","options":["In São Paulo, the webinar ends at 4:30 p.m.","The access link is sent by 11:00 Lisbon time.","The webinar starts at 5:00 p.m. in Lisbon.","Only registered participants will receive the access link."],"answer":1,"explanation":"The notice states the São Paulo time as 14:00–15:30, so it ends at 3:30 p.m., not 4:30. The link is sent by 11:00 São Paulo time, not Lisbon time. The Lisbon start is 18:00 (6:00 p.m.), not 5:00 p.m. It also says the link is emailed only to registered participants.","difficulty":"avançada","sourceBasis":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — calibração apenas; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Reading — scanning and interpreting time zones","commonError":"Ignorar o fuso e projetar horário local; confundir o horário de envio do link.","whyWrong":"A: Termina às 15:30 em São Paulo, não às 16:30. B: O envio é às 11:00 no horário de São Paulo. C: Começa às 18:00 em Lisboa, não às 17:00. D: Correto: apenas inscritos recebem o link; as demais estão incorretas.","reviewHint":"Converta mentalmente os horários comparando UTC+1 e UTC−3 e verifique quem recebe o link e em qual fuso é enviado. (14:00–15:30 SP; link 11:00 SP.)","contentId":"en-reading"},{"id":"m45-en-reported-01","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"backshift em afirmações","prompt":"Choose the correct reported version: Maya said, \"I am checking the figures here today.\"","options":["Maya said that she was checking the figures there that day.","Maya said that I am checking the figures here today.","Maya said that she is checking the figures there today.","Maya said that she had checked the figures here that day."],"answer":0,"explanation":"Com said no passado, am checking normalmente recua para was checking; I muda para she e, em um relato deslocado, here/today passam a there/that day.","difficulty":"intermediária","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/High-Intermediate_Academic_Grammar_for_ESL_Students_(Al_Haider) — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/High-Intermediate_Academic_Grammar_for_ESL_Students_(Al_Haider) — calibração apenas; questão autoral/similar; não oficial.","skill":"aplicar backshift e ajustar pronomes e dêiticos em uma afirmação relatada","commonError":"Fazer somente a troca de tempo ou manter a perspectiva de pessoa, lugar e tempo da fala original.","whyWrong":"1 mantém I e a estrutura direta; 2 mantém presente e hoje sem justificar a perspectiva; 3 troca uma ação em andamento por uma ação concluída.","reviewHint":"Marque separadamente o verbo de relato, o sujeito da fala e as expressões here/today antes de transformar.","contentId":"en-reported"},{"id":"m45-en-reported-02","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"modal e tempo verbal","prompt":"Choose the best reported form: Leo said, \"I can finish the task tonight.\" The next morning, the supervisor reported that Leo...","options":["can finish the task tonight.","could finish the task that night.","could have finished the task tonight.","will finish the task the next morning."],"answer":1,"explanation":"No relato no passado, can normalmente recua para could e tonight, visto na manhã seguinte, torna-se that night. Não há informação de que a tarefa já tivesse sido concluída, portanto o perfect não é necessário.","difficulty":"intermediária","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette) — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette) — calibração apenas; questão autoral/similar; não oficial.","skill":"relacionar modais e marcadores temporais na passagem ao discurso indireto","commonError":"Confundir a possibilidade futura relatada com uma ação já concluída.","whyWrong":"0 ignora o backshift; 2 acrescenta uma conclusão passada não informada; 3 usa will e muda tonight para uma manhã posterior sem base.","reviewHint":"Pergunte se a fala original expressa capacidade futura ou resultado concluído; can + verbo não implica perfect.","contentId":"en-reported"},{"id":"m45-en-reported-03","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"yes/no questions","prompt":"Choose the correct indirect question: \"Have you sent the invoice?\" the clerk asked me.","options":["The clerk asked me whether had I sent the invoice.","The clerk asked me that I had sent the invoice.","The clerk asked me whether I had sent the invoice.","The clerk said me if I sent the invoice."],"answer":2,"explanation":"Uma pergunta de sim/não usa if ou whether e, no discurso indireto, a ordem é declarativa: I had sent. Have sent recua para had sent.","difficulty":"intermediária","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/High-Intermediate_Academic_Grammar_for_ESL_Students_(Al_Haider) — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/High-Intermediate_Academic_Grammar_for_ESL_Students_(Al_Haider) — calibração apenas; questão autoral/similar; não oficial.","skill":"converter pergunta de sim/não em oração indireta","commonError":"Preservar a inversão auxiliar-sujeito da pergunta direta.","whyWrong":"0 mantém a inversão; 1 usa that, que não introduz adequadamente uma pergunta de sim/não; 3 combina say com objeto direto e não forma uma pergunta indireta correta.","reviewHint":"Depois de if/whether, leia como uma afirmação: subject + verb, sem do/does/did auxiliar.","contentId":"en-reported"},{"id":"m45-en-reported-04","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"wh-questions e referência temporal","prompt":"At the end of the day, the manager asked Ana, \"Why did you leave the office early?\" Which reported version is correct?","options":["The manager asked Ana why did she leave the office early.","The manager asked Ana why she had left the office early.","The manager asked Ana that why she left the office early.","The manager asked Ana why had she left the office early."],"answer":1,"explanation":"A palavra why é preservada, mas a oração passa à ordem declarativa. Como asked está no passado e a saída ocorreu antes desse momento, past simple recua para past perfect: had left.","difficulty":"avançada","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette) — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette) — calibração apenas; questão autoral/similar; não oficial.","skill":"combinar wh-question, ordem indireta e anterioridade temporal","commonError":"Escolher a alternativa com a palavra interrogativa correta sem verificar a ordem sintática e a cronologia.","whyWrong":"0 e 3 mantêm inversão; 2 insere that junto de why e não constrói uma pergunta; somente 1 apresenta ordem declarativa e anterioridade adequada.","reviewHint":"Em wh-questions indiretas, mantenha wh-, retire a inversão e compare o momento da pergunta com o da ação.","contentId":"en-reported"},{"id":"m45-en-reported-05","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"commands e proibições","prompt":"Choose the correct report of the curator's instruction: \"Do not touch the display,\" the curator told the visitors.","options":["The curator told that the visitors did not touch the display.","The curator said the visitors not to touch the display.","The curator warned the visitors not to touch the display.","The curator asked whether the visitors touched the display."],"answer":2,"explanation":"Uma proibição é relatada com not to + verbo; warned combina com destinatário e ideia de advertência: warned the visitors not to touch.","difficulty":"avançada","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/High-Intermediate_Academic_Grammar_for_ESL_Students_(Al_Haider) — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/High-Intermediate_Academic_Grammar_for_ESL_Students_(Al_Haider) — calibração apenas; questão autoral/similar; não oficial.","skill":"relatar imperativo negativo com verbo de atribuição adequado","commonError":"Tratar uma proibição como uma afirmação no passado ou esquecer o destinatário da ordem.","whyWrong":"0 não expressa a estrutura de comando; 1 usa say sem a construção correta com objeto + infinitivo; 3 transforma a ordem em pergunta. 2 mantém destinatário e proibição.","reviewHint":"Para ordens, procure tell/ask/warn + pessoa + (not) to + verbo base.","contentId":"en-reported"},{"id":"m45-en-reported-06","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"say e tell","prompt":"Complete the sentence correctly: The witness ______ the investigator that she had seen the vehicle.","options":["said","spoke","told","told to"],"answer":2,"explanation":"Tell normalmente recebe a pessoa como objeto direto: told the investigator that... Say pode ocorrer como said that... ou said to the investigator that..., mas said isolado não aceita esse objeto.","difficulty":"avançada","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette) — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette) — calibração apenas; questão autoral/similar; não oficial.","skill":"selecionar reporting verb conforme a função do complemento","commonError":"Traduzir say e tell pela mesma palavra e ignorar a regência do verbo.","whyWrong":"0 exige to antes do destinatário; 1 é intransitivo e não recebe the investigator nesse padrão; 3 acrescenta to indevidamente depois de told. Apenas told recebe diretamente a pessoa seguida de that.","reviewHint":"Memorize os moldes: say something/to someone; tell someone something.","contentId":"en-reported"},{"id":"m45-en-reported-07","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"verdades gerais e ausência de backshift","prompt":"Which sentence best reports a scientific fact? The teacher said, \"Water boils at 100°C at sea level.\"","options":["The teacher said that water boiled at 100°C at sea level, presenting it as a current fact.","The teacher said that water had boiled at 100°C at sea level, presenting it as a current fact.","The teacher told that water boils at 100°C at sea level.","The teacher asked whether water boils at 100°C at sea level."],"answer":0,"explanation":"O presente pode ser mantido porque a afirmação é uma verdade geral apresentada como válida no momento do relato. A alternativa também usa corretamente said that.","difficulty":"intermediária","sourceBasis":"https://openoregon.pressbooks.pub/synthesis/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://openoregon.pressbooks.pub/synthesis/ — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer quando o presente permanece após verbo de relato passado","commonError":"Aplicar o recuo verbal como regra absoluta, mesmo diante de um fato geral atual.","whyWrong":"1 sugere um evento concluído no passado, não uma lei geral; 2 usa told sem destinatário; 3 muda afirmação para pergunta.","reviewHint":"Verifique se o falante trata a proposição como fato ainda válido antes de fazer o backshift.","contentId":"en-reported"},{"id":"m45-en-reported-08","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"zero e first conditional","prompt":"Which option correctly expresses a general result rather than a single future prediction?","options":["If metal will be heated, it expands.","If metal is heated, it expands.","If metal were heated, it would expand every time.","If metal had been heated, it would have expanded now."],"answer":1,"explanation":"A relação geral entre aquecimento e expansão usa zero conditional: if + present simple, present simple. As outras alternativas introduzem futuro inadequado, hipótese distante ou passado contrafactual.","difficulty":"intermediária","sourceBasis":"https://udel.pressbooks.pub/language/chapter/conditional-clauses/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://udel.pressbooks.pub/language/chapter/conditional-clauses/ — calibração apenas; questão autoral/similar; não oficial.","skill":"distinguir zero conditional de condicionais hipotéticas","commonError":"Usar will automaticamente na oração com if ou confundir regra geral com previsão futura.","whyWrong":"0 viola o padrão básico de zero conditional; 2 marca hipótese irreal; 3 cria anterioridade contrafactual sem sentido para a generalização.","reviewHint":"Se o resultado ocorre normalmente sempre que a condição ocorre, use presente + presente.","contentId":"en-reported"},{"id":"m45-en-reported-09","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"third e mixed conditionals","prompt":"Choose the sentence that means the past decision caused a present situation: the person did not accept the offer and does not live abroad now.","options":["If she accepted the offer, she would live abroad now.","If she had accepted the offer, she would have lived abroad then.","If she had accepted the offer, she would live abroad now.","If she would have accepted the offer, she lived abroad now."],"answer":2,"explanation":"A condição passada irreal usa had accepted, enquanto a consequência presente usa would live now: é um mixed conditional. A frase traduz a relação temporal proposta.","difficulty":"avançada","sourceBasis":"https://openoregon.pressbooks.pub/synthesis/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://openoregon.pressbooks.pub/synthesis/ — calibração apenas; questão autoral/similar; não oficial.","skill":"interpretar e formar mixed conditional com causa passada e efeito presente","commonError":"Usar second conditional nos dois verbos ou third conditional nos dois verbos sem observar a linha temporal.","whyWrong":"0 trata a decisão como hipótese presente; 1 produz consequência passada; 3 põe would na if-clause e ainda mistura tempos de modo agramatical.","reviewHint":"Separe os tempos: quando ocorreu a condição e quando se verifica o resultado?","contentId":"en-reported"},{"id":"m45-en-reported-10","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"gerund após verbo e preposição","prompt":"Choose the grammatically correct completion: The research team avoided ______ the preliminary result before checking it.","options":["to announce","announce","announcing","announced"],"answer":2,"explanation":"Avoid é seguido por gerund: avoided announcing. A preposição ou o verbo regente determina o padrão; aqui o infinitivo com to não é selecionado.","difficulty":"intermediária","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/High-Intermediate_Academic_Grammar_for_ESL_Students_(Al_Haider) — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/High-Intermediate_Academic_Grammar_for_ESL_Students_(Al_Haider) — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer verb pattern com gerund após avoid","commonError":"Usar to + infinitive depois de qualquer verbo, por influência da tradução para o português.","whyWrong":"0 não é o padrão de avoid; 1 omite a forma exigida; 3 usa passado simples como complemento verbal. A forma nominal em -ing é a adequada.","reviewHint":"Memorize grupos de verbos: avoid, enjoy, suggest e consider normalmente pedem verbo em -ing.","contentId":"en-reported"},{"id":"m45-en-reported-11","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"infinitivo de finalidade","prompt":"Choose the option that expresses purpose: The pilot contacted the tower ______ the route.","options":["confirming","to confirm","confirm","for confirm"],"answer":1,"explanation":"O infinitivo com to pode indicar finalidade: contacted the tower to confirm the route, isto é, contatou a torre com o objetivo de confirmar a rota.","difficulty":"intermediária","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/High-Intermediate_Academic_Grammar_for_ESL_Students_(Al_Haider) — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/High-Intermediate_Academic_Grammar_for_ESL_Students_(Al_Haider) — calibração apenas; questão autoral/similar; não oficial.","skill":"identificar infinitivo de finalidade em contexto","commonError":"Escolher gerúndio porque a ação ocorre depois do verbo principal, sem perceber a ideia de objetivo.","whyWrong":"0 pode sugerir simultaneidade, mas não marca claramente finalidade; 2 é bare infinitive inadequado após a lacuna; 3 não é construção padrão. 1 expressa propósito.","reviewHint":"Parafraseie por in order to; se a paráfrase funcionar, use to + verbo base.","contentId":"en-reported"},{"id":"m45-en-reported-12","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"contraste remember e stop","prompt":"What is the meaning of the sentence: The technician stopped to restart the server?","options":["The technician ceased restarting the server permanently.","The technician interrupted another activity in order to restart the server.","The technician remembered that the server had been restarted.","The technician avoided restarting the server."],"answer":1,"explanation":"Stop + to-infinitive significa interromper uma atividade para realizar outra. Portanto, o técnico parou o que fazia com a finalidade de reiniciar o servidor.","difficulty":"avançada","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette) — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette) — calibração apenas; questão autoral/similar; não oficial.","skill":"interpretar mudança de sentido produzida por stop + infinitive","commonError":"Ler stop to restart como se fosse stop restarting e concluir que a ação de reiniciar terminou.","whyWrong":"0 corresponderia a stop restarting; 2 descreve remember, não stop; 3 confunde interrupção com avoid. 1 preserva a finalidade do infinitivo.","reviewHint":"Compare mentalmente stop doing (cessar a atividade) com stop to do (parar para executar outra).","contentId":"en-reported"},{"id":"m45-en-reported-13","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"gerund e infinitivo após remember","prompt":"Which sentence says that Ana performed the check and later retained the memory of it?","options":["Ana remembered to check the seal.","Ana remembered checking the seal.","Ana remembered check the seal.","Ana remembered to checking the seal."],"answer":1,"explanation":"Remember + gerund apresenta a lembrança de uma ação já realizada: remembered checking. Remember + to-infinitive indica não esquecer uma ação que deveria ser feita.","difficulty":"avançada","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette) — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette) — calibração apenas; questão autoral/similar; não oficial.","skill":"distinguir mudança semântica entre remember + gerund e remember + infinitive","commonError":"Escolher a forma pelo tempo da frase, sem considerar se a lembrança é anterior ou se a ação era uma tarefa futura.","whyWrong":"0 significa lembrar-se de fazer a checagem, sem afirmar que ela foi feita; 2 e 3 são padrões agramaticais; 1 afirma ação realizada e lembrada.","reviewHint":"Pergunte: a pessoa se lembra de uma experiência ou se lembra de cumprir uma obrigação?","contentId":"en-reported"},{"id":"m45-en-reported-14","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"inversão em condicionais formais","prompt":"Which formal sentence is equivalent to If the committee had known the risk, it would have postponed the launch?","options":["Had the committee known the risk, it would have postponed the launch.","Had the committee knew the risk, it would postpone the launch.","Were the committee had known the risk, it would have postponed the launch.","Should the committee had known the risk, it postponed the launch."],"answer":0,"explanation":"Na inversão formal do third conditional, omite-se if e coloca-se had antes do sujeito: Had the committee known... A forma do particípio de know é known.","difficulty":"avançada","sourceBasis":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette) — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/ESL_Grammar_The_Way_You_Like_It_(Bissonnette) — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer inversão formal equivalente ao third conditional","commonError":"Aplicar a inversão sem identificar o auxiliar correto ou misturar had com a forma simples do verbo.","whyWrong":"1 usa knew após had; 2 combina estruturas incompatíveis; 3 usa should, forma verbal e resultado inadequados. 0 mantém a relação contrafactual passada.","reviewHint":"No third conditional invertido, transforme if + subject + had + past participle em Had + subject + past participle.","contentId":"en-reported"},{"id":"m45-en-reported-15","subject":"Inglês","topic":"Reported speech and advanced usage","subtopic":"reporting verbs e gerund/infinitive","prompt":"Choose the correct sentence reporting the employee's suggestion: \"Let's postpone the test,\" the employee said.","options":["The employee suggested to postpone the test.","The employee suggested postponing the test.","The employee suggested us postpone the test.","The employee suggested that postponing the test to."],"answer":1,"explanation":"Suggest aceita gerund diretamente: suggested postponing the test. Também seria possível uma oração com that e sujeito explícito, mas suggest + to-infinitive não é o padrão desta construção.","difficulty":"avançada","sourceBasis":"https://openoregon.pressbooks.pub/synthesis/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://openoregon.pressbooks.pub/synthesis/ — calibração apenas; questão autoral/similar; não oficial.","skill":"usar reporting verb com padrão de gerúndio em paráfrase","commonError":"Aplicar a estrutura tell someone to do a verbos que selecionam gerund, como suggest.","whyWrong":"0 usa to-infinitive após suggest; 2 omite a estrutura possível de oração com that e não forma padrão; 3 deixa a oração incompleta. 1 é a construção idiomática.","reviewHint":"Separe o significado de sugestão da regência: suggest + -ing ou suggest that + sujeito + verbo.","contentId":"en-reported"},{"id":"m45-en-tenses-01","subject":"Inglês","topic":"Verb tenses","subtopic":"present simple vs present progressive (stative vs dynamic)","prompt":"Complete the sentence: Right now, the supervisor ___ the cause of the failure, so he is not starting the test. (atenção: certos verbos estativos não usam forma -ing)","options":["is believing","believe","believes","is believe"],"answer":2,"explanation":"Usamos o present simple com verbos estativos como believe, know, understand. A frase traz o marcador “Right now”, que poderia sugerir -ing, mas o verbo believe não aceita forma progressiva nesse sentido. Portanto, “the supervisor believes the cause...” é a forma correta.","difficulty":"intermediária","sourceBasis":"Explorations 1: Grammar for the Experienced Beginner — Ch. 4 (simple present vs present progressive). CC BY-NC-SA. https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/Explorations_1%3A_Grammar_for_the_Experienced_Beginner; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Explorations 1: Grammar for the Experienced Beginner — Ch. 4 (simple present vs present progressive). CC BY-NC-SA. https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/Explorations_1%3A_Grammar_for_the_Experienced_Beginner; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"aspecto verbal (estativo vs dinâmico) e concordância","commonError":"Aplicar -ing mecanicamente por causa de “right now” mesmo com verbo estativo.","whyWrong":"is believing: uso indevido de -ing com verbo estativo. believe: falta de concordância sujeito-verbo; o sujeito é singular (supervisor), exigindo believes. is believe: estrutura incorreta; o verbo principal não pode seguir be sem -ing nesse contexto.","reviewHint":"Revise a lista de verbos estativos comuns (know, believe, love, want) e quando evitar o progressivo.","contentId":"en-tenses"},{"id":"m45-en-tenses-02","subject":"Inglês","topic":"Verb tenses","subtopic":"simple past (regular verbs)","prompt":"Choose the correct form: Yesterday, the crew ___ the damaged panel and continued the flight.","options":["replaces","did replace","replaced","was replacing"],"answer":2,"explanation":"Com o marcador de passado “Yesterday”, usamos simple past. Para verbo regular, basta acrescentar -ed: replaced. As demais opções erram no tempo ou aspecto.","difficulty":"intermediária","sourceBasis":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (past forms). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (past forms). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"reconhecimento de marcadores temporais e forma do simple past","commonError":"Usar auxiliar did no afirmativo sem necessidade ou manter presente apesar do marcador ‘Yesterday’.","whyWrong":"did replace: estrutura possível apenas se houver ênfase/contraste; aqui é narrativa simples, e o uso de did + base fica marcado e desnecessário. replaces: present simple, incompatível com “Yesterday”. was replacing: past progressive sugere ação em andamento; não há ação de interrupção ou contexto que justifique o aspecto contínuo.","reviewHint":"Associe ‘yesterday’, ‘last’, ‘ago’ ao simple past e revise terminações regulares -ed.","contentId":"en-tenses"},{"id":"m45-en-tenses-03","subject":"Inglês","topic":"Verb tenses","subtopic":"present perfect (posse/estado contínuo com since)","prompt":"Complete the sentence: I ___ this ID card since 2018.","options":["had","have been having","am having","have had"],"answer":3,"explanation":"Com since + ponto inicial usamos present perfect para estado que continua até agora. O verbo have (posse) é estativo; a forma correta é “have had”. Progressivo com have (posse) é inadequado.","difficulty":"avançada","sourceBasis":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (perfect aspect; since/for). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (perfect aspect; since/for). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"uso de present perfect com since e verbos estativos","commonError":"Escolher past perfect por causa do passado no ‘2018’ ou usar -ing com verbo de posse.","whyWrong":"had: past perfect exige referência a outro evento passado; aqui a situação continua até o presente. am having: present progressive não expressa posse contínua neste sentido. have been having: progressivo com have de posse é incorreto e gera ideia de ocorrência repetida, não posse contínua.","reviewHint":"Lembre: since + ponto inicial → present perfect; evite -ing com have (posse).","contentId":"en-tenses"},{"id":"m45-en-tenses-04","subject":"Inglês","topic":"Verb tenses","subtopic":"past perfect vs simple past (anterioridade)","prompt":"Choose the option that best completes the sequence: By the time the inspection team arrived, we ___ the hangar.","options":["had already locked","already locked","have already locked","were already locking"],"answer":1,"explanation":"A ação de trancar ocorreu antes da chegada. Com ‘By the time + passado’, usamos past perfect para o evento anterior: “had already locked”.","difficulty":"avançada","sourceBasis":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (past perfect and time relations). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (past perfect and time relations). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"sequência temporal e uso do past perfect","commonError":"Manter simple past nas duas ações sem marcar a anterioridade.","whyWrong":"already locked: simple past não marca anterioridade clara em relação a ‘arrived’. have already locked: present perfect não combina com marcador passado ‘By the time … arrived’. were already locking: past progressive indica ação em andamento, mas a ideia é tarefa concluída antes da chegada.","reviewHint":"Com ‘by the time + past’, use past perfect para o evento que já estava concluído antes.","contentId":"en-tenses"},{"id":"m45-en-tenses-05","subject":"Inglês","topic":"Verb tenses","subtopic":"future (will vs going to; decisão espontânea)","prompt":"Fill in the blank: “Watch out! The toolbox is sliding off the bench!” — “I ___ it!”","options":["am going to catch","am catching","will catch","catch"],"answer":2,"explanation":"Diante de uma decisão tomada no momento da fala, usa-se will (promessa/decisão espontânea): “I will catch it!”.","difficulty":"avançada","sourceBasis":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (future forms: will vs going to). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (future forms: will vs going to). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"escolha de forma de futuro por intenção vs decisão imediata","commonError":"Escolher going to por ser futuro sem considerar o tipo de decisão.","whyWrong":"am going to catch: indica plano/intenção prévia; aqui é reação imediata. am catching: present progressive indicaria ação já em andamento; não é o caso. catch: simple present não expressa decisão imediata no inglês moderno.","reviewHint":"Decisão no momento → will; plano já formado/evidência → going to.","contentId":"en-tenses"},{"id":"m45-en-tenses-06","subject":"Inglês","topic":"Verb tenses","subtopic":"future in time clauses (present after when)","prompt":"Complete the sentence: I’ll call you when I ___ at the base. (regra: após when, use present)","options":["arrived","will arrive","am going to arrive","arrive"],"answer":3,"explanation":"Em orações temporais (when, as soon as, after), usamos present simple para referência futura: “when I arrive”.","difficulty":"intermediária","sourceBasis":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (future time clauses). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (future time clauses). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"orações temporais com referência ao futuro","commonError":"Colocar will após when por transferência do português.","whyWrong":"will arrive: uso indevido de futuro após when. am going to arrive: mesma razão; após when não usamos futuro explícito. arrived: simple past, tempo errado para referência futura.","reviewHint":"Memorize: after/before/when/as soon as + present para ideia futura.","contentId":"en-tenses"},{"id":"m45-en-tenses-07","subject":"Inglês","topic":"Verb tenses","subtopic":"present perfect progressive (duração até agora)","prompt":"Choose the correct option: She ___ on the simulator for three hours, so she needs a break.","options":["has trained","is training for three hours","trained for three hours","has been training"],"answer":3,"explanation":"Para duração que começou no passado e segue até o presente, usa-se present perfect progressive: “has been training for three hours”.","difficulty":"avançada","sourceBasis":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (perfect progressive; for/since). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (perfect progressive; for/since). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"aspecto perfeito-contínuo com marcadores de duração","commonError":"Usar simple present/past com ‘for + período’ referindo-se a continuidade até agora.","whyWrong":"has trained: pode indicar resultado, mas a ênfase aqui é duração contínua; a forma contínua é preferida. is training for three hours: misto de presente com marcador de duração concluída/até agora; requer perfect. trained for three hours: simple past indica ação terminada no passado, sem ligação ao presente.","reviewHint":"Para foco na duração até agora, prefira have/has been + -ing.","contentId":"en-tenses"},{"id":"m45-en-tenses-08","subject":"Inglês","topic":"Verb tenses","subtopic":"be used to vs used to (hábito passado vs acostumar-se)","prompt":"Complete the sentence: When I joined the unit, I ___ waking up at 4 a.m., but now it’s easy.","options":["didn’t used to","wasn’t used to","wouldn’t used to","am not use to"],"answer":1,"explanation":"Be used to + noun/gerúndio indica estar acostumado. No passado negativo: “I wasn’t used to waking up…”.","difficulty":"avançada","sourceBasis":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (habitual aspect and periphrastic forms). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (habitual aspect and periphrastic forms). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"diferenciação entre estruturas de hábito e de acostumar-se","commonError":"Confundir ‘used to’ (hábito passado) com ‘be used to’ (estar acostumado a).","whyWrong":"didn’t used to: estrutura ‘used to’ expressa hábito passado, mas aqui precisamos ‘be used to’ (acostumado a) + gerúndio. wouldn’t used to: forma incorreta; ‘would’ não combina com ‘used to’ dessa maneira. am not use to: erro duplo: tempo (passado exigido por “When I joined”) e forma (‘use’ em vez de ‘used’).","reviewHint":"Memorize: be used to + gerund (acostumado); used to + base verb (hábito passado).","contentId":"en-tenses"},{"id":"m45-en-tenses-09","subject":"Inglês","topic":"Verb tenses","subtopic":"auxiliaries (do/does in questions)","prompt":"Choose the correct question form: Why ___ the technician check the gauges every hour?","options":["does","do","is checking","did"],"answer":0,"explanation":"No present simple interrogativo com 3ª pessoa singular, usamos ‘does’ + base verb: “does the technician check…”.","difficulty":"intermediária","sourceBasis":"Explorations 1: Grammar for the Experienced Beginner — Ch. 3 Simple Present (questions with do/does). CC BY-NC-SA. https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/Explorations_1%3A_Grammar_for_the_Experienced_Beginner; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Explorations 1: Grammar for the Experienced Beginner — Ch. 3 Simple Present (questions with do/does). CC BY-NC-SA. https://human.libretexts.org/Bookshelves/Languages/English_as_a_Second_Language/Explorations_1%3A_Grammar_for_the_Experienced_Beginner; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"formação de perguntas no present simple com auxiliar","commonError":"Esquecer de ajustar o auxiliar à 3ª pessoa e colocar -s no verbo principal.","whyWrong":"do: usado com I/you/we/they, não com 3ª pessoa singular. is checking: present progressive muda o sentido para ação em andamento, não hábito regular. did: simple past; a frase pede rotina atual (every hour).","reviewHint":"Perguntas no present simple: do/does + sujeito + base verb.","contentId":"en-tenses"},{"id":"m45-en-tenses-10","subject":"Inglês","topic":"Verb tenses","subtopic":"present perfect (particípio irregular)","prompt":"Complete: We have already ___ the final report.","options":["written","wrote","writing","write"],"answer":0,"explanation":"Present perfect exige particípio passado. De ‘write’, o particípio é ‘written’.","difficulty":"intermediária","sourceBasis":"Writing Guide with Handbook — Verb tenses and irregular verbs. CC BY-NC-SA 4.0. https://openstax.org/books/writing-guide/pages/handbook; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Writing Guide with Handbook — Verb tenses and irregular verbs. CC BY-NC-SA 4.0. https://openstax.org/books/writing-guide/pages/handbook; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"formas irregulares de particípio com present perfect","commonError":"Trocar simple past (‘wrote’) pelo particípio (‘written’) em tempos perfeitos.","whyWrong":"wrote: é simple past, não particípio. writing: gerúndio; forma incorreta após have no present perfect. write: forma base, falta particípio.","reviewHint":"Revise a lista de verbos irregulares: base–past–particípio (write–wrote–written).","contentId":"en-tenses"},{"id":"m45-en-tenses-11","subject":"Inglês","topic":"Verb tenses","subtopic":"time markers (ago, since, for)","prompt":"Choose the correct pair: I moved to Recife two years ___, but I have lived in this apartment ___ March.","options":["ago / since","since / for","for / ago","for / since"],"answer":0,"explanation":"Para passado concluído: ‘two years ago’. Para início de período até agora: ‘since March’. Logo, ‘ago / since’.","difficulty":"avançada","sourceBasis":"Writing Guide with Handbook — Verb tenses and irregular verbs (markers of time). CC BY-NC-SA 4.0. https://openstax.org/books/writing-guide/pages/handbook; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Writing Guide with Handbook — Verb tenses and irregular verbs (markers of time). CC BY-NC-SA 4.0. https://openstax.org/books/writing-guide/pages/handbook; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"seleção de marcadores temporais conforme estrutura verbal","commonError":"Trocar since e for ou usar ago com present perfect.","whyWrong":"since / for: ‘since’ não acompanha ‘two years’; e ‘for’ não combina com ponto específico ‘March’. for / ago: ‘for’ não acompanha ‘two years’ no simple past com ‘moved’ desta forma; e ‘ago’ não serve com present perfect. for / since: primeira lacuna pede ‘ago’, não ‘for’.","reviewHint":"Regra rápida: ago → passado simples; since → ponto inicial; for → duração.","contentId":"en-tenses"},{"id":"m45-en-tenses-12","subject":"Inglês","topic":"Verb tenses","subtopic":"past progressive vs simple past (interrupção)","prompt":"Complete the sentence: I ___ the update when the laptop suddenly shut down.","options":["was installing","am installing","installed","had installed"],"answer":0,"explanation":"A estrutura descreve uma ação em andamento interrompida por outra: past progressive (‘was installing’) + simple past (‘shut down’).","difficulty":"intermediária","sourceBasis":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (progressive aspect in narratives). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (progressive aspect in narratives). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"contraste entre ação contínua e ação pontual no passado","commonError":"Usar simple past nas duas ações e perder o contraste de aspecto.","whyWrong":"am installing: presente, incompatível com a sequência narrativa no passado. installed: perde a ideia de interrupção e simultaneidade. had installed: indica ação concluída antes de outra, não em andamento no momento do evento súbito.","reviewHint":"História no passado com interrupção: was/were + -ing para o pano de fundo; simple past para o evento que interrompe.","contentId":"en-tenses"},{"id":"m45-en-tenses-13","subject":"Inglês","topic":"Verb tenses","subtopic":"future perfect (conclusão antes de um ponto futuro)","prompt":"Choose the best option: By next week, we ___ the simulations.","options":["will finish","will have finished","are finishing by next week","will have finish"],"answer":1,"explanation":"‘By next week’ pede foco em conclusão antes de um ponto futuro. Usa-se future perfect: will have finished.","difficulty":"avançada","sourceBasis":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (future perfect). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (future perfect). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"interpretação de anterioridade no futuro","commonError":"Escolher will + base em vez da forma perfeita com ‘by’.","whyWrong":"will finish: não marca conclusão anterior a um marco futuro. are finishing by next week: mistura present progressive com marcador de prazo; menos natural e não indica anterioridade. will have finish: erro de forma; falta particípio ‘finished’.","reviewHint":"Com ‘by + time’ no futuro, use will have + particípio para indicar tarefa concluída antes do prazo.","contentId":"en-tenses"},{"id":"m45-en-tenses-14","subject":"Inglês","topic":"Verb tenses","subtopic":"present simple for schedules/timetables","prompt":"Complete the sentence: According to the flight plan, the briefing ___ at 0600 tomorrow.","options":["will start","starts","is starting","start"],"answer":2,"explanation":"Para eventos programados (timetables/schedules), usa-se present simple: “starts at 0600 tomorrow”.","difficulty":"intermediária","sourceBasis":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (present for scheduled future). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (present for scheduled future). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"seleção de tempo para eventos programados","commonError":"Usar will por ser futuro, ignorando a regra de horários fixos/agendados.","whyWrong":"will start: possível, mas menos adequado quando o foco é horário de agenda oficial. is starting: sugere arranjo pessoal; com ‘flight plan’ (timetable), o padrão é present simple. start: falta de concordância na 3ª pessoa singular.","reviewHint":"Para horários oficiais (timetable), prefira present simple: the plane departs at...","contentId":"en-tenses"},{"id":"m45-en-tenses-15","subject":"Inglês","topic":"Verb tenses","subtopic":"past perfect progressive (duração anterior a outra ação passada)","prompt":"Fill in the blank: They ___ for two hours before the gate opened.","options":["had waited","had been waiting","were waiting","have been waiting"],"answer":1,"explanation":"Quando a ênfase é a duração até um ponto passado (‘before the gate opened’), usa-se past perfect progressive: had been waiting.","difficulty":"avançada","sourceBasis":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (perfect progressive in the past). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"Brehe’s Grammar Anatomy — Chapter 3: Get Tense (perfect progressive in the past). CC BY-SA. https://ung.edu/university-press/_uploads/files/brehes-grammar-anatomy-v2.pdf; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"marcação de duração e anterioridade no passado","commonError":"Usar past continuous sem marcar que a ação já vinha ocorrendo por um período antes de outra ação passada.","whyWrong":"had waited: marca anterioridade, mas perde a noção clara de duração contínua. were waiting: simples pano de fundo; não expressa anterioridade até o ponto ‘opened’. have been waiting: present perfect progressive refere-se ao presente, não a um ponto passado.","reviewHint":"Para duração contínua imediatamente anterior a outro evento passado, use had been + -ing.","contentId":"en-tenses"},{"id":"m45-en-vocabulary-01","subject":"Inglês","topic":"Vocabulary","subtopic":"contextual meaning (significado por contexto)","prompt":"In the sentence, \"The team proposed a robust plan that could handle budget cuts and schedule changes without failing,\" which word best preserves the meaning of robust?","options":["delicate","moderate","resilient","ornate"],"answer":2,"explanation":"Robust in this context means strong, durable, or able to withstand pressure. Resilient matches that idea: a plan that can absorb shocks and still work. Delicate is the opposite of robust; moderate suggests average strength (not strong); ornate relates to decoration, not strength.","difficulty":"avançada","sourceBasis":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — CC BY-NC 4.0 — vocabulary/context focus consulted for calibration Academic Word List practice.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — CC BY-NC 4.0 — vocabulary/context focus consulted for calibration Academic Word List practice.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Infer lexical meaning from immediate context and collocation cues.","commonError":"Choosing moderate because it seems positive but it fails to convey the key meaning of withstanding difficulties.","whyWrong":"A: Delicate = easily broken, opposite of robust. B: Moderate = neither strong nor weak, misses the emphasis on durability. D: Ornate = decorative, unrelated to functional strength.","reviewHint":"Revise common synonyms for strong/solid in planning contexts: robust, resilient, sound, solid.","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-02","subject":"Inglês","topic":"Vocabulary","subtopic":"antonyms (antônimos de precisão semântica)","prompt":"Choose the word that is the best antonym for terse in: \"Unlike his terse emails, her responses were quite ____.\"","options":["verbose","concise","succinct","brief"],"answer":0,"explanation":"Terse means very short, using few words (sometimes abrupt). The direct antonym is verbose (using too many words). Concise and succinct are near-synonyms of terse, and brief is also close in meaning to terse, not its antonym.","difficulty":"avançada","sourceBasis":"https://opentextbc.ca/abealf2/ — CC BY 4.0 — consulted for calibration vocabulary-building emphasis on meaning contrast.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://opentextbc.ca/abealf2/ — CC BY 4.0 — consulted for calibration vocabulary-building emphasis on meaning contrast.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Differentiate near-synonyms from true antonyms using context.","commonError":"Confusing terse with rude and picking concise or succinct as an antonym; both are actually positive versions of brevity.","whyWrong":"B: Concise = economical with words (positive); not opposite. C: Succinct = brief/clear; not opposite. D: Brief = short; not opposite.","reviewHint":"Build antonym pairs and watch for false antonyms where the difference is connotation rather than meaning.","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-03","subject":"Inglês","topic":"Vocabulary","subtopic":"prefixes (mis-, over-, re-, co-)","prompt":"Which option correctly forms the verb meaning \"to interpret incorrectly\"? (Português: prefixo que indica erro)","options":["re-interpret","misinterpret","co-interpret","overinterpret"],"answer":1,"explanation":"The prefix mis- means wrongly or badly, so misinterpret means interpret incorrectly. Re- means again; co- means together; over- means excessively.","difficulty":"intermediária","sourceBasis":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — CC BY-NC 4.0 — consulted for calibration from prefix/suffix focus activities.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — CC BY-NC 4.0 — consulted for calibration from prefix/suffix focus activities.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Recognize meaning carried by common English prefixes.","commonError":"Selecting overinterpret because \"too much\" feels wrong; but mis- specifically marks error, not excess.","whyWrong":"A: Re-interpret = interpret again, not incorrectly. C: Co-interpret = interpret together. D: Overinterpret = interpret too much/excessively, not necessarily wrongly.","reviewHint":"Memorize high-frequency prefixes: mis- (wrongly), re- (again), over- (excessively), co- (together).","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-04","subject":"Inglês","topic":"Vocabulary","subtopic":"suffixes e formação de substantivos (-ation)","prompt":"Choose the correct noun to complete the sentence: \"The policy aims at the long-term ______ of freshwater resources.\"","options":["preservance","preservativity","preservion","preservation"],"answer":3,"explanation":"From the verb preserve, the standard abstract noun is preservation. The productive pattern is verb + -ation for many Latinate forms (preserve → preservation). The other options are malformed or rare/nonstandard.","difficulty":"intermediária","sourceBasis":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — CC BY-NC 4.0 — consulted for calibration word-formation focus.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — CC BY-NC 4.0 — consulted for calibration word-formation focus.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Apply common suffix patterns to form abstract nouns from verbs.","commonError":"Choosing a look-alike ending by sight (-ance/-ivity) without checking the known base-form pair preserve → preservation.","whyWrong":"A: Preservance is not the accepted noun for this meaning. B: Preservativity is nonstandard and suggests an unrelated property. C: Preservion is not a standard formation.","reviewHint":"Study frequent verb→noun mappings: approve→approval, decide→decision, preserve→preservation, inform→information.","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-05","subject":"Inglês","topic":"Vocabulary","subtopic":"phrasal verbs (adiamento)","prompt":"Complete the sentence: \"The committee decided to ______ the launch until the software is fully tested.\"","options":["put off","bring up","carry on","take in"],"answer":0,"explanation":"Put off means postpone, which fits the context of delaying a launch. Bring up = mention/introduce a topic; carry on = continue; take in = absorb/deceive/receive, none mean postpone here.","difficulty":"avançada","sourceBasis":"https://open.umn.edu/opentextbooks/textbooks/college-esl-writers-applied-grammar-and-composing-strategies-for-success — CC BY-NC-SA — calibrated focus on verb + particle meaning.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://open.umn.edu/opentextbooks/textbooks/college-esl-writers-applied-grammar-and-composing-strategies-for-success — CC BY-NC-SA — calibrated focus on verb + particle meaning.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Select context-appropriate phrasal verbs with precise meanings.","commonError":"Picking carry on by misreading the sentence as \"continue with the launch\" and ignoring \"until... tested\" which signals delay.","whyWrong":"B: Bring up = introduce a topic, not delay. C: Carry on = continue, opposite of postponing. D: Take in = absorb/deceive/receive, not postpone.","reviewHint":"Group phrasal verbs by semantic field: delay (put off), continue (carry on), introduce (bring up), refuse (turn down).","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-06","subject":"Inglês","topic":"Vocabulary","subtopic":"false cognates (falsos cognatos)","prompt":"In the sentence \"Actually, we cannot guarantee delivery this week,\" the word actually most nearly means:","options":["currently","in fact","eventually","lately"],"answer":2,"explanation":"Actually in English means in fact or really, not atualmente (currently). Therefore, in fact is the correct paraphrase. Currently, eventually (no futuro), and lately (recently) do not match.","difficulty":"intermediária","sourceBasis":"https://opentextbc.ca/abealf2/ — CC BY 4.0 — calibrated emphasis on vocabulary pitfalls.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://opentextbc.ca/abealf2/ — CC BY 4.0 — calibrated emphasis on vocabulary pitfalls.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Identify and correct false cognates using context and known equivalences.","commonError":"Translating actually as atualmente and choosing currently.","whyWrong":"A: Currently = agora/atualmente, false cognate trap. C: Eventually = finalmente/em algum momento futuro. D: Lately = recentemente. None match in fact.","reviewHint":"Make a list of classic traps: actually = in fact; eventually = finally; pretend = agir como se; pushy ≠ puxar.","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-07","subject":"Inglês","topic":"Vocabulary","subtopic":"function words (conjunctions/prepositions)","prompt":"Choose the best option: \"______ the heavy traffic, we arrived on time.\" (Português: com nome após a lacuna)","options":["Although","Despite","Even though","However"],"answer":1,"explanation":"Despite must be followed by a noun phrase (the heavy traffic). Although/even though take a clause; however is a conjunctive adverb, not used before a noun phrase like this.","difficulty":"intermediária","sourceBasis":"https://openstax.org/books/writing-guide/pages/handbook — CC BY-NC-SA — consulted for calibration for connector choice in context.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://openstax.org/books/writing-guide/pages/handbook — CC BY-NC-SA — consulted for calibration for connector choice in context.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Differentiate connectors by the structures they introduce (NP vs. clause).","commonError":"Choosing although because it signals contrast but ignoring that a noun phrase follows, not a clause.","whyWrong":"A/C: Although / Even though require a clause (subject + verb), not a noun phrase. D: However cannot directly modify a noun phrase here.","reviewHint":"Remember: despite/in spite of + noun/gerund; although/even though + clause; however + sentence/clause boundary.","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-08","subject":"Inglês","topic":"Vocabulary","subtopic":"collocations (naturalness)","prompt":"Choose the most natural collocation: \"The forecast says there will be ______ tomorrow.\"","options":["strong rain","big rain","heavy rain","massive rain"],"answer":3,"explanation":"The fixed, natural collocation in English is heavy rain. Strong/big/massive with rain sound non-idiomatic in standard usage.","difficulty":"avançada","sourceBasis":"https://opentextbc.ca/abealf2/ — CC BY 4.0 — calibrated focus on natural word combinations.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://opentextbc.ca/abealf2/ — CC BY 4.0 — calibrated focus on natural word combinations.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Recognize fixed collocations common in everyday forecasts and reports.","commonError":"Translating literalmente de \"chuva forte\" e escolhendo strong rain por interferência do português.","whyWrong":"A/B/D: These adjectives do not typically collocate with rain in standard English, even if understandable.","reviewHint":"Study weather collocations: heavy rain, strong wind, thick fog, light drizzle.","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-09","subject":"Inglês","topic":"Vocabulary","subtopic":"word formation (adjetivo derivado)","prompt":"Fill in the blank: \"The city invested in ______ energy projects to reduce emissions.\"","options":["sustainable","sustainability","unsustainable","sustainably"],"answer":0,"explanation":"We need an adjective to modify energy projects. Sustainable fits. Sustainability is a noun; unsustainable means the opposite; sustainably is an adverb.","difficulty":"intermediária","sourceBasis":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — CC BY-NC 4.0 — consulted for calibration from AWL vocabulary context.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — CC BY-NC 4.0 — consulted for calibration from AWL vocabulary context.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Choose the correct part of speech in academic-word contexts.","commonError":"Picking sustainability due to topic familiarity and not checking part of speech.","whyWrong":"B: Sustainability (noun) cannot modify projects directly. C: Unsustainable contradicts the sentence purpose. D: Sustainably (adverb) is not used before a noun.","reviewHint":"Map common families: sustain (v), sustainable (adj), sustainability (n), sustainably (adv).","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-10","subject":"Inglês","topic":"Vocabulary","subtopic":"connotation and nuance (conotação)","prompt":"Choose the option with a positive/neutral connotation: \"She is ______ with money, avoiding waste while still being generous when needed.\"","options":["stingy","miserly","frugal","cheap"],"answer":2,"explanation":"Frugal means careful with money without a negative judgment. Stingy, miserly, and cheap carry negative connotations of ungenerosity.","difficulty":"avançada","sourceBasis":"https://openstax.org/books/writing-guide/pages/handbook — CC BY-NC-SA — calibrated focus on word choice and connotation.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://openstax.org/books/writing-guide/pages/handbook — CC BY-NC-SA — calibrated focus on word choice and connotation.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Distinguish denotation from connotation to fit tone and context.","commonError":"Choosing cheap because it can mean inexpensive, but here it describes a person and is negative.","whyWrong":"A/B/D: All imply unwillingness to spend/give, clashing with \"still being generous.\"","reviewHint":"When describing people, prefer frugal/economical over stingy/cheap unless you intend a negative tone.","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-11","subject":"Inglês","topic":"Vocabulary","subtopic":"polysemy (palavras de múltiplos sentidos)","prompt":"In: \"Following the investigation, the prosecutor decided to charge the suspect the next day,\" charge most nearly means:","options":["to ask for a price","to make an accusation","to store electricity","to rush forward"],"answer":1,"explanation":"In legal context, to charge someone means to formally accuse them of a crime. The other senses (set a price, load a battery, rush) do not match the legal frame suggested by prosecutor and suspect.","difficulty":"avançada","sourceBasis":"https://opentextbc.ca/abealf2/ — CC BY 4.0 — consulted for calibration reading-in-context vocabulary skill.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","origin":"autoral/similar","source":"https://opentextbc.ca/abealf2/ — CC BY 4.0 — consulted for calibration reading-in-context vocabulary skill.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial.","skill":"Use domain cues in the sentence to select among multiple meanings.","commonError":"Defaulting to the most frequent everyday sense (price) and missing legal-context clues.","whyWrong":"A: Pricing sense needs goods/services, not a suspect. C: Electricity sense applies to devices, not people. D: Rush at is a physical action, not legal.","reviewHint":"List common polysemous words (charge, file, appeal) and tie meanings to domain triggers (law, finance, tech).","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-12","subject":"Inglês","topic":"Vocabulary","subtopic":"phrasal verbs (gerar/idear)","prompt":"Select the option that best completes the idea: \"We need to ______ a new idea for the slogan.\"","options":["come across with","come over with","come through with","come up with"],"answer":3,"explanation":"Come up with means to produce or think of (an idea). Come across with means to provide reluctantly, come over with is not standard in this sense, and come through with means to provide/fulfill after a promise, not generate.","difficulty":"avançada","sourceBasis":"https://open.umn.edu/opentextbooks/textbooks/college-esl-writers-applied-grammar-and-composing-strategies-for-success — CC BY-NC-SA — consulted for calibration verb + particle selection.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://open.umn.edu/opentextbooks/textbooks/college-esl-writers-applied-grammar-and-composing-strategies-for-success — CC BY-NC-SA — consulted for calibration verb + particle selection.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Match phrasal verbs to creation vs. delivery contexts.","commonError":"Choosing come through with because it sounds like \"deliver\"; but the task is to invent, not to fulfill.","whyWrong":"A: Come across with = hand over/provide, not create. B: Come over with is not idiomatic here. C: Come through with = deliver on a promise, not invent.","reviewHint":"Differentiate idea-generation (come up with) from provision (come through with) and mere encounter (come across).","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-13","subject":"Inglês","topic":"Vocabulary","subtopic":"prefix semantics (anti-, bio-, geo-, semi-)","prompt":"In the expression \"antiviral medication,\" the prefix anti- most nearly means:","options":["against","before","inside","around"],"answer":0,"explanation":"Anti- means against or opposing, so antiviral = against viruses. Before = pre-/ante-; inside = intra-/endo-; around = peri-/circum-.","difficulty":"intermediária","sourceBasis":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — CC BY-NC 4.0 — consulted for calibration from prefix recognition practice.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — CC BY-NC 4.0 — consulted for calibration from prefix recognition practice.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Recognize Greek/Latin-derived prefixes to infer meaning.","commonError":"Confusing anti- with ante- due to similar spelling/pronunciation.","whyWrong":"B: Before is pre-/ante-, not anti-. C: Inside is intra-/endo-, not anti-. D: Around is peri-/circum-, not anti-.","reviewHint":"Create a mini-glossary of scientific prefixes: anti- (against), pro- (for), ante- (before), post- (after).","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-14","subject":"Inglês","topic":"Vocabulary","subtopic":"academic register synonyms (AWL)","prompt":"Choose the best synonym to maintain meaning and register: \"The new policy offers significant ______ to apprentices.\"","options":["profits","advantages","charities","benefactors"],"answer":1,"explanation":"Benefits in this context = advantages. Profits relates to financial gain for businesses; charities are organizations/acts of giving; benefactors are people who give help, none fitting recipients \"to apprentices.\"","difficulty":"avançada","sourceBasis":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — CC BY-NC 4.0 — Academic Word List synonym practice (consulted for calibration).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://pdxscholar.library.pdx.edu/pdxopen/10/ — CC BY-NC 4.0 — Academic Word List synonym practice (consulted for calibration).; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Select synonyms that preserve sense and academic tone in context.","commonError":"Choosing profits due to perceived positivity, but it shifts meaning to money/business.","whyWrong":"A: Profits = monetary gain, not general advantages to people. C: Charities = organizations/aid, wrong part of speech/meaning. D: Benefactors = people who give, not what is offered.","reviewHint":"Review AWL families: benefit (n/v), advantage (n), advantageous (adj), beneficiary (n).","contentId":"en-vocabulary"},{"id":"m45-en-vocabulary-15","subject":"Inglês","topic":"Vocabulary","subtopic":"dependent prepositions (regência lexical)","prompt":"Choose the correct option: \"She is capable ___ solving complex equations quickly.\"","options":["for","at","of","to"],"answer":2,"explanation":"Capable takes the preposition of: capable of + gerund/noun. For/at/to do not collocate with capable in standard usage.","difficulty":"intermediária","sourceBasis":"https://open.umn.edu/opentextbooks/textbooks/college-esl-writers-applied-grammar-and-composing-strategies-for-success — CC BY-NC-SA — consulted for calibration adjective + preposition usage.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","origin":"autoral/similar","source":"https://open.umn.edu/opentextbooks/textbooks/college-esl-writers-applied-grammar-and-composing-strategies-for-success — CC BY-NC-SA — consulted for calibration adjective + preposition usage.; questão autoral/similar; fonte consultada para calibrar subtema e nível; não oficial. Licença restrita: somente referência de calibração; nenhum texto de exercício é redistribuído.","skill":"Recall fixed adjective + preposition patterns and follow with gerunds when needed.","commonError":"Transferring from able to and writing capable to by analogy.","whyWrong":"A: Capable for is nonstandard. B: Capable at is nonstandard; able at exists but differs. D: Capable to + infinitive is not standard; use able to instead.","reviewHint":"Memorize common patterns: capable of -ing; interested in -ing; responsible for -ing; opposed to -ing.","contentId":"en-vocabulary"},{"id":"m45-mat-algebra-01","subject":"Matemática","topic":"Álgebra","subtopic":"expressões algébricas","prompt":"Simplifique a expressão (3x - 2)(x + 4) - 3x².","options":["10x - 8","6x² + 10x - 8","10x + 8","3x² + 10x - 8"],"answer":0,"explanation":"A distributiva dá (3x - 2)(x + 4) = 3x² + 10x - 8. Subtraindo 3x², restam 10x - 8.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/012016/d1eab99681feeb983a44471df9e2d1d3.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/d1eab99681feeb983a44471df9e2d1d3.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"distribuir produtos algébricos e reduzir termos semelhantes","commonError":"Distribuir apenas o primeiro termo ou esquecer que o termo -3x² também deve ser combinado.","whyWrong":"A alternativa 1 mantém um 6x² inexistente; a 3 erra o sinal do termo constante; a 4 interrompe a simplificação antes de subtrair 3x².","reviewHint":"Faça a distributiva em duas linhas e agrupe os termos por grau antes de finalizar.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-02","subject":"Matemática","topic":"Álgebra","subtopic":"produtos notáveis","prompt":"Qual é a forma simplificada de (a + 2b)² - (a - 2b)²?","options":["8a²b²","4ab","8ab","2a² + 8b²"],"answer":2,"explanation":"Usando a diferença de quadrados, [ (a+2b) - (a-2b) ][ (a+2b) + (a-2b) ] = (4b)(2a) = 8ab.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/012016/d1eab99681feeb983a44471df9e2d1d3.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/d1eab99681feeb983a44471df9e2d1d3.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"reconhecer e aplicar a diferença de quadrados","commonError":"Elevar cada binômio ao quadrado sem controlar o termo do meio ou confundir a diferença entre os resultados.","whyWrong":"A alternativa 0 introduz graus que não aparecem; a 1 perde um fator 2; a 3 corresponde a uma expansão incompleta, não à subtração dos quadrados.","reviewHint":"Trate a expressão como U² - V² e calcule (U-V)(U+V) antes de expandir.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-03","subject":"Matemática","topic":"Álgebra","subtopic":"fatoração","prompt":"A fatoração completa de 6x² - 15x é:","options":["3(2x² - 5x)","3x(2x - 5)","x(6x - 15x)","6x(x - 15)"],"answer":1,"explanation":"O maior fator comum de 6x² e -15x é 3x. Retirando-o, obtém-se 3x(2x - 5), que não admite nova fatoração inteira comum.","difficulty":"intermediária","sourceBasis":"https://www.ced.seduc.ce.gov.br/wp-content/uploads/sites/82/2022/03/caderno06_deAluno.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://www.ced.seduc.ce.gov.br/wp-content/uploads/sites/82/2022/03/caderno06_deAluno.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"identificar o maior fator comum em uma expressão","commonError":"Retirar somente o fator numérico e deixar a variável comum fora da fatoração.","whyWrong":"A alternativa 0 ainda contém fator x comum; a 2 não preserva a expressão ao desenvolver; a 3 altera o segundo termo e não é equivalente.","reviewHint":"Compare os fatores primos e as menores potências de cada termo antes de colocar o fator comum em evidência.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-04","subject":"Matemática","topic":"Álgebra","subtopic":"fatoração por identidades","prompt":"Fatore completamente x⁴ - 16 no conjunto dos números reais.","options":["(x² - 4)²","(x - 4)(x + 4)","(x² - 16)(x² + 1)","(x - 2)(x + 2)(x² + 4)"],"answer":3,"explanation":"Primeiro, x⁴ - 16 = (x² - 4)(x² + 4). Depois, x² - 4 = (x - 2)(x + 2). Logo a fatoração é (x - 2)(x + 2)(x² + 4); o último fator não se decompõe em fatores lineares reais.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/012016/208b6a9289c8e8f001ef1de6f5c6875f.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/208b6a9289c8e8f001ef1de6f5c6875f.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"encadear diferenças de quadrados e verificar fatoração completa","commonError":"Aplicar a diferença de quadrados uma única vez ou trocar x² + 4 por x² - 4.","whyWrong":"A alternativa 0 desenvolve para x⁴ - 8x² + 16; a 1 resulta em x² - 16; a 2 produz x⁴ - 15x² - 16, portanto nenhuma é equivalente.","reviewHint":"Procure novamente uma diferença de quadrados após a primeira fatoração e teste o produto final.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-05","subject":"Matemática","topic":"Álgebra","subtopic":"equações lineares","prompt":"Resolva 5(2x - 1) = 3x + 16.","options":["x = 2","x = 7/3","x = 3","x = 21"],"answer":2,"explanation":"Expandindo, 10x - 5 = 3x + 16. Assim, 7x = 21 e x = 3. A substituição dá 5(6-1)=25 e 9+16=25.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/012016/d1eab99681feeb983a44471df9e2d1d3.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/d1eab99681feeb983a44471df9e2d1d3.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"resolver equação linear mantendo a equivalência","commonError":"Distribuir 5 apenas ao termo com x ou transportar -5 sem trocar corretamente o sinal.","whyWrong":"As alternativas 0, 1 e 3 surgem de erros de distribuição ou de isolamento; somente x=3 satisfaz os dois membros.","reviewHint":"Expanda primeiro, reúna os termos com x em um lado e os constantes no outro, e teste o resultado.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-06","subject":"Matemática","topic":"Álgebra","subtopic":"equações quadráticas","prompt":"O conjunto-solução real de 2x² - 7x + 3 = 0 é:","options":["{1, 3}","{1/2, 3}","{-1/2, -3}","{2, 3/2}"],"answer":1,"explanation":"Com a=2, b=-7 e c=3, Δ=49-24=25. Portanto x=(7±5)/4, produzindo x=3 e x=1/2.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/012016/d1eab99681feeb983a44471df9e2d1d3.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/d1eab99681feeb983a44471df9e2d1d3.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"aplicar o discriminante e a fórmula quadrática com sinais corretos","commonError":"Usar b=7 em vez de b=-7 ou dividir o numerador por 2 em vez de 4.","whyWrong":"A alternativa 0 troca a raiz 1/2 por 1; a 2 troca os sinais sem justificativa; a 3 não resulta da fórmula e não zera o polinômio.","reviewHint":"Escreva b entre parênteses no discriminante e mantenha 2a no denominador até o final.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-07","subject":"Matemática","topic":"Álgebra","subtopic":"sistemas lineares","prompt":"Resolva o sistema x + y = 11 e 2x - y = 4.","options":["(5, 6)","(6, 5)","(4, 7)","(7, 4)"],"answer":0,"explanation":"Somando as equações, 3x=15, logo x=5. Na primeira, y=11-5=6. O par (5,6) verifica também 2·5-6=4.","difficulty":"intermediária","sourceBasis":"https://poti.ufpr.br/wp-content/uploads/2022/11/algebra_n2.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://poti.ufpr.br/wp-content/uploads/2022/11/algebra_n2.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"resolver sistema linear por eliminação e verificar o par","commonError":"Encontrar x corretamente e associá-lo ao segundo componente, ou não conferir a segunda equação.","whyWrong":"As alternativas 1 e 3 trocam a ordem das coordenadas; a 2 não satisfaz simultaneamente as duas igualdades.","reviewHint":"Some as equações para eliminar y e, depois, substitua o x obtido na equação mais simples.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-08","subject":"Matemática","topic":"Álgebra","subtopic":"sistemas não lineares","prompt":"Se x + y = 7 e xy = 10, quais são os possíveis valores do par (x,y), sem distinguir a ordem?","options":["(1, 6)","(3, 4)","(-2, -5)","(2, 5)"],"answer":3,"explanation":"Os números x e y são raízes de t² - 7t + 10 = 0, que fatoriza como (t-2)(t-5). Portanto o par é (2,5) ou (5,2), representado na alternativa 4.","difficulty":"avançada","sourceBasis":"https://poti.ufpr.br/wp-content/uploads/2022/11/algebra_n2.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://poti.ufpr.br/wp-content/uploads/2022/11/algebra_n2.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"converter soma e produto em uma equação quadrática auxiliar","commonError":"Procurar apenas dois números que somem 7, sem exigir também produto 10.","whyWrong":"(1,6) e (3,4) têm soma 7, mas produtos 6 e 12; (-2,-5) tem produto 10, porém soma -7. Apenas (2,5) atende às duas condições.","reviewHint":"Use t²-(x+y)t+xy=0 e confirme tanto a soma quanto o produto dos candidatos.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-09","subject":"Matemática","topic":"Álgebra","subtopic":"inequações lineares","prompt":"Resolva a inequação 3x - 5 ≤ 10.","options":["x ≥ 5","x ≤ 5","x < 5","x ≥ -5"],"answer":1,"explanation":"Somando 5 aos dois membros, 3x≤15. Como a divisão é por 3 positivo, o sinal permanece: x≤5.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/012016/d1eab99681feeb983a44471df9e2d1d3.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/d1eab99681feeb983a44471df9e2d1d3.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"isolar a variável em uma inequação linear","commonError":"Trocar o sentido do sinal mesmo dividindo por número positivo ou esquecer que a igualdade é permitida.","whyWrong":"A alternativa 0 inverte indevidamente o sinal; a 2 exclui x=5; a 3 vem de erro no transporte do termo constante.","reviewHint":"Só inverta o sinal ao multiplicar ou dividir por número negativo; observe se o símbolo inclui igualdade.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-10","subject":"Matemática","topic":"Álgebra","subtopic":"inequações quadráticas","prompt":"Qual é o conjunto-solução real de x² - 5x + 6 < 0?","options":["(2, 3)","(-∞, 2) ∪ (3, ∞)","[2, 3]","(-∞, 3)"],"answer":0,"explanation":"A expressão fatoriza como (x-2)(x-3). Como o coeficiente de x² é positivo, o produto é negativo entre as raízes. A desigualdade é estrita, então 2 e 3 ficam excluídos: (2,3).","difficulty":"avançada","sourceBasis":"https://www.ced.seduc.ce.gov.br/wp-content/uploads/sites/82/2022/03/caderno06_deAluno.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://www.ced.seduc.ce.gov.br/wp-content/uploads/sites/82/2022/03/caderno06_deAluno.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"resolver inequação quadrática por análise de sinais","commonError":"Escolher os intervalos externos por olhar apenas para as raízes ou incluir as raízes em uma desigualdade estrita.","whyWrong":"A alternativa 1 descreve produto positivo; a 2 inclui zeros proibidos pelo <; a 3 inclui valores que tornam o produto positivo.","reviewHint":"Marque as raízes na reta, teste um ponto entre elas e outro fora, e só depois escolha o sinal pedido.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-11","subject":"Matemática","topic":"Álgebra","subtopic":"polinômios e teorema do resto","prompt":"Qual é o resto da divisão de P(x) = x³ - 2x + 5 por x - 2?","options":["0","5","9","13"],"answer":2,"explanation":"Pelo Teorema do Resto, o resto é P(2). Calculando, P(2)=2³-2·2+5=8-4+5=9.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/012016/208b6a9289c8e8f001ef1de6f5c6875f.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/208b6a9289c8e8f001ef1de6f5c6875f.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"aplicar o Teorema do Resto a um divisor linear","commonError":"Substituir -2 em vez de 2 porque o divisor é x-2, ou esquecer o termo constante.","whyWrong":"A alternativa 0 confundiria resto zero com raiz; 5 ignora os termos em x; 13 resulta de erro de sinal ou de soma.","reviewHint":"No divisor x-r, use diretamente P(r), mantendo os sinais da substituição entre parênteses.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-12","subject":"Matemática","topic":"Álgebra","subtopic":"polinômios e raízes","prompt":"Para que x = 2 seja raiz de P(x) = x³ + ax² - 4x - 4, o valor de a deve ser:","options":["1","-1","2","4"],"answer":0,"explanation":"A condição de raiz é P(2)=0: 8 + 4a - 8 - 4 = 0, portanto 4a - 4 = 0 e a=1.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/012016/208b6a9289c8e8f001ef1de6f5c6875f.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/208b6a9289c8e8f001ef1de6f5c6875f.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"usar a condição P(r)=0 para determinar parâmetro","commonError":"Substituir 2 apenas no termo cúbico ou não igualar o valor do polinômio a zero.","whyWrong":"Os valores -1, 2 e 4 não anulam P(2); resultam de ignorar um termo ou de resolver 4a-4 com erro aritmético.","reviewHint":"Escreva todos os termos de P(2) em uma linha e só depois isole o parâmetro a.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-13","subject":"Matemática","topic":"Álgebra","subtopic":"sistemas de inequações","prompt":"Resolva simultaneamente 2x - 1 > 3 e x + 4 ≤ 9.","options":["x < 2","x ≥ 5","x > 2","2 < x ≤ 5"],"answer":3,"explanation":"A primeira inequação dá 2x>4, isto é, x>2. A segunda dá x≤5. A interseção das duas condições é 2<x≤5.","difficulty":"avançada","sourceBasis":"https://poti.ufpr.br/wp-content/uploads/2022/11/algebra_n2.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://poti.ufpr.br/wp-content/uploads/2022/11/algebra_n2.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"calcular a interseção de soluções de inequações","commonError":"Resolver cada desigualdade, mas unir os intervalos como se a condição fosse alternativa em vez de simultânea.","whyWrong":"A alternativa 0 inclui valores que falham na primeira; a 1 inclui valores que falham na segunda; a 2 não impõe o limite superior x≤5.","reviewHint":"Para 'e', desenhe as duas soluções na mesma reta e mantenha apenas a parte sobreposta.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-14","subject":"Matemática","topic":"Álgebra","subtopic":"expressões fracionárias e domínio","prompt":"Para x ≠ 3, a simplificação correta de (x² - 9)/(x - 3) é:","options":["x - 3","x + 3","x² + 3","1"],"answer":1,"explanation":"Fatorando o numerador, x²-9=(x-3)(x+3). Como x≠3, pode-se cancelar o fator x-3 e obter x+3. A restrição original continua válida.","difficulty":"avançada","sourceBasis":"https://poti.ufpr.br/wp-content/uploads/2022/11/algebra_n2.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://poti.ufpr.br/wp-content/uploads/2022/11/algebra_n2.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"fatorar uma fração algébrica sem perder a restrição de domínio","commonError":"Cancelar parcelas ou aceitar x=3 depois da simplificação.","whyWrong":"A alternativa 0 cancela o fator errado; a 2 não é resultado de fatoração; a 3 só ocorreria se numerador e denominador fossem o mesmo fator, o que não ocorre.","reviewHint":"Fatore antes de cancelar e escreva ao lado os valores que zeram o denominador original.","contentId":"mat-algebra"},{"id":"m45-mat-algebra-15","subject":"Matemática","topic":"Álgebra","subtopic":"polinômios e fatoração por agrupamento","prompt":"As raízes reais de P(x) = x³ - 3x² - 4x + 12 são:","options":["-3, 2 e 2","-2, 3 e 4","-2, 2 e 3","1, 3 e 4"],"answer":2,"explanation":"Por agrupamento, P=x²(x-3)-4(x-3)=(x-3)(x²-4)=(x-3)(x-2)(x+2). Logo as raízes são 3, 2 e -2.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/012016/208b6a9289c8e8f001ef1de6f5c6875f.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/208b6a9289c8e8f001ef1de6f5c6875f.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"fatorar polinômio por agrupamento e diferença de quadrados","commonError":"Trocar o sinal ao resolver x²-4=0 ou concluir raízes a partir de coeficientes sem fatorar.","whyWrong":"A alternativa 0 repete a raiz 2 e não anula o polinômio em -3; a 1 inclui 4, que não é raiz; a 3 falha em x=1 e x=4.","reviewHint":"Agrupe os dois primeiros e os dois últimos termos para obter um fator comum; depois resolva cada fator igual a zero.","contentId":"mat-algebra"},{"id":"m45-mat-analytic-01","subject":"Matemática","topic":"Geometria analítica","subtopic":"plano cartesiano e quadrantes","prompt":"O ponto P(-4, 7) está localizado em qual região do plano cartesiano?","options":["I quadrante","II quadrante","III quadrante","IV quadrante"],"answer":1,"explanation":"A abscissa é negativa e a ordenada é positiva; portanto, P está no II quadrante.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","skill":"interpretar sinais de abscissa e ordenada para localizar pontos","commonError":"Associar o sinal negativo da abscissa ao III quadrante sem verificar o sinal da ordenada.","whyWrong":"0 exigiria duas coordenadas positivas; 2 exigiria abscissa e ordenada negativas; 3 exigiria abscissa positiva e ordenada negativa.","reviewHint":"Memorize a sequência de sinais: I (+,+), II (-,+), III (-,-), IV (+,-).","contentId":"mat-analytic"},{"id":"m45-mat-analytic-02","subject":"Matemática","topic":"Geometria analítica","subtopic":"distância entre pontos","prompt":"Qual é a distância entre A(-1, 2) e B(5, 10)?","options":["10","12","14","100"],"answer":0,"explanation":"As diferenças são Δx=6 e Δy=8. Logo, AB=√(6²+8²)=√100=10.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar a fórmula da distância euclidiana no plano","commonError":"Parar em 100, que é o quadrado da distância, ou somar os deslocamentos sem usar Pitágoras.","whyWrong":"1 e 2 não resultam de √(36+64); 3 é o valor dentro da raiz e não a distância pedida.","reviewHint":"Calcule primeiro Δx e Δy, some seus quadrados e só então extraia a raiz.","contentId":"mat-analytic"},{"id":"m45-mat-analytic-03","subject":"Matemática","topic":"Geometria analítica","subtopic":"ponto médio","prompt":"O ponto médio do segmento com extremos A(-4, 6) e B(2, -2) é:","options":["(-2, 4)","(3, 2)","(-1, 2)","(-1, -2)"],"answer":2,"explanation":"M=((−4+2)/2,(6−2)/2)=(-1,2). A média deve ser feita separadamente para as abscissas e para as ordenadas.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufmg.br/items/f36f0932-0c49-4316-b938-7bad156ad0b4 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufmg.br/items/f36f0932-0c49-4316-b938-7bad156ad0b4 (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular o ponto de equilíbrio de um segmento por médias coordenadas","commonError":"Misturar a coordenada x de um ponto com a coordenada y do outro.","whyWrong":"0 usa somas ou divisões incorretas; 1 não corresponde às médias das coordenadas; 3 troca o sinal da ordenada média.","reviewHint":"Escreva a fórmula em duas linhas: xM=(xA+xB)/2 e yM=(yA+yB)/2.","contentId":"mat-analytic"},{"id":"m45-mat-analytic-04","subject":"Matemática","topic":"Geometria analítica","subtopic":"coeficiente angular","prompt":"Qual é o coeficiente angular da reta que passa por P(-2, 3) e Q(4, 0)?","options":["2","1/2","-3/4","-1/2"],"answer":3,"explanation":"m=(0−3)/(4−(−2))=−3/6=−1/2.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","skill":"obter a inclinação a partir de dois pontos","commonError":"Usar x1-x2 no denominador sem trocar também a ordem do numerador.","whyWrong":"0 e 1 ignoram a razão entre as variações; 2 usa uma diferença de ordenadas incorreta e não simplifica a fração correta.","reviewHint":"Use sempre a mesma ordem: coordenada final menos coordenada inicial em cima e embaixo.","contentId":"mat-analytic"},{"id":"m45-mat-analytic-05","subject":"Matemática","topic":"Geometria analítica","subtopic":"equação da reta","prompt":"A reta que passa por (1, 2) e tem coeficiente angular 3 é:","options":["y=3x-1","y=3x+1","y=-3x+5","y=x+3"],"answer":0,"explanation":"Pela forma ponto-inclinação, y−2=3(x−1), portanto y=3x−1.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","skill":"construir a equação reduzida de uma reta com ponto e inclinação","commonError":"Usar y=mx+b e concluir b=2, confundindo ordenada do ponto com intercepto.","whyWrong":"1 não passa por (1,2); 2 tem inclinação oposta; 3 tem inclinação 1 em vez de 3.","reviewHint":"Depois de obter a equação, substitua x=1 e confirme que y=2.","contentId":"mat-analytic"},{"id":"m45-mat-analytic-06","subject":"Matemática","topic":"Geometria analítica","subtopic":"circunferência e forma padrão","prompt":"Qual é o centro e o raio da circunferência x²+y²−4x+6y−12=0?","options":["Centro (-2, 3) e raio 5","Centro (2, -3) e raio 5","Centro (2, 3) e raio 25","Centro (-2, -3) e raio 4"],"answer":1,"explanation":"Completando quadrados: (x−2)²−4+(y+3)²−9−12=0, então (x−2)²+(y+3)²=25. O centro é (2,-3) e o raio é 5.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufmg.br/items/f36f0932-0c49-4316-b938-7bad156ad0b4 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufmg.br/items/f36f0932-0c49-4316-b938-7bad156ad0b4 (calibração apenas; questão autoral/similar; não oficial).","skill":"converter a equação geral da circunferência em forma padrão","commonError":"Ler o centro com o mesmo sinal dos termos lineares ou confundir r² com r.","whyWrong":"0 inverte apenas uma coordenada; 2 erra o sinal de y e toma 25 como raio; 3 erra o centro e o valor do raio.","reviewHint":"Na forma (x-h)²+(y-k)²=r², os sinais internos são opostos às coordenadas do centro.","contentId":"mat-analytic"},{"id":"m45-mat-analytic-07","subject":"Matemática","topic":"Geometria analítica","subtopic":"posições relativas de retas","prompt":"As retas r: 2x+y−3=0 e s: 4x+2y+1=0 são:","options":["perpendiculares","coincidentes","paralelas distintas","concorrentes com inclinações iguais"],"answer":2,"explanation":"Os coeficientes de x e y da segunda equação são o dobro dos da primeira, mas o termo independente não é o dobro: s não coincide com r. Logo, são paralelas distintas.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","skill":"classificar retas comparando coeficientes de equações gerais","commonError":"Concluir coincidência porque os coeficientes de x e y são proporcionais, sem conferir o termo independente.","whyWrong":"0 exigiria produto das inclinações igual a -1; 1 exigiria proporcionalidade também nos termos independentes; 3 é contraditória, pois retas distintas com mesma inclinação não são concorrentes.","reviewHint":"Para coincidência, todos os coeficientes devem ser multiplicados pelo mesmo fator, inclusive o termo constante.","contentId":"mat-analytic"},{"id":"m45-mat-analytic-08","subject":"Matemática","topic":"Geometria analítica","subtopic":"distância ponto-reta","prompt":"A distância do ponto P(2,-1) à reta 6x−8y+5=0 é:","options":["5/2","2","25/2","10"],"answer":0,"explanation":"d=|6·2−8·(−1)+5|/√(6²+(-8)²)=25/10=5/2.","difficulty":"avançada","sourceBasis":"https://www.ime.unicamp.br/~dledesma/disciplinasministradas/apostilas/Apostila-GA.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www.ime.unicamp.br/~dledesma/disciplinasministradas/apostilas/Apostila-GA.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar a fórmula da distância perpendicular de ponto a reta","commonError":"Esquecer o módulo ou calcular o denominador como 6+8.","whyWrong":"1 é um resultado intermediário incorreto; 2 usa o numerador 25 sem dividir pela norma dos coeficientes; 3 é a norma √100 e não a distância.","reviewHint":"Separe a conta em numerador absoluto e norma √(a²+b²) antes de simplificar.","contentId":"mat-analytic"},{"id":"m45-mat-analytic-09","subject":"Matemática","topic":"Geometria analítica","subtopic":"interseção de retas","prompt":"Qual é o ponto de interseção das retas y=x+1 e y=−2x+7?","options":["(1, 2)","(2, 3)","(3, 2)","(−2, 3)"],"answer":1,"explanation":"Igualando as expressões: x+1=−2x+7, logo 3x=6 e x=2. Substituindo, y=3; o ponto é (2,3).","difficulty":"avançada","sourceBasis":"https://repositorio.ufmg.br/items/f36f0932-0c49-4316-b938-7bad156ad0b4 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufmg.br/items/f36f0932-0c49-4316-b938-7bad156ad0b4 (calibração apenas; questão autoral/similar; não oficial).","skill":"resolver sistema formado por duas equações de reta e validar o par ordenado","commonError":"Encontrar x corretamente, mas informar (y,x) ou não substituir para obter y.","whyWrong":"0, 2 e 3 não satisfazem simultaneamente as duas equações; em particular, trocar a ordem das coordenadas altera o ponto.","reviewHint":"Depois de encontrar x, calcule y em uma das retas e teste o par na outra.","contentId":"mat-analytic"},{"id":"m45-mat-analytic-10","subject":"Matemática","topic":"Geometria analítica","subtopic":"reta tangente à circunferência","prompt":"A reta 3x+4y+14=0 é tangente à circunferência de centro C(1,2) e raio 5?","options":["Não; é secante, pois a distância é menor que 5.","Não; é externa, pois a distância é maior que 5.","Sim; a distância do centro à reta é exatamente 5.","Sim; toda reta que contém o centro é tangente."],"answer":2,"explanation":"A distância é |3·1+4·2+14|/√(3²+4²)=25/5=5. Como coincide com o raio, a reta é tangente.","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","skill":"classificar a posição de uma reta em relação à circunferência pela distância ao centro","commonError":"Comparar o numerador 25 diretamente com o raio e ignorar a norma dos coeficientes.","whyWrong":"0 seria o caso d<r; 1 seria d>r, mas a distância calculada é 5; 3 confunde reta que passa pelo centro com reta tangente.","reviewHint":"Calcule δ primeiro: δ<r secante, δ=r tangente e δ>r externa.","contentId":"mat-analytic"},{"id":"m45-mat-analytic-11","subject":"Matemática","topic":"Geometria analítica","subtopic":"circunferência por três pontos","prompt":"A circunferência que passa por A(0,0), B(4,0) e C(0,6) tem qual centro e raio?","options":["Centro (4,6) e raio √52","Centro (-2,-3) e raio √13","Centro (2,3) e raio √13","Centro (2,3) e raio 13"],"answer":2,"explanation":"Na forma x²+y²+Dx+Ey+F=0, A dá F=0; B dá D=-4; C dá E=-6. Assim, o centro é (2,3) e r²=2²+3²=13, logo r=√13.","difficulty":"avançada","sourceBasis":"https://repositorio.ufmg.br/items/f36f0932-0c49-4316-b938-7bad156ad0b4 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufmg.br/items/f36f0932-0c49-4316-b938-7bad156ad0b4 (calibração apenas; questão autoral/similar; não oficial).","skill":"determinar circunferência a partir de três pontos não colineares","commonError":"Tomar r² como se fosse r ou usar o ponto (4,6), que não foi dado como centro.","whyWrong":"0 troca o centro pelo ponto obtido somando coordenadas; 1 inverte sinais; 3 mantém r²=13 como raio.","reviewHint":"Monte a equação geral substituindo cada ponto e, ao final, use C=(-D/2,-E/2).","contentId":"mat-analytic"},{"id":"m45-mat-analytic-12","subject":"Matemática","topic":"Geometria analítica","subtopic":"equação paramétrica da reta","prompt":"A reta parametrizada por (x,y)=(1,-2)+t(2,3) passa pelo ponto Q(7,7) para qual valor de t?","options":["2","3","4","5"],"answer":1,"explanation":"Pela coordenada x, 1+2t=7, então t=3. A coordenada y confirma: -2+3·3=7.","difficulty":"avançada","sourceBasis":"https://repositorio.ufmg.br/items/d5222a27-479f-4099-ab4d-0d40c3069c5a (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufmg.br/items/d5222a27-479f-4099-ab4d-0d40c3069c5a (calibração apenas; questão autoral/similar; não oficial).","skill":"interpretar parâmetro e vetor diretor em uma reta","commonError":"Usar apenas a coordenada y com sinal errado ou somar o vetor diretor sem multiplicá-lo por t.","whyWrong":"0, 2 e 3 não fazem simultaneamente 1+2t=7 e -2+3t=7; a verificação das duas coordenadas elimina esses valores.","reviewHint":"Escreva as duas equações escalares e confirme o parâmetro nas duas, não apenas em uma.","contentId":"mat-analytic"},{"id":"m45-mat-analytic-13","subject":"Matemática","topic":"Geometria analítica","subtopic":"lugar geométrico e mediatriz","prompt":"Qual é o lugar geométrico dos pontos P(x,y) equidistantes de A(-2,1) e B(4,1)?","options":["A reta x=1","A reta y=1","A circunferência de centro (1,1)","A reta y=x+1"],"answer":0,"explanation":"Igualando os quadrados das distâncias: (x+2)²+(y−1)²=(x−4)²+(y−1)². Após cancelar o termo comum, obtém-se x=1, a mediatriz do segmento horizontal AB.","difficulty":"avançada","sourceBasis":"https://www.ime.unicamp.br/~dledesma/disciplinasministradas/apostilas/Apostila-GA.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www.ime.unicamp.br/~dledesma/disciplinasministradas/apostilas/Apostila-GA.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"obter a mediatriz como lugar de pontos equidistantes","commonError":"Escolher y=1 por ser a linha que contém os pontos, confundindo segmento com sua mediatriz.","whyWrong":"1 é a reta suporte de AB; 2 descreve uma curva e não o conjunto equidistante; 3 não satisfaz a igualdade para todos os pontos.","reviewHint":"Iguale d(P,A)² e d(P,B)²: os termos quadráticos de P cancelam e resta uma reta.","contentId":"mat-analytic"},{"id":"m45-mat-analytic-14","subject":"Matemática","topic":"Geometria analítica","subtopic":"interseção de reta e circunferência","prompt":"Quantos pontos reais de interseção existem entre a reta y=x+1 e a circunferência x²+y²=25?","options":["Nenhum","Um","Três","Dois"],"answer":3,"explanation":"Substituindo y=x+1: x²+(x+1)²=25, ou 2x²+2x−24=0. As raízes são x=3 e x=-4, produzindo os pontos (3,4) e (-4,-3); portanto há dois pontos.","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufu.br/handle/123456789/25321 (calibração apenas; questão autoral/similar; não oficial).","skill":"combinar substituição de reta na circunferência e análise do discriminante","commonError":"Contar o grau da equação como três pontos ou considerar apenas uma das raízes quadráticas.","whyWrong":"0 ignora que o discriminante é positivo; 1 ocorreria com discriminante zero; 2 é impossível para uma reta e uma circunferência não degenerada neste contexto.","reviewHint":"Substitua a reta, resolva a quadrática e conte apenas as raízes reais distintas.","contentId":"mat-analytic"},{"id":"m45-mat-analytic-15","subject":"Matemática","topic":"Geometria analítica","subtopic":"área por coordenadas e colinearidade","prompt":"Qual é a área do triângulo com vértices A(1,2), B(5,3) e C(2,7)?","options":["9","19","19/2","38"],"answer":2,"explanation":"Usando vetores AB=(4,1) e AC=(1,5), a área é metade do valor absoluto do determinante: |4·5−1·1|/2=19/2.","difficulty":"avançada","sourceBasis":"https://repositorio.ufmg.br/items/f36f0932-0c49-4316-b938-7bad156ad0b4 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufmg.br/items/f36f0932-0c49-4316-b938-7bad156ad0b4 (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular área orientada de triângulo a partir de coordenadas","commonError":"Esquecer o fator 1/2 ou usar dois vetores que não partem do mesmo vértice.","whyWrong":"0 não é o determinante correto; 1 é o dobro da área; 3 é o dobro do determinante e também não representa área.","reviewHint":"Forme dois vetores com a mesma origem, calcule o determinante e divida seu módulo por 2.","contentId":"mat-analytic"},{"id":"m45-mat-geometria-01","subject":"Matemática","topic":"Geometria plana","subtopic":"ângulos e retas paralelas","prompt":"Duas retas paralelas são cortadas por uma transversal. Dois ângulos internos do mesmo lado da transversal medem (3x + 20)° e (5x − 40)°. Qual é o valor de x?","options":["20","25","30","35"],"answer":1,"explanation":"Ângulos internos do mesmo lado de uma transversal em paralelas são suplementares: (3x+20)+(5x−40)=180. Assim, 8x−20=180, 8x=200 e x=25.","difficulty":"intermediária","sourceBasis":"https://sites.icmc.usp.br/manfio/GeoAxiomatica.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://sites.icmc.usp.br/manfio/GeoAxiomatica.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar relações angulares em retas paralelas cortadas por transversal","commonError":"Igualar os dois ângulos em vez de reconhecer que são suplementares.","whyWrong":"Os ângulos estão no mesmo lado da transversal e entre as paralelas; portanto somam 180°, não são correspondentes nem alternos internos.","reviewHint":"Classifique a posição dos ângulos antes de montar a equação: correspondentes e alternos são iguais; colaterais internos são suplementares.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-02","subject":"Matemática","topic":"Geometria plana","subtopic":"triângulos e ângulo externo","prompt":"No triângulo ABC, AB = AC e o ângulo interno em A mede 40°. Qual é a medida do ângulo externo adjacente ao ângulo interno em C?","options":["40°","70°","110°","140°"],"answer":2,"explanation":"Como AB=AC, os ângulos da base B e C são iguais. Cada um vale (180°−40°)/2=70°. O ângulo externo adjacente a C é suplementar a 70°, portanto mede 110°.","difficulty":"intermediária","sourceBasis":"https://www.ime.usp.br/~afisher/ps/MAT0230/Fundamentos_de_geometria_planaMachado.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www.ime.usp.br/~afisher/ps/MAT0230/Fundamentos_de_geometria_planaMachado.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"usar soma dos ângulos do triângulo e propriedade do isósceles","commonError":"Responder o ângulo interno da base, sem converter para o externo pedido.","whyWrong":"70° é o ângulo interno em C; o externo adjacente forma um par linear com ele e deve completar 180°.","reviewHint":"Calcule primeiro o ângulo interno e, no final, use externo + interno = 180°.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-03","subject":"Matemática","topic":"Geometria plana","subtopic":"congruência de triângulos","prompt":"Dois triângulos têm, respectivamente, lados de 7 cm e 10 cm formando um ângulo incluído de 48°; no segundo triângulo, esses dois lados também medem 7 cm e 10 cm e o ângulo entre eles é 48°. O que se pode concluir?","options":["São semelhantes apenas pelo caso AA.","São congruentes pelo caso LAL.","São congruentes apenas porque têm o mesmo perímetro.","Não é possível estabelecer relação entre eles."],"answer":1,"explanation":"Há dois lados correspondentes iguais e o ângulo compreendido entre eles igual. Isso caracteriza o caso LAL (lado-ângulo-lado), que garante congruência dos triângulos.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufu.br/handle/123456789/25320 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufu.br/handle/123456789/25320 (calibração apenas; questão autoral/similar; não oficial).","skill":"identificar critérios de congruência a partir de dados correspondentes","commonError":"Aplicar AA sem que dois ângulos tenham sido fornecidos.","whyWrong":"O dado decisivo é a igualdade de dois lados e do ângulo entre eles; isso é LAL, não AA. Perímetro igual isoladamente não garante congruência.","reviewHint":"Observe se o ângulo informado está entre os dois lados conhecidos; essa posição distingue LAL de outros critérios.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-04","subject":"Matemática","topic":"Geometria plana","subtopic":"semelhança e perímetro","prompt":"Dois polígonos semelhantes têm razão linear do menor para o maior igual a 3/5. Se o perímetro do menor é 36 cm, qual é o perímetro do maior?","options":["21,6 cm","54 cm","60 cm","96 cm"],"answer":2,"explanation":"Perímetros de figuras semelhantes variam na mesma razão dos lados. Se Pmenor/Pmaior=3/5, então 36/Pmaior=3/5, logo Pmaior=36·5/3=60 cm.","difficulty":"intermediária","sourceBasis":"https://www.ime.usp.br/~afisher/ps/MAT0230/Fundamentos_de_geometria_planaMachado.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www.ime.usp.br/~afisher/ps/MAT0230/Fundamentos_de_geometria_planaMachado.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"transferir a razão de semelhança para comprimentos e perímetros","commonError":"Aplicar a razão ao quadrado, que é própria de áreas.","whyWrong":"Perímetro é soma de comprimentos, portanto cresce por 5/3; o quadrado da razão só seria usado para áreas correspondentes.","reviewHint":"Pergunte qual grandeza está sendo comparada: comprimento/perímetro usa k; área usa k².","contentId":"mat-geometria"},{"id":"m45-mat-geometria-05","subject":"Matemática","topic":"Geometria plana","subtopic":"Teorema de Tales","prompt":"Em um triângulo, uma reta paralela à base divide um dos lados em segmentos de 6 cm e 9 cm e o outro lado em segmentos de 8 cm e x cm, em posições correspondentes. Qual é x?","options":["10 cm","12 cm","14 cm","15 cm"],"answer":1,"explanation":"Pelo Teorema de Tales, os segmentos correspondentes são proporcionais: 6/9=8/x. Assim, 6x=72 e x=12 cm.","difficulty":"intermediária","sourceBasis":"https://livroaberto.ufpa.br/items/be3babdc-ae14-4ea5-9d30-4fa32030e61f (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://livroaberto.ufpa.br/items/be3babdc-ae14-4ea5-9d30-4fa32030e61f (calibração apenas; questão autoral/similar; não oficial).","skill":"montar proporção entre segmentos determinados por paralelas","commonError":"Comparar 6 com 8 e 9 com x sem verificar a correspondência posicional.","whyWrong":"A proporção deve manter a mesma ordem nos dois lados: o primeiro segmento corresponde ao primeiro e o segundo ao segundo.","reviewHint":"Escreva os segmentos de cada lado de cima para baixo antes de cruzar os produtos.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-06","subject":"Matemática","topic":"Geometria plana","subtopic":"triângulo retângulo e Pitágoras","prompt":"Um triângulo retângulo tem catetos de 9 cm e 12 cm. Qual é a área desse triângulo?","options":["45 cm²","54 cm²","108 cm²","144 cm²"],"answer":1,"explanation":"Os catetos podem ser base e altura perpendicular. Logo, A=(9·12)/2=54 cm². A hipotenusa, 15 cm, não é necessária para a área.","difficulty":"intermediária","sourceBasis":"https://www.ime.usp.br/~afisher/ps/MAT0230/Fundamentos_de_geometria_planaMachado.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www.ime.usp.br/~afisher/ps/MAT0230/Fundamentos_de_geometria_planaMachado.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular área de triângulo retângulo reconhecendo base e altura","commonError":"Multiplicar os catetos e esquecer a divisão por 2.","whyWrong":"O produto base vezes altura é a área do retângulo correspondente; o triângulo ocupa metade dele.","reviewHint":"Mesmo quando os lados são catetos, escreva A=b·h/2 antes de substituir.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-07","subject":"Matemática","topic":"Geometria plana","subtopic":"trapézio e áreas","prompt":"Um trapézio tem bases paralelas de 18 cm e 10 cm e altura de 7 cm. Qual é sua área?","options":["91 cm²","98 cm²","126 cm²","196 cm²"],"answer":1,"explanation":"A área do trapézio é A=(B+b)h/2. Portanto, A=(18+10)·7/2=28·3,5=98 cm².","difficulty":"intermediária","sourceBasis":"https://repositorio.ufu.br/handle/123456789/25320 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufu.br/handle/123456789/25320 (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar fórmula de área de trapézio com altura perpendicular","commonError":"Usar a soma das bases sem dividir por 2.","whyWrong":"A média das bases é (B+b)/2; multiplicá-la pela altura produz 98 cm², não 196 cm².","reviewHint":"Interprete a fórmula como média das bases vezes altura: isso ajuda a lembrar o fator 1/2.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-08","subject":"Matemática","topic":"Geometria plana","subtopic":"polígonos regulares","prompt":"Cada ângulo externo de um polígono regular mede 24°. Quantos lados tem esse polígono e qual é a soma de seus ângulos internos?","options":["12 lados e 1.800°","15 lados e 2.340°","15 lados e 2.700°","24 lados e 3.960°"],"answer":1,"explanation":"A soma dos ângulos externos é 360°, então n=360/24=15. A soma interna é (n−2)·180°=13·180°=2.340°.","difficulty":"avançada","sourceBasis":"https://sites.icmc.usp.br/manfio/GeoAxiomatica.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://sites.icmc.usp.br/manfio/GeoAxiomatica.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"relacionar ângulo externo, número de lados e soma interna de polígono regular","commonError":"Dividir 180° pelo ângulo externo ou usar n·180° para a soma interna.","whyWrong":"Uma volta completa fornece 360° de ângulos externos; a soma interna correta é (n−2)·180°, não n·180°.","reviewHint":"Resolva em duas etapas: primeiro n pela volta completa, depois a soma interna pela decomposição em triângulos.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-09","subject":"Matemática","topic":"Geometria plana","subtopic":"figuras compostas e perímetro","prompt":"Um retângulo de 12 cm por 8 cm tem um semicírculo de diâmetro 8 cm anexado externamente a um de seus lados menores. Qual é o perímetro do contorno externo da figura?","options":["24 + 4π cm","28 + 4π cm","32 + 4π cm","40 + 8π cm"],"answer":2,"explanation":"O lado menor de 8 cm fica interno à união. O contorno contém os dois lados de 12 cm, o outro lado de 8 cm e o arco semicircular de raio 4, cujo comprimento é 4π. Logo, P=12+12+8+4π=32+4π cm.","difficulty":"avançada","sourceBasis":"https://www.ime.usp.br/~afisher/ps/MAT0230/Fundamentos_de_geometria_planaMachado.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www.ime.usp.br/~afisher/ps/MAT0230/Fundamentos_de_geometria_planaMachado.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"decompor o contorno de uma figura composta e usar comprimento de arco","commonError":"Somar o diâmetro de 8 cm ao contorno, embora ele seja a linha de contato interna.","whyWrong":"O diâmetro é substituído pelo arco na borda externa; apenas o lado menor oposto permanece exposto.","reviewHint":"Percorra o contorno com o dedo: inclua apenas segmentos e arcos que podem ser vistos externamente.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-10","subject":"Matemática","topic":"Geometria plana","subtopic":"circunferência e cordas","prompt":"Duas cordas de uma circunferência se intersectam internamente. Em uma corda, os segmentos determinados pelo ponto de interseção medem 3 cm e 8 cm; na outra, medem 4 cm e x cm. Qual é x?","options":["4 cm","5 cm","6 cm","8 cm"],"answer":2,"explanation":"Pelo teorema das cordas que se cruzam, o produto dos segmentos de uma corda é igual ao produto dos segmentos da outra: 3·8=4·x. Assim, 24=4x e x=6 cm.","difficulty":"avançada","sourceBasis":"https://livroaberto.ufpa.br/items/be3babdc-ae14-4ea5-9d30-4fa32030e61f (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://livroaberto.ufpa.br/items/be3babdc-ae14-4ea5-9d30-4fa32030e61f (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar produto dos segmentos de cordas que se intersectam","commonError":"Somar segmentos ou igualar segmentos de cordas diferentes.","whyWrong":"A relação é multiplicativa: PA·PB=PC·PD. Não há regra geral de igualdade ou soma entre os quatro segmentos.","reviewHint":"Escreva os dois produtos completos antes de substituir os números.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-11","subject":"Matemática","topic":"Geometria plana","subtopic":"área de triângulo e Heron","prompt":"Um triângulo tem lados 13 cm, 14 cm e 15 cm. Qual é sua área?","options":["42 cm²","84 cm²","96 cm²","105 cm²"],"answer":1,"explanation":"O semiperímetro é s=(13+14+15)/2=21. Pela fórmula de Heron, A=√[21·(21−13)·(21−14)·(21−15)]=√(21·8·7·6)=√7056=84 cm².","difficulty":"avançada","sourceBasis":"https://livroaberto.ufpa.br/items/be3babdc-ae14-4ea5-9d30-4fa32030e61f (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://livroaberto.ufpa.br/items/be3babdc-ae14-4ea5-9d30-4fa32030e61f (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular área a partir dos três lados usando o semiperímetro","commonError":"Usar o perímetro no lugar do semiperímetro ou esquecer um dos fatores de Heron.","whyWrong":"A fórmula exige s=(a+b+c)/2 e os fatores s−a, s−b e s−c; usar 42 gera uma expressão diferente e incorreta.","reviewHint":"Calcule s em uma linha separada e confira que os quatro fatores sob a raiz são positivos.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-12","subject":"Matemática","topic":"Geometria plana","subtopic":"quadriláteros e diagonais","prompt":"Um quadrilátero convexo possui diagonais perpendiculares de comprimentos 12 cm e 20 cm. Qual é sua área?","options":["60 cm²","120 cm²","240 cm²","400 cm²"],"answer":1,"explanation":"Diagonais perpendiculares dividem o quadrilátero em quatro triângulos cujas alturas, tomadas sobre as diagonais, totalizam a outra diagonal. A soma das áreas resulta em A=D·d/2=(12·20)/2=120 cm².","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/handle/123456789/25320 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufu.br/handle/123456789/25320 (calibração apenas; questão autoral/similar; não oficial).","skill":"reconhecer a área de quadrilátero com diagonais perpendiculares","commonError":"Multiplicar as diagonais sem dividir por 2, como se fosse um retângulo.","whyWrong":"A decomposição em triângulos fornece metade do produto das diagonais, não o produto inteiro.","reviewHint":"Imagine a interseção das diagonais e some as áreas dos quatro triângulos formados.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-13","subject":"Matemática","topic":"Geometria plana","subtopic":"semelhança e escala de áreas","prompt":"Dois polígonos semelhantes têm razão entre suas áreas igual a 49/81, do menor para o maior. Se o perímetro do menor é 56 cm, qual é o perímetro do maior?","options":["64 cm","72 cm","80 cm","96 cm"],"answer":1,"explanation":"A razão linear é a raiz da razão de áreas: k=√(49/81)=7/9. Assim, 56/Pmaior=7/9, e Pmaior=56·9/7=72 cm.","difficulty":"avançada","sourceBasis":"https://sites.icmc.usp.br/manfio/GeoAxiomatica.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://sites.icmc.usp.br/manfio/GeoAxiomatica.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"extrair razão linear da razão de áreas e aplicá-la ao perímetro","commonError":"Usar diretamente 49/81 como razão de perímetros.","whyWrong":"A área escala com o quadrado da razão linear; primeiro é necessário extrair √(49/81)=7/9.","reviewHint":"Escreva explicitamente área=k² e perímetro=k antes de resolver.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-14","subject":"Matemática","topic":"Geometria plana","subtopic":"círculo e coroa circular","prompt":"Uma coroa circular tem raio externo 10 cm e raio interno 6 cm. Qual é sua área, em função de π?","options":["16π cm²","36π cm²","64π cm²","100π cm²"],"answer":2,"explanation":"A coroa é a área do círculo maior menos a do círculo menor: π·10²−π·6²=π(100−36)=64π cm².","difficulty":"avançada","sourceBasis":"https://www.ime.usp.br/~afisher/ps/MAT0230/Fundamentos_de_geometria_planaMachado.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www.ime.usp.br/~afisher/ps/MAT0230/Fundamentos_de_geometria_planaMachado.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular área por diferença de regiões circulares concêntricas","commonError":"Subtrair os raios e elevar a diferença ao quadrado.","whyWrong":"A área é diferença dos quadrados dos raios, R²−r², e não (R−r)².","reviewHint":"Escreva as duas áreas completas antes de fatorar π.","contentId":"mat-geometria"},{"id":"m45-mat-geometria-15","subject":"Matemática","topic":"Geometria plana","subtopic":"quadrilátero cíclico e teorema de Ptolomeu","prompt":"Um quadrilátero cíclico tem lados consecutivos de 4 cm, 5 cm, 6 cm e 7 cm. Uma diagonal mede 8 cm. Qual é a medida da outra diagonal?","options":["59/8 cm","8 cm","15/2 cm","59/4 cm"],"answer":0,"explanation":"Pelo teorema de Ptolomeu, o produto das diagonais é igual à soma dos produtos dos lados opostos: 8d=4·6+5·7=24+35=59. Portanto, d=59/8 cm.","difficulty":"avançada","sourceBasis":"https://livroaberto.ufpa.br/items/be3babdc-ae14-4ea5-9d30-4fa32030e61f (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://livroaberto.ufpa.br/items/be3babdc-ae14-4ea5-9d30-4fa32030e61f (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar Ptolomeu em quadrilátero inscrito na circunferência","commonError":"Aplicar a relação sem verificar que o quadrilátero é cíclico ou multiplicar lados adjacentes.","whyWrong":"Ptolomeu exige quadrilátero cíclico e usa os produtos dos pares de lados opostos: 4·6 e 5·7 neste ordenamento.","reviewHint":"Marque a ordem dos quatro lados ao redor da figura e identifique quais pares são opostos.","contentId":"mat-geometria"},{"id":"m45-mat-progressions-01","subject":"Matemática","topic":"Progressões e funções","subtopic":"sequências e identificação de PA","prompt":"A sequência 7, 11, 15, 19, ... é uma progressão aritmética. Qual é o seu 12º termo?","options":["47","51","55","59"],"answer":1,"explanation":"A diferença comum é r=4. Como a1=7, a12=7+(12-1)·4=7+44=51.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer a diferença comum e calcular termo geral de uma PA","commonError":"Usar 12 multiplicações da razão, esquecendo que do primeiro ao 12º termo existem 11 intervalos.","whyWrong":"0 corresponde a usar apenas 10 intervalos; 2 e 3 resultam de diferenças ou posições incorretas e não satisfazem a sequência iniciada em 7.","reviewHint":"Escreva a_n=a_1+(n-1)r e identifique explicitamente a1, r e n antes de operar.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-02","subject":"Matemática","topic":"Progressões e funções","subtopic":"PA: determinação de termo e razão","prompt":"Em uma PA, a3=10 e a8=30. Qual é o valor de a15?","options":["54","58","62","66"],"answer":1,"explanation":"Entre a3 e a8 há cinco intervalos: 30-10=5r, portanto r=4. Assim, a15=a8+7r=30+28=58.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"relacionar termos não consecutivos de uma PA por meio da razão","commonError":"Dividir a diferença por seis, contando termos em vez de intervalos.","whyWrong":"0 usa cinco intervalos para avançar de a8 até a13; 2 soma oito razões a a7; 3 não respeita a razão obtida de a3 e a8.","reviewHint":"De uma posição p até q, a diferença é (q-p)r, não qr.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-03","subject":"Matemática","topic":"Progressões e funções","subtopic":"PA: soma de termos","prompt":"Uma PA tem primeiro termo 12 e razão -2. Qual é a soma dos seus 20 primeiros termos?","options":["-140","-120","140","-280"],"answer":0,"explanation":"O 20º termo é a20=12+19·(-2)=-26. Logo S20=20(12+(-26))/2=10·(-14)=-140.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular soma de PA decrescente usando o último termo","commonError":"Aplicar a fórmula de soma sem encontrar o 20º termo ou perder o sinal da razão negativa.","whyWrong":"1 e 3 não usam corretamente a média entre primeiro e último termo; 2 troca o sinal e trata uma soma negativa como positiva.","reviewHint":"Calcule primeiro a_n e só então use S_n=n(a_1+a_n)/2; a média pode ser negativa.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-04","subject":"Matemática","topic":"Progressões e funções","subtopic":"função afim e inclinação","prompt":"A função afim f passa pelos pontos (2,7) e (6,19). Qual é o valor de f(10)?","options":["29","31","33","37"],"answer":1,"explanation":"A inclinação é (19-7)/(6-2)=3. Usando (2,7), f(x)=3x+1; portanto f(10)=31.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"obter a lei de uma função afim a partir de dois pontos","commonError":"Usar a ordenada 7 como coeficiente angular ou calcular a inclinação invertendo numerador e denominador.","whyWrong":"0 e 2 refletem erros na inclinação ou no intercepto; 3 não passa pelos dois pontos dados, pois a variação de 2 para 6 deve produzir aumento 12.","reviewHint":"Calcule a=(y2-y1)/(x2-x1), depois descubra b substituindo qualquer ponto.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-05","subject":"Matemática","topic":"Progressões e funções","subtopic":"função quadrática: vértice","prompt":"Considere f(x)=-x²+6x-1. Qual afirmação descreve corretamente o vértice e o extremo da parábola?","options":["O vértice é (3,-10) e representa um mínimo.","O vértice é (-3,8) e representa um máximo.","O vértice é (3,8) e representa um máximo.","O vértice é (6, -1) e representa um mínimo."],"answer":2,"explanation":"xv=-b/(2a)=-6/(-2)=3 e f(3)=-9+18-1=8. Como a=-1<0, a parábola é voltada para baixo e o vértice é um máximo.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"determinar o vértice e interpretar a concavidade de uma quadrática","commonError":"Confundir a coordenada x do vértice com a coordenada y ou esquecer que o sinal de a define o tipo de extremo.","whyWrong":"0 troca o sinal do valor de f(3); 1 troca o sinal de xv; 3 usa coeficientes da expressão como se fossem diretamente as coordenadas do vértice.","reviewHint":"Use xv=-b/(2a), calcule yv=f(xv) e só depois classifique como máximo ou mínimo.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-06","subject":"Matemática","topic":"Progressões e funções","subtopic":"função quadrática: raízes e sinal","prompt":"Para f(x)=2x²-5x-3, em qual intervalo a função é negativa?","options":["(-∞,-1/2) e (3,∞)","(-1/2,3)","(-∞,3)","(-1/2,∞)"],"answer":1,"explanation":"As raízes são x=(5±7)/4, isto é, -1/2 e 3. Como a=2>0, a função é negativa entre as raízes: (-1/2,3).","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"combinar raízes e concavidade para analisar o sinal da quadrática","commonError":"Marcar as regiões externas sem observar que a parábola tem concavidade para cima.","whyWrong":"0 é o conjunto positivo; 2 e 3 incluem somente parte do intervalo negativo e ignoram uma das raízes ou a mudança de sinal.","reviewHint":"Encontre as duas raízes, desenhe uma parábola com a>0 e teste um ponto entre elas.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-07","subject":"Matemática","topic":"Progressões e funções","subtopic":"PG: termo geral e razão negativa","prompt":"Em uma PG, a1=4 e q=-3/2. Qual é o sexto termo?","options":["-243/8","243/8","-81/8","-729/8"],"answer":0,"explanation":"a6=4(-3/2)^(6-1)=4(-3/2)^5=4·(-243/32)=-243/8. O expoente ímpar preserva o sinal negativo.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/082022/219b27a21d08c9b390fcb2d42d74fc0c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/082022/219b27a21d08c9b390fcb2d42d74fc0c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"usar o termo geral de PG com razão fracionária e negativa","commonError":"Usar expoente 6 em vez de 5 ou retirar o sinal negativo ao elevar a razão.","whyWrong":"1 ignora o sinal alternado; 2 usa potência ou fator incorreto; 3 corresponde a um expoente maior que o necessário e não é o sexto termo.","reviewHint":"Conte as multiplicações: do primeiro ao sexto termo são cinco; avalie separadamente sinal e módulo.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-08","subject":"Matemática","topic":"Progressões e funções","subtopic":"PG: soma finita","prompt":"Qual é a soma dos quatro primeiros termos da PG 81, 27, 9, ...?","options":["108","120","121","243/2"],"answer":1,"explanation":"Os quatro termos são 81, 27, 9 e 3, pois q=1/3. A soma é 81+27+9+3=120, também obtida pela fórmula da soma finita.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/082022/219b27a21d08c9b390fcb2d42d74fc0c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/082022/219b27a21d08c9b390fcb2d42d74fc0c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular soma finita de PG decrescente","commonError":"Continuar a soma indefinidamente ou usar a soma infinita quando o enunciado pede quatro termos.","whyWrong":"0 omite o quarto termo 3; 2 soma uma unidade extra; 3 é resultado de uma aplicação algébrica incorreta e excede o total dos quatro termos.","reviewHint":"Determine q e escreva explicitamente os n termos pedidos antes de decidir entre soma direta e fórmula.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-09","subject":"Matemática","topic":"Progressões e funções","subtopic":"função exponencial e porcentagem","prompt":"Uma quantidade inicial de 500 unidades cresce 10% por período. Qual é a quantidade após três períodos, sem arredondar durante o cálculo?","options":["650","665,5","665","550"],"answer":1,"explanation":"Crescimento de 10% multiplica por 1,10 a cada período. Logo P(3)=500·1,1³=500·1,331=665,5.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/082022/219b27a21d08c9b390fcb2d42d74fc0c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/082022/219b27a21d08c9b390fcb2d42d74fc0c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"modelar crescimento percentual por função exponencial","commonError":"Adicionar 10 unidades por período ou aplicar 10% somente uma vez ao valor inicial.","whyWrong":"0 resulta de crescimento linear aproximado; 2 trunca o valor correto; 3 aplica a taxa uma única vez e ignora a composição dos períodos.","reviewHint":"Percentual sucessivo é fator multiplicativo: use P0(1+k)^t e mantenha a taxa em forma decimal.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-10","subject":"Matemática","topic":"Progressões e funções","subtopic":"função logarítmica: equação","prompt":"Resolva, nos reais, log₂(x-3)=4.","options":["x=7","x=11","x=16","x=19"],"answer":3,"explanation":"A equação equivale a x-3=2⁴=16, portanto x=19. O argumento x-3 é positivo nessa solução, então a condição de existência é satisfeita.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/082022/219b27a21d08c9b390fcb2d42d74fc0c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/082022/219b27a21d08c9b390fcb2d42d74fc0c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"converter uma equação logarítmica para a forma exponencial","commonError":"Resolver x-3=4, tratando o valor do logaritmo como se fosse o argumento.","whyWrong":"0 e 1 não aplicam a potência da base; 2 confunde 2⁴ com 2³ ou não soma corretamente o deslocamento 3.","reviewHint":"Use log_a A=b ⇔ A=a^b e só depois isole x; confira sempre argumento positivo.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-11","subject":"Matemática","topic":"Progressões e funções","subtopic":"gráficos de função exponencial","prompt":"Sobre o gráfico de y=-2^(x+1)+4, qual conjunto de características está correto?","options":["É decrescente, tem assíntota horizontal y=4 e imagem (-∞,4).","É crescente, tem assíntota y=-4 e imagem (-4,∞).","É decrescente, tem assíntota y=-4 e imagem (-4,∞).","É crescente, tem assíntota y=4 e imagem (4,∞)."],"answer":0,"explanation":"2^(x+1) cresce; o sinal negativo reflete o gráfico, tornando-o decrescente. O +4 desloca a assíntota de y=0 para y=4, e os valores ficam abaixo de 4.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/082022/219b27a21d08c9b390fcb2d42d74fc0c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/082022/219b27a21d08c9b390fcb2d42d74fc0c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"interpretar reflexão, translação, monotonicidade e imagem de exponencial","commonError":"Ler o sinal negativo como se alterasse a base, sem refletir a função em torno do eixo horizontal.","whyWrong":"1 e 3 invertem crescimento e imagem; 2 desloca a assíntota para baixo, embora o termo constante seja +4.","reviewHint":"Analise em sequência: exponencial base 2, reflexão pelo menos, depois translação vertical de 4.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-12","subject":"Matemática","topic":"Progressões e funções","subtopic":"composição de funções","prompt":"Se f(x)=2x+1 e g(x)=x-4, qual é (f∘g)(x)?","options":["2x-3","2x-7","2x+5","x-7"],"answer":1,"explanation":"Em f∘g, aplica-se g primeiro: f(g(x))=f(x-4)=2(x-4)+1=2x-7.","difficulty":"intermediária","sourceBasis":"https://wp.ufpel.edu.br/projetogama/files/2022/07/Livro-1-GAMA.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://wp.ufpel.edu.br/projetogama/files/2022/07/Livro-1-GAMA.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular composição respeitando a ordem das funções","commonError":"Calcular g(f(x)) ou substituir x-4 sem distribuir corretamente o fator 2.","whyWrong":"0 soma o termo constante como se fosse +5; 2 corresponde a outra ordem ou erro de sinal; 3 perde o fator 2 de f.","reviewHint":"Escreva a seta x → g(x) → f(g(x)); a função mais próxima de x é aplicada primeiro.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-13","subject":"Matemática","topic":"Progressões e funções","subtopic":"função inversa","prompt":"Qual é a função inversa de f(x)=3x-5?","options":["f⁻¹(x)=(x+5)/3","f⁻¹(x)=(x-5)/3","f⁻¹(x)=3x+5","f⁻¹(x)=5-3x"],"answer":0,"explanation":"Escreva y=3x-5, troque x e y: x=3y-5. Isolando y, y=(x+5)/3; essa é a inversa.","difficulty":"avançada","sourceBasis":"https://wp.ufpel.edu.br/projetogama/files/2022/07/Livro-1-GAMA.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://wp.ufpel.edu.br/projetogama/files/2022/07/Livro-1-GAMA.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"obter e verificar a inversa de uma função afim","commonError":"Trocar apenas o sinal de um coeficiente ou esquecer de dividir por 3 ao isolar a variável.","whyWrong":"1 mantém o deslocamento com sinal inadequado; 2 e 3 não desfazem simultaneamente a multiplicação por 3 e a subtração de 5.","reviewHint":"Use o procedimento y=f(x), troque x por y e isole y; verifique compondo nos dois sentidos.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-14","subject":"Matemática","topic":"Progressões e funções","subtopic":"relação entre PA e função afim","prompt":"A sequência é dada por a_n=5+3(n-1), para n=1,2,3,... Qual função afim coincide com seus valores nas posições inteiras positivas?","options":["f(x)=5x+3","f(x)=3x+5","f(x)=3x+2","f(x)=5+3x-1"],"answer":2,"explanation":"Desenvolvendo, a_n=5+3n-3=3n+2. Logo a função afim f(x)=3x+2 coincide com a sequência quando x=n.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/395d0defbcdfdb88709310531589757c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"converter termo geral de PA em função afim equivalente","commonError":"Tomar 5 como coeficiente de x ou esquecer de distribuir o 3 em (n-1).","whyWrong":"0 troca o papel do primeiro termo e da razão; 1 não ajusta o índice; 3 mantém uma expressão equivalente mal simplificada e, como escrita, não corresponde a 3x+2.","reviewHint":"Expanda o parêntese e simplifique antes de comparar com a forma ax+b.","contentId":"mat-progressions"},{"id":"m45-mat-progressions-15","subject":"Matemática","topic":"Progressões e funções","subtopic":"equação exponencial com mudança de base","prompt":"Resolva 3^(2x-1)=27^(x-2), considerando x real.","options":["x=2","x=3","x=5","x=7"],"answer":2,"explanation":"Como 27=3³, a igualdade vira 3^(2x-1)=3^(3x-6). As bases são iguais e diferentes de 1, então 2x-1=3x-6, dando x=5.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/082022/219b27a21d08c9b390fcb2d42d74fc0c.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/082022/219b27a21d08c9b390fcb2d42d74fc0c.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"reduzir potências à mesma base e resolver equação exponencial","commonError":"Igualar os expoentes antes de reescrever 27 como potência de 3 ou distribuir incorretamente 3(x-2).","whyWrong":"0, 1 e 3 vêm de manipulações lineares que não satisfazem a igualdade de expoentes; substituindo x=5, ambos os expoentes são 9.","reviewHint":"Procure uma base comum; depois compare expoentes somente porque a função exponencial nessa base é injetiva.","contentId":"mat-progressions"},{"id":"m45-mat-spatial-01","subject":"Matemática","topic":"Geometria espacial","subtopic":"unidades e paralelepípedos","prompt":"Um reservatório em forma de paralelepípedo retângulo mede 1,2 m de comprimento, 80 cm de largura e 50 cm de altura. Qual é sua capacidade, em litros?","options":["48 L","480 L","4.800 L","0,48 L"],"answer":1,"explanation":"Convertem-se as dimensões para metro: 80 cm = 0,8 m e 50 cm = 0,5 m. O volume é 1,2 × 0,8 × 0,5 = 0,48 m³. Como 1 m³ = 1.000 L, a capacidade é 480 L.","difficulty":"intermediária","sourceBasis":"https://openstax.org/books/prealgebra-2e/pages/9-6-solve-geometry-applications-volume-and-surface-area (calibração apenas; unidades e volume, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://openstax.org/books/prealgebra-2e/pages/9-6-solve-geometry-applications-volume-and-surface-area (calibração apenas; questão autoral/similar; não oficial).","skill":"converter unidades cúbicas e calcular volume de paralelepípedo","commonError":"Multiplicar medidas em centímetros por medidas em metros sem conversão ou confundir m³ com litros.","whyWrong":"0 resulta de tratar 0,48 m³ como 48 L; 2 desloca a conversão de m³ para litros por um fator 10; 3 confunde o valor numérico em m³ com o valor em litros.","reviewHint":"Uniformize as dimensões primeiro e use 1 m³ = 1.000 L somente depois do produto.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-02","subject":"Matemática","topic":"Geometria espacial","subtopic":"prismas e área da base","prompt":"Um prisma reto tem área da base igual a 12 cm² e altura igual a 9 cm. Qual é o seu volume?","options":["21 cm³","36 cm³","108 cm³","324 cm³"],"answer":2,"explanation":"Para qualquer prisma, o volume é o produto da área da base pela altura. Portanto, V = 12 × 9 = 108 cm³.","difficulty":"intermediária","sourceBasis":"https://math.libretexts.org/Bookshelves/Applied_Mathematics/Developmental_Math_(NROC)/07%3A_Geometry/7.03%3A_Volume_of_Geometric_Solids/7.3.01%3A_Solids (calibração apenas; identificação e volume de sólidos, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://math.libretexts.org/Bookshelves/Applied_Mathematics/Developmental_Math_(NROC)/07%3A_Geometry/7.03%3A_Volume_of_Geometric_Solids/7.3.01%3A_Solids (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar V = área da base × altura em um prisma","commonError":"Somar a área da base à altura ou usar uma fórmula de pirâmide.","whyWrong":"0 soma 12 e 9; 1 multiplica apenas parte das medidas; 3 equivale a multiplicar 12 por 9 e ainda por 3, inserindo um fator que não existe para prismas.","reviewHint":"Prisma mantém a mesma seção ao longo da altura: volume é área da base vezes a distância entre as bases.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-03","subject":"Matemática","topic":"Geometria espacial","subtopic":"área total de paralelepípedo","prompt":"Uma caixa fechada tem formato de paralelepípedo retângulo com dimensões 2 cm, 3 cm e 5 cm. Qual é a área total de sua superfície?","options":["30 cm²","46 cm²","62 cm²","94 cm²"],"answer":2,"explanation":"As três áreas de pares de faces são 2×3, 2×5 e 3×5. Logo, A_t = 2(6 + 10 + 15) = 62 cm².","difficulty":"intermediária","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; áreas de sólidos, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"somar pares de faces para obter área total","commonError":"Calcular apenas a área de uma face ou confundir área total com volume.","whyWrong":"0 é a soma 2×3 + 2×5 + 3×5, sem duplicar as faces opostas; 1 usa uma combinação incompleta; 3 não corresponde à soma correta das seis faces.","reviewHint":"Em uma caixa fechada, cada retângulo aparece duas vezes: A_t = 2(ab + ac + bc).","contentId":"mat-spatial"},{"id":"m45-mat-spatial-04","subject":"Matemática","topic":"Geometria espacial","subtopic":"pirâmides regulares","prompt":"Uma pirâmide de base quadrada tem lado da base 8 cm e altura perpendicular 6 cm. Qual é o volume da pirâmide?","options":["64 cm³","128 cm³","192 cm³","384 cm³"],"answer":1,"explanation":"A base quadrada tem área 8² = 64 cm². Como o volume de uma pirâmide é um terço da área da base vezes a altura, V = 64×6/3 = 128 cm³.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; pirâmides e volumes, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular volume de pirâmide a partir da base e da altura","commonError":"Usar a fórmula do prisma e esquecer o fator 1/3.","whyWrong":"0 é somente a área da base; 2 é o produto base×altura sem dividir por 3; 3 triplica esse produto, em vez de aplicar o fator correto.","reviewHint":"Associe pirâmide ao modelo de três pirâmides equivalentes preenchendo um prisma de mesma base e altura.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-05","subject":"Matemática","topic":"Geometria espacial","subtopic":"cilindros e volume","prompt":"Um cilindro circular reto tem raio 4 cm e altura 5 cm. Qual é seu volume exato?","options":["20π cm³","40π cm³","80π cm³","160π cm³"],"answer":2,"explanation":"A base é um círculo de área π·4² = 16π cm². Multiplicando pela altura, V = 16π·5 = 80π cm³.","difficulty":"intermediária","sourceBasis":"https://openstax.org/books/prealgebra-2e/pages/9-6-solve-geometry-applications-volume-and-surface-area (calibração apenas; cilindros e volume, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://openstax.org/books/prealgebra-2e/pages/9-6-solve-geometry-applications-volume-and-surface-area (calibração apenas; questão autoral/similar; não oficial).","skill":"usar a área circular da base no volume do cilindro","commonError":"Usar o diâmetro no lugar do raio ou esquecer de elevar o raio ao quadrado.","whyWrong":"0 é πr² sem multiplicar pela altura; 1 corresponde a πrh e ignora o quadrado do raio; 3 duplica o resultado correto, geralmente por tratar o cilindro como se tivesse duas vezes a altura.","reviewHint":"Escreva a fórmula completa antes de substituir: V = πr²h.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-06","subject":"Matemática","topic":"Geometria espacial","subtopic":"cones e volume","prompt":"Um cone circular reto tem diâmetro 10 cm e altura 12 cm. Qual é seu volume exato?","options":["50π cm³","100π cm³","200π cm³","300π cm³"],"answer":1,"explanation":"O raio é metade do diâmetro: r = 5 cm. Então V = πr²h/3 = π·25·12/3 = 100π cm³.","difficulty":"intermediária","sourceBasis":"https://openstax.org/books/prealgebra-2e/pages/9-6-solve-geometry-applications-volume-and-surface-area (calibração apenas; cones e volume, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://openstax.org/books/prealgebra-2e/pages/9-6-solve-geometry-applications-volume-and-surface-area (calibração apenas; questão autoral/similar; não oficial).","skill":"distinguir diâmetro de raio e aplicar o fator um terço do cone","commonError":"Substituir 10 diretamente como raio ou omitir o divisor 3.","whyWrong":"0 usa o raio correto, mas divide o resultado por 2 sem motivo; 2 é o produto πr²h sem o terço; 3 equivale a usar o diâmetro como raio e ainda não aplicar corretamente a fórmula.","reviewHint":"Faça duas anotações separadas: d = 10, r = 5; só então use V = πr²h/3.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-07","subject":"Matemática","topic":"Geometria espacial","subtopic":"esferas e área da superfície","prompt":"Uma esfera tem diâmetro 6 cm. Qual é a área de sua superfície?","options":["6π cm²","18π cm²","36π cm²","72π cm²"],"answer":2,"explanation":"O raio é 3 cm. A área da esfera é A = 4πr² = 4π·9 = 36π cm².","difficulty":"intermediária","sourceBasis":"https://math.libretexts.org/Bookshelves/Applied_Mathematics/Developmental_Math_(NROC)/07%3A_Geometry/7.03%3A_Volume_of_Geometric_Solids/7.3.01%3A_Solids (calibração apenas; esfera e raio/diâmetro, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://math.libretexts.org/Bookshelves/Applied_Mathematics/Developmental_Math_(NROC)/07%3A_Geometry/7.03%3A_Volume_of_Geometric_Solids/7.3.01%3A_Solids (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular área esférica usando o raio obtido do diâmetro","commonError":"Usar fórmula de volume ou considerar 6 cm como raio.","whyWrong":"0 é apenas 2r; 1 combina incorretamente fatores da fórmula; 3 usa 6 como raio em 2πr², não em 4πr².","reviewHint":"Área esférica é 4πr² e exige raio; o diâmetro deve ser dividido por dois.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-08","subject":"Matemática","topic":"Geometria espacial","subtopic":"sólidos compostos","prompt":"Um sólido é formado por um cilindro de raio 3 cm e altura 8 cm, unido a uma semiesfera do mesmo raio pela base circular. Qual é o volume externo total do sólido?","options":["72π cm³","90π cm³","108π cm³","144π cm³"],"answer":1,"explanation":"O cilindro tem volume π·3²·8 = 72π cm³. A semiesfera tem metade do volume de uma esfera de raio 3: (1/2)(4π·3³/3) = 18π cm³. A união soma 90π cm³; a face circular comum não altera volume.","difficulty":"avançada","sourceBasis":"https://math.libretexts.org/Bookshelves/Applied_Mathematics/Developmental_Math_(NROC)/07%3A_Geometry/7.03%3A_Volume_of_Geometric_Solids/7.3.01%3A_Solids (calibração apenas; sólidos compostos, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://math.libretexts.org/Bookshelves/Applied_Mathematics/Developmental_Math_(NROC)/07%3A_Geometry/7.03%3A_Volume_of_Geometric_Solids/7.3.01%3A_Solids (calibração apenas; questão autoral/similar; não oficial).","skill":"decompor sólido composto e somar volumes compatíveis","commonError":"Usar o volume da esfera inteira ou subtrair a interface comum ao calcular volume.","whyWrong":"0 considera só o cilindro; 2 adiciona uma esfera inteira, 36π, à parte cilíndrica; 3 usa a esfera inteira e ainda acrescenta outro termo, excedendo a composição descrita.","reviewHint":"Separe o desenho em cilindro + semiesfera; áreas de contato só precisam ser retiradas em problemas de superfície, não de volume.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-09","subject":"Matemática","topic":"Geometria espacial","subtopic":"tronco de cone","prompt":"Um tronco de cone circular reto tem raios das bases 6 cm e 3 cm e altura 4 cm. Qual é seu volume?","options":["63π cm³","72π cm³","84π cm³","96π cm³"],"answer":2,"explanation":"Usa-se V = πh(R² + Rr + r²)/3. Substituindo R = 6, r = 3 e h = 4: V = 4π(36 + 18 + 9)/3 = 4π·63/3 = 84π cm³.","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; troncos e volumes, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar a fórmula do volume de tronco de cone","commonError":"Calcular o tronco como cilindro usando apenas um dos raios ou esquecer o termo Rr.","whyWrong":"0 é próximo de uma soma incompleta das áreas; 1 usa πRh sem considerar a variação do raio; 3 substitui uma soma incorreta, geralmente R² + r² sem o produto cruzado.","reviewHint":"Memorize a estrutura simétrica R² + Rr + r² e verifique que o resultado fica entre volumes plausíveis das bases extremas.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-10","subject":"Matemática","topic":"Geometria espacial","subtopic":"relações métricas no cone","prompt":"Em um cone circular reto, o raio mede 5 cm e a geratriz mede 13 cm. Qual é a área total do cone?","options":["65π cm²","90π cm²","120π cm²","180π cm²"],"answer":1,"explanation":"A área total do cone é a área lateral mais a base: A_t = πrg + πr² = π·5·13 + π·25 = 65π + 25π = 90π cm². A altura não é necessária para essa área, embora Pitágoras dê h = 12 cm.","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; cones e relações métricas, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"distinguir geratriz, altura e componentes da área do cone","commonError":"Usar πr²h/3 para uma pergunta de área ou esquecer a área da base.","whyWrong":"0 é apenas a área lateral; 2 mistura o valor da altura 12 com a geratriz; 3 soma ou duplica componentes sem respeitar A_t = πr(g+r).","reviewHint":"Para área total, use geratriz na lateral e raio na base; para volume, use altura perpendicular.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-11","subject":"Matemática","topic":"Geometria espacial","subtopic":"seções e semelhança","prompt":"Um cone reto tem altura 15 cm e raio da base 9 cm. Um plano paralelo à base corta o cone a 5 cm do vértice. Qual é a área da seção circular?","options":["3π cm²","6π cm²","9π cm²","27π cm²"],"answer":2,"explanation":"O cone menor, entre o vértice e o corte, é semelhante ao cone original com fator linear 5/15 = 1/3. Seu raio é 9/3 = 3 cm. A seção é um círculo de área π·3² = 9π cm².","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; seções e relações métricas, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"usar semelhança para determinar o raio de uma seção paralela","commonError":"Aplicar o fator linear diretamente à área ou medir a distância a partir da base em vez do vértice.","whyWrong":"0 reduz o raio 9 por 3 mais uma vez; 1 trata 5/15 como fator de área sem elevar ou calcular o raio; 3 usa o raio original ou aplica uma razão linear à área de forma inconsistente.","reviewHint":"Primeiro encontre o raio da seção por semelhança; somente depois eleve ao quadrado para a área.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-12","subject":"Matemática","topic":"Geometria espacial","subtopic":"esfera inscrita em cubo","prompt":"Uma esfera está inscrita em um cubo de aresta 6 cm. Qual fração do volume do cubo é ocupada pela esfera?","options":["π/12","π/6","π/3","2π/3"],"answer":1,"explanation":"Na esfera inscrita, o diâmetro é a aresta do cubo; portanto r = 3 cm. O volume da esfera é 4π·3³/3 = 36π cm³, e o do cubo é 6³ = 216 cm³. A fração é 36π/216 = π/6.","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; inscrição e volumes, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"relacionar diâmetro da esfera inscrita à aresta do cubo e comparar volumes","commonError":"Tomar a aresta como raio ou comparar área da esfera com volume do cubo.","whyWrong":"0 usa um raio incorreto e ainda altera a razão; 2 resulta de esquecer parte da divisão pelo volume do cubo; 3 é maior que 1 em aproximação, o que já contradiz a esfera contida no cubo.","reviewHint":"Inscrita significa tangente às seis faces: diâmetro = aresta. Calcule ambos os volumes antes de simplificar a fração.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-13","subject":"Matemática","topic":"Geometria espacial","subtopic":"prisma, pirâmide e Cavalieri","prompt":"Um prisma e uma pirâmide têm a mesma base, de área 30 cm², e a mesma altura, de 12 cm. Qual é a diferença entre o volume do prisma e o da pirâmide?","options":["120 cm³","180 cm³","240 cm³","360 cm³"],"answer":2,"explanation":"O prisma tem volume 30×12 = 360 cm³. A pirâmide, com a mesma base e altura, tem volume 360/3 = 120 cm³. A diferença é 360 − 120 = 240 cm³.","difficulty":"avançada","sourceBasis":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; relação entre prismas e pirâmides, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.ufu.br/bitstream/123456789/25348/1/Geometria%20Espacial.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"comparar volumes de prismas e pirâmides com base e altura comuns","commonError":"Calcular apenas um volume ou subtrair a área da base em vez dos volumes.","whyWrong":"0 é o volume da pirâmide; 1 não é diferença entre os resultados obtidos; 3 é o volume do prisma, não a diferença entre prisma e pirâmide.","reviewHint":"Calcule o prisma primeiro e use a relação de um terço para a pirâmide; só então faça a subtração.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-14","subject":"Matemática","topic":"Geometria espacial","subtopic":"área de sólido composto","prompt":"Um sólido é formado por um cilindro de raio 2 cm e altura 7 cm, com uma semiesfera de raio 2 cm unida à sua base superior. A base inferior do cilindro permanece exposta. Qual é a área externa do sólido, sem contar a circunferência de contato?","options":["32π cm²","36π cm²","40π cm²","48π cm²"],"answer":2,"explanation":"A área lateral do cilindro é 2πrh = 2π·2·7 = 28π. A base inferior vale πr² = 4π. A superfície curva da semiesfera vale metade da área da esfera: 2πr² = 8π. A soma externa é 28π + 4π + 8π = 40π cm²; a base circular de contato não é exposta.","difficulty":"avançada","sourceBasis":"https://math.libretexts.org/Bookshelves/Applied_Mathematics/Developmental_Math_(NROC)/07%3A_Geometry/7.03%3A_Volume_of_Geometric_Solids/7.3.01%3A_Solids (calibração apenas; sólidos compostos e superfícies, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://math.libretexts.org/Bookshelves/Applied_Mathematics/Developmental_Math_(NROC)/07%3A_Geometry/7.03%3A_Volume_of_Geometric_Solids/7.3.01%3A_Solids (calibração apenas; questão autoral/similar; não oficial).","skill":"selecionar somente as superfícies expostas de um sólido composto","commonError":"Adicionar as duas bases circulares ou usar a área total de uma esfera inteira.","whyWrong":"0 omite a superfície curva da semiesfera; 1 inclui apenas parte da composição; 3 acrescenta uma base circular que está em contato ou duplica a contribuição hemisférica.","reviewHint":"Faça uma lista das superfícies visíveis: lateral do cilindro, base inferior e superfície curva da semiesfera.","contentId":"mat-spatial"},{"id":"m45-mat-spatial-15","subject":"Matemática","topic":"Geometria espacial","subtopic":"esfera: volume e área","prompt":"Uma esfera tem volume 288π cm³. Qual é a área de sua superfície?","options":["24π cm²","72π cm²","144π cm²","288π cm²"],"answer":2,"explanation":"De 4πr³/3 = 288π, obtém-se r³ = 216 e, portanto, r = 6 cm. A área da superfície é 4πr² = 4π·36 = 144π cm².","difficulty":"avançada","sourceBasis":"https://www.gutenberg.org/ebooks/29807 (calibração apenas; relações entre volume e área da esfera, conceitos adaptados); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.gutenberg.org/ebooks/29807 (calibração apenas; questão autoral/similar; não oficial).","skill":"inverter a fórmula do volume esférico e calcular a área correspondente","commonError":"Tratar 288 como r³ diretamente ou conservar a unidade cúbica na área.","whyWrong":"0 e 1 surgem de divisões parciais sem recuperar r = 6; 3 repete o número do volume e mantém uma grandeza cúbica, não uma área.","reviewHint":"Isole r³ com cuidado, extraia a raiz cúbica e só depois use A = 4πr², com unidade cm².","contentId":"mat-spatial"},{"id":"m45-mat-stats-01","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"tabelas e frequências","prompt":"Uma turma registrou os valores 1, 1, 2, 2, 2, 2, 2, 3, 4, 4 para uma variável discreta. Qual é a frequência relativa do valor 2?","options":["20%","50%","60%","70%"],"answer":1,"explanation":"Há cinco ocorrências do valor 2 em um total de dez observações. Logo, a frequência relativa é 5/10 = 0,5 = 50%.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/recurso/4684 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/recurso/4684 — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular e interpretar frequência relativa em uma distribuição simples","commonError":"Dividir a frequência do valor 2 pela quantidade de valores distintos, em vez do total de observações.","whyWrong":"0 usa 2/10 e ignora que há cinco ocorrências; 2 conta seis ocorrências inexistentes; 3 confunde frequência absoluta com porcentagem do total.","reviewHint":"Some todas as frequências antes de transformar uma frequência absoluta em porcentagem.","contentId":"mat-stats"},{"id":"m45-mat-stats-02","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"média aritmética","prompt":"As temperaturas anotadas em cinco horários foram 6, 8, 10, 12 e 14 graus. Qual é a média aritmética dessas medidas?","options":["8","9","10","12"],"answer":2,"explanation":"A soma é 6 + 8 + 10 + 12 + 14 = 50. Dividindo pelas cinco observações, obtém-se média 50/5 = 10.","difficulty":"intermediária","sourceBasis":"https://repositorio.furg.br/bitstreams/89cdf6f7-a8a6-47b5-bbd5-9190fc3327ce/download — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.furg.br/bitstreams/89cdf6f7-a8a6-47b5-bbd5-9190fc3327ce/download — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular média aritmética simples a partir de dados não agrupados","commonError":"Somar os dados e esquecer de dividir pelo número de observações.","whyWrong":"0 e 1 resultam de divisões por quantidades que não são o total de dados; 3 é um dos valores observados, não a média calculada.","reviewHint":"Use a relação soma = média × quantidade e confira se a média fica entre o menor e o maior valor.","contentId":"mat-stats"},{"id":"m45-mat-stats-03","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"mediana e moda","prompt":"Considere a lista ordenada 3, 7, 7, 8, 11, 13, 13, 13 e 20. Qual é o par formado pela mediana e pela moda?","options":["8 e 7","11 e 13","12 e 13","11 e 11"],"answer":1,"explanation":"Como há nove valores, a mediana é o quinto, 11. O valor 13 aparece três vezes, mais do que os demais, portanto é a moda.","difficulty":"intermediária","sourceBasis":"https://umbu.uft.edu.br/bitstream/11612/1434/1/Estat%C3%ADstica%20B%C3%A1sica.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://umbu.uft.edu.br/bitstream/11612/1434/1/Estat%C3%ADstica%20B%C3%A1sica.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"localizar a mediana e identificar a maior frequência","commonError":"Escolher a média ou o valor central visual sem verificar a posição e as repetições.","whyWrong":"0 toma 8 como centro e 7 como moda; 2 calcula uma média dos dois valores centrais que não se aplica a nove dados; 3 confunde mediana com moda.","reviewHint":"Conte a quantidade de dados: para número ímpar, a mediana é o termo de posição (n+1)/2.","contentId":"mat-stats"},{"id":"m45-mat-stats-04","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"dispersão e amplitude","prompt":"Os tempos de uma tarefa foram 4, 4, 6, 6 e 7 minutos. Qual é a amplitude total desses dados?","options":["2","3","4","7"],"answer":1,"explanation":"A amplitude é a diferença entre o maior e o menor valor: 7 − 4 = 3 minutos.","difficulty":"intermediária","sourceBasis":"https://umbu.uft.edu.br/bitstream/11612/1434/1/Estat%C3%ADstica%20B%C3%A1sica.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://umbu.uft.edu.br/bitstream/11612/1434/1/Estat%C3%ADstica%20B%C3%A1sica.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular amplitude total usando os extremos do conjunto","commonError":"Somar o maior e o menor valor ou contar o número de intervalos da lista.","whyWrong":"0 não corresponde à diferença entre 7 e 4; 2 pode surgir de uma contagem parcial dos dados; 3 é o máximo, não a amplitude.","reviewHint":"Para amplitude, ignore os valores intermediários e faça máximo menos mínimo.","contentId":"mat-stats"},{"id":"m45-mat-stats-05","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"princípio multiplicativo e combinações","prompt":"De um grupo de cinco candidatos, serão escolhidos dois representantes sem distinção de cargos. Quantas duplas diferentes podem ser formadas?","options":["10","15","20","25"],"answer":0,"explanation":"Como a ordem dos dois representantes não importa, usa-se C(5,2) = 5!/(2!3!) = 10 duplas.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/recurso/4684 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/recurso/4684 — calibração apenas; questão autoral/similar; não oficial.","skill":"distinguir combinação de arranjo em uma escolha sem cargos","commonError":"Contar a dupla AB e BA como resultados diferentes.","whyWrong":"1, 2 e 3 correspondem a contagens que não eliminam adequadamente a duplicação causada pela ordem ou a cálculos incompatíveis com cinco escolhidos dois a dois.","reviewHint":"Pergunte se trocar as pessoas de posição cria uma nova situação; sem cargos, não cria.","contentId":"mat-stats"},{"id":"m45-mat-stats-06","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"probabilidade simples e união","prompt":"Um dado honesto é lançado uma vez. Qual é a probabilidade de sair um número par ou um múltiplo de 3?","options":["1/3","1/2","2/3","5/6"],"answer":2,"explanation":"Os resultados favoráveis são 2, 3, 4 e 6: quatro entre seis. Assim, P = 4/6 = 2/3. O 6 pertence aos dois eventos e foi contado apenas uma vez na enumeração.","difficulty":"intermediária","sourceBasis":"https://sibiuni.unilab.edu.br/wp-content/uploads/2023/05/PNAP-Bacharelado-Estatistica-Aplicada-a-Administracao.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://sibiuni.unilab.edu.br/wp-content/uploads/2023/05/PNAP-Bacharelado-Estatistica-Aplicada-a-Administracao.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular união de eventos em espaço equiprovável","commonError":"Somar as probabilidades de par e múltiplo de 3 sem retirar a interseção do resultado 6.","whyWrong":"0 e 1 subestimam os quatro resultados favoráveis; 3 equivale a contar cinco resultados ou a somar eventos sobrepostos sem o ajuste correto.","reviewHint":"Liste os seis resultados ou aplique P(A∪B)=P(A)+P(B)−P(A∩B).","contentId":"mat-stats"},{"id":"m45-mat-stats-07","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"probabilidade condicional sem reposição","prompt":"Uma urna contém 4 bolas vermelhas e 3 azuis. Uma bola vermelha foi retirada e não foi devolvida. Qual é a probabilidade de a segunda bola retirada também ser vermelha, sabendo-se que a primeira foi vermelha?","options":["3/7","1/2","4/7","2/3"],"answer":1,"explanation":"Após a primeira retirada vermelha, restam 3 vermelhas entre 6 bolas. Portanto, a probabilidade condicional é 3/6 = 1/2.","difficulty":"intermediária","sourceBasis":"https://sibiuni.unilab.edu.br/wp-content/uploads/2023/05/PNAP-Bacharelado-Estatistica-Aplicada-a-Administracao.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://sibiuni.unilab.edu.br/wp-content/uploads/2023/05/PNAP-Bacharelado-Estatistica-Aplicada-a-Administracao.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"atualizar o espaço amostral em uma probabilidade condicional","commonError":"Usar 3/7, como se o total original permanecesse depois da retirada.","whyWrong":"0 mantém sete bolas no denominador; 2 usa quatro vermelhas originais; 3 não representa a razão entre vermelhas restantes e bolas restantes.","reviewHint":"A expressão 'sabendo que' restringe o universo: descreva primeiro o que sobra após o evento conhecido.","contentId":"mat-stats"},{"id":"m45-mat-stats-08","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"média ponderada por frequências","prompt":"Em uma avaliação, as notas 5, 7 e 9 ocorreram, respectivamente, 2, 3 e 5 vezes. Qual é a média das dez notas?","options":["7,0","7,4","7,6","8,0"],"answer":2,"explanation":"A soma ponderada é 5·2 + 7·3 + 9·5 = 10 + 21 + 45 = 76. Como há dez notas, a média é 76/10 = 7,6.","difficulty":"avançada","sourceBasis":"https://repositorio.furg.br/bitstreams/89cdf6f7-a8a6-47b5-bbd5-9190fc3327ce/download — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.furg.br/bitstreams/89cdf6f7-a8a6-47b5-bbd5-9190fc3327ce/download — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular média de dados agrupados por frequência","commonError":"Fazer (5+7+9)/3, ignorando que as notas têm frequências diferentes.","whyWrong":"0 não considera pesos; 1 e 3 resultam de ponderações ou divisões incorretas; 3 fica próximo do maior grupo, mas não é a soma ponderada dividida por dez.","reviewHint":"Repita mentalmente cada valor conforme sua frequência ou use Σ(xᵢfᵢ)/Σfᵢ.","contentId":"mat-stats"},{"id":"m45-mat-stats-09","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"variância populacional","prompt":"Considere toda a população de dados 2, 4, 4 e 6. Qual é a variância populacional desse conjunto?","options":["1","2","4","8"],"answer":1,"explanation":"A média é 4. Os quadrados dos desvios são 4, 0, 0 e 4, cuja soma é 8. Como se trata da variância populacional, divide-se por 4: 8/4 = 2.","difficulty":"avançada","sourceBasis":"https://umbu.uft.edu.br/bitstream/11612/1434/1/Estat%C3%ADstica%20B%C3%A1sica.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://umbu.uft.edu.br/bitstream/11612/1434/1/Estat%C3%ADstica%20B%C3%A1sica.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular variância populacional a partir dos desvios em relação à média","commonError":"Dividir a soma dos quadrados por n−1 sem que o enunciado trate de estimativa amostral.","whyWrong":"0 divide por oito, a soma dos quadrados, sem calcular a média dos desvios quadráticos; 2 é o valor correto; 3 é a soma dos quadrados pela metade; 4 é a soma antes da divisão.","reviewHint":"Diferencie variância populacional (divide por N) de variância amostral (frequentemente divide por n−1).","contentId":"mat-stats"},{"id":"m45-mat-stats-10","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"coeficiente de variação","prompt":"O conjunto A tem média 40 e desvio-padrão 6; o conjunto B tem média 100 e desvio-padrão 12. Qual conjunto apresenta menor dispersão relativa, medida pelo coeficiente de variação?","options":["A, pois seu desvio-padrão absoluto é menor.","B, pois seu coeficiente de variação é 12% contra 15% de A.","Os dois, pois os desvios-padrão são proporcionais às médias.","Não é possível comparar coeficientes de variação."],"answer":1,"explanation":"CV(A)=6/40=15% e CV(B)=12/100=12%. Embora B tenha maior desvio absoluto, sua dispersão é menor em relação à própria média.","difficulty":"avançada","sourceBasis":"https://umbu.uft.edu.br/bitstream/11612/1434/1/Estat%C3%ADstica%20B%C3%A1sica.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://umbu.uft.edu.br/bitstream/11612/1434/1/Estat%C3%ADstica%20B%C3%A1sica.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"comparar variabilidade relativa por meio do coeficiente de variação","commonError":"Escolher o menor desvio-padrão sem normalizá-lo pela média.","whyWrong":"0 olha apenas a escala absoluta; 2 calcula incorretamente os dois percentuais; 3 ignora que o CV foi justamente definido para comparação relativa quando as médias são adequadas.","reviewHint":"Calcule desvio-padrão/média para cada grupo antes de comparar, e transforme em porcentagem apenas no final.","contentId":"mat-stats"},{"id":"m45-mat-stats-11","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"independência de eventos","prompt":"Para dois eventos A e B, sabe-se que P(A)=0,4, P(B)=0,5 e P(A∩B)=0,2. O que se pode concluir?","options":["São mutuamente exclusivos, pois a interseção é menor que 1.","São independentes, pois P(A∩B)=P(A)P(B).","A e B são complementares, pois suas probabilidades somam 0,9.","Não é possível verificar independência com probabilidades marginais."],"answer":1,"explanation":"O produto das probabilidades marginais é 0,4·0,5=0,2, exatamente a interseção informada. Portanto, os eventos são independentes. Eles não são mutuamente exclusivos porque a interseção não é zero.","difficulty":"avançada","sourceBasis":"https://sibiuni.unilab.edu.br/wp-content/uploads/2023/05/PNAP-Bacharelado-Estatistica-Aplicada-a-Administracao.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://sibiuni.unilab.edu.br/wp-content/uploads/2023/05/PNAP-Bacharelado-Estatistica-Aplicada-a-Administracao.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"testar independência usando a relação entre interseção e produto","commonError":"Confundir independência com exclusão mútua.","whyWrong":"0 exigiria interseção zero; 2 exigiria soma 1 e interseção vazia; 3 é falso porque a igualdade P(A∩B)=P(A)P(B) permite verificar o caso.","reviewHint":"Independência significa que uma ocorrência não altera a chance da outra; teste o produto, não apenas a soma.","contentId":"mat-stats"},{"id":"m45-mat-stats-12","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"probabilidade total","prompt":"Uma peça vem da máquina A com probabilidade 0,6 e da máquina B com probabilidade 0,4. As taxas de defeito são 2% em A e 5% em B. Qual é a probabilidade de uma peça escolhida ao acaso ser defeituosa?","options":["2,0%","2,8%","3,2%","5,0%"],"answer":2,"explanation":"P(defeito)=P(defeito|A)P(A)+P(defeito|B)P(B)=0,02·0,6+0,05·0,4=0,012+0,020=0,032, ou 3,2%.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/recurso/4684 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/recurso/4684 — calibração apenas; questão autoral/similar; não oficial.","skill":"combinar probabilidades condicionais e proporções de origem","commonError":"Fazer a média simples das taxas de defeito, ignorando que as máquinas têm participações diferentes.","whyWrong":"0 usa somente a taxa da máquina A; 1 resulta de uma ponderação incorreta; 3 usa somente a taxa da máquina B, apesar de ambas produzirem peças.","reviewHint":"Desenhe uma árvore: multiplique cada caminho (origem e defeito) e some os caminhos de defeito.","contentId":"mat-stats"},{"id":"m45-mat-stats-13","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"Bayes e probabilidade inversa","prompt":"Usando a situação das máquinas A e B, com proporções 0,6 e 0,4 e taxas de defeito 2% e 5%, qual é a probabilidade de uma peça defeituosa ter vindo da máquina B?","options":["12,5%","40,0%","62,5%","80,0%"],"answer":2,"explanation":"P(B|defeito)=P(defeito|B)P(B)/P(defeito)=(0,05·0,4)/0,032=0,020/0,032=0,625, isto é, 62,5%.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/recurso/4684 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/recurso/4684 — calibração apenas; questão autoral/similar; não oficial.","skill":"inverter uma probabilidade condicional com o teorema de Bayes","commonError":"Responder P(defeito|B)=5% em vez de calcular P(B|defeito).","whyWrong":"0 é uma fração sem o numerador e denominador adequados; 1 confunde a proporção inicial de B com a probabilidade posterior; 3 não resulta da razão 0,020/0,032.","reviewHint":"Leia a ordem da barra: a pergunta começa com 'dado defeito', então o defeito é o novo universo.","contentId":"mat-stats"},{"id":"m45-mat-stats-14","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"contagem e probabilidade sem repetição","prompt":"Um código é formado por quatro algarismos distintos, e o primeiro não pode ser zero. Se todos os códigos permitidos são igualmente prováveis, qual é a probabilidade de o primeiro algarismo ser ímpar?","options":["1/10","4/9","5/9","1/2"],"answer":2,"explanation":"Há 9·9·8·7 códigos: 9 opções não nulas para o primeiro e depois 9, 8 e 7 sem repetição. Para primeiro ímpar, há 5 opções (1, 3, 5, 7, 9), seguidas de 9·8·7 escolhas; a razão é (5·9·8·7)/(9·9·8·7)=5/9.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/recurso/4684 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/recurso/4684 — calibração apenas; questão autoral/similar; não oficial.","skill":"modelar contagem com restrição de primeiro algarismo e ausência de repetição","commonError":"Usar dez possibilidades para o primeiro algarismo, permitindo zero, ou repetir algarismos nas posições seguintes.","whyWrong":"0 trata apenas uma das dez cifras como favorável e ignora a estrutura do código; 1 não contabiliza as cinco cifras ímpares; 3 supõe equiprobabilidade entre par e ímpar no primeiro sem considerar que zero é proibido e que o primeiro tem nove opções.","reviewHint":"Conte primeiro o universo válido e depois os códigos favoráveis; fatores comuns podem ser cancelados na razão.","contentId":"mat-stats"},{"id":"m45-mat-stats-15","subject":"Matemática","topic":"Estatística e probabilidade","subtopic":"tabela de contingência e união","prompt":"Em um grupo de 80 alunos, 45 estudam o tema A, 30 estudam o tema B e 15 estudam ambos. Qual é a probabilidade de um aluno escolhido ao acaso estudar exatamente um dos dois temas?","options":["3/8","9/16","5/8","15/16"],"answer":1,"explanation":"Os que estudam somente A são 45−15=30, e os que estudam somente B são 30−15=15. Exatamente um tema corresponde a 45 alunos; a probabilidade é 45/80=9/16.","difficulty":"avançada","sourceBasis":"https://repositorio.furg.br/bitstreams/89cdf6f7-a8a6-47b5-bbd5-9190fc3327ce/download — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://repositorio.furg.br/bitstreams/89cdf6f7-a8a6-47b5-bbd5-9190fc3327ce/download — calibração apenas; questão autoral/similar; não oficial.","skill":"separar interseção e partes exclusivas em uma tabela de contingência","commonError":"Somar 45 e 30 e contar os 15 alunos da interseção duas vezes.","whyWrong":"0 corresponde a 30/80; 2 é a fração correta; 3 e 4 incluem também alunos que estudam os dois temas ou usam o complemento de modo indevido.","reviewHint":"'Exatamente um' significa (somente A) ou (somente B), não a união inteira.","contentId":"mat-stats"},{"id":"m45-mat-trig-01","subject":"Matemática","topic":"Trigonometria","subtopic":"razões no triângulo retângulo","prompt":"Em um triângulo retângulo, os catetos medem 9 e 12. Considerando o ângulo θ oposto ao cateto de medida 9, qual é o valor de tan θ?","options":["3/4","4/3","3/5","4/5"],"answer":0,"explanation":"A hipotenusa é 15, mas a tangente usa diretamente cateto oposto dividido pelo cateto adjacente: tan θ = 9/12 = 3/4.","difficulty":"intermediária","sourceBasis":"https://doi.org/10.11606/9786587023359 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://doi.org/10.11606/9786587023359 (calibração apenas; questão autoral/similar; não oficial).","skill":"identificar os lados em relação a um ângulo e aplicar a tangente","commonError":"Inverter cateto oposto e cateto adjacente ou usar a hipotenusa na tangente.","whyWrong":"3/4 é oposto sobre adjacente. 4/3 inverte a razão; 3/5 e 4/5 são seno e cosseno do mesmo ângulo, não tangente.","reviewHint":"Marque o ângulo antes de nomear os lados e recorde TOA: tangente é oposto sobre adjacente.","contentId":"mat-trig"},{"id":"m45-mat-trig-02","subject":"Matemática","topic":"Trigonometria","subtopic":"ângulos notáveis no triângulo retângulo","prompt":"Uma rampa forma 30° com o chão e tem projeção horizontal de 8 m. Qual é a elevação vertical da rampa, desprezando espessuras?","options":["8/3 m","8√3/3 m","4√3 m","8√3 m"],"answer":1,"explanation":"A elevação é o cateto oposto e 8 m é o adjacente. Logo, tan 30° = h/8 = √3/3, de modo que h = 8√3/3 m.","difficulty":"intermediária","sourceBasis":"https://sites.unipampa.edu.br/pibid2014/files/2015/11/sequencia-didatica-trigonometria_ifsulii.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://sites.unipampa.edu.br/pibid2014/files/2015/11/sequencia-didatica-trigonometria_ifsulii.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"modelar uma aplicação por tangente e usar valor notável","commonError":"Usar seno ou cosseno quando são fornecidos o avanço horizontal e o ângulo com o solo.","whyWrong":"A razão adequada é oposto/adjacente. 8/3 não inclui √3; 4√3 equivale a uma conta incorreta com √3; 8√3 omite o fator 1/3 de tan 30°.","reviewHint":"Desenhe a rampa como triângulo e pergunte quais dois lados aparecem na situação: altura e base.","contentId":"mat-trig"},{"id":"m45-mat-trig-03","subject":"Matemática","topic":"Trigonometria","subtopic":"círculo trigonométrico e coordenadas","prompt":"No círculo unitário, qual é o par ordenado associado ao ângulo 7π/6? Considere a ordem (cos x, sen x).","options":["(-1/2, -√3/2)","(-√3/2, -1/2)","(√3/2, -1/2)","(-√3/2, 1/2)"],"answer":1,"explanation":"7π/6 = π + π/6, portanto está no terceiro quadrante. O ângulo de referência é π/6, com módulo de cosseno √3/2 e de seno 1/2; ambos são negativos.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/052020/ed2337dad6fe0d39afe2091c27241978.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/052020/ed2337dad6fe0d39afe2091c27241978.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"localizar um ângulo no ciclo e combinar valores notáveis com sinais","commonError":"Trocar as coordenadas ou esquecer que seno é a ordenada e cosseno é a abscissa.","whyWrong":"A primeira alternativa troca seno e cosseno. A terceira usa sinal de quarto quadrante; a quarta atribui seno positivo ao terceiro quadrante.","reviewHint":"Reduza o ângulo a π + π/6, determine o quadrante e só então preencha (cos, sen).","contentId":"mat-trig"},{"id":"m45-mat-trig-04","subject":"Matemática","topic":"Trigonometria","subtopic":"quadrantes e sinais","prompt":"Qual ângulo no intervalo [0, 2π) tem seno positivo, cosseno negativo e ângulo de referência igual a π/6?","options":["π/6","π/3","5π/6","7π/6"],"answer":2,"explanation":"Seno positivo e cosseno negativo caracterizam o segundo quadrante. No segundo quadrante, o ângulo com referência π/6 é π − π/6 = 5π/6.","difficulty":"intermediária","sourceBasis":"https://sites.unipampa.edu.br/pibid2014/files/2015/11/sequencia-didatica-trigonometria_ifsulii.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://sites.unipampa.edu.br/pibid2014/files/2015/11/sequencia-didatica-trigonometria_ifsulii.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"usar sinais por quadrante e ângulo de referência","commonError":"Escolher um múltiplo conhecido sem verificar os sinais pedidos.","whyWrong":"π/6 está no primeiro quadrante e π/3 não tem referência π/6. 7π/6 tem referência π/6, mas está no terceiro, onde o seno é negativo.","reviewHint":"Faça primeiro a interseção das condições de sinais; depois aplique a simetria do ângulo de referência.","contentId":"mat-trig"},{"id":"m45-mat-trig-05","subject":"Matemática","topic":"Trigonometria","subtopic":"identidade fundamental","prompt":"Sabendo que θ está no primeiro quadrante e que sen θ = 5/13, qual é cos θ?","options":["12/13","-12/13","5/13","-5/13"],"answer":0,"explanation":"Pela identidade sen²θ + cos²θ = 1, cos²θ = 1 − 25/169 = 144/169. Como θ está no primeiro quadrante, o cosseno é positivo: cos θ = 12/13.","difficulty":"intermediária","sourceBasis":"https://doi.org/10.11606/9786587023359 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://doi.org/10.11606/9786587023359 (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar a identidade fundamental e selecionar o sinal pelo quadrante","commonError":"Extrair a raiz sem considerar o sinal determinado pelo quadrante.","whyWrong":"O quadrado fornece duas possibilidades algébricas, mas o primeiro quadrante torna o cosseno positivo. 5/13 repete o seno e os valores negativos contradizem o quadrante.","reviewHint":"Depois de calcular o quadrado, escreva ± e resolva o sinal com a posição do ângulo.","contentId":"mat-trig"},{"id":"m45-mat-trig-06","subject":"Matemática","topic":"Trigonometria","subtopic":"equações trigonométricas simples","prompt":"Quais são as soluções de tan x = 1 no intervalo [0, 2π)?","options":["π/4","3π/4","π/4 e 5π/4","3π/4 e 7π/4"],"answer":2,"explanation":"A tangente vale 1 no ângulo de referência π/4 e é positiva no primeiro e no terceiro quadrantes. Assim, no intervalo pedido, x = π/4 e x = 5π/4.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/052020/ed2337dad6fe0d39afe2091c27241978.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/052020/ed2337dad6fe0d39afe2091c27241978.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"resolver uma equação de tangente usando periodicidade e quadrantes","commonError":"Listar apenas o ângulo notável principal ou confundir os quadrantes de tangente positiva.","whyWrong":"A tangente tem período π, portanto a solução do terceiro quadrante também aparece. Nos quadrantes II e IV ela é negativa, não positiva.","reviewHint":"Para tangente, repita o ângulo de referência somando π e filtre pelo intervalo.","contentId":"mat-trig"},{"id":"m45-mat-trig-07","subject":"Matemática","topic":"Trigonometria","subtopic":"lei dos senos","prompt":"Em um triângulo, A = 30°, a = 10 e B = 90°, com a e b opostos a A e B, respectivamente. Qual é o valor de b?","options":["5","10√3","20","20√3"],"answer":2,"explanation":"Pela lei dos senos, b/sen 90° = a/sen 30°. Logo, b = 10 · 1/(1/2) = 20.","difficulty":"intermediária","sourceBasis":"https://doi.org/10.11606/9786587023359 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://doi.org/10.11606/9786587023359 (calibração apenas; questão autoral/similar; não oficial).","skill":"associar lados a ângulos opostos e aplicar a lei dos senos","commonError":"Associar b ao ângulo A por proximidade da letra, em vez de usar o ângulo oposto.","whyWrong":"b é oposto a B = 90°, e a é oposto a A = 30°. 10√3 e 20√3 resultam de valores notáveis inadequados; 5 reduz a razão em vez de duplicá-la.","reviewHint":"Escreva lado minúsculo em frente ao ângulo maiúsculo correspondente antes de montar a proporção.","contentId":"mat-trig"},{"id":"m45-mat-trig-08","subject":"Matemática","topic":"Trigonometria","subtopic":"lei dos cossenos","prompt":"Dois lados de um triângulo medem 7 e 8, e o ângulo entre eles mede 60°. Qual é a medida do terceiro lado?","options":["√113","√57","√169","15"],"answer":1,"explanation":"Pela lei dos cossenos, c² = 7² + 8² − 2·7·8·cos 60° = 49 + 64 − 56 = 57. Portanto c = √57.","difficulty":"avançada","sourceBasis":"https://doi.org/10.11606/9786587023359 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://doi.org/10.11606/9786587023359 (calibração apenas; questão autoral/similar; não oficial).","skill":"selecionar e executar a lei dos cossenos em uma configuração SAS","commonError":"Usar o sinal de mais no termo que contém o cosseno ou colocar um lado que não delimita o ângulo.","whyWrong":"√113 ignora o termo de correção; √169 e 15 tratam o caso como soma ou outra relação sem considerar o ângulo de 60°.","reviewHint":"Identifique os dois lados que formam o ângulo e use c² = a² + b² − 2ab cos C.","contentId":"mat-trig"},{"id":"m45-mat-trig-09","subject":"Matemática","topic":"Trigonometria","subtopic":"funções trigonométricas e transformações","prompt":"Para f(x) = 2 sen(3x − π/2) + 1, qual conjunto de características está correto?","options":["Amplitude 2, período 2π/3 e linha média y = 1","Amplitude 3, período 2π e linha média y = 1","Amplitude 2, período 3π e linha média y = 0","Amplitude 1, período 2π/3 e linha média y = 2"],"answer":0,"explanation":"Na forma A sen(Bx + C) + D, a amplitude é |A| = 2, o período é 2π/|B| = 2π/3 e a linha média é y = D = 1. O termo −π/2 desloca horizontalmente o gráfico.","difficulty":"avançada","sourceBasis":"https://www2.unifap.br/matematica/files/2017/07/TRIGONOMETRIA-E-FUN%C3%87%C3%95ES-TRIGONOM%C3%89TRICAS-UMA-ABORDAGEM-DID%C3%81TICO-METODOL%C3%93GICA.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www2.unifap.br/matematica/files/2017/07/TRIGONOMETRIA-E-FUN%C3%87%C3%95ES-TRIGONOM%C3%89TRICAS-UMA-ABORDAGEM-DID%C3%81TICO-METODOL%C3%93GICA.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"interpretar amplitude, período e translação vertical de uma função","commonError":"Confundir o coeficiente interno 3 com amplitude ou usar 2π·3 como período.","whyWrong":"O coeficiente externo controla amplitude, o interno controla período e D controla a linha média. As alternativas restantes trocam esses papéis ou ignoram o fator interno.","reviewHint":"Separe os parâmetros externos (A,D) dos internos (B,C) antes de aplicar as fórmulas.","contentId":"mat-trig"},{"id":"m45-mat-trig-10","subject":"Matemática","topic":"Trigonometria","subtopic":"identidades e domínio","prompt":"Para quais condições e qual resultado vale a simplificação (1 − cos² x)/sen x?","options":["sen x, desde que sen x ≠ 0","cos x, desde que cos x ≠ 0","tan x, desde que cos x ≠ 0","1, sem restrição de domínio"],"answer":0,"explanation":"A identidade fundamental dá 1 − cos² x = sen² x. Dividindo por sen x, obtém-se sen x, mas a expressão original exige sen x ≠ 0.","difficulty":"avançada","sourceBasis":"https://doi.org/10.11606/9786587023359 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://doi.org/10.11606/9786587023359 (calibração apenas; questão autoral/similar; não oficial).","skill":"transformar uma expressão pela identidade fundamental sem perder o domínio","commonError":"Cancelar um fator seno e declarar a igualdade também nos zeros do denominador original.","whyWrong":"A forma sen x é equivalente apenas onde a fração inicial está definida. cos x e tan x não são o resultado da substituição; sem restrição inclui pontos proibidos.","reviewHint":"Anote o denominador original antes de simplificar e só depois use sen²x = 1 − cos²x.","contentId":"mat-trig"},{"id":"m45-mat-trig-11","subject":"Matemática","topic":"Trigonometria","subtopic":"equações no ciclo trigonométrico","prompt":"Resolva sen x = √3/2 no intervalo [0, 2π).","options":["π/6 e 5π/6","π/3 e 4π/3","π/3 e 2π/3","2π/3 e 5π/3"],"answer":2,"explanation":"O ângulo de referência para seno √3/2 é π/3. O seno é positivo nos quadrantes I e II, fornecendo x = π/3 e x = π − π/3 = 2π/3.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/052020/ed2337dad6fe0d39afe2091c27241978.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/052020/ed2337dad6fe0d39afe2091c27241978.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"resolver uma equação de seno por referência e quadrantes","commonError":"Escolher π/6 por associação incorreta ou incluir uma solução de seno negativo.","whyWrong":"sen π/3 = √3/2, não sen π/6. 4π/3 e 5π/3 pertencem a quadrantes em que o seno é negativo; a primeira alternativa usa o valor errado.","reviewHint":"Memorize a tabela notável e liste os dois quadrantes de seno positivo antes de calcular o simétrico.","contentId":"mat-trig"},{"id":"m45-mat-trig-12","subject":"Matemática","topic":"Trigonometria","subtopic":"ângulo duplo","prompt":"Se α está no primeiro quadrante e cos α = 3/5, qual é o valor de cos(2α)?","options":["7/25","−1/25","1/25","−7/25"],"answer":3,"explanation":"Usando cos(2α) = 2cos²α − 1, obtém-se 2·(9/25) − 1 = 18/25 − 25/25 = −7/25.","difficulty":"avançada","sourceBasis":"https://www2.unifap.br/matematica/files/2017/07/TRIGONOMETRIA-E-FUN%C3%87%C3%95ES-TRIGONOM%C3%89TRICAS-UMA-ABORDAGEM-DID%C3%81TICO-METODOL%C3%93GICA.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www2.unifap.br/matematica/files/2017/07/TRIGONOMETRIA-E-FUN%C3%87%C3%95ES-TRIGONOM%C3%89TRICAS-UMA-ABORDAGEM-DID%C3%81TICO-METODOL%C3%93GICA.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar uma fórmula de ângulo duplo com valor trigonométrico conhecido","commonError":"Usar cos(2α) = 2cos α ou esquecer de elevar o cosseno ao quadrado.","whyWrong":"As expressões de ângulo duplo têm cos²α. O valor correto fica negativo porque 18/25 é menor que 1; 7/25 troca o sinal da subtração.","reviewHint":"Escolha uma das formas de cos(2α) e substitua com parênteses: 2(3/5)² − 1.","contentId":"mat-trig"},{"id":"m45-mat-trig-13","subject":"Matemática","topic":"Trigonometria","subtopic":"área de triângulo e seno","prompt":"Qual é a área de um triângulo cujos lados medem 6 e 10 e cujo ângulo compreendido entre eles mede 150°?","options":["12","15","30","15√3"],"answer":1,"explanation":"A área é (1/2)ab sen C. Portanto, A = (1/2)·6·10·sen 150° = 30·(1/2) = 15.","difficulty":"avançada","sourceBasis":"https://doi.org/10.11606/9786587023359 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://doi.org/10.11606/9786587023359 (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular área com dois lados e ângulo compreendido","commonError":"Usar cos 150° na fórmula da área ou tomar sen 150° como negativo.","whyWrong":"A fórmula da área usa seno. Embora o cosseno de 150° seja negativo, o seno é 1/2; a área deve ser positiva. 30 omite o fator seno e 15√3 usa valor notável inadequado.","reviewHint":"Confirme que o ângulo está entre os dois lados e use A = ab sen C/2.","contentId":"mat-trig"},{"id":"m45-mat-trig-14","subject":"Matemática","topic":"Trigonometria","subtopic":"aplicações e equações geométricas","prompt":"Uma torre é observada de dois pontos alinhados com sua base, no mesmo lado. O ponto mais próximo está a d metros da base e vê o topo sob 60°; o mais distante está a 20 m além e vê o topo sob 30°. Qual é a altura da torre?","options":["10 m","10√3 m","20√3 m","30 m"],"answer":1,"explanation":"Se h é a altura, pelo ponto próximo h = d tan 60° = d√3. Pelo ponto distante, h = (d + 20)tan 30° = (d + 20)√3/3. Igualando: 3d = d + 20, então d = 10 e h = 10√3 m.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/052020/ed2337dad6fe0d39afe2091c27241978.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/052020/ed2337dad6fe0d39afe2091c27241978.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"montar e resolver um sistema de alturas por ângulos de elevação","commonError":"Usar a mesma distância horizontal para os dois pontos ou somar as alturas obtidas separadamente.","whyWrong":"Os pontos estão separados por 20 m, logo as bases dos triângulos são d e d+20. A altura é única e deve ser igual nas duas equações; 10 é a distância do ponto próximo, não a altura.","reviewHint":"Desenhe as duas linhas de visada e chame de d a distância do ponto próximo antes de escrever as tangentes.","contentId":"mat-trig"},{"id":"m45-mat-trig-15","subject":"Matemática","topic":"Trigonometria","subtopic":"equações algébricas trigonométricas","prompt":"Determine as soluções de 2cos² x − 3cos x + 1 = 0 no intervalo [0, 2π).","options":["π/3 e 5π/3","0, π/3 e 5π/3","0, 2π/3 e 4π/3","π/6, π/3 e 5π/6"],"answer":1,"explanation":"Fazendo u = cos x, (2u − 1)(u − 1) = 0, então cos x = 1/2 ou cos x = 1. No intervalo [0,2π), isso produz π/3, 5π/3 e 0; 2π não entra porque o extremo direito é aberto.","difficulty":"avançada","sourceBasis":"https://www2.unifap.br/matematica/files/2017/07/TRIGONOMETRIA-E-FUN%C3%87%C3%95ES-TRIGONOM%C3%89TRICAS-UMA-ABORDAGEM-DID%C3%81TICO-METODOL%C3%93GICA.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www2.unifap.br/matematica/files/2017/07/TRIGONOMETRIA-E-FUN%C3%87%C3%95ES-TRIGONOM%C3%89TRICAS-UMA-ABORDAGEM-DID%C3%81TICO-METODOL%C3%93GICA.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"converter equação trigonométrica em quadrática e filtrar soluções pelo intervalo","commonError":"Resolver apenas a raiz cos x = 1/2 ou incluir 2π em um intervalo semiaberto.","whyWrong":"A fatoração tem duas raízes admissíveis. cos x = 1/2 ocorre nos quadrantes I e IV; cos x = 1 ocorre em 0 dentro do intervalo. 2π é excluído por [0,2π).","reviewHint":"Substitua a função por uma variável, fatore, resolva cada valor e só então volte ao ciclo trigonométrico.","contentId":"mat-trig"},{"id":"m45-fis-cinematica-01","subject":"Física","topic":"Cinemática","subtopic":"referencial e repouso","prompt":"Um elevador sobe verticalmente a 2 m/s em relação ao prédio. Uma pessoa permanece parada dentro do elevador. Qual é a velocidade da pessoa em relação ao elevador e em relação ao prédio, respectivamente, tomando para cima como sentido positivo?","options":["0 m/s e +2 m/s","+2 m/s e 0 m/s","−2 m/s e +2 m/s","0 m/s e −2 m/s"],"answer":0,"explanation":"A pessoa está em repouso no referencial do elevador, portanto sua velocidade relativa é 0 m/s. Em relação ao prédio, acompanha o elevador para cima a +2 m/s.","difficulty":"intermediária","sourceBasis":"https://www.if.ufrgs.br/tex/fis01043/20042/Luciano/cinematica.html (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://www.if.ufrgs.br/tex/fis01043/20042/Luciano/cinematica.html (calibração apenas; questão autoral/similar; não oficial)","skill":"identificar a dependência do movimento em relação ao referencial","commonError":"Supor que repouso ou movimento seja uma propriedade absoluta do corpo.","whyWrong":"1 troca os referenciais; 2 atribui à pessoa a velocidade do elevador no referencial errado; 3 inverte o sentido positivo sem justificativa.","reviewHint":"Sempre complete a frase ‘velocidade em relação a...’ antes de escolher um sinal.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-02","subject":"Física","topic":"Cinemática","subtopic":"posição e deslocamento","prompt":"Um móvel passa da posição x = −4 m para a posição x = 11 m em uma trajetória retilínea. Qual é seu deslocamento escalar nesse intervalo?","options":["−15 m","−7 m","+15 m","+7 m"],"answer":2,"explanation":"O deslocamento é a posição final menos a inicial: Δx = 11 − (−4) = +15 m. O sinal positivo indica deslocamento no sentido positivo do eixo escolhido.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"calcular deslocamento com posições orientadas","commonError":"Subtrair os módulos das posições ou ignorar que a posição inicial é negativa.","whyWrong":"0 troca a ordem final−inicial; 1 e 3 resultam de operações com os sinais incorretos e não representam a diferença entre as posições.","reviewHint":"Escreva literalmente Δx = x_final − x_inicial antes de substituir os valores.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-03","subject":"Física","topic":"Cinemática","subtopic":"velocidade média","prompt":"Um ciclista percorre 120 m para leste em 10 s e depois 40 m para oeste em mais 10 s. Qual é sua velocidade média no percurso completo?","options":["4 m/s para leste","8 m/s para leste","4 m/s para oeste","8 m/s para oeste"],"answer":0,"explanation":"Tomando leste como positivo, o deslocamento é 120 − 40 = 80 m e o tempo total é 20 s. Assim, v_m = 80/20 = 4 m/s para leste.","difficulty":"intermediária","sourceBasis":"https://www.if.ufrgs.br/tex/fis01043/20042/Luciano/cinematica.html (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://www.if.ufrgs.br/tex/fis01043/20042/Luciano/cinematica.html (calibração apenas; questão autoral/similar; não oficial)","skill":"distinguir velocidade média de rapidez média em percurso com retorno","commonError":"Somar as distâncias e dividir pelo tempo quando a pergunta pede velocidade média orientada.","whyWrong":"1 e 3 usam 160 m, que é a distância total, e ainda confundem o sentido; 2 acerta o módulo de uma operação, mas erra o sentido do deslocamento.","reviewHint":"Para velocidade média, use deslocamento; para rapidez média, use distância total.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-04","subject":"Física","topic":"Cinemática","subtopic":"gráfico velocidade-tempo","prompt":"A velocidade de um móvel cresce linearmente de 0 a 8 m/s entre 0 e 4 s, permanece em 8 m/s entre 4 e 7 s e vale zero depois disso. Qual deslocamento o móvel realiza entre 0 e 7 s?","options":["16 m","24 m","32 m","40 m"],"answer":3,"explanation":"No gráfico v×t, o deslocamento é a área algébrica. O primeiro trecho forma um triângulo de área 4·8/2 = 16 m; o segundo forma um retângulo de área 3·8 = 24 m. A soma é 40 m.","difficulty":"avançada","sourceBasis":"https://www.if.ufrgs.br/tex/fis01043/20042/Luciano/cinematica.html (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://www.if.ufrgs.br/tex/fis01043/20042/Luciano/cinematica.html (calibração apenas; questão autoral/similar; não oficial)","skill":"interpretar área sob gráfico velocidade-tempo","commonError":"Usar apenas a área triangular ou tratar a altura 8 m/s como se fosse o deslocamento.","whyWrong":"0 é só a área do triângulo; 1 é só a área do retângulo; 2 soma ou calcula as áreas de modo incompleto.","reviewHint":"Divida o gráfico em figuras geométricas e some as áreas de todos os intervalos.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-05","subject":"Física","topic":"Cinemática","subtopic":"aceleração média","prompt":"A velocidade de um móvel varia de 6 m/s para −2 m/s em 4 s. Qual é sua aceleração média?","options":["+2 m/s²","−2 m/s²","−0,5 m/s²","−8 m/s²"],"answer":1,"explanation":"a_m = (v_f − v_i)/Δt = (−2 − 6)/4 = −8/4 = −2 m/s². A mudança de sinal da velocidade é incluída na variação, não descartada.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"calcular aceleração média preservando sinais","commonError":"Usar apenas a diferença dos módulos das velocidades.","whyWrong":"0 inverte o resultado; 2 divide a variação por um tempo incorreto; 3 é a variação de velocidade sem divisão pelo intervalo de tempo.","reviewHint":"Substitua sempre v_f e v_i com seus sinais antes de dividir por Δt.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-06","subject":"Física","topic":"Cinemática","subtopic":"MRU e encontro de móveis","prompt":"Em unidades do SI, dois móveis têm as posições x_A = 20 + 5t e x_B = 80 − 7t. Em que instante e posição ocorre o encontro?","options":["t = 4 s e x = 40 m","t = 5 s e x = 45 m","t = 5 s e x = 55 m","t = 10 s e x = 70 m"],"answer":1,"explanation":"No encontro, 20 + 5t = 80 − 7t. Logo, 12t = 60 e t = 5 s. Substituindo em qualquer lei, x = 20 + 25 = 45 m.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"modelar encontro de móveis por igualdade de posições","commonError":"Igualar velocidades ou somar posições sem considerar o mesmo instante.","whyWrong":"0 e 3 resultam de tempos obtidos por operações inadequadas; 2 calcula a posição com sinal ou lei horária incorreta.","reviewHint":"Encontro significa uma única coordenada para os dois móveis no mesmo t: iguale x_A(t) e x_B(t).","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-07","subject":"Física","topic":"Cinemática","subtopic":"MRUV e lei horária","prompt":"Um móvel parte com velocidade inicial de 4 m/s e aceleração constante de 3 m/s². Qual deslocamento ele realiza nos primeiros 2 s?","options":["8 m","10 m","12 m","14 m"],"answer":3,"explanation":"Pelo MRUV, Δx = v_0t + at²/2 = 4·2 + 3·(2²)/2 = 8 + 6 = 14 m.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"aplicar a equação horária do MRUV","commonError":"Esquecer o termo da aceleração ou usar at em vez de at²/2 no deslocamento.","whyWrong":"0 é apenas v_0t; 1 e 2 decorrem de coeficientes ou potências aplicados incorretamente.","reviewHint":"Separe o deslocamento inicial v_0t da contribuição at²/2 e verifique as unidades de cada termo.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-08","subject":"Física","topic":"Cinemática","subtopic":"MRUV e frenagem","prompt":"Um carro move-se a 20 m/s e freia com aceleração constante de −4 m/s² até parar. Qual é o tempo de frenagem e o deslocamento durante a frenagem, respectivamente?","options":["4 s e 40 m","5 s e 40 m","5 s e 50 m","6 s e 60 m"],"answer":2,"explanation":"De 0 = 20 − 4t resulta t = 5 s. O deslocamento é Δx = 20·5 + (−4)·25/2 = 100 − 50 = 50 m.","difficulty":"avançada","sourceBasis":"https://www2.unifap.br/editora/files/2023/07/Problemas-resolvidos-de-fisica-parte-1-cinematica-grupo-pet-fisica-unifap.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://www2.unifap.br/editora/files/2023/07/Problemas-resolvidos-de-fisica-parte-1-cinematica-grupo-pet-fisica-unifap.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"combinar condição de parada e deslocamento no MRUV","commonError":"Parar após encontrar o tempo ou somar a desaceleração ao deslocamento sem o fator quadrático.","whyWrong":"0 usa tempo de 4 s; 1 encontra o tempo, mas calcula deslocamento como v_0t; 3 prolonga a frenagem além do instante em que v chega a zero.","reviewHint":"Use v=0 para achar o tempo e depois aplique uma segunda relação, conferindo que a aceleração é negativa.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-09","subject":"Física","topic":"Cinemática","subtopic":"gráfico posição-tempo","prompt":"Em um trecho retilíneo do gráfico posição-tempo, o móvel passa por (t = 2 s, x = 10 m) e (t = 6 s, x = 2 m), com segmento de reta entre os pontos. Qual é sua velocidade nesse trecho?","options":["+2 m/s","−2 m/s","+8 m/s","−8 m/s"],"answer":1,"explanation":"A velocidade é a inclinação do gráfico x×t: v = (2 − 10)/(6 − 2) = −8/4 = −2 m/s.","difficulty":"intermediária","sourceBasis":"https://www.if.ufrgs.br/tex/fis01043/20042/Luciano/cinematica.html (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://www.if.ufrgs.br/tex/fis01043/20042/Luciano/cinematica.html (calibração apenas; questão autoral/similar; não oficial)","skill":"obter velocidade pela inclinação de um gráfico posição-tempo","commonError":"Dividir a variação de posição pelo tempo final, sem usar o intervalo Δt, ou ignorar o sinal.","whyWrong":"0 inverte a inclinação; 2 e 3 usam 8 m como se fosse uma velocidade ou esquecem de dividir pelo intervalo de 4 s.","reviewHint":"Calcule a inclinação como (x_2−x_1)/(t_2−t_1), mantendo a ordem correspondente dos pontos.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-10","subject":"Física","topic":"Cinemática","subtopic":"queda livre","prompt":"Uma esfera é abandonada do repouso a 45 m do solo. Desprezando a resistência do ar e adotando g = 10 m/s², quanto tempo ela leva para atingir o solo?","options":["3 s","4,5 s","9 s","90 s"],"answer":0,"explanation":"Para queda a partir do repouso, h = gt²/2. Assim, 45 = 10t²/2, isto é, t² = 9 e t = 3 s; considera-se a raiz positiva por se tratar de tempo.","difficulty":"avançada","sourceBasis":"https://www2.unifap.br/editora/files/2023/07/Problemas-resolvidos-de-fisica-parte-1-cinematica-grupo-pet-fisica-unifap.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://www2.unifap.br/editora/files/2023/07/Problemas-resolvidos-de-fisica-parte-1-cinematica-grupo-pet-fisica-unifap.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"modelar queda livre como MRUV e selecionar a raiz física","commonError":"Usar h = gt ou aceitar tempo negativo após resolver a equação.","whyWrong":"1 não considera o fator 1/2; 2 confunde altura com aceleração ou tempo; 3 ignora completamente as dimensões e a relação quadrática.","reviewHint":"Comece com Δy = v_0t + gt²/2 e lembre que ‘abandonada’ significa v_0 = 0.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-11","subject":"Física","topic":"Cinemática","subtopic":"movimento circular uniforme","prompt":"Uma roda de raio 2 m gira com frequência de 0,5 Hz. Qual é a rapidez tangencial de um ponto na borda?","options":["π m/s","2π m/s","4π m/s","8π m/s"],"answer":1,"explanation":"A rapidez tangencial no MCU é v = 2πRf. Com R = 2 m e f = 0,5 Hz, v = 2π·2·0,5 = 2π m/s.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"relacionar frequência, raio e velocidade tangencial no MCU","commonError":"Usar v = Rf e esquecer que uma volta corresponde a 2π radianos.","whyWrong":"0 perde um fator 2; 2 e 3 introduzem fatores extras de raio ou de frequência que não aparecem na expressão correta.","reviewHint":"Parta de v = ωR e substitua ω por 2πf para não esquecer a conversão angular.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-12","subject":"Física","topic":"Cinemática","subtopic":"período e frequência no movimento circular","prompt":"Um rotor completa uma volta a cada 0,25 s. Qual é sua frequência?","options":["0,25 Hz","0,5 Hz","2 Hz","4 Hz"],"answer":3,"explanation":"Frequência e período são inversos: f = 1/T = 1/0,25 = 4 Hz. Isso significa quatro voltas por segundo.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"converter período em frequência","commonError":"Confundir o tempo de uma volta com o número de voltas por segundo.","whyWrong":"0 repete o período com unidade de frequência; 1 e 2 não calculam corretamente o inverso de 0,25.","reviewHint":"Pergunte quantos intervalos de 0,25 s cabem em 1 s: essa quantidade é a frequência.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-13","subject":"Física","topic":"Cinemática","subtopic":"velocidade relativa","prompt":"Um avião voa para leste a 200 m/s em relação ao ar. Um vento sopra para oeste a 50 m/s em relação ao solo. Qual é a velocidade do avião em relação ao solo?","options":["150 m/s para leste","250 m/s para leste","150 m/s para oeste","50 m/s para leste"],"answer":0,"explanation":"Escolhendo leste como positivo, v_avião,solo = v_avião,ar + v_ar,solo = 200 + (−50) = 150 m/s para leste.","difficulty":"avançada","sourceBasis":"https://www2.unifap.br/editora/files/2023/07/Problemas-resolvidos-de-fisica-parte-1-cinematica-grupo-pet-fisica-unifap.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://www2.unifap.br/editora/files/2023/07/Problemas-resolvidos-de-fisica-parte-1-cinematica-grupo-pet-fisica-unifap.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"somar velocidades relativas com orientação consistente","commonError":"Somar os módulos sempre, sem considerar que o vento tem sentido oposto ao avião.","whyWrong":"1 trata vento contrário como favorável; 2 inverte o sentido do resultado; 3 considera apenas o vento e ignora a velocidade do avião em relação ao ar.","reviewHint":"Escreva cada velocidade como componente orientada antes de fazer a soma vetorial em uma dimensão.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-14","subject":"Física","topic":"Cinemática","subtopic":"função posição, velocidade e aceleração","prompt":"A posição de um móvel é x(t) = 2 + 6t − t², em unidades do SI. Quais são sua velocidade e sua aceleração no instante t = 4 s?","options":["+2 m/s e +2 m/s²","−2 m/s e −2 m/s²","−2 m/s e +2 m/s²","+2 m/s e −2 m/s²"],"answer":1,"explanation":"A velocidade é a taxa de variação de x: v(t) = 6 − 2t; em t = 4, v = −2 m/s. A aceleração é constante, a = −2 m/s².","difficulty":"avançada","sourceBasis":"https://www.if.ufrgs.br/tex/fis01043/20042/Luciano/cinematica.html (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://www.if.ufrgs.br/tex/fis01043/20042/Luciano/cinematica.html (calibração apenas; questão autoral/similar; não oficial)","skill":"extrair velocidade e aceleração de uma função horária","commonError":"Usar a posição como se fosse velocidade ou avaliar somente o termo linear sem considerar −t².","whyWrong":"0 e 3 trocam sinais; 2 acerta a velocidade, mas atribui sinal incorreto à aceleração, que vem do coeficiente quadrático.","reviewHint":"Identifique a forma MRUV: v(t) = v_0 + at; compare-a com a derivada da posição ou com a lei horária.","contentId":"fis-cinematica"},{"id":"m45-fis-cinematica-15","subject":"Física","topic":"Cinemática","subtopic":"aceleração centrípeta","prompt":"Um móvel percorre uma circunferência de raio 5 m com rapidez constante de 10 m/s. Qual é o módulo de sua aceleração centrípeta?","options":["2 m/s²","5 m/s²","10 m/s²","20 m/s²"],"answer":3,"explanation":"No movimento circular, a_c = v²/R = 10²/5 = 100/5 = 20 m/s². Mesmo com rapidez constante, existe aceleração porque a direção da velocidade muda.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/042022/cad642065613839097b51486f3ec3eec.pdf (calibração apenas; questão autoral/similar; não oficial)","skill":"calcular aceleração centrípeta e interpretar sua origem vetorial","commonError":"Concluir que a aceleração é zero porque o módulo da velocidade é constante.","whyWrong":"0, 1 e 2 resultam de dividir ou combinar v e R de forma incompatível com a fórmula v²/R; também ignoram a mudança de direção.","reviewHint":"No MCU, rapidez constante não significa vetor velocidade constante: use a_c = v²/R, dirigida ao centro.","contentId":"fis-cinematica"},{"id":"m45-fis-dinamica-01","subject":"Física","topic":"Dinâmica","subtopic":"segunda lei de Newton e força resultante","prompt":"Um carrinho de massa 4 kg recebe uma força horizontal de 18 N para a direita e outra de 6 N para a esquerda. Desprezando outras forças horizontais, qual é a aceleração do carrinho?","options":["1 m/s² para a direita","2 m/s² para a direita","3 m/s² para a direita","6 m/s² para a esquerda"],"answer":2,"explanation":"A resultante horizontal é 18 − 6 = 12 N para a direita. Pela segunda lei, a = ΣF/m = 12/4 = 3 m/s², também para a direita.","difficulty":"intermediária","sourceBasis":"https://hdl.handle.net/10216/126235 (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10216/126235 (calibração apenas); questão autoral/similar; não oficial.","skill":"calcular a aceleração a partir da resultante vetorial","commonError":"Somar os módulos das forças ou dividir apenas a maior força pela massa.","whyWrong":"A alternativa 0 usa 4 N como resultante; a 1 usa 8 N; a 3 troca o sentido e ainda usa módulo incorreto. É necessário subtrair forças opostas antes de aplicar ΣF = ma.","reviewHint":"Defina um sentido positivo, some algebricamente as forças no eixo e só depois divida pela massa.","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-02","subject":"Física","topic":"Dinâmica","subtopic":"terceira lei de Newton e ação-reação","prompt":"Uma pessoa empurra uma parede e sente uma força exercida pela parede sobre suas mãos. Sobre esse par de forças, é correto afirmar que:","options":["a força da pessoa é maior, porque ela iniciou a interação","as forças têm mesmo módulo e sentidos opostos, aplicadas em corpos diferentes","as forças se anulam no diagrama de forças da pessoa","a parede não exerce força, pois permanece em repouso"],"answer":1,"explanation":"A terceira lei estabelece forças de mesmo módulo e sentidos opostos, mas cada uma atua em um corpo: uma na parede e outra na pessoa. Por isso, elas não se cancelam no DCL de um único corpo.","difficulty":"avançada","sourceBasis":"https://www.ufrb.edu.br/pibid/documentos/category/54-dinamica?download=184:dinmica (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ufrb.edu.br/pibid/documentos/category/54-dinamica?download=184:dinmica (calibração apenas); questão autoral/similar; não oficial.","skill":"identificar corretamente um par de ação e reação","commonError":"Pensar que forças de ação e reação se anulam porque têm mesmo módulo.","whyWrong":"A alternativa 0 confunde causa temporal com interação simultânea; a 2 ignora que as forças estão em corpos diferentes; a 3 confunde repouso com ausência de força resultante.","reviewHint":"Para cada força, pergunte: quem exerce, em quem atua e qual é a força correspondente no outro corpo?","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-03","subject":"Física","topic":"Dinâmica","subtopic":"diagrama de corpo livre e força normal","prompt":"Um bloco de 6 kg permanece em repouso sobre uma mesa horizontal, sem outras forças verticais além do peso e da normal. Adote g = 10 m/s². Qual é o módulo da normal sobre o bloco?","options":["6 N","30 N","60 N","600 N"],"answer":2,"explanation":"Como não há aceleração vertical, ΣFy = 0. O peso vale mg = 6·10 = 60 N para baixo; portanto, a normal tem módulo 60 N para cima.","difficulty":"intermediária","sourceBasis":"http://minerva.ufsc.br/~natalia/teaching/FSC5101-FSC5107-2022-1/FSC5101-20221.pdf (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"http://minerva.ufsc.br/~natalia/teaching/FSC5101-FSC5107-2022-1/FSC5101-20221.pdf (calibração apenas); questão autoral/similar; não oficial.","skill":"montar o equilíbrio de forças perpendiculares à superfície","commonError":"Usar a massa em quilogramas como se fosse o peso em newtons.","whyWrong":"A alternativa 0 é a massa, não uma força; a 1 corresponde a metade do peso; a 3 resulta de multiplicar 6 por 100. O peso correto é 60 N e a normal o equilibra.","reviewHint":"Desenhe peso e normal em sentidos opostos e use ΣFy = 0 antes de substituir números.","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-04","subject":"Física","topic":"Dinâmica","subtopic":"peso aparente e elevador","prompt":"Uma pessoa de 70 kg está sobre uma balança dentro de um elevador que acelera verticalmente para cima a 2 m/s². Com g = 10 m/s², qual leitura a balança fornece?","options":["560 N","700 N","840 N","980 N"],"answer":2,"explanation":"No eixo vertical, N − mg = ma. Assim, N = m(g + a) = 70(10 + 2) = 840 N. A leitura aumenta porque a aceleração é para cima.","difficulty":"avançada","sourceBasis":"https://hdl.handle.net/10216/126235 (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10216/126235 (calibração apenas); questão autoral/similar; não oficial.","skill":"distinguir peso gravitacional de força normal ou peso aparente","commonError":"Assumir que a balança sempre lê mg, independentemente da aceleração do elevador.","whyWrong":"A alternativa 0 usa g − a; a 1 é válida apenas em repouso ou movimento uniforme; a 3 soma incorretamente 4 m/s² ao g. A equação correta é N − mg = ma.","reviewHint":"A balança mede a normal; escreva a segunda lei no sentido da aceleração, não a fórmula do peso isoladamente.","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-05","subject":"Física","topic":"Dinâmica","subtopic":"atrito estático","prompt":"Um bloco de 10 kg está em repouso sobre uma superfície horizontal. Uma força de 30 N é aplicada horizontalmente, e o coeficiente de atrito estático é 0,40. Use g = 10 m/s². Qual é o módulo do atrito que atua enquanto o bloco permanece parado?","options":["0 N","10 N","30 N","40 N"],"answer":2,"explanation":"A normal é 100 N e o atrito estático máximo é 0,40·100 = 40 N. Como a força aplicada é 30 N, o atrito se ajusta a 30 N em sentido oposto, mantendo a resultante nula.","difficulty":"intermediária","sourceBasis":"https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax) (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax) (calibração apenas); questão autoral/similar; não oficial.","skill":"diferenciar atrito estático real de seu valor máximo","commonError":"Aplicar diretamente f = μeN mesmo sem haver deslizamento.","whyWrong":"A alternativa 3 é o máximo possível, não o valor real neste caso; 0 ignora a oposição à força aplicada; 10 não decorre dos dados. O atrito real precisa equilibrar 30 N.","reviewHint":"Calcule primeiro o máximo e compare com a força necessária para impedir o movimento.","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-06","subject":"Física","topic":"Dinâmica","subtopic":"atrito cinético em plano inclinado","prompt":"Um bloco de 4 kg desliza para baixo em um plano inclinado de 30°. O coeficiente de atrito cinético é 0,25; use g = 10 m/s², sen 30° = 0,5 e cos 30° ≈ 0,866. Qual é aproximadamente sua aceleração ao longo do plano?","options":["0,6 m/s² para baixo","1,1 m/s² para baixo","2,8 m/s² para baixo","5,0 m/s² para baixo"],"answer":2,"explanation":"Ao longo do plano, o peso contribui com mg sen 30° = 20 N para baixo. A normal é mg cos 30° ≈ 34,64 N, então o atrito é 0,25·34,64 ≈ 8,66 N para cima. A resultante é 11,34 N e a ≈ 11,34/4 = 2,84 m/s² para baixo.","difficulty":"avançada","sourceBasis":"https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax) (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax) (calibração apenas); questão autoral/similar; não oficial.","skill":"projetar peso e calcular atrito cinético em uma rampa","commonError":"Usar mg diretamente ao longo do plano ou calcular o atrito com N = mg.","whyWrong":"A alternativa 3 ignora o atrito e usa a componente errada; 0 e 1 subestimam a resultante por decomposição ou subtração inadequada. A normal é mg cos 30°, não mg.","reviewHint":"Separe os eixos paralelo e perpendicular: mg sen θ impulsiona a descida e μk mg cos θ resiste.","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-07","subject":"Física","topic":"Dinâmica","subtopic":"tração em sistema de polia ideal","prompt":"Dois corpos de 2 kg e 3 kg estão ligados por uma corda ideal que passa por uma polia ideal. O corpo de 3 kg desce. Adote g = 10 m/s². Qual é o módulo da tração na corda?","options":["12 N","20 N","24 N","30 N"],"answer":2,"explanation":"A aceleração do conjunto é (3−2)10/(3+2) = 2 m/s². No corpo de 2 kg, que sobe, T − 20 = 2·2; logo T = 24 N. A idealização torna a tração igual nos dois trechos.","difficulty":"avançada","sourceBasis":"https://hdl.handle.net/10216/126235 (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10216/126235 (calibração apenas); questão autoral/similar; não oficial.","skill":"combinar equações de Newton para determinar tração","commonError":"Igualar a tração ao peso de um dos corpos, como se o sistema estivesse em equilíbrio.","whyWrong":"12 N não satisfaz a equação do corpo leve; 20 N seria o peso dele e só valeria em equilíbrio; 30 N é o peso do corpo pesado. Como há aceleração, T não é simplesmente mg.","reviewHint":"Calcule primeiro a aceleração do conjunto e depois use o DCL de apenas um corpo para encontrar T.","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-08","subject":"Física","topic":"Dinâmica","subtopic":"equilíbrio de partícula","prompt":"Sobre uma partícula atuam uma força de 8 N para a direita e outra de 3 N para a esquerda. Para que a partícula permaneça em equilíbrio, a terceira força deve ser:","options":["2 N para a direita","5 N para a esquerda","5 N para a direita","11 N para a esquerda"],"answer":1,"explanation":"As duas forças dadas produzem resultante de 5 N para a direita. A força equilibrante deve ter mesmo módulo e sentido oposto: 5 N para a esquerda.","difficulty":"intermediária","sourceBasis":"http://minerva.ufsc.br/~natalia/teaching/FSC5101-FSC5107-2022-1/FSC5101-20221.pdf (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"http://minerva.ufsc.br/~natalia/teaching/FSC5101-FSC5107-2022-1/FSC5101-20221.pdf (calibração apenas); questão autoral/similar; não oficial.","skill":"encontrar a força equilibrante por soma vetorial","commonError":"Confundir equilibrante com a resultante das forças já existentes.","whyWrong":"A alternativa 0 não cancela a resultante; a 2 reforça o sentido direito; a 3 soma módulos e aponta para o lado errado. A terceira força deve ser oposta à resultante de 5 N.","reviewHint":"Calcule a resultante das forças conhecidas e inverta seu vetor para obter a equilibrante.","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-09","subject":"Física","topic":"Dinâmica","subtopic":"movimento circular e aceleração centrípeta","prompt":"Um objeto de 2 kg se move em uma circunferência de raio 3 m com rapidez constante de 6 m/s. Qual é o módulo da aceleração centrípeta?","options":["2 m/s²","4 m/s²","12 m/s²","18 m/s²"],"answer":2,"explanation":"A aceleração centrípeta é a_c = v²/r = 6²/3 = 12 m/s². A massa não é necessária para a aceleração, embora fosse necessária para calcular a força radial.","difficulty":"intermediária","sourceBasis":"https://www.ufrb.edu.br/pibid/documentos/category/54-dinamica?download=184:dinmica (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ufrb.edu.br/pibid/documentos/category/54-dinamica?download=184:dinmica (calibração apenas); questão autoral/similar; não oficial.","skill":"aplicar a relação entre rapidez, raio e aceleração centrípeta","commonError":"Multiplicar pela massa ou dividir a rapidez pelo raio sem elevar ao quadrado.","whyWrong":"A alternativa 0 resulta de v/r; a 1 mistura v e r sem a potência correta; a 3 usa 2v/r. A fórmula correta é v²/r e não depende da massa.","reviewHint":"Em movimento circular, confirme se a grandeza pedida é aceleração (v²/r) ou força (mv²/r).","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-10","subject":"Física","topic":"Dinâmica","subtopic":"força centrípeta e atrito em curva","prompt":"Um carro de 1.000 kg faz uma curva plana de raio 50 m. O coeficiente de atrito estático máximo entre pneus e pista é 0,30. Com g = 10 m/s², qual é aproximadamente a maior rapidez sem derrapar?","options":["8,7 m/s","10,0 m/s","12,2 m/s","15,0 m/s"],"answer":2,"explanation":"A normal vale mg = 10.000 N e o atrito máximo é 0,30·10.000 = 3.000 N. Na iminência de derrapar, μmg = mv²/r, então v = √(μgr) = √(0,30·10·50) = √150 ≈ 12,2 m/s.","difficulty":"avançada","sourceBasis":"https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax) (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax) (calibração apenas); questão autoral/similar; não oficial.","skill":"relacionar atrito estático limite à força centrípeta","commonError":"Somar uma força centrípeta ao atrito em vez de reconhecer que o atrito fornece a resultante radial.","whyWrong":"8,7 e 10 m/s vêm de combinações incompletas de μ, g e r; 15 m/s excede o limite calculado. A condição crítica é μmg = mv²/r.","reviewHint":"Em curva plana, identifique o atrito como a força real radial e use o valor máximo apenas na iminência de derrapagem.","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-11","subject":"Física","topic":"Dinâmica","subtopic":"lei da gravitação universal","prompt":"A força gravitacional entre dois corpos vale F quando a distância entre seus centros é r. Se a distância passar a 2r, mantendo as massas, a nova força será:","options":["2F","F/2","F/4","4F"],"answer":2,"explanation":"Como F é proporcional a 1/r², substituir r por 2r produz F' = GMm/(2r)² = F/4.","difficulty":"intermediária","sourceBasis":"https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax) (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax) (calibração apenas); questão autoral/similar; não oficial.","skill":"usar a dependência do inverso do quadrado na gravitação","commonError":"Achar que dobrar a distância apenas divide a força por dois.","whyWrong":"As alternativas 0 e 3 fazem a força crescer, contrariando a distância maior; 1 usa dependência 1/r em vez de 1/r². O fator de distância deve ser elevado ao quadrado.","reviewHint":"Escreva a razão F'/F antes de substituir: (r/r')².","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-12","subject":"Física","topic":"Dinâmica","subtopic":"campo gravitacional em diferentes altitudes","prompt":"Na superfície de um planeta de raio R, o campo gravitacional vale g0. Qual é o campo a uma altitude R acima da superfície, isto é, a uma distância 2R do centro?","options":["g0/2","g0/4","2g0","4g0"],"answer":1,"explanation":"Na superfície, g0 = GM/R². Na distância 2R, g' = GM/(2R)² = GM/(4R²) = g0/4.","difficulty":"avançada","sourceBasis":"http://minerva.ufsc.br/~natalia/teaching/FSC5101-FSC5107-2022-1/FSC5101-20221.pdf (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"http://minerva.ufsc.br/~natalia/teaching/FSC5101-FSC5107-2022-1/FSC5101-20221.pdf (calibração apenas); questão autoral/similar; não oficial.","skill":"interpretar a distância ao centro na expressão do campo gravitacional","commonError":"Ler altitude R como distância R do centro, sem somar o raio do planeta.","whyWrong":"A alternativa 0 trata a dependência como inversa simples; 2 e 3 aumentam o campo sem base. A altitude R somada ao raio R dá distância 2R ao centro, gerando fator 1/4.","reviewHint":"Diferencie altitude acima da superfície de distância medida a partir do centro do astro.","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-13","subject":"Física","topic":"Dinâmica","subtopic":"equilíbrio e atrito estático em plano inclinado","prompt":"Um bloco de 5 kg está em repouso num plano de 30°. Uma força de 40 N puxa-o para cima, paralelamente ao plano. Com g = 10 m/s², sen 30° = 0,5, cos 30° ≈ 0,866 e μe = 0,50, qual é o atrito estático real sobre o bloco?","options":["15 N para baixo do plano","21,7 N para cima do plano","25 N para baixo do plano","40 N para cima do plano"],"answer":0,"explanation":"A componente do peso para baixo é 5·10·0,5 = 25 N. Sem atrito, a força de 40 N deixaria 15 N para cima; portanto, o atrito necessário é 15 N para baixo. O máximo é μeN = 0,5(5·10·0,866) ≈ 21,7 N, então o equilíbrio é possível.","difficulty":"avançada","sourceBasis":"https://hdl.handle.net/10216/126235 (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10216/126235 (calibração apenas); questão autoral/similar; não oficial.","skill":"determinar módulo e sentido do atrito estático por equilíbrio","commonError":"Usar o atrito máximo como se fosse sempre o atrito real ou escolher o sentido sem analisar a tendência.","whyWrong":"21,7 N é o limite, não a necessidade; 25 N apenas cancela a componente do peso e ignora a força aplicada; 40 N tem sentido incorreto. A tendência sem atrito é subir, logo o atrito aponta para baixo e vale 15 N.","reviewHint":"Calcule a resultante sem atrito para descobrir a tendência; depois verifique se o valor exigido cabe no limite μeN.","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-14","subject":"Física","topic":"Dinâmica","subtopic":"resultante em uma dimensão","prompt":"Um corpo de 3 kg sofre forças horizontais de 18 N para a direita e 7 N para a esquerda. Qual é aproximadamente o módulo da aceleração?","options":["2,3 m/s²","3,0 m/s²","3,7 m/s²","8,3 m/s²"],"answer":2,"explanation":"A força resultante é 18 − 7 = 11 N para a direita. Assim, a = 11/3 ≈ 3,67 m/s², cujo módulo é aproximadamente 3,7 m/s².","difficulty":"intermediária","sourceBasis":"https://www.ufrb.edu.br/pibid/documentos/category/54-dinamica?download=184:dinmica (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ufrb.edu.br/pibid/documentos/category/54-dinamica?download=184:dinmica (calibração apenas); questão autoral/similar; não oficial.","skill":"calcular aceleração com forças colineares opostas","commonError":"Dividir a soma 25 N pela massa ou arredondar 11/3 para 3,0.","whyWrong":"A alternativa 0 usa resultado e massa incompatíveis; 1 despreza a subtração das forças; 3 divide a força maior pela massa. Forças opostas devem ser subtraídas, resultando em 11 N.","reviewHint":"Mantenha o sinal das forças no eixo: direita positiva, esquerda negativa.","contentId":"fis-dinamica"},{"id":"m45-fis-dinamica-15","subject":"Física","topic":"Dinâmica","subtopic":"órbita circular e terceira lei de Kepler","prompt":"Um satélite descreve órbita circular em torno do mesmo astro. Se o raio orbital passa de r para 4r, como muda o período orbital?","options":["Torna-se 2 vezes maior","Torna-se 4 vezes maior","Torna-se 8 vezes maior","Torna-se 16 vezes maior"],"answer":2,"explanation":"Para a mesma massa central, T = 2π√(r³/GM), portanto T é proporcional a r^(3/2). Ao multiplicar r por 4, o período é multiplicado por 4^(3/2) = 8.","difficulty":"avançada","sourceBasis":"https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax) (calibração apenas); questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Bookshelves/College_Physics/College_Physics_1e_(OpenStax) (calibração apenas); questão autoral/similar; não oficial.","skill":"usar a dependência do período orbital com o raio","commonError":"Aplicar proporcionalidade direta T ∝ r ou confundir período com velocidade orbital.","whyWrong":"2 e 4 ignoram o expoente 3/2; 16 eleva o fator de raio a 2. A lei orbital exige 4^(3/2) = 4·2 = 8.","reviewHint":"Parta da relação T² proporcional a r³ ou escreva a razão de períodos antes de calcular.","contentId":"fis-dinamica"},{"id":"m45-fis-eletrica-01","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"Lei de Coulomb e interação entre cargas","prompt":"No ar, duas cargas puntiformes estão separadas por 0,20 m: q₁ = +4 μC e q₂ = −2 μC. Use k = 9,0 × 10⁹ N·m²/C². Qual é a força elétrica entre elas?","options":["0,45 N, repulsiva.","1,8 N, atrativa.","1,8 N, repulsiva.","7,2 N, atrativa."],"answer":1,"explanation":"Pela Lei de Coulomb, F = k|q₁q₂|/r² = 9,0×10⁹·(8×10⁻¹²)/(0,20)² = 1,8 N. Como os sinais são opostos, a interação é atrativa.","difficulty":"intermediária","sourceBasis":"https://hdl.handle.net/10923/12475 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10923/12475 — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular a intensidade pela Lei de Coulomb e interpretar o sentido pela combinação de sinais","commonError":"Usar μC como se fosse C ou escolher o sentido sem examinar os sinais.","whyWrong":"0 resulta de uma conversão/aritmética incorreta; 2 troca atração por repulsão; 3 ignora o quadrado da distância e superestima o módulo.","reviewHint":"Converta cada microcoulomb para 10⁻⁶ C e só depois aplique r².","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-02","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"campo elétrico e superposição","prompt":"Duas cargas estão sobre um eixo: +3 μC em x = −0,10 m e −3 μC em x = +0,10 m. Qual é o campo elétrico no ponto x = 0? Use k = 9,0 × 10⁹ N·m²/C².","options":["Zero, pois os módulos das cargas são iguais.","2,7 × 10⁶ N/C para a esquerda.","5,4 × 10⁶ N/C para a direita.","5,4 × 10⁶ N/C para a esquerda."],"answer":2,"explanation":"Cada carga está a 0,10 m e produz E = k|q|/r² = 2,7×10⁶ N/C. No ponto médio, o campo da carga positiva aponta para a direita e o da negativa também aponta para a direita; portanto, somam-se e dão 5,4×10⁶ N/C para a direita.","difficulty":"avançada","sourceBasis":"https://hdl.handle.net/10216/129323 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10216/129323 — calibração apenas; questão autoral/similar; não oficial.","skill":"somar campos como vetores, considerando a direção determinada por cada carga","commonError":"Cancelar campos apenas porque os módulos das cargas são iguais, sem desenhar os sentidos.","whyWrong":"0 esquece que os sentidos são iguais no ponto médio; 1 e 3 usam apenas um campo ou apontam na direção contrária à regra do campo; a distância correta é 0,10 m.","reviewHint":"Para carga positiva, o campo sai; para carga negativa, o campo entra. Faça as duas setas no ponto.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-03","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"potencial e energia elétrica","prompt":"Uma carga de prova positiva q = 2,0 μC passa de A, onde V_A = 120 V, para B, onde V_B = 40 V. Qual é o trabalho realizado pelo campo elétrico?","options":["−1,6 × 10⁻⁴ J.","+1,6 × 10⁻⁴ J.","−1,6 × 10⁻⁵ J.","+1,6 × 10⁻⁵ J."],"answer":1,"explanation":"W_campo = q(V_A − V_B) = 2,0×10⁻⁶·(120−40) = 1,6×10⁻⁴ J. A carga positiva vai para menor potencial, portanto o trabalho do campo é positivo.","difficulty":"intermediária","sourceBasis":"https://phys.libretexts.org/Bookshelves/University_Physics/Calculus-Based_Physics_(Schnick)/Volume_B%3A_Electricity_Magnetism_and_Optics — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Bookshelves/University_Physics/Calculus-Based_Physics_(Schnick)/Volume_B%3A_Electricity_Magnetism_and_Optics — calibração apenas; questão autoral/similar; não oficial.","skill":"relacionar diferença de potencial, trabalho e sinal da carga","commonError":"Usar ΔV na ordem errada ou confundir trabalho do campo com variação da energia potencial.","whyWrong":"0 e 2 têm sinal incompatível com o movimento para menor potencial; 2 e 3 ainda deslocam a potência de dez por erro na conversão de μC.","reviewHint":"Use W_campo = q(V_inicial − V_final) para uma carga que se desloca entre dois potenciais.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-04","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"corrente elétrica","prompt":"Uma seção de um fio é atravessada por 3,6 × 10³ C de carga em 2,0 minutos. Qual é a corrente média?","options":["18 A.","30 A.","60 A.","120 A."],"answer":1,"explanation":"Converta 2,0 min para 120 s e use I = ΔQ/Δt = 3,6×10³/120 = 30 A.","difficulty":"intermediária","sourceBasis":"https://hdl.handle.net/10216/129323 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10216/129323 — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular corrente média a partir de carga e intervalo de tempo","commonError":"Dividir pelo tempo em minutos ou multiplicar carga e tempo.","whyWrong":"0 usa 200 s ou uma divisão inadequada; 2 desconsidera a conversão de minutos; 3 dobra indevidamente o resultado.","reviewHint":"A unidade do ampère é C/s; transforme minutos em segundos.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-05","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"resistência e resistividade","prompt":"Um fio cilíndrico é substituído por outro do mesmo material. O novo fio tem o dobro do comprimento e a metade do raio. Qual é a razão R_novo/R_antigo?","options":["2.","4.","6.","8."],"answer":3,"explanation":"Como R = ρL/A e A é proporcional a r², reduzir o raio à metade reduz a área a um quarto. Assim, R_novo/R_antigo = 2/(1/4) = 8.","difficulty":"avançada","sourceBasis":"https://phys.libretexts.org/Bookshelves/University_Physics/Calculus-Based_Physics_(Schnick)/Volume_B%3A_Electricity_Magnetism_and_Optics — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Bookshelves/University_Physics/Calculus-Based_Physics_(Schnick)/Volume_B%3A_Electricity_Magnetism_and_Optics — calibração apenas; questão autoral/similar; não oficial.","skill":"combinar dependências geométricas da resistência com a área da seção circular","commonError":"Tratar área como proporcional ao raio, e não ao quadrado do raio.","whyWrong":"0 considera apenas o comprimento; 1 usa a redução de área como fator 2; 2 combina fatores sem reconhecer que a área caiu para um quarto.","reviewHint":"Escreva A = πr² antes de comparar os dois fios.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-06","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"associação de resistores","prompt":"Uma fonte ideal de 12 V alimenta um resistor de 4 Ω em série com a associação em paralelo de 6 Ω e 3 Ω. Qual é a corrente no resistor de 3 Ω?","options":["2/3 A.","4/3 A.","2 A.","4 A."],"answer":1,"explanation":"O paralelo equivale a (6·3)/(6+3) = 2 Ω; com o resistor de 4 Ω, R_eq = 6 Ω e a corrente total é 2 A. A queda no paralelo é 2·2 = 4 V, logo no resistor de 3 Ω a corrente é 4/3 A.","difficulty":"intermediária","sourceBasis":"https://hdl.handle.net/10216/129323 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10216/129323 — calibração apenas; questão autoral/similar; não oficial.","skill":"reduzir uma associação mista e aplicar a mesma tensão aos ramos paralelos","commonError":"Atribuir a corrente total a cada ramo ou somar resistores em paralelo diretamente.","whyWrong":"0 usa a corrente no ramo de 6 Ω; 2 é a corrente total, não a do ramo; 3 ignora a redução do paralelo e a tensão efetiva de 4 V.","reviewHint":"Resolva primeiro o equivalente, depois encontre a tensão comum aos dois resistores do paralelo.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-07","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"potência e energia elétrica","prompt":"Um aquecedor de 600 W permanece ligado durante 30 minutos. Qual é o consumo de energia nesse intervalo, em kWh?","options":["0,03 kWh.","0,30 kWh.","1,80 kWh.","18 kWh."],"answer":1,"explanation":"A potência é 0,600 kW e o tempo é 0,5 h. Portanto, E = PΔt = 0,600·0,5 = 0,30 kWh.","difficulty":"intermediária","sourceBasis":"https://hdl.handle.net/10923/12475 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10923/12475 — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular energia consumida mantendo potência e tempo em unidades compatíveis","commonError":"Usar 600 como se fosse kW ou converter meia hora para 30 h.","whyWrong":"0 perde um fator 10; 2 multiplica 0,6 por 3 em vez de 0,5; 3 mistura watts com horas e produz valor mil vezes maior.","reviewHint":"Em kWh, use potência em kW e tempo em horas.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-08","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"leis de Kirchhoff","prompt":"Uma única malha contém fontes ideais de 18 V e 6 V em oposição, além de resistores de 3 Ω e 3 Ω em série. A fonte de 18 V favorece o sentido horário. Qual é a corrente e seu sentido?","options":["1 A no sentido anti-horário.","2 A no sentido horário.","4 A no sentido horário.","8 A no sentido anti-horário."],"answer":1,"explanation":"Percorrendo a malha no sentido horário, a força eletromotriz resultante é 18−6 = 12 V e a resistência total é 6 Ω. Logo, I = 12/6 = 2 A; como o resultado no sentido escolhido é positivo, o sentido é horário.","difficulty":"avançada","sourceBasis":"https://hdl.handle.net/10216/129323 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10216/129323 — calibração apenas; questão autoral/similar; não oficial.","skill":"aplicar conservação de energia em uma malha com fontes em oposição","commonError":"Somar fontes com polaridades opostas ou usar apenas um dos resistores.","whyWrong":"0 inverte o sentido sem justificar; 2 ignora o resistor total; 3 soma tensões e/ou usa resistência incorreta, além de inverter o sentido.","reviewHint":"Escolha um sentido, some as variações de potencial com sinais e interprete um resultado negativo como sentido oposto.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-09","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"força magnética sobre carga","prompt":"Uma carga q = −2,0 μC move-se para a direita com velocidade 3,0 × 10⁵ m/s em um campo uniforme de 0,40 T dirigido para cima, perpendicular à velocidade. Qual é a força magnética?","options":["0,24 N para fora do plano.","0,24 N para dentro do plano.","0,48 N para dentro do plano.","Zero, pois a carga é negativa."],"answer":1,"explanation":"O módulo é |q|vB = 2,0×10⁻⁶·3,0×10⁵·0,40 = 0,24 N. Para carga positiva, direita × cima aponta para fora da página; como a carga é negativa, o sentido se inverte: para dentro.","difficulty":"avançada","sourceBasis":"https://phys.libretexts.org/Bookshelves/University_Physics/Calculus-Based_Physics_(Schnick)/Volume_B%3A_Electricity_Magnetism_and_Optics — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Bookshelves/University_Physics/Calculus-Based_Physics_(Schnick)/Volume_B%3A_Electricity_Magnetism_and_Optics — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular força magnética e inverter sua orientação para carga negativa","commonError":"Aplicar a regra da mão direita diretamente à carga negativa ou esquecer que o movimento é perpendicular ao campo.","whyWrong":"0 dá o sentido de uma carga positiva; 2 erra o módulo por fator 2; 3 confunde carga negativa com ausência de força.","reviewHint":"Calcule o módulo com o valor absoluto da carga e só depois determine o sentido.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-10","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"campo magnético de corrente retilínea","prompt":"Um fio longo e retilíneo conduz 10 A. Qual é o módulo do campo magnético a 5,0 cm do fio? Use μ₀ = 4π × 10⁻⁷ T·m/A.","options":["4,0 × 10⁻⁶ T.","4,0 × 10⁻⁵ T.","2,0 × 10⁻⁴ T.","4,0 × 10⁻⁴ T."],"answer":1,"explanation":"Para fio longo, B = μ₀I/(2πr). Com r = 0,050 m, B = (4π×10⁻⁷·10)/(2π·0,050) = 4,0×10⁻⁵ T.","difficulty":"intermediária","sourceBasis":"https://hdl.handle.net/10216/129323 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10216/129323 — calibração apenas; questão autoral/similar; não oficial.","skill":"usar a expressão do campo de fio longo e converter a distância para metro","commonError":"Substituir 5 cm por 5 m ou esquecer o fator 2π.","whyWrong":"0 resulta de deslocar uma casa decimal; 2 e 3 deixam de considerar a distância e/ou o denominador 2π.","reviewHint":"Antes da fórmula, escreva 5,0 cm = 5,0×10⁻² m.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-11","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"Lei de Faraday e fluxo magnético","prompt":"Uma bobina de 200 espiras e área 2,0 × 10⁻² m² permanece com sua normal paralela ao campo. O campo aumenta uniformemente de 0,10 T para 0,40 T em 0,30 s. Qual é o módulo da fem induzida?","options":["0,20 V.","2,0 V.","3,0 V.","4,0 V."],"answer":3,"explanation":"A variação de fluxo por espira é ΔΦ = AΔB = 0,02·0,30 = 0,006 Wb. Faraday dá |ε| = N|ΔΦ|/Δt = 200·0,006/0,30 = 4,0 V.","difficulty":"avançada","sourceBasis":"https://phys.libretexts.org/Bookshelves/University_Physics/Calculus-Based_Physics_(Schnick)/Volume_B%3A_Electricity_Magnetism_and_Optics — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Bookshelves/University_Physics/Calculus-Based_Physics_(Schnick)/Volume_B%3A_Electricity_Magnetism_and_Optics — calibração apenas; questão autoral/similar; não oficial.","skill":"relacionar variação de fluxo, número de espiras e fem induzida","commonError":"Usar apenas a variação de campo, sem área ou número de espiras, ou esquecer o intervalo de tempo.","whyWrong":"0 não inclui corretamente o número de espiras; 1 e 2 omitem um fator de escala na divisão pelo tempo ou na multiplicação por N.","reviewHint":"Calcule primeiro o fluxo por espira e depois multiplique a taxa de variação por N.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-12","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"transformadores e potência","prompt":"Um transformador ideal tem N_p = 500 espiras, N_s = 100 espiras e recebe 220 V no primário. Se a corrente no primário é 0,50 A, qual é a corrente no secundário?","options":["0,10 A.","0,50 A.","2,5 A.","5,0 A."],"answer":2,"explanation":"A tensão secundária é V_s = 220·(100/500) = 44 V. Em transformador ideal, V_pI_p = V_sI_s; então I_s = 220·0,50/44 = 2,5 A.","difficulty":"avançada","sourceBasis":"https://phys.libretexts.org/Bookshelves/University_Physics/Calculus-Based_Physics_(Schnick)/Volume_B%3A_Electricity_Magnetism_and_Optics — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Bookshelves/University_Physics/Calculus-Based_Physics_(Schnick)/Volume_B%3A_Electricity_Magnetism_and_Optics — calibração apenas; questão autoral/similar; não oficial.","skill":"usar a relação de espiras e a conservação de potência em transformador ideal","commonError":"Supor que corrente e tensão sempre variam na mesma razão ou ignorar a hipótese de idealidade.","whyWrong":"0 usa a razão de espiras para a corrente sem inversão; 1 repete a corrente do primário; 3 duplica o resultado ao trocar a razão.","reviewHint":"Transformador elevador de tensão reduz corrente, e transformador abaixador de tensão aumenta corrente, idealmente.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-13","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"condutores em equilíbrio eletrostático","prompt":"Uma esfera condutora oca está em equilíbrio eletrostático, possui carga líquida excedente e sua cavidade interna está vazia. Qual afirmação é correta?","options":["O campo é máximo no interior do material condutor.","O campo é nulo no material condutor e também na cavidade vazia.","O campo é nulo no material, mas necessariamente uniforme e não nulo na cavidade.","A carga excedente permanece distribuída uniformemente no volume do metal."],"answer":1,"explanation":"Em equilíbrio eletrostático, o campo no material condutor é nulo. Como a cavidade não contém carga, a superfície gaussiana dentro da cavidade também envolve carga líquida zero e o campo permanece nulo. A carga excedente fica nas superfícies.","difficulty":"avançada","sourceBasis":"https://hdl.handle.net/10923/12475 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10923/12475 — calibração apenas; questão autoral/similar; não oficial.","skill":"aplicar a condição de equilíbrio eletrostático e a Lei de Gauss qualitativamente","commonError":"Imaginar que a carga excedente ocupa o volume ou que todo interior de um condutor tem campo não nulo.","whyWrong":"0 contradiz o equilíbrio; 2 inventa campo na cavidade; 3 confunde distribuição superficial com volumétrica.","reviewHint":"Em equilíbrio, cargas livres não podem continuar acelerando dentro do material; por isso E = 0 no metal.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-14","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"fonte real e tensão nos terminais","prompt":"Uma fonte de fem 12 V e resistência interna 1,0 Ω alimenta um resistor externo de 5,0 Ω. Qual é a tensão nos terminais da fonte durante o fornecimento de corrente?","options":["2,0 V.","10 V.","12 V.","60 V."],"answer":1,"explanation":"A corrente é I = ε/(R_ext+r) = 12/6 = 2 A. A queda interna é Ir = 2 V, portanto a tensão terminal é V = ε−Ir = 10 V, igual a I·R_ext.","difficulty":"avançada","sourceBasis":"https://def.fe.up.pt/eletricidade/problemas.html — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://def.fe.up.pt/eletricidade/problemas.html — calibração apenas; questão autoral/similar; não oficial.","skill":"modelar resistência interna e distinguir fem da tensão terminal sob carga","commonError":"Tomar a fem como tensão terminal em qualquer condição ou multiplicar a fem pelas resistências.","whyWrong":"0 é apenas a queda interna; 2 é a resposta correta; 3 usa produto sem interpretação física e não é tensão terminal.","reviewHint":"Quando a fonte fornece corrente, subtraia a queda na resistência interna da fem.","contentId":"fis-eletrica"},{"id":"m45-fis-eletrica-15","subject":"Física","topic":"Eletricidade e magnetismo","subtopic":"indução por movimento","prompt":"Uma barra condutora de 0,50 m desliza a 4,0 m/s perpendicularmente a um campo magnético uniforme de 0,20 T, mantendo a geometria perpendicular. Qual é a fem motional entre as extremidades?","options":["0,04 V.","0,10 V.","0,40 V.","4,0 V."],"answer":2,"explanation":"Para a geometria perpendicular, ε = Bℓv = 0,20·0,50·4,0 = 0,40 V.","difficulty":"intermediária","sourceBasis":"https://hdl.handle.net/10216/129323 — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://hdl.handle.net/10216/129323 — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular a fem de movimento em uma barra condutora","commonError":"Usar a velocidade em cm/s, esquecer o comprimento ou aplicar um seno adicional quando a geometria já é perpendicular.","whyWrong":"0 desloca a vírgula por fator 10; 1 usa apenas Bℓ; 3 multiplica por 10 o resultado correto.","reviewHint":"A expressão Bℓv vale diretamente quando barra, velocidade e campo são mutuamente perpendiculares.","contentId":"fis-eletrica"},{"id":"m45-fis-energia-01","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"trabalho de força constante","prompt":"Uma caixa desloca-se 4 m horizontalmente enquanto uma força constante de 20 N atua fazendo 60° com a direção do deslocamento. Qual é o trabalho realizado por essa força?","options":["40 J","80 J","0 J","160 J"],"answer":0,"explanation":"Para uma força constante, W = Fd cosθ. Assim, W = 20 · 4 · cos60° = 80 · 0,5 = 40 J.","difficulty":"intermediária","sourceBasis":"https://www2.unifap.br/pet-fisica/files/2022/11/Apostila-Oficial-Mecanica_-Trabalho-e-Energia-Grupo-PET.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www2.unifap.br/pet-fisica/files/2022/11/Apostila-Oficial-Mecanica_-Trabalho-e-Energia-Grupo-PET.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular trabalho usando a componente da força paralela ao deslocamento","commonError":"Aplicar W = Fd sem considerar o ângulo entre força e deslocamento.","whyWrong":"1 usa a força inteira e ignora cos60°; 2 trata a força como perpendicular, embora o ângulo seja 60°; 3 duplica indevidamente o trabalho obtido sem projeção.","reviewHint":"Identifique o ângulo e escreva primeiro W = Fd cosθ antes de inserir os valores.","contentId":"fis-energia"},{"id":"m45-fis-energia-02","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"potência média","prompt":"Um motor realiza 1.800 J de trabalho útil em 30 s. Qual é sua potência média útil nesse intervalo?","options":["30 W","60 W","540 W","1.830 W"],"answer":1,"explanation":"A potência média é Pm = W/Δt. Portanto, Pm = 1.800/30 = 60 W.","difficulty":"intermediária","sourceBasis":"https://epamig.br/itap/wp-content/uploads/2020/07/Fisica-Aplicada.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://epamig.br/itap/wp-content/uploads/2020/07/Fisica-Aplicada.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"relacionar trabalho e intervalo de tempo para obter potência média","commonError":"Multiplicar trabalho e tempo ou confundir potência com energia.","whyWrong":"0 resulta de dividir 1.800 por 60, não pelo intervalo dado; 2 é o produto 1.800 · 30; 3 soma grandezas de naturezas diferentes.","reviewHint":"Potência é taxa: pense em quantos joules são transferidos a cada segundo.","contentId":"fis-energia"},{"id":"m45-fis-energia-03","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"teorema trabalho–energia","prompt":"Um carrinho de massa 2 kg aumenta sua velocidade de 2 m/s para 6 m/s. Qual é o trabalho da força resultante sobre ele?","options":["16 J","32 J","36 J","40 J"],"answer":1,"explanation":"Pelo teorema trabalho–energia, Wresultante = ΔEc = (m/2)(vf² − vi²). Logo, W = (2/2)(36 − 4) = 32 J.","difficulty":"intermediária","sourceBasis":"https://www2.unifap.br/pet-fisica/files/2022/11/Apostila-Oficial-Mecanica_-Trabalho-e-Energia-Grupo-PET.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www2.unifap.br/pet-fisica/files/2022/11/Apostila-Oficial-Mecanica_-Trabalho-e-Energia-Grupo-PET.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular variação de energia cinética e trabalho resultante","commonError":"Usar apenas a energia cinética final ou esquecer o quadrado das velocidades.","whyWrong":"0 é a energia cinética inicial; 2 é vf² sem o fator m/2 nem a subtração; 3 resulta de somar os quadrados em vez de calcular a diferença.","reviewHint":"O trabalho resultante é a energia cinética final menos a inicial, não apenas a final.","contentId":"fis-energia"},{"id":"m45-fis-energia-04","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"energia potencial gravitacional","prompt":"Considerando g = 10 m/s², qual é o aumento da energia potencial gravitacional de um pacote de 3 kg elevado 5 m?","options":["15 J","50 J","150 J","300 J"],"answer":2,"explanation":"A variação de energia potencial gravitacional é ΔUg = mgΔh = 3 · 10 · 5 = 150 J.","difficulty":"intermediária","sourceBasis":"https://epamig.br/itap/wp-content/uploads/2020/07/Fisica-Aplicada.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://epamig.br/itap/wp-content/uploads/2020/07/Fisica-Aplicada.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar energia potencial gravitacional a uma diferença de altura","commonError":"Usar apenas a altura ou confundir massa com peso sem concluir o produto completo.","whyWrong":"0 é mΔh sem g; 1 é gΔh sem massa; 3 duplica o valor correto, sem justificativa física.","reviewHint":"Escreva ΔUg = mg(hfinal − hinicial) e verifique que a unidade final é joule.","contentId":"fis-energia"},{"id":"m45-fis-energia-05","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"energia potencial elástica","prompt":"Uma mola ideal de constante elástica 400 N/m é comprimida 0,10 m. Qual energia potencial elástica fica armazenada?","options":["0,2 J","2 J","20 J","40 J"],"answer":1,"explanation":"A energia da mola é Ue = kx²/2 = 400 · (0,10)²/2 = 400 · 0,01/2 = 2 J.","difficulty":"intermediária","sourceBasis":"https://www2.unifap.br/pet-fisica/files/2022/11/Apostila-Oficial-Mecanica_-Trabalho-e-Energia-Grupo-PET.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www2.unifap.br/pet-fisica/files/2022/11/Apostila-Oficial-Mecanica_-Trabalho-e-Energia-Grupo-PET.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular energia armazenada em uma mola ideal","commonError":"Usar x em vez de x² ou esquecer o fator 1/2.","whyWrong":"0 e 2 decorrem de não elevar a deformação ao quadrado ou de erros de escala; 3 omite o fator 1/2 e ainda usa unidade incompatível com o resultado correto.","reviewHint":"Conserve a unidade da deformação em metros e calcule primeiro x².","contentId":"fis-energia"},{"id":"m45-fis-energia-06","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"rendimento","prompt":"Uma máquina recebe 1.000 J de energia e entrega 750 J como energia útil. Qual é o seu rendimento?","options":["7,5%","25%","75%","133%"],"answer":2,"explanation":"η = Eútil/Efornecida = 750/1.000 = 0,75. Em porcentagem, η = 75%.","difficulty":"intermediária","sourceBasis":"https://estudante.ifpb.edu.br/media/cursos/82/disciplina/F%C3%ADsica_1%C2%BA_ano.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://estudante.ifpb.edu.br/media/cursos/82/disciplina/F%C3%ADsica_1%C2%BA_ano.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"determinar rendimento pela razão entre saída útil e entrada","commonError":"Inverter a razão ou apresentar uma fração decimal como se já fosse porcentagem.","whyWrong":"0 corresponde a 75/10 sem conversão coerente; 1 é a fração perdida, não o rendimento; 3 inverteria a razão e produziria rendimento acima de 100%.","reviewHint":"A energia útil fica no numerador; multiplique por 100 somente ao transformar em porcentagem.","contentId":"fis-energia"},{"id":"m45-fis-energia-07","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"impulso e quantidade de movimento","prompt":"Uma força média constante de 50 N atua na direção do movimento durante 0,20 s. Qual é o módulo do impulso transmitido ao corpo?","options":["0,10 N·s","10 N·s","25 N·s","250 N·s"],"answer":1,"explanation":"Para força constante, o impulso é I = FΔt = 50 · 0,20 = 10 N·s.","difficulty":"intermediária","sourceBasis":"https://ufrb.edu.br/pibid/documentos/category/60-quantidade-de-movimento?download=223:apostila-impulso-e-quantidade-de-movimento-2 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://ufrb.edu.br/pibid/documentos/category/60-quantidade-de-movimento?download=223:apostila-impulso-e-quantidade-de-movimento-2 (calibração apenas; questão autoral/similar; não oficial).","skill":"relacionar força média, tempo de atuação e impulso","commonError":"Dividir a força pelo tempo ou esquecer a conversão de 0,20 s.","whyWrong":"0 é o produto de 50 por 0,002; 2 é 50/2, sem relação com o intervalo dado; 3 multiplica por 5 em vez de por 0,20.","reviewHint":"Para força constante, impulso é simplesmente a área do retângulo no gráfico força-tempo.","contentId":"fis-energia"},{"id":"m45-fis-energia-08","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"trabalho de força variável","prompt":"O gráfico força versus posição de uma força variável é um triângulo totalmente acima do eixo, com base de 6 m e altura de 10 N. Qual é o trabalho realizado nesse trecho?","options":["16 J","30 J","60 J","120 J"],"answer":1,"explanation":"O trabalho é a área sob o gráfico F×x. Para o triângulo, W = base · altura/2 = 6 · 10/2 = 30 J.","difficulty":"avançada","sourceBasis":"https://estudante.ifpb.edu.br/media/cursos/82/disciplina/F%C3%ADsica_1%C2%BA_ano.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://estudante.ifpb.edu.br/media/cursos/82/disciplina/F%C3%ADsica_1%C2%BA_ano.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"interpretar a área algébrica sob um gráfico força–posição","commonError":"Multiplicar base e altura sem dividir pela forma triangular.","whyWrong":"0 usa uma área sem os dados corretos; 2 é base vezes altura, como se fosse retângulo; 3 duplica o produto e ignora novamente o fator geométrico 1/2.","reviewHint":"Reconheça a forma geométrica do gráfico e use área algébrica, não o valor máximo da força vezes todo o deslocamento.","contentId":"fis-energia"},{"id":"m45-fis-energia-09","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"conservação da energia com dissipação","prompt":"Um bloco de 2 kg move-se a 5 m/s sobre uma superfície rugosa e para. Qual é o trabalho realizado pelo atrito, supondo que nenhuma outra força horizontal realize trabalho?","options":["−25 J","0 J","25 J","−50 J"],"answer":0,"explanation":"O trabalho resultante é ΔEc. Como a velocidade final é zero, W = 0 − (2 · 5²/2) = −25 J. Esse trabalho negativo representa a dissipação por atrito.","difficulty":"avançada","sourceBasis":"https://www2.unifap.br/pet-fisica/files/2022/11/Apostila-Oficial-Mecanica_-Trabalho-e-Energia-Grupo-PET.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www2.unifap.br/pet-fisica/files/2022/11/Apostila-Oficial-Mecanica_-Trabalho-e-Energia-Grupo-PET.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"usar o teorema trabalho–energia para quantificar dissipação","commonError":"Tomar o módulo da energia cinética inicial e esquecer que o atrito se opõe ao movimento.","whyWrong":"1 ignora a diminuição da energia cinética; 2 fornece o módulo, mas não o sinal do trabalho resistente; 3 dobra sem fundamento o valor da energia inicial.","reviewHint":"Calcule sempre ΔEc = Ecf − Eci; a ordem final menos inicial determina o sinal.","contentId":"fis-energia"},{"id":"m45-fis-energia-10","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"potência instantânea","prompt":"Um corpo de 3 kg move-se instantaneamente a 4 m/s, e uma força de 12 N atua no mesmo sentido da velocidade. Qual é a potência instantânea dessa força?","options":["9 W","36 W","48 W","144 W"],"answer":2,"explanation":"Como força e velocidade têm a mesma direção, P = Fv cos0° = 12 · 4 = 48 W. A massa não é necessária para este cálculo.","difficulty":"avançada","sourceBasis":"https://epamig.br/itap/wp-content/uploads/2020/07/Fisica-Aplicada.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://epamig.br/itap/wp-content/uploads/2020/07/Fisica-Aplicada.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular potência instantânea pelo produto escalar força–velocidade","commonError":"Usar massa e aceleração sem verificar que a pergunta fornece diretamente força e velocidade.","whyWrong":"0 divide a força pela massa; 1 multiplica força por massa; 3 eleva ou multiplica grandezas sem usar a relação P = Fv.","reviewHint":"Para a potência de uma força, use sua componente na direção da velocidade: P = Fv cosθ.","contentId":"fis-energia"},{"id":"m45-fis-energia-11","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"colisões e conservação da quantidade de movimento","prompt":"Um carrinho de 2 kg move-se a 6 m/s e colide com outro de 4 kg inicialmente em repouso. Se os dois ficam unidos, qual é a velocidade do conjunto imediatamente após a colisão?","options":["1 m/s","2 m/s","3 m/s","6 m/s"],"answer":1,"explanation":"Conservando o momento linear, 2·6 + 4·0 = (2 + 4)v. Logo, 12 = 6v e v = 2 m/s. Como ficam unidos, o choque é perfeitamente inelástico.","difficulty":"avançada","sourceBasis":"https://ufrb.edu.br/pibid/documentos/category/60-quantidade-de-movimento?download=223:apostila-impulso-e-quantidade-de-movimento-2 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://ufrb.edu.br/pibid/documentos/category/60-quantidade-de-movimento?download=223:apostila-impulso-e-quantidade-de-movimento-2 (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar conservação do momento em colisão perfeitamente inelástica","commonError":"Conservar a velocidade do primeiro carrinho ou a energia cinética em vez do momento.","whyWrong":"0 subestima o momento inicial sem justificativa; 2 ignora a massa total do conjunto; 3 mantém a velocidade inicial e não considera o segundo carrinho incorporado.","reviewHint":"Quando os corpos ficam unidos, escreva massa total vezes velocidade final e iguale ao momento inicial total.","contentId":"fis-energia"},{"id":"m45-fis-energia-12","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"conversão de energia elástica em cinética","prompt":"Um bloco de 0,5 kg é lançado por uma mola ideal de constante 400 N/m comprimida 0,10 m, sem perdas. Qual é a velocidade do bloco ao deixar a mola?","options":["1 m/s","2 m/s","2√2 m/s","4 m/s"],"answer":2,"explanation":"A mola armazena Ue = 400(0,10)²/2 = 2 J. Pela conservação, mv²/2 = 2; então 0,5v²/2 = 2, isto é, v² = 8 e v = 2√2 m/s.","difficulty":"avançada","sourceBasis":"https://www2.unifap.br/pet-fisica/files/2022/11/Apostila-Oficial-Mecanica_-Trabalho-e-Energia-Grupo-PET.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www2.unifap.br/pet-fisica/files/2022/11/Apostila-Oficial-Mecanica_-Trabalho-e-Energia-Grupo-PET.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"combinar energia potencial elástica e energia cinética","commonError":"Usar a deformação como velocidade ou esquecer que a energia cinética também tem fator 1/2.","whyWrong":"0 não satisfaz a igualdade de energias; 1 resulta de erro ao extrair a raiz; 3 seria compatível com uma energia cinética quatro vezes maior que a armazenada.","reviewHint":"Calcule a energia da mola separadamente e só depois iguale a mv²/2.","contentId":"fis-energia"},{"id":"m45-fis-energia-13","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"trabalho não conservativo e queda","prompt":"Um corpo de 4 kg parte do repouso e desce 5 m. Adote g = 10 m/s² e suponha que a resistência do ar realiza trabalho de −20 J. Qual é aproximadamente a velocidade ao final da descida?","options":["8,0 m/s","9,5 m/s","10,0 m/s","11,0 m/s"],"answer":1,"explanation":"A energia potencial perdida é mgh = 4·10·5 = 200 J. Como a resistência retira 20 J, a energia cinética final é 180 J. Então mv²/2 = 180, logo v² = 90 e v = √90 ≈ 9,5 m/s.","difficulty":"avançada","sourceBasis":"https://epamig.br/itap/wp-content/uploads/2020/07/Fisica-Aplicada.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://epamig.br/itap/wp-content/uploads/2020/07/Fisica-Aplicada.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar conservação de energia incluindo trabalho dissipativo","commonError":"Usar toda a energia potencial como cinética final, ignorando o trabalho negativo da resistência.","whyWrong":"0 subestima a conversão ao tratar a perda como muito maior; 2 é a velocidade ideal sem resistência; 3 excede a velocidade ideal, contrariando o trabalho dissipativo.","reviewHint":"Escreva Ecfinal = mgh + Wnão conservativo; um trabalho negativo reduz a energia disponível.","contentId":"fis-energia"},{"id":"m45-fis-energia-14","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"impulso obtido por gráfico força–tempo","prompt":"A força resultante sobre um corpo varia com o tempo formando um triângulo no gráfico F×t, de base 0,40 s e altura 100 N. O corpo tem massa 5 kg e velocidade inicial de 2 m/s no sentido da força. Qual é a velocidade final?","options":["4 m/s","5 m/s","6 m/s","10 m/s"],"answer":2,"explanation":"O impulso é a área do triângulo: I = 0,40·100/2 = 20 N·s. O momento inicial é 5·2 = 10 kg·m/s; o final é 10 + 20 = 30 kg·m/s. Portanto, vf = 30/5 = 6 m/s.","difficulty":"avançada","sourceBasis":"https://ufrb.edu.br/pibid/documentos/category/60-quantidade-de-movimento?download=223:apostila-impulso-e-quantidade-de-movimento-2 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://ufrb.edu.br/pibid/documentos/category/60-quantidade-de-movimento?download=223:apostila-impulso-e-quantidade-de-movimento-2 (calibração apenas; questão autoral/similar; não oficial).","skill":"obter impulso pela área F×t e convertê-lo em variação do momento","commonError":"Usar a altura do gráfico como impulso ou somar força diretamente à velocidade.","whyWrong":"0 corresponde a uma área ou atualização incompleta; 1 ignora o momento inicial ou usa área sem o fator triangular; 3 trata o pico de força como se atuasse por tempo unitário e despreza a massa.","reviewHint":"Primeiro calcule a área do gráfico em N·s; depois use pfinal = pinicial + I.","contentId":"fis-energia"},{"id":"m45-fis-energia-15","subject":"Física","topic":"Trabalho, energia e potência","subtopic":"potência útil e rendimento","prompt":"Um elevador ergue uma carga de 200 kg por 6 m em 12 s. Adote g = 10 m/s². Se o rendimento do sistema é 75%, qual é a potência fornecida ao motor?","options":["750 W","1.000 W","1.333 W aproximadamente","16.000 W"],"answer":2,"explanation":"O trabalho útil é mgh = 200·10·6 = 12.000 J, logo a potência útil é 12.000/12 = 1.000 W. Como η = Pútil/Pfornecida = 0,75, Pfornecida = 1.000/0,75 ≈ 1.333 W.","difficulty":"avançada","sourceBasis":"https://estudante.ifpb.edu.br/media/cursos/82/disciplina/F%C3%ADsica_1%C2%BA_ano.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://estudante.ifpb.edu.br/media/cursos/82/disciplina/F%C3%ADsica_1%C2%BA_ano.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"encadear energia potencial, potência útil e rendimento","commonError":"Aplicar o rendimento à potência útil multiplicando em vez de dividir para encontrar a entrada.","whyWrong":"0 multiplica a potência útil por 0,75 e reduz indevidamente a entrada; 1 é a potência útil, não a fornecida; 3 confunde trabalho com potência e não divide pelo tempo.","reviewHint":"Calcule primeiro a saída útil por segundo; depois use η = saída/entrada para obter a potência de entrada.","contentId":"fis-energia"},{"id":"m45-fis-fluidos-01","subject":"Física","topic":"Fluidos","subtopic":"densidade","prompt":"Uma amostra homogênea tem massa de 1,2 kg e volume de 1,5 × 10⁻³ m³. Qual é sua densidade média?","options":["8,0 × 10² kg/m³","8,0 × 10⁻⁴ kg/m³","1,8 × 10³ kg/m³","2,7 × 10³ kg/m³"],"answer":0,"explanation":"Pela definição, ρ = m/V = 1,2/(1,5 × 10⁻³) = 8,0 × 10² kg/m³. A alternativa 1 resulta de uma conversão ou divisão inadequada; as alternativas 2 e 3 não correspondem à razão entre os dados.","difficulty":"intermediária","sourceBasis":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular densidade a partir de massa e volume com unidades do SI","commonError":"Dividir a massa pelo valor numérico do volume sem considerar a potência de dez.","whyWrong":"A alternativa 1 ignora que 1,5 × 10⁻³ é muito menor que 1,5; as alternativas 2 e 3 decorrem de multiplicações ou combinações indevidas de massa e volume.","reviewHint":"Escreva 1,5 × 10⁻³ no denominador e estime: dividir por um número menor que 1 deve produzir uma densidade maior que 1 kg/m³.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-02","subject":"Física","topic":"Fluidos","subtopic":"pressão absoluta e hidrostática","prompt":"Um ponto está 5,0 m abaixo da superfície livre de um óleo de densidade 800 kg/m³. Adote g = 10 m/s² e p_atm = 1,0 × 10⁵ Pa. Qual é a pressão absoluta no ponto?","options":["2,0 × 10⁴ Pa","1,0 × 10⁵ Pa","1,4 × 10⁵ Pa","1,8 × 10⁵ Pa"],"answer":2,"explanation":"A pressão manométrica é ρgh = 800 · 10 · 5 = 4,0 × 10⁴ Pa. Como a superfície é livre, a pressão absoluta é p_atm + ρgh = 1,0 × 10⁵ + 4,0 × 10⁴ = 1,4 × 10⁵ Pa.","difficulty":"avançada","sourceBasis":"https://wp.ufpel.edu.br/ciceroescobar/mecanica-dos-fluidos/ — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://wp.ufpel.edu.br/ciceroescobar/mecanica-dos-fluidos/ — calibração apenas; questão autoral/similar; não oficial.","skill":"distinguir pressão manométrica de pressão absoluta e aplicar Stevin","commonError":"Entregar apenas ρgh quando o enunciado solicita pressão absoluta.","whyWrong":"A alternativa 0 é somente a pressão manométrica; a 1 é apenas a atmosférica; a 3 soma uma parcela hidrostática incorreta, pois ρgh vale 4,0 × 10⁴ Pa.","reviewHint":"Pergunte primeiro qual pressão atua na superfície livre e depois some a coluna hidrostática, se a grandeza pedida for absoluta.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-03","subject":"Física","topic":"Fluidos","subtopic":"lei de Stevin","prompt":"Em água de densidade 1,0 × 10³ kg/m³, dois pontos estão a 1,2 m e 3,7 m abaixo da mesma superfície livre. Com g = 10 m/s², qual é a diferença entre as pressões manométricas?","options":["2,5 × 10³ Pa","2,5 × 10⁴ Pa","3,7 × 10⁴ Pa","4,9 × 10⁴ Pa"],"answer":1,"explanation":"A diferença de profundidade é 3,7 − 1,2 = 2,5 m. Logo, Δp = ρgΔh = 1000 · 10 · 2,5 = 2,5 × 10⁴ Pa. As pressões atmosféricas se cancelam ao comparar os dois pontos.","difficulty":"intermediária","sourceBasis":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"relacionar diferença de pressão à diferença de profundidade em líquido em repouso","commonError":"Usar a profundidade do ponto mais fundo em vez da diferença entre as profundidades.","whyWrong":"A alternativa 2 usa 3,7 m isoladamente; a 0 perde um fator 10; a 3 usa uma diferença que não existe no enunciado.","reviewHint":"Ao comparar dois pontos do mesmo líquido, escreva diretamente Δp = ρg(h₂ − h₁).","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-04","subject":"Física","topic":"Fluidos","subtopic":"princípio de Pascal","prompt":"Em uma prensa hidráulica ideal, o êmbolo menor tem área de 5,0 cm² e recebe força de 200 N. O êmbolo maior tem área de 40 cm². Qual força ideal ele exerce?","options":["25 N","160 N","800 N","1600 N"],"answer":3,"explanation":"Pelo princípio de Pascal, F₁/A₁ = F₂/A₂. Portanto, F₂ = 200 · (40/5) = 1600 N. A razão entre as áreas é 8, logo a força é multiplicada por 8.","difficulty":"intermediária","sourceBasis":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"aplicar igualdade de pressão em êmbolos de uma prensa hidráulica","commonError":"Multiplicar a força pela soma das áreas ou inverter a razão entre as áreas.","whyWrong":"As alternativas 0 e 1 não usam a razão 40/5; a 2 corresponde a multiplicar por 4, embora a área maior seja oito vezes a menor.","reviewHint":"Monte a proporção F₂/F₁ = A₂/A₁ antes de substituir os números.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-05","subject":"Física","topic":"Fluidos","subtopic":"pressão e manometria","prompt":"Um manômetro com água indica que a pressão no ponto A excede a pressão no ponto B por uma coluna equivalente de 0,45 m. Usando ρ = 1000 kg/m³ e g = 10 m/s², qual é p_A − p_B?","options":["45 Pa","450 Pa","4500 Pa","45 000 Pa"],"answer":2,"explanation":"A diferença de pressão representada por uma coluna de altura h é Δp = ρgh. Assim, Δp = 1000 · 10 · 0,45 = 4500 Pa, e o sinal é positivo porque o enunciado já informa que A tem pressão maior.","difficulty":"avançada","sourceBasis":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"interpretar uma diferença de nível em manômetro como diferença de pressão","commonError":"Ler 0,45 m como 45 cm sem converter ou esquecer o fator g.","whyWrong":"As alternativas 0 e 1 omitem fatores de escala; a 3 equivale a usar 4,5 m, dez vezes a altura indicada.","reviewHint":"Use a unidade final como teste: pressão deve sair em N/m², portanto ρg h precisa conservar todas as três parcelas.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-06","subject":"Física","topic":"Fluidos","subtopic":"empuxo","prompt":"Um cilindro de volume 0,004 m³ está totalmente imerso em água. Qual é o empuxo, adotando ρ_água = 1000 kg/m³ e g = 10 m/s²?","options":["4 N","25 N","40 N","400 N"],"answer":2,"explanation":"O volume deslocado é o volume total, pois o cilindro está totalmente imerso. Então E = ρ_f g V_deslocado = 1000 · 10 · 0,004 = 40 N.","difficulty":"intermediária","sourceBasis":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/lista-hidrostatica.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/lista-hidrostatica.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular empuxo pelo volume de fluido deslocado","commonError":"Usar a massa do cilindro ou seu peso para calcular diretamente o empuxo.","whyWrong":"O empuxo depende da densidade do fluido e do volume imerso; a alternativa 1 pode coincidir com um peso particular, mas o peso não foi fornecido.","reviewHint":"Identifique primeiro o fluido e o volume deslocado; só depois use E = ρ_f g V_submerso.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-07","subject":"Física","topic":"Fluidos","subtopic":"flutuação e densidade relativa","prompt":"Um bloco homogêneo flutua em um líquido de densidade 900 kg/m³ com 40% de seu volume submerso. Qual é a densidade do bloco?","options":["225 kg/m³","360 kg/m³","540 kg/m³","900 kg/m³"],"answer":1,"explanation":"Na flutuação, peso e empuxo se igualam. Logo, ρ_bloco V_total g = ρ_líquido (0,40 V_total) g, resultando em ρ_bloco = 0,40 · 900 = 360 kg/m³.","difficulty":"avançada","sourceBasis":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/lista-hidrostatica.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/lista-hidrostatica.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"deduzir a densidade de um corpo flutuante a partir da fração submersa","commonError":"Afirmar que a densidade do corpo é igual à do líquido sempre que há flutuação.","whyWrong":"Densidades iguais correspondem a equilíbrio totalmente imerso; aqui a fração submersa é 0,40, portanto a densidade do bloco é 40% da do líquido.","reviewHint":"Use V_submerso/V_total = ρ_corpo/ρ_fluido quando o corpo flutua em equilíbrio.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-08","subject":"Física","topic":"Fluidos","subtopic":"vazão volumétrica","prompt":"Uma mangueira fornece 18 litros de água em 30 s. Qual é a vazão média em m³/s?","options":["6,0 × 10⁻⁴ m³/s","6,0 × 10⁻³ m³/s","0,60 m³/s","540 m³/s"],"answer":0,"explanation":"Como 18 L = 0,018 m³, Q = ΔV/Δt = 0,018/30 = 0,0006 m³/s = 6,0 × 10⁻⁴ m³/s.","difficulty":"intermediária","sourceBasis":"https://www.ufrb.edu.br/pibid/documentos/category/59-hidrostatica-e-hidrodinamica?download=218:hidrodi — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ufrb.edu.br/pibid/documentos/category/59-hidrostatica-e-hidrodinamica?download=218:hidrodi — calibração apenas; questão autoral/similar; não oficial.","skill":"calcular vazão como volume escoado por unidade de tempo","commonError":"Usar 18 como se fosse volume em metros cúbicos ou multiplicar, em vez de dividir, pelo tempo.","whyWrong":"A alternativa 1 mantém a conversão errada de litros; a 2 ignora a conversão e o tempo; a 3 resulta de multiplicar volume e tempo.","reviewHint":"Lembre que 1 L = 10⁻³ m³ e que vazão tem dimensão volume dividido por tempo.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-09","subject":"Física","topic":"Fluidos","subtopic":"continuidade","prompt":"Em um tubo com líquido incompressível, a área da seção inicial é 8,0 cm² e a velocidade é 0,75 m/s. Se a seção seguinte tem 2,0 cm², qual é a velocidade nessa seção?","options":["0,19 m/s","0,75 m/s","1,50 m/s","3,0 m/s"],"answer":3,"explanation":"Pela continuidade, A₁v₁ = A₂v₂. Assim, v₂ = (8,0/2,0) · 0,75 = 3,0 m/s. A área foi reduzida a um quarto, então a velocidade quadruplica.","difficulty":"intermediária","sourceBasis":"https://www.ufrb.edu.br/pibid/documentos/category/59-hidrostatica-e-hidrodinamica?download=218:hidrodi — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ufrb.edu.br/pibid/documentos/category/59-hidrostatica-e-hidrodinamica?download=218:hidrodi — calibração apenas; questão autoral/similar; não oficial.","skill":"usar a conservação da vazão em duas seções de um tubo","commonError":"Concluir que a velocidade diminui porque a área diminuiu.","whyWrong":"Para líquido incompressível, a mesma vazão atravessa as seções; uma seção menor exige velocidade maior, não menor.","reviewHint":"Reorganize a equação como v₂ = (A₁/A₂)v₁ e observe se a razão das áreas é maior ou menor que 1.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-10","subject":"Física","topic":"Fluidos","subtopic":"Bernoulli em tubo horizontal","prompt":"Em um tubo horizontal com água ideal, a velocidade passa de 2,0 m/s no ponto 1 para 8,0 m/s no ponto 2. Se p₁ = 2,00 × 10⁵ Pa, qual é p₂? Adote ρ = 1000 kg/m³.","options":["1,40 × 10⁵ Pa","1,70 × 10⁵ Pa","2,30 × 10⁵ Pa","2,60 × 10⁵ Pa"],"answer":1,"explanation":"Como o tubo é horizontal, Bernoulli dá p₁ + ½ρv₁² = p₂ + ½ρv₂². Então p₂ = 200000 + 500(4 − 64) = 170000 Pa. A maior velocidade no ponto 2 vem acompanhada de menor pressão estática.","difficulty":"avançada","sourceBasis":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"aplicar Bernoulli eliminando o termo de altura em tubulação horizontal","commonError":"Somar a contribuição cinética ao passar para o ponto de maior velocidade.","whyWrong":"Na forma rearranjada, a pressão diminui quando a energia cinética por volume aumenta; as alternativas 2 e 3 fazem a variação ter sinal errado.","reviewHint":"Escreva os quatro termos antes de cancelar as alturas e mantenha a ordem p₂ = p₁ + termo cinético 1 − termo cinético 2.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-11","subject":"Física","topic":"Fluidos","subtopic":"Torricelli e escoamento por orifício","prompt":"Um reservatório aberto possui um pequeno orifício 1,8 m abaixo da superfície da água. No modelo ideal, com g = 10 m/s², qual é a velocidade de saída?","options":["3,0 m/s","4,5 m/s","6,0 m/s","18 m/s"],"answer":2,"explanation":"Pela lei de Torricelli, v = √(2gh) = √(2 · 10 · 1,8) = √36 = 6,0 m/s. O modelo considera reservatório grande, orifício pequeno, pressões atmosféricas iguais e perdas desprezíveis.","difficulty":"avançada","sourceBasis":"https://www.ufrb.edu.br/pibid/documentos/category/59-hidrostatica-e-hidrodinamica?download=218:hidrodi — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ufrb.edu.br/pibid/documentos/category/59-hidrostatica-e-hidrodinamica?download=218:hidrodi — calibração apenas; questão autoral/similar; não oficial.","skill":"obter a velocidade ideal de saída usando a equação de Torricelli","commonError":"Usar v = 2gh sem extrair a raiz quadrada ou esquecer o fator 2.","whyWrong":"A alternativa 3 é 2gh sem raiz; as alternativas 0 e 1 não satisfazem √36 e não preservam a relação quadrática entre velocidade e altura.","reviewHint":"Torricelli é a forma de Bernoulli v = √(2gh), não uma relação linear entre v e h.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-12","subject":"Física","topic":"Fluidos","subtopic":"continuidade e Bernoulli","prompt":"Em uma tubulação horizontal ideal, a área da seção 2 é um quarto da área da seção 1. Em 1, v₁ = 1,5 m/s e p₁ = 1,80 × 10⁵ Pa. Para água com ρ = 1000 kg/m³, qual é a pressão em 2?","options":["1,63125 × 10⁵ Pa","1,96875 × 10⁵ Pa","1,6875 × 10⁴ Pa","1,80 × 10⁵ Pa"],"answer":0,"explanation":"A continuidade fornece v₂ = 4v₁ = 6,0 m/s. Bernoulli horizontal dá p₂ = p₁ + ½ρ(v₁² − v₂²) = 180000 + 500(2,25 − 36) = 163125 Pa.","difficulty":"avançada","sourceBasis":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"encadear continuidade e Bernoulli em um estreitamento horizontal","commonError":"Aplicar Bernoulli antes de determinar a velocidade na segunda seção.","whyWrong":"Sem v₂, não se conhece o termo cinético do ponto 2; a alternativa 1 soma, em vez de subtrair, o aumento da energia cinética.","reviewHint":"Resolva em duas etapas: primeiro A₁v₁ = A₂v₂; depois substitua as velocidades em Bernoulli.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-13","subject":"Física","topic":"Fluidos","subtopic":"Bernoulli e perdas de carga","prompt":"Em uma tubulação real, horizontal e sem bomba, o escoamento percorre um trecho longo com viscosidade significativa. Qual afirmação é compatível com esse modelo?","options":["A soma p + ½ρv² permanece constante exatamente, pois o tubo é horizontal.","A energia mecânica por unidade de volume pode diminuir no sentido do escoamento por perdas viscosas.","A pressão necessariamente aumenta, porque toda viscosidade produz empuxo.","A densidade do líquido deve aumentar continuamente para compensar o atrito."],"answer":1,"explanation":"A forma ideal de Bernoulli não inclui dissipação. Em um escoamento real, o atrito transforma parte da energia mecânica em energia interna, de modo que a carga disponível pode diminuir mesmo em tubo horizontal. Isso não é empuxo nem exige variação de densidade.","difficulty":"avançada","sourceBasis":"https://www.ufrb.edu.br/pibid/documentos/category/59-hidrostatica-e-hidrodinamica?download=218:hidrodi — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ufrb.edu.br/pibid/documentos/category/59-hidrostatica-e-hidrodinamica?download=218:hidrodi — calibração apenas; questão autoral/similar; não oficial.","skill":"reconhecer os limites de validade de Bernoulli ideal em escoamentos reais","commonError":"Tratar a constante de Bernoulli ideal como uma conservação sem perdas em qualquer fluido.","whyWrong":"A alternativa 0 ignora a viscosidade; a 2 confunde atrito com empuxo; a 3 inventa uma variação de densidade que não é necessária para líquido incompressível.","reviewHint":"Antes de usar Bernoulli, procure no enunciado viscosidade, trecho longo, bomba ou perda de carga.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-14","subject":"Física","topic":"Fluidos","subtopic":"pressão em mesma profundidade","prompt":"Dois pontos estão na mesma profundidade, no mesmo líquido em repouso e sob a mesma pressão atmosférica. Um deles pertence a um recipiente largo e o outro a um tubo estreito. Como se comparam suas pressões?","options":["São iguais, pois a pressão hidrostática depende da densidade, de g e da profundidade.","A do recipiente largo é maior, pois ele contém mais líquido.","A do tubo estreito é maior, pois a coluna é mais comprimida lateralmente.","Não é possível comparar sem conhecer o formato completo dos recipientes."],"answer":0,"explanation":"Pela lei de Stevin, p = p₀ + ρgh. Com o mesmo líquido, a mesma pressão na superfície e a mesma profundidade, as pressões são iguais, independentemente da largura ou do formato do recipiente.","difficulty":"intermediária","sourceBasis":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/Fluidos.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"interpretar a dependência da pressão hidrostática sem se deixar levar pelo formato do recipiente","commonError":"Confundir força total sobre o fundo com pressão em um ponto.","whyWrong":"A quantidade total de líquido pode alterar a força resultante em uma área, mas não altera a pressão local determinada por ρgh nas condições dadas.","reviewHint":"Separe as grandezas: pressão é força por área e, na hidrostática, a pressão local é função da profundidade.","contentId":"fis-fluidos"},{"id":"m45-fis-fluidos-15","subject":"Física","topic":"Fluidos","subtopic":"equilíbrio com empuxo e força externa","prompt":"Um objeto de peso 90 N e volume 0,008 m³ permanece totalmente submerso em água. Com ρ_água = 1000 kg/m³ e g = 10 m/s², que força vertical adicional, além do peso, deve ser aplicada para mantê-lo em equilíbrio?","options":["10 N para cima","10 N para baixo","80 N para cima","170 N para baixo"],"answer":0,"explanation":"O empuxo vale E = 1000 · 10 · 0,008 = 80 N para cima, enquanto o peso é 90 N para baixo. Sobra uma resultante de 10 N para baixo; portanto, é necessária uma força adicional de 10 N para cima para zerar a resultante.","difficulty":"avançada","sourceBasis":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/lista-hidrostatica.pdf — calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://www.ifsc.usp.br/~hoyos/courses/2024/SLC0628/lista-hidrostatica.pdf — calibração apenas; questão autoral/similar; não oficial.","skill":"combinar empuxo, peso e equilíbrio de forças em corpo totalmente imerso","commonError":"Escolher o sentido da força externa pelo sentido do empuxo, sem calcular a resultante.","whyWrong":"Como o peso excede o empuxo em 10 N, o corpo tenderia a descer; a força externa deve ser para cima. A alternativa 1 reforçaria o movimento para baixo, e as alternativas 2 e 3 têm módulo ou sentido incompatível com o equilíbrio.","reviewHint":"Some vetorialmente: empuxo é 80 N para cima e peso é 90 N para baixo; a força externa deve apontar contra a resultante residual.","contentId":"fis-fluidos"},{"id":"m45-fis-ondas-01","subject":"Física","topic":"Ondas e óptica","subtopic":"classificação de ondas","prompt":"Qual afirmação classifica corretamente as ondas?","options":["A luz é uma onda mecânica e precisa de ar para se propagar.","O som no ar é uma onda mecânica longitudinal e a luz pode ser eletromagnética.","Toda onda transporta matéria de um ponto ao outro sem exceção.","Ondas eletromagnéticas só podem existir no interior de sólidos."],"answer":1,"explanation":"O som depende de um meio material e, no ar, as oscilações são predominantemente longitudinais. A luz é eletromagnética e pode propagar-se no vácuo. Uma onda transporta energia e informação, mas não há transporte permanente de matéria como um todo.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufsm.br/handle/1/18388 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufsm.br/handle/1/18388 (calibração apenas; questão autoral/similar; não oficial).","skill":"distinguir ondas mecânicas e eletromagnéticas e reconhecer a direção de vibração","commonError":"Tratar toda onda como transporte de matéria ou supor que a luz exige ar.","whyWrong":"0 confunde luz com som; 2 contradiz o conceito de transporte de energia sem transporte permanente de matéria; 3 ignora a propagação eletromagnética no vácuo.","reviewHint":"Pergunte se há necessidade de meio material e se a vibração é paralela ou perpendicular à propagação.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-02","subject":"Física","topic":"Ondas e óptica","subtopic":"frequência, período, comprimento de onda e velocidade","prompt":"Uma onda periódica tem frequência de 5,0 Hz e comprimento de onda de 0,80 m. Qual é o par correto formado por seu período e sua velocidade de propagação?","options":["T = 5,0 s e v = 0,16 m/s","T = 0,80 s e v = 6,25 m/s","T = 0,20 s e v = 4,0 m/s","T = 4,0 s e v = 0,20 m/s"],"answer":2,"explanation":"O período é o inverso da frequência: T = 1/5,0 = 0,20 s. A velocidade é v = λf = 0,80 × 5,0 = 4,0 m/s.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufsm.br/handle/1/18388 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufsm.br/handle/1/18388 (calibração apenas; questão autoral/similar; não oficial).","skill":"relacionar frequência, período, comprimento de onda e velocidade","commonError":"Usar T = f ou dividir o comprimento de onda pela frequência.","whyWrong":"O período é inversamente proporcional à frequência, enquanto v = λf; as alternativas 0, 1 e 3 trocam essas relações ou as unidades.","reviewHint":"Escreva primeiro T = 1/f e depois v = λf, conferindo as unidades em segundos e metros por segundo.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-03","subject":"Física","topic":"Ondas e óptica","subtopic":"som e batimentos","prompt":"Duas fontes sonoras emitem simultaneamente frequências de 256 Hz e 260 Hz. Qual frequência de batimento será percebida, idealmente?","options":["4 Hz","256 Hz","260 Hz","516 Hz"],"answer":0,"explanation":"A frequência de batimento é o módulo da diferença entre as frequências: f_b = |260 − 256| = 4 Hz. Esse valor indica a taxa de variação da intensidade resultante, não substitui as frequências das fontes.","difficulty":"intermediária","sourceBasis":"https://repositorio.ufsm.br/handle/1/18388 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufsm.br/handle/1/18388 (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar superposição a fontes de frequências próximas","commonError":"Somar as frequências ou confundir a taxa de batimentos com a altura do som.","whyWrong":"A soma não representa batimentos, e 256 Hz ou 260 Hz são as frequências individuais, não a frequência de variação da intensidade.","reviewHint":"Para batimentos, use sempre o módulo da diferença entre as frequências próximas.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-04","subject":"Física","topic":"Ondas e óptica","subtopic":"reflexão da luz","prompt":"Um raio incide em um espelho plano formando 35° com a normal. Qual é o ângulo entre o raio incidente e o raio refletido?","options":["35°","55°","70°","145°"],"answer":2,"explanation":"Pela lei da reflexão, o ângulo de reflexão também é 35° em relação à normal. Os dois raios ficam em lados opostos da normal, portanto o ângulo entre eles é 35° + 35° = 70°.","difficulty":"intermediária","sourceBasis":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"usar a lei da reflexão com ângulos medidos em relação à normal","commonError":"Medir o ângulo a partir da superfície ou responder apenas com o ângulo de reflexão.","whyWrong":"O enunciado fornece o ângulo com a normal, e pede o ângulo entre os raios; são duas parcelas iguais, não uma só.","reviewHint":"Desenhe a normal e marque um ângulo igual de cada lado antes de somar.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-05","subject":"Física","topic":"Ondas e óptica","subtopic":"refração e lei de Snell","prompt":"Um raio passa do ar, de índice 1,0, para um vidro de índice 1,5, incidindo a 30° da normal. Qual é aproximadamente o ângulo refratado?","options":["30,0°","19,5°","45,0°","60,0°"],"answer":1,"explanation":"Pela lei de Snell, 1,0 sen 30° = 1,5 sen r. Assim, sen r = 1/3 e r ≈ 19,5°. A luz entra em meio de maior índice e se aproxima da normal.","difficulty":"intermediária","sourceBasis":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"aplicar a lei de Snell e interpretar a mudança de direção","commonError":"Conservar o ângulo ou usar cosseno em vez de seno.","whyWrong":"A passagem para índice maior altera o ângulo, e a lei de Snell usa o seno dos ângulos medidos a partir da normal.","reviewHint":"Escreva n1 sen i = n2 sen r e verifique se o raio se aproxima ou se afasta da normal.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-06","subject":"Física","topic":"Ondas e óptica","subtopic":"espelho plano","prompt":"Um objeto está a 2,5 m diante de um espelho plano. Qual é a distância entre o objeto e sua imagem?","options":["2,5 m","1,25 m","3,0 m","5,0 m"],"answer":3,"explanation":"A imagem virtual fica 2,5 m atrás do espelho, simétrica à posição do objeto. A distância total entre objeto e imagem é 2,5 + 2,5 = 5,0 m.","difficulty":"intermediária","sourceBasis":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"determinar a posição de imagem em espelho plano","commonError":"Tomar a distância do objeto ao espelho como a distância objeto-imagem.","whyWrong":"A imagem está atrás do espelho e a pergunta mede de um ponto ao outro, atravessando o plano refletor.","reviewHint":"Represente o espelho como uma linha: marque 2,5 m de cada lado.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-07","subject":"Física","topic":"Ondas e óptica","subtopic":"espelho esférico","prompt":"Um espelho côncavo tem distância focal de 20 cm e recebe um objeto real a 60 cm do vértice. Qual é a posição e a ampliação linear da imagem, usando a convenção usual para espelhos?","options":["p' = 15 cm e m = −4","p' = 30 cm e m = −0,5","p' = 60 cm e m = +1","p' = −30 cm e m = +0,5"],"answer":1,"explanation":"Pela equação 1/f = 1/p + 1/p', 1/p' = 1/20 − 1/60 = 1/30, logo p' = 30 cm. A ampliação é m = −p'/p = −30/60 = −0,5: imagem real, invertida e reduzida à metade.","difficulty":"intermediária","sourceBasis":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"resolver formação de imagem por espelho côncavo e interpretar a ampliação","commonError":"Esquecer o sinal negativo da ampliação ou trocar p por f na equação.","whyWrong":"A posição é obtida isolando p' após inserir f e p; o sinal de m indica inversão, enquanto seu módulo indica redução.","reviewHint":"Calcule p' primeiro e só então use m = −p'/p para interpretar a imagem.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-08","subject":"Física","topic":"Ondas e óptica","subtopic":"efeito Doppler","prompt":"Uma fonte sonora de 500 Hz aproxima-se de um observador parado a 20 m/s. Adotando velocidade do som de 340 m/s, qual frequência aproximada o observador percebe?","options":["468,75 Hz","500,00 Hz","531,25 Hz","520,00 Hz"],"answer":2,"explanation":"Para fonte que se aproxima de observador parado, f' = f v/(v − v_s). Logo f' = 500 × 340/(340 − 20) = 531,25 Hz. A frequência percebida aumenta na aproximação.","difficulty":"avançada","sourceBasis":"https://repositorio.ufsm.br/handle/1/18388 (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.ufsm.br/handle/1/18388 (calibração apenas; questão autoral/similar; não oficial).","skill":"selecionar a expressão adequada do efeito Doppler para fonte móvel","commonError":"Usar v + v_s no denominador quando a fonte se aproxima ou alterar a frequência emitida.","whyWrong":"Na aproximação da fonte, as frentes chegam mais próximas e o denominador correto é v − v_s; a fonte continua emitindo 500 Hz.","reviewHint":"Identifique quem se move: fonte no denominador, observador no numerador, respeitando o sinal da aproximação.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-09","subject":"Física","topic":"Ondas e óptica","subtopic":"mudança de meio","prompt":"Quando uma onda luminosa passa do ar para um vidro transparente em repouso, qual conjunto de alterações é correto?","options":["A frequência permanece, a velocidade diminui e o comprimento de onda diminui.","A frequência diminui, a velocidade permanece igual e o comprimento aumenta.","A frequência aumenta, a velocidade aumenta e o comprimento permanece.","Frequência, velocidade e comprimento de onda permanecem sempre iguais."],"answer":0,"explanation":"A frequência é determinada pela fonte e permanece contínua na interface. Como o vidro tem maior índice, a velocidade da luz diminui; de λ = v/f, o comprimento de onda também diminui.","difficulty":"avançada","sourceBasis":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"relacionar índice de refração, velocidade, frequência e comprimento de onda","commonError":"Supor que a frequência sempre muda porque o comprimento de onda muda.","whyWrong":"Na interface, a fonte não muda seu ritmo; a alteração de velocidade é compensada por alteração de λ para manter v = λf.","reviewHint":"Use simultaneamente n = c/v e v = λf; conserve f antes de recalcular λ.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-10","subject":"Física","topic":"Ondas e óptica","subtopic":"reflexão interna total","prompt":"Um raio viaja no vidro, de índice 1,5, em direção ao ar, de índice 1,0. Se o ângulo de incidência é 50° em relação à normal, o que ocorre?","options":["Há refração para o ar, aproximando-se da normal.","Há refração para o ar com ângulo menor que 50°.","Ocorre reflexão interna total, pois 50° supera o ângulo crítico aproximado de 41,8°.","Não há reflexão porque o ar tem índice menor."],"answer":2,"explanation":"Como a luz vai do índice maior para o menor, pode ocorrer reflexão interna total. O ângulo crítico satisfaz sen θc = 1,0/1,5, dando θc ≈ 41,8°. Como 50° é maior, não há raio refratado idealmente.","difficulty":"avançada","sourceBasis":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"verificar direção, ângulo crítico e condição de reflexão interna total","commonError":"Aplicar reflexão interna total quando a luz vai do ar para o vidro ou comparar com a superfície.","whyWrong":"A condição exige passagem do maior para o menor índice e incidência acima do crítico, com ângulos medidos da normal.","reviewHint":"Calcule primeiro sen θc = n_menor/n_maior e só depois compare o ângulo informado.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-11","subject":"Física","topic":"Ondas e óptica","subtopic":"espelho convexo e sinais","prompt":"Um espelho convexo tem foco f = −20 cm e recebe um objeto real a p = 30 cm. Pela equação de Gauss, quais são aproximadamente a posição e a ampliação da imagem?","options":["p' = +12 cm e m = −0,4, imagem real e invertida","p' = −12 cm e m = +0,4, imagem virtual, direita e reduzida","p' = +60 cm e m = −2,0, imagem real e ampliada","p' = −60 cm e m = −2,0, imagem virtual e invertida"],"answer":1,"explanation":"De 1/f = 1/p + 1/p', resulta −1/20 = 1/30 + 1/p', portanto p' = −12 cm. Assim, m = −p'/p = +12/30 = +0,4. O sinal de p' indica imagem virtual e o de m, direita; o módulo menor que 1 indica redução.","difficulty":"avançada","sourceBasis":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"http://fisica.ufpr.br/celso/FundOptica.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"interpretar sinais e natureza da imagem em espelho convexo","commonError":"Forçar p' positivo ou concluir que todo espelho forma imagem real.","whyWrong":"No modelo usual, o espelho convexo tem foco negativo e, para objeto real, a imagem fica virtual, direita e menor.","reviewHint":"Não interprete o sinal antes de terminar a equação; depois use p' e m para classificar a imagem.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-12","subject":"Física","topic":"Ondas e óptica","subtopic":"lente convergente","prompt":"Uma lente convergente delgada tem f = 12 cm e um objeto real está a p = 18 cm. Qual é a descrição correta da imagem?","options":["p' = 36 cm, real, invertida e duas vezes maior.","p' = −36 cm, virtual, direita e duas vezes maior.","p' = 6 cm, real, direita e reduzida.","p' = −6 cm, virtual, invertida e reduzida."],"answer":0,"explanation":"A equação fornece 1/p' = 1/12 − 1/18 = 1/36, logo p' = 36 cm. A ampliação é m = −36/18 = −2: imagem real, invertida e com o dobro da altura. Isso também concorda com objeto entre f e 2f.","difficulty":"avançada","sourceBasis":"https://www.if.ufrj.br/~marta/int-fis/icf-mod1-cap5.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www.if.ufrj.br/~marta/int-fis/icf-mod1-cap5.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular posição e ampliação em lente convergente","commonError":"Aplicar a regra qualitativa de objeto além de 2f a um objeto que está entre f e 2f.","whyWrong":"18 cm está entre 12 cm e 24 cm; nessa faixa a imagem é real, invertida e maior, exatamente como os sinais calculados.","reviewHint":"Compare p com f e 2f antes da conta e use o sinal de m para confirmar a orientação.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-13","subject":"Física","topic":"Ondas e óptica","subtopic":"lupa e ampliação angular","prompt":"Uma lupa tem distância focal de 5,0 cm e é usada com o olho relaxado. Adotando ponto próximo D = 25 cm, qual é sua ampliação angular aproximada?","options":["0,20","4,0","25","5,0"],"answer":3,"explanation":"Para uma lupa com imagem final no infinito, M ≈ D/f. Assim, M ≈ 25/5,0 = 5,0. A aproximação pressupõe f muito menor que a distância de referência e olho relaxado.","difficulty":"avançada","sourceBasis":"https://www.if.ufrj.br/~marta/int-fis/icf-mod1-cap5.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www.if.ufrj.br/~marta/int-fis/icf-mod1-cap5.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"distinguir ampliação angular de ampliação linear em uma lupa","commonError":"Usar f/D ou tratar a ampliação da lupa como tamanho da imagem em uma lente formadora.","whyWrong":"A lupa é avaliada pelo ângulo aparente e, no ajuste para olho relaxado, a relação é D/f; o resultado não é uma distância.","reviewHint":"Verifique se o enunciado pede aumento angular e identifique o estado de acomodação do olho.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-14","subject":"Física","topic":"Ondas e óptica","subtopic":"luneta astronômica","prompt":"Uma luneta astronômica é ajustada para imagem final no infinito. Sua objetiva tem f_obj = 100 cm e sua ocular f_oc = 5 cm. Qual é a ampliação angular em módulo e a orientação usual da imagem?","options":["5 vezes e direita","20 vezes e direita","20 vezes e invertida","95 vezes e invertida"],"answer":2,"explanation":"No ajuste normal, |M| = f_obj/f_oc = 100/5 = 20. A luneta astronômica formada por duas lentes convergentes produz, no modelo usual, imagem invertida; por isso a alternativa correta é 20 vezes e invertida.","difficulty":"avançada","sourceBasis":"https://www.if.ufrj.br/~marta/int-fis/icf-mod1-cap5.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://www.if.ufrj.br/~marta/int-fis/icf-mod1-cap5.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"calcular ampliação angular de luneta e reconhecer a inversão","commonError":"Subtrair as distâncias focais ou esquecer que a razão usa objetiva sobre ocular.","whyWrong":"A ampliação normal é uma razão de focos, 100/5, e o arranjo astronômico de duas lentes convergentes inverte a imagem.","reviewHint":"Separe módulo do aumento (razão dos focos) da orientação, determinada pelo sistema de lentes.","contentId":"fis-ondas"},{"id":"m45-fis-ondas-15","subject":"Física","topic":"Ondas e óptica","subtopic":"microscópio composto","prompt":"Sobre um microscópio composto, qual descrição é compatível com o modelo de lentes convergentes?","options":["A objetiva é divergente e produz diretamente uma imagem virtual menor; a ocular não altera o ângulo.","A objetiva convergente forma uma imagem intermediária real, invertida e ampliada; a ocular atua como lupa para produzir a imagem final virtual.","As duas lentes devem ser divergentes e formar duas imagens reais para o olho.","A objetiva apenas reflete a luz, enquanto a ocular funciona como espelho plano."],"answer":1,"explanation":"No microscópio composto, a objetiva convergente forma uma imagem intermediária real, invertida e ampliada. A ocular recebe essa imagem como objeto e fornece ampliação angular adicional, normalmente formando uma imagem final virtual para observação.","difficulty":"avançada","sourceBasis":"https://repositorio.utfpr.edu.br/jspui/handle/1/33920 (calibração apenas; questão autoral/similar; não oficial) + https://www.if.ufrj.br/~marta/int-fis/icf-mod1-cap5.pdf (calibração apenas; questão autoral/similar; não oficial).","origin":"autoral/similar","source":"https://repositorio.utfpr.edu.br/jspui/handle/1/33920 (calibração apenas; questão autoral/similar; não oficial) + https://www.if.ufrj.br/~marta/int-fis/icf-mod1-cap5.pdf (calibração apenas; questão autoral/similar; não oficial).","skill":"encadear formação de imagem em instrumentos ópticos","commonError":"Descrever o microscópio como uma única lente ou confundir imagem intermediária com imagem final observada.","whyWrong":"O instrumento opera em duas etapas: a objetiva forma uma imagem real intermediária, e a ocular amplia angularmente essa imagem como uma lupa.","reviewHint":"Analise o caminho em sequência: objeto, objetiva, imagem intermediária, ocular e imagem final.","contentId":"fis-ondas"},{"id":"m45-fis-termica-01","subject":"Física","topic":"Calor e termodinâmica","subtopic":"escalas termométricas","prompt":"Um termômetro indica 77 °F. Considerando θC = 5(θF − 32)/9 e T = θC + 273,15, quais são aproximadamente as leituras em Celsius e em kelvin?","options":["25 °C e 248,15 K","35 °C e 308,15 K","25 °C e 298,15 K","45 °C e 318,15 K"],"answer":2,"explanation":"A conversão dá θC = 5(77 − 32)/9 = 25 °C. Somando 273,15, obtém-se T = 298,15 K. A alternativa 0 erra ao subtrair 25 de 273,15; as demais usam conversões incorretas.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/012016/d4b99c5451211f0f5f7a50379bc79a0f.pdf; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/d4b99c5451211f0f5f7a50379bc79a0f.pdf; calibração apenas; questão autoral/similar; não oficial.","skill":"converter temperaturas entre Celsius, Fahrenheit e kelvin","commonError":"Aplicar a mesma origem ou a mesma razão de escala às escalas Celsius e Fahrenheit.","whyWrong":"0 confunde a conversão absoluta; 1 e 3 produzem valores Celsius incompatíveis com 77 °F por não subtrair 32 ou usar a razão 5/9.","reviewHint":"Primeiro elimine o deslocamento 32 da escala Fahrenheit; depois aplique 5/9 e só então some 273,15.","contentId":"fis-termica"},{"id":"m45-fis-termica-02","subject":"Física","topic":"Calor e termodinâmica","subtopic":"Lei Zero e equilíbrio térmico","prompt":"O termômetro C está em equilíbrio térmico com o bloco A e também com o bloco B, quando cada contato é feito separadamente. O que se conclui, idealmente, sobre A e B?","options":["A e B têm a mesma temperatura e não trocariam calor líquido ao serem postos em contato.","A tem necessariamente o dobro da energia interna de B.","A e B possuem necessariamente a mesma massa e o mesmo calor específico.","A e B só podem entrar em equilíbrio se o termômetro for retirado do sistema."],"answer":0,"explanation":"A Lei Zero estabelece a transitividade do equilíbrio térmico: se A e B estão em equilíbrio com C, têm a mesma temperatura entre si. Isso não informa massa, calor específico ou energia interna total.","difficulty":"intermediária","sourceBasis":"https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_9B__Waves_Sound_Optics_Thermodynamics_and_Fluids/05%3A_Fundamentals_of_Thermodynamics; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_9B__Waves_Sound_Optics_Thermodynamics_and_Fluids/05%3A_Fundamentals_of_Thermodynamics; calibração apenas; questão autoral/similar; não oficial.","skill":"aplicar a Lei Zero ao conceito de equilíbrio térmico","commonError":"Confundir temperatura, que é uma variável de estado, com energia interna total.","whyWrong":"1, 2 e 3 introduzem informações sobre energia, massa ou procedimento que não decorrem da Lei Zero; apenas a igualdade de temperatura é garantida.","reviewHint":"Pergunte exatamente o que o equilíbrio mede: a ausência de troca líquida de calor, não a igualdade de todas as propriedades do corpo.","contentId":"fis-termica"},{"id":"m45-fis-termica-03","subject":"Física","topic":"Calor e termodinâmica","subtopic":"dilatação linear","prompt":"Uma barra de 2,0 m tem coeficiente de dilatação linear 1,0 × 10⁻⁵ K⁻¹. Se sua temperatura aumenta 50 K, qual é a variação aproximada de comprimento?","options":["0,010 mm","0,10 mm","1,0 mm","10 mm"],"answer":2,"explanation":"Usa-se ΔL = L0αΔT. Logo, ΔL = 2,0 × 1,0×10⁻⁵ × 50 = 1,0×10⁻³ m = 1,0 mm.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/012016/d4b99c5451211f0f5f7a50379bc79a0f.pdf; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/d4b99c5451211f0f5f7a50379bc79a0f.pdf; calibração apenas; questão autoral/similar; não oficial.","skill":"calcular dilatação linear em aproximação de pequenas variações","commonError":"Esquecer que o coeficiente é muito menor que 1 e perder uma potência de dez na conversão para milímetros.","whyWrong":"0 e 1 resultam de fatores 100 ou 10 menores; 3 resulta de aumentar uma ordem de grandeza ao converter 10⁻³ m para mm.","reviewHint":"Faça primeiro o cálculo em metros e só depois use 1 m = 1000 mm.","contentId":"fis-termica"},{"id":"m45-fis-termica-04","subject":"Física","topic":"Calor e termodinâmica","subtopic":"calorimetria e equilíbrio térmico","prompt":"Em um recipiente isolado, misturam-se 200 g de água a 80 °C com 300 g de água a 20 °C. Desprezando o calor do recipiente, a temperatura final é:","options":["32 °C","44 °C","50 °C","60 °C"],"answer":1,"explanation":"Como o líquido é o mesmo, o calor específico cancela no balanço: 200(80 − Tf) = 300(Tf − 20). Assim, 16 000 − 200Tf = 300Tf − 6 000, portanto Tf = 44 °C.","difficulty":"intermediária","sourceBasis":"https://canal.cecierj.edu.br/012016/d4b99c5451211f0f5f7a50379bc79a0f.pdf; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/d4b99c5451211f0f5f7a50379bc79a0f.pdf; calibração apenas; questão autoral/similar; não oficial.","skill":"resolver balanço de calor em mistura sem perdas","commonError":"Fazer média aritmética das temperaturas sem ponderar as massas.","whyWrong":"0, 2 e 3 ignoram que a massa de água fria é maior; a temperatura final deve ficar mais próxima de 20 °C do que de 80 °C.","reviewHint":"Escreva calor perdido pelo corpo quente igual a calor recebido pelo corpo frio e confira se o resultado está entre as temperaturas iniciais.","contentId":"fis-termica"},{"id":"m45-fis-termica-05","subject":"Física","topic":"Calor e termodinâmica","subtopic":"calor latente","prompt":"Uma amostra de gelo a 0 °C recebe 33,4 kJ. Usando calor latente de fusão igual a 334 J/g e desprezando perdas, qual massa de gelo derrete?","options":["10 g","50 g","100 g","1 000 g"],"answer":2,"explanation":"No patamar de fusão, Q = mL. Como 33,4 kJ = 33 400 J, m = 33 400/334 = 100 g. Não há variação de temperatura a ser usada em mcΔT.","difficulty":"intermediária","sourceBasis":"https://phys.libretexts.org/Courses/Georgia_State_University/GSU-TM-Physics_I_(2211)/12%3A_Temperature_and_Heat; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Courses/Georgia_State_University/GSU-TM-Physics_I_(2211)/12%3A_Temperature_and_Heat; calibração apenas; questão autoral/similar; não oficial.","skill":"aplicar calor latente em uma mudança de fase","commonError":"Usar Q = mcΔT durante o derretimento, embora a temperatura permaneça constante.","whyWrong":"0, 1 e 3 correspondem a divisões por fatores inadequados; o processo descrito é uma mudança de fase e exige Q=mL.","reviewHint":"Identifique o estado inicial, o estado final e se há patamar de temperatura constante antes de escolher a fórmula.","contentId":"fis-termica"},{"id":"m45-fis-termica-06","subject":"Física","topic":"Calor e termodinâmica","subtopic":"gás ideal e transformação isovolumétrica","prompt":"Uma quantidade fixa de gás ideal está em volume constante, a 100 kPa e 300 K. Se a temperatura passa a 450 K, qual é a nova pressão?","options":["66,7 kPa","100 kPa","150 kPa","450 kPa"],"answer":2,"explanation":"Com volume e quantidade constantes, P/T é constante. Assim, P2 = 100 × 450/300 = 150 kPa.","difficulty":"intermediária","sourceBasis":"https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_9B__Waves_Sound_Optics_Thermodynamics_and_Fluids/05%3A_Fundamentals_of_Thermodynamics; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_9B__Waves_Sound_Optics_Thermodynamics_and_Fluids/05%3A_Fundamentals_of_Thermodynamics; calibração apenas; questão autoral/similar; não oficial.","skill":"usar a lei combinada dos gases em transformação isovolumétrica","commonError":"Tratar a temperatura Celsius como proporcional à pressão ou esquecer que o volume permanece constante.","whyWrong":"0 inverte a razão de temperaturas; 1 supõe pressão constante; 3 multiplica pela temperatura absoluta sem dividir pela inicial.","reviewHint":"Liste as grandezas constantes antes de escrever a relação entre os dois estados.","contentId":"fis-termica"},{"id":"m45-fis-termica-07","subject":"Física","topic":"Calor e termodinâmica","subtopic":"gases e transformações","prompt":"Um gás ideal ocupa 2,0 L a 300 K. Ele é aquecido sob pressão constante até 450 K. Qual será seu volume?","options":["1,33 L","2,0 L","2,5 L","3,0 L"],"answer":3,"explanation":"Em processo isobárico, V/T é constante. Portanto V2 = 2,0 × 450/300 = 3,0 L.","difficulty":"intermediária","sourceBasis":"https://phys.libretexts.org/Courses/Georgia_State_University/GSU-TM-Physics_I_(2211)/12%3A_Temperature_and_Heat; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Courses/Georgia_State_University/GSU-TM-Physics_I_(2211)/12%3A_Temperature_and_Heat; calibração apenas; questão autoral/similar; não oficial.","skill":"relacionar volume e temperatura em transformação isobárica","commonError":"Usar a diferença de temperaturas ou supor que o volume varie linearmente com Celsius a partir do zero da escala.","whyWrong":"0 divide em vez de multiplicar pela razão T2/T1; 1 e 2 não preservam a proporcionalidade direta entre volume e temperatura absoluta.","reviewHint":"Use kelvin e a razão V2/V1=T2/T1, não a diferença T2−T1.","contentId":"fis-termica"},{"id":"m45-fis-termica-08","subject":"Física","topic":"Calor e termodinâmica","subtopic":"primeira lei e sinais","prompt":"Um gás recebe 500 J de calor e realiza 200 J de trabalho sobre a vizinhança. Adotando trabalho realizado pelo gás como positivo, qual é a variação da energia interna?","options":["−700 J","−300 J","300 J","700 J"],"answer":2,"explanation":"A primeira lei nessa convenção é ΔU = Q − W. Com Q=+500 J e W=+200 J, ΔU=300 J. A energia interna aumenta, embora parte do calor recebido saia como trabalho.","difficulty":"avançada","sourceBasis":"https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_9B__Waves_Sound_Optics_Thermodynamics_and_Fluids/05%3A_Fundamentals_of_Thermodynamics; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_9B__Waves_Sound_Optics_Thermodynamics_and_Fluids/05%3A_Fundamentals_of_Thermodynamics; calibração apenas; questão autoral/similar; não oficial.","skill":"aplicar a primeira lei com convenção explícita de trabalho","commonError":"Somar Q e W sem identificar se o trabalho foi realizado pelo gás ou sobre o gás.","whyWrong":"0 e 1 trocam o sinal do calor ou do trabalho; 3 soma 500 e 200, como se todo trabalho também fosse energia recebida pelo sistema.","reviewHint":"Escreva a convenção antes do cálculo: para trabalho do gás positivo, ΔU=Q−W.","contentId":"fis-termica"},{"id":"m45-fis-termica-09","subject":"Física","topic":"Calor e termodinâmica","subtopic":"trabalho em diagrama P–V","prompt":"Um gás se expande sob pressão constante de 2,0 × 10⁵ Pa, passando de 0,010 m³ para 0,030 m³. Qual é o trabalho realizado pelo gás?","options":["2,0 × 10³ J","4,0 × 10³ J","6,0 × 10³ J","4,0 × 10⁵ J"],"answer":1,"explanation":"Para pressão constante, W=PΔV. A variação de volume é 0,020 m³; logo W=2,0×10⁵×0,020=4,0×10³ J. A expansão torna o trabalho positivo nessa convenção.","difficulty":"avançada","sourceBasis":"https://canal.cecierj.edu.br/012016/d4b99c5451211f0f5f7a50379bc79a0f.pdf; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://canal.cecierj.edu.br/012016/d4b99c5451211f0f5f7a50379bc79a0f.pdf; calibração apenas; questão autoral/similar; não oficial.","skill":"calcular trabalho como área sob a curva P–V","commonError":"Multiplicar pela velocidade ou pelo volume final, em vez de usar a variação de volume.","whyWrong":"0 usa metade do deslocamento; 2 usa o volume final; 3 mantém a unidade de pressão sem converter o produto para joules corretamente.","reviewHint":"Para um trecho horizontal no gráfico P–V, use o retângulo de altura P e largura V2−V1.","contentId":"fis-termica"},{"id":"m45-fis-termica-10","subject":"Física","topic":"Calor e termodinâmica","subtopic":"processo isotérmico","prompt":"Em uma expansão isotérmica reversível de um gás ideal, qual conjunto de afirmações é compatível com o modelo?","options":["A temperatura varia, ΔU é positivo e Q=0.","A temperatura é constante, ΔU=0 e o calor recebido é igual ao trabalho realizado pelo gás.","O volume é constante, o trabalho é nulo e Q=ΔU sempre.","A pressão e o volume crescem juntos e a energia interna depende do caminho."],"answer":1,"explanation":"Para gás ideal, a energia interna depende apenas da temperatura; em processo isotérmico, ΔT=0 e ΔU=0. Pela primeira lei, Q=W, e a expansão exige calor recebido para fornecer o trabalho.","difficulty":"avançada","sourceBasis":"https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_9B__Waves_Sound_Optics_Thermodynamics_and_Fluids/05%3A_Fundamentals_of_Thermodynamics; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Courses/University_of_California_Davis/UCD%3A_Physics_9B__Waves_Sound_Optics_Thermodynamics_and_Fluids/05%3A_Fundamentals_of_Thermodynamics; calibração apenas; questão autoral/similar; não oficial.","skill":"combinar condição isotérmica, energia interna e primeira lei","commonError":"Confundir isotérmico com adiabático ou concluir que temperatura constante implica ausência de calor.","whyWrong":"0 descreve variação de temperatura e Q=0; 2 troca isotérmico por isocórico; 3 viola PV constante e a propriedade de estado da energia interna.","reviewHint":"Comece pela propriedade do gás ideal: U depende de T; depois aplique a primeira lei.","contentId":"fis-termica"},{"id":"m45-fis-termica-11","subject":"Física","topic":"Calor e termodinâmica","subtopic":"processo adiabático","prompt":"Um gás ideal é comprimido rapidamente em um cilindro termicamente isolado. Considerando desprezíveis outras perdas, o que ocorre com Q, ΔU e a temperatura do gás?","options":["Q=0, ΔU>0 e a temperatura aumenta.","Q>0, ΔU=0 e a temperatura permanece constante.","Q=0, ΔU<0 e a temperatura diminui.","Q<0, ΔU=0 e a temperatura aumenta apenas por causa do volume."],"answer":0,"explanation":"Isolamento térmico implica Q=0. Na compressão, o trabalho é feito sobre o gás, portanto o trabalho realizado pelo gás é negativo; pela primeira lei, ΔU=−W>0. Para gás ideal, a elevação de U significa aumento de T.","difficulty":"avançada","sourceBasis":"https://phys.libretexts.org/Courses/Georgia_State_University/GSU-TM-Physics_I_(2211)/12%3A_Temperature_and_Heat; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Courses/Georgia_State_University/GSU-TM-Physics_I_(2211)/12%3A_Temperature_and_Heat; calibração apenas; questão autoral/similar; não oficial.","skill":"analisar compressão adiabática pela primeira lei","commonError":"Interpretar adiabático como temperatura constante ou atribuir Q positivo ao trabalho sobre o gás.","whyWrong":"1 e 3 confundem adiabático com isotérmico; 2 atribui sinal de ΔU incompatível com o trabalho realizado sobre o gás.","reviewHint":"Traduza “isolado” para Q=0 e depois determine o sinal de W usando o sentido da transformação.","contentId":"fis-termica"},{"id":"m45-fis-termica-12","subject":"Física","topic":"Calor e termodinâmica","subtopic":"máquinas térmicas e Carnot","prompt":"Uma máquina térmica reversível opera entre uma fonte quente a 600 K e uma fonte fria a 300 K. Qual é seu rendimento máximo ideal?","options":["25%","40%","50%","100%"],"answer":2,"explanation":"Para Carnot, η=1−Tc/Th=1−300/600=0,50, ou 50%. O resultado é um limite ideal; uma máquina real não pode superá-lo nem atingir 100% entre fontes finitas.","difficulty":"avançada","sourceBasis":"https://portal.ifce.edu.br/documents/21166/s4-lf-termodinamica_86CFtJH.pdf; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://portal.ifce.edu.br/documents/21166/s4-lf-termodinamica_86CFtJH.pdf; calibração apenas; questão autoral/similar; não oficial.","skill":"calcular limite de rendimento de Carnot em kelvin","commonError":"Usar graus Celsius na razão ou interpretar rendimento como razão entre temperaturas em vez de 1−Tc/Th.","whyWrong":"0 e 1 não resultam da fórmula de Carnot; 3 viola a segunda lei ao admitir conversão integral de calor em trabalho.","reviewHint":"Use as temperaturas absolutas e identifique qual é o reservatório quente e qual é o frio.","contentId":"fis-termica"},{"id":"m45-fis-termica-13","subject":"Física","topic":"Calor e termodinâmica","subtopic":"entropia e segunda lei","prompt":"Dois blocos isolados, um quente e outro frio, são postos em contato até o equilíbrio. Qual afirmação descreve corretamente a variação de entropia do conjunto?","options":["É necessariamente negativa, pois o bloco quente perde energia.","É nula em qualquer contato, pois a energia total se conserva.","É positiva para uma transferência irreversível real; seria nula apenas no limite reversível.","É positiva somente se o bloco frio perder calor para o quente."],"answer":2,"explanation":"A energia total do conjunto se conserva, mas o processo espontâneo de calor do quente para o frio é irreversível e aumenta a entropia total. Conservação de energia não implica entropia constante.","difficulty":"avançada","sourceBasis":"https://portal.ifce.edu.br/documents/21166/s4-lf-termodinamica_86CFtJH.pdf; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://portal.ifce.edu.br/documents/21166/s4-lf-termodinamica_86CFtJH.pdf; calibração apenas; questão autoral/similar; não oficial.","skill":"interpretar a segunda lei por meio da entropia total","commonError":"Concluir que a entropia não varia porque a energia total é conservada.","whyWrong":"0 confunde perda de energia do bloco com entropia do conjunto; 1 confunde conservação de energia com reversibilidade; 3 inverte o sentido espontâneo.","reviewHint":"Defina o sistema como os dois blocos juntos e diferencie primeira lei (energia) de segunda lei (sentido e irreversibilidade).","contentId":"fis-termica"},{"id":"m45-fis-termica-14","subject":"Física","topic":"Calor e termodinâmica","subtopic":"aquecimento com mudança de fase","prompt":"Calcule o calor necessário para levar 100 g de gelo a −10 °C até água líquida a 20 °C. Use c_gelo=2,1 J/(g·°C), L_f=334 J/g e c_água=4,2 J/(g·°C), sem perdas.","options":["35,5 kJ","39,7 kJ","43,9 kJ","52,3 kJ"],"answer":2,"explanation":"Há três etapas: aquecer o gelo (2,1 kJ), fundir (33,4 kJ) e aquecer a água (8,4 kJ). A soma é 2,1+33,4+8,4=43,9 kJ.","difficulty":"avançada","sourceBasis":"https://phys.libretexts.org/Courses/Georgia_State_University/GSU-TM-Physics_I_(2211)/12%3A_Temperature_and_Heat; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://phys.libretexts.org/Courses/Georgia_State_University/GSU-TM-Physics_I_(2211)/12%3A_Temperature_and_Heat; calibração apenas; questão autoral/similar; não oficial.","skill":"decompor um processo térmico em calor sensível e latente","commonError":"Calcular apenas a fusão ou aplicar um único calor específico ao percurso inteiro.","whyWrong":"0 e 1 omitem ou subestimam uma das etapas sensíveis; 3 soma uma contribuição excessiva por usar dados incompatíveis ou duplicar o latente.","reviewHint":"Faça uma linha de estados: gelo −10 °C → gelo 0 °C → água 0 °C → água 20 °C.","contentId":"fis-termica"},{"id":"m45-fis-termica-15","subject":"Física","topic":"Calor e termodinâmica","subtopic":"ciclo termodinâmico","prompt":"Um gás percorre um ciclo fechado no diagrama P–V e retorna ao estado inicial. Qual afirmação é necessariamente correta ao final de um ciclo completo?","options":["A energia interna aumentou, pois o gás realizou trabalho líquido.","A variação de energia interna é zero; o calor líquido recebido é igual ao trabalho líquido realizado pelo gás.","O calor líquido é sempre zero, independentemente do trabalho.","A pressão e a temperatura são constantes durante todo o ciclo."],"answer":1,"explanation":"Energia interna é função de estado: ao retornar ao estado inicial, ΔU=0. Pela primeira lei, 0=Qlíq−Wlíq, portanto Qlíq=Wlíq. Isso não exige pressão ou temperatura constantes ao longo do caminho.","difficulty":"avançada","sourceBasis":"https://portal.ifce.edu.br/documents/21166/s4-lf-termodinamica_86CFtJH.pdf; calibração apenas; questão autoral/similar; não oficial.","origin":"autoral/similar","source":"https://portal.ifce.edu.br/documents/21166/s4-lf-termodinamica_86CFtJH.pdf; calibração apenas; questão autoral/similar; não oficial.","skill":"relacionar função de estado, ciclo e primeira lei","commonError":"Supor que toda grandeza trocada ao longo do caminho também tenha variação nula no ciclo.","whyWrong":"0 admite ΔU diferente de zero no mesmo estado final; 2 confunde ciclo com processo adiabático; 3 confunde retorno ao estado inicial com constância durante o percurso.","reviewHint":"Separe grandezas de estado (como U) de grandezas dependentes do caminho (Q e W).","contentId":"fis-termica"}] as const;
export const V45_QUESTION_COUNT = v45Questions.length;
